 15: // CreateSessionReq reuses the session-spawn contract across HTTP and cron.
 16: type CreateSessionReq struct {
 17: 	Name           string
 18: 	Host           string
 19: 	Path           string
 20: 	Command        string
 21: 	AgentType      string
 22: 	WorktreeBranch string
 23: 	ScheduleID     string
 24: 	CommandID      string // stable command id derived from schedule identity
 25: }
 26: 
 27: // CreateSessionFunc spawns one session.
 28: type CreateSessionFunc func(CreateSessionReq) error
 29: 
 30: type PeerLookup interface {
 31: 	IsLocal(hostID string) bool
 32: 	GetPeerConnection(id string) *peer.PeerConnection
 33: }
 34: 
 35: // Runner fires due jobs on a 1s tick.
 36: type Runner struct {
 37: 	store    *Store
 38: 	stateMgr *state.Manager
 39: 	peerMgr  PeerLookup
 40: 	createFn CreateSessionFunc
 41: 	capFn    func(job Job)
 42: 	log      *logrus.Entry
 43: 	nowFn    func() time.Time
 44: 	Owner    string // v2 owner id used to derive stable command IDs
 45: }
 46: 
 47: // SetCapEnforcer installs an optional pre-spawn hook that prunes a schedule's
 48: // existing sessions down to its MaxConcurrency before a new one is spawned.
 49: func (r *Runner) SetCapEnforcer(fn func(job Job)) {
 50: 	if r == nil {
 51: 		return
 52: 	}
 53: 	r.capFn = fn
 54: }
 55: 
 56: func NewRunner(store *Store, stateMgr *state.Manager, peerMgr PeerLookup, createFn CreateSessionFunc, log *logrus.Entry) *Runner {
 57: 	if log == nil {
 58: 		log = logrus.NewEntry(logrus.StandardLogger())
 59: 	}
 60: 	return &Runner{
 61: 		store:    store,
 62: 		stateMgr: stateMgr,
 63: 		peerMgr:  peerMgr,
 64: 		createFn: createFn,
 65: 		log:      log,
 66: 		nowFn:    time.Now,
 67: 	}
 68: }
 69: 
 70: func (r *Runner) Run(ctx context.Context) {
 71: 	if r == nil || r.store == nil || r.createFn == nil {
 72: 		return
 73: 	}
 74: 	nowFn := r.nowFn
 75: 	if nowFn == nil {
 76: 		nowFn = time.Now
 77: 	}
 78: 	if err := r.store.reconcileNextRuns(nowFn()); err != nil {
 79: 		r.log.WithError(err).Warn("scheduler startup reconcile failed")
 80: 	}
 81: 	ticker := time.NewTicker(time.Second)
 82: 	defer ticker.Stop()
 83: 	for {
 84: 		select {
 85: 		case <-ctx.Done():
 86: 			return
 87: 		case <-ticker.C:
 88: 			r.runOnce(nowFn())
 89: 		}
 90: 	}
 91: }
 92: 
 93: func (r *Runner) runOnce(now time.Time) {
 94: 	for _, job := range r.store.List() {
 95: 		if !job.Enabled || job.CronSpec == "" {
 96: 			continue
 97: 		}
 98: 		if job.NextRun.After(now) {
 99: 			continue
100: 		}
101: 			schedule, err := cron.ParseStandard(job.CronSpec)
102: 		if err != nil {
103: 			r.log.WithError(err).WithField("job_id", job.ID).Warn("scheduler job disabled: invalid cron")
104: 			if disErr := r.store.disable(job.ID); disErr != nil {
105: 				r.log.WithError(disErr).WithField("job_id", job.ID).Warn("scheduler disable update failed")
106: 			}
107: 			continue
108: 		}
109: 		next := schedule.Next(now)
110: 		if next.IsZero() {
111: 			next = now.Add(time.Minute)
112: 		}
113: 
114: 		cmdID := ""
115: 		if r.Owner != "" {
116: 			cmdID = string(state.NewCommandIDFromSchedule(state.OwnerID(r.Owner), job.ID, now))
117: 		}
118: 
119: 		if job.Host != "" && r.peerMgr != nil && !r.peerMgr.IsLocal(job.Host) {
120: 			if r.peerMgr.GetPeerConnection(job.Host) == nil {
121: 				r.log.WithField("job_id", job.ID).WithField("host", job.Host).Warn("scheduler peer offline, skipping fire")
122: 				job.NextRun = next
123: 				if _, updErr := r.store.Update(job); updErr != nil {
124: 					r.log.WithError(updErr).WithField("job_id", job.ID).Warn("scheduler next-run update failed")
125: 				}
126: 				continue
127: 			}
128: 		}
129: 
130: 		name := job.SessionNamePrefix
131: 		if name == "" {
132: 			name = job.Name
133: 		}
134: 		if name == "" {
135: 			name = "schedule"
136: 		}
137: 		req := CreateSessionReq{
138: 			Name:           fmt.Sprintf("%s-%d", name, now.Unix()),
139: 			Host:           job.Host,
140: 			Path:           job.Path,
141: 			Command:        job.Command,
142: 			AgentType:      job.AgentType,
143: 			WorktreeBranch: job.WorktreeBranch,
144: 			ScheduleID:     job.ID,
145: 			CommandID:      cmdID,
146: 		}
147: 		if job.MaxConcurrency > 0 && r.capFn != nil {
148: 			r.capFn(job)
149: 		}
150: 		if err := r.createFn(req); err != nil {
151: 			r.log.WithError(err).WithField("job_id", job.ID).Warn("scheduler fire failed")
152: 			job.NextRun = next
153: 			if _, updErr := r.store.Update(job); updErr != nil {
154: 				r.log.WithError(updErr).WithField("job_id", job.ID).Warn("scheduler next-run update failed")
155: 			}
156: 			continue
157: 		}
158: 		if _, err := r.store.MarkRan(job.ID, now, next); err != nil {
159: 			r.log.WithError(err).WithField("job_id", job.ID).Warn("scheduler mark-ran failed")
160: 		}
161: 	}
