 29: // Status represents the current state of an agent
 30: type Status string
 31: 
 32: const (
 33: 	StatusActive    Status = "active"    // agent is running, doing work
 34: 	StatusWaiting   Status = "waiting"   // agent needs user attention/approval
 35: 	StatusCompleted Status = "completed" // agent finished its task
 36: 	StatusError     Status = "error"     // agent encountered an error
 37: 	StatusStuck     Status = "stuck"     // agent claims active but made no observable progress
