 40: // FileArtifact is a file an agent produced, with server-local stat metadata.
 41: type FileArtifact struct {
 42: 	Path        string    `json:"path"`
 43: 	DisplayPath string    `json:"display_path,omitempty"`
 44: 	Name        string    `json:"name"`
 45: 	Size        int64     `json:"size,omitempty"`
 46: 	ModTime     time.Time `json:"mod_time,omitempty"`
 47: 	Tool        Tool      `json:"tool,omitempty"`
 48: 	Source      string    `json:"source"`
 49: 	FirstSeen   time.Time `json:"first_seen"`
 50: 	Stale       bool      `json:"stale,omitempty"`
