 53: // Event is a single notification from an agent hook
 54: type Event struct {
 55: 	Tool           Tool            `json:"tool"`
 56: 	Status         Status          `json:"status"`
 57: 	Kind           string          `json:"kind,omitempty"`
 58: 	Host           string          `json:"host,omitempty"`             // peer fingerprint (empty = local)
 59: 	HostName       string          `json:"host_name,omitempty"`        // peer display name
 60: 	Session        string          `json:"session"`                    // session name (display alias, mutable on rename)
 61: 	SessionID      string          `json:"session_id,omitempty"`       // durable session identity; stable across renames
 62: 	Window         int             `json:"window"`                     // window index
 63: 	Pane           string          `json:"pane,omitempty"`             // pane ID (optional)
 64: 	Message        string          `json:"message,omitempty"`          // human-readable detail
 65: 	CWD            string          `json:"cwd,omitempty"`              // current working directory when provided by the agent hook
 66: 	AgentSessionID string          `json:"agent_session_id,omitempty"` // upstream agent session/thread id when available
 67: 	Timestamp      time.Time       `json:"timestamp"`
 68: 	AutoDetected   bool            `json:"auto_detected,omitempty"` // true if detected via process tree (not hooks)
 69: 	UserPrompt     string          `json:"user_prompt,omitempty"`   // first user message for this session (set once)
 70: 	AgentMessage   string          `json:"agent_message,omitempty"` // last agent response message (updates each turn)
 71: 	Files          []string        `json:"files,omitempty"`
 72: 	Artifacts      []*FileArtifact `json:"artifacts,omitempty"`
 73: }
 74: 
 75: // PaneKey uniquely identifies a pane
 76: type PaneKey struct {
 77: 	Host    string
 78: 	Session string
 79: 	Window  int
 80: 	Pane    string
 81: }
 82: 
 83: // eventSessionKey returns the session identity used to track and correlate
 84: // an event: the durable SessionID when present, otherwise the session name.
 85: // The name is a display alias that can change on rename, so preferring the
 86: // stable id keeps already-recorded (in-flight) events correlated across
 87: // renames. Legacy events without a SessionID fall back to the name.
 88: func eventSessionKey(sessionID, sessionName string) string {
 89: 	if sessionID != "" {
 90: 		return sessionID
 91: 	}
 92: 	return sessionName
 93: }
 94: 
 95: type SessionMeta struct {
 96: 	Tool             Tool
 97: 	CWD              string
 98: 	AgentSessionID   string
 99: 	Message          string
100: 	UserPrompt       string // first user message; set once, never overwritten
101: 	LastAgentMessage string // last agent response; updated each turn
102: }
103: 
104: // nativeWaitingTools is the set of tools that send explicit "waiting" events
105: // via hooks. Tools not in this set will have inactivity-based and
106: // silence-based waiting detection as fallbacks.
107: var nativeWaitingTools = map[Tool]bool{
108: 	ToolClaude:   true,
109: 	ToolOpenCode: true,
110: 	ToolPi:       true,
111: }
112: 
113: // Tracker tracks the latest status of AI tools per pane
114: type Tracker struct {
115: 	mu        sync.RWMutex
116: 	events    map[PaneKey]*Event
117: 	artifacts map[string][]*FileArtifact
118: 
119: 	// lastActive tracks the most recent "active" event per pane for tools
120: 	// that lack native waiting detection. Used by the inactivity promoter.
121: 	lastActive map[PaneKey]*Event
122: 
123: 	// activePanes tracks local panes whose latest hook status is "active",
124: 	// including native-waiting tools (Claude/Pi/OpenCode). Used by the stuck
125: 	// monitor to detect agents that claim to be working but make no
126: 	// observable progress (no tool events and no pane output). Keyed by
127: 	// pane ID so the %output handler can refresh progress cheaply.
128: 	activePanes map[string]*activeState
129: 
130: 	// activeTurns tracks panes with an in-progress hook-based agent turn,
131: 	// keyed by pane. Set on a hook "active" event, cleared on any terminal
132: 	// status (completed/waiting/error). Unlike t.events it survives the
133: 	// active-clears-tracking rule, giving the frontend an authoritative source
134: 	// to reconcile its "working" badge against. notify -> server is HTTP (not
135: 	// the lossy WS broadcast), so this map is reliable even when a completed
136: 	// WS frame is dropped.
137: 	activeTurns map[PaneKey]*Event
138: 
139: 	// Subscribers
140: 	subMu       sync.RWMutex
141: 	subscribers []chan *Event
142: 
143: 	sessionMeta map[string]SessionMeta
144: 
145: 	// path is the on-disk file for retained state (waiting/error events +
146: 	// session metadata) so it survives a server restart. Empty = persistence
147: 	// disabled (the default; tests stay in-memory). Set via EnablePersistence.
148: 	path string
149: }
150: 
151: // NewTracker creates a new tool event tracker
152: // activeState tracks an actively-working local pane for stuck detection.
153: type activeState struct {
154: 	evt          *Event    // the originating active event (session/window/pane context)
155: 	lastProgress time.Time // last tool event or pane output for this pane
156: 	flagged      bool      // true once we've emitted a stuck event (avoid repeats)
157: }
158: 
159: func NewTracker() *Tracker {
160: 	return &Tracker{
161: 		events:      make(map[PaneKey]*Event),
162: 		artifacts:   make(map[string][]*FileArtifact),
163: 		lastActive:  make(map[PaneKey]*Event),
164: 		activePanes: make(map[string]*activeState),
165: 		activeTurns: make(map[PaneKey]*Event),
166: 		sessionMeta: make(map[string]SessionMeta),
167: 	}
168: }
169: 
170: // persistedState is the on-disk snapshot of retained tracker state. Events
171: // are stored as a slice (PaneKey is a struct and can't be a JSON map key);
172: // the key is reconstructed from each event's host/session/window/pane on load.
173: type persistedState struct {
174: 	Events      []*Event                   `json:"events"`
175: 	Artifacts   map[string][]*FileArtifact `json:"artifacts"`
176: 	SessionMeta map[string]SessionMeta     `json:"session_meta"`
177: }
178: 
179: // EnablePersistence loads any previously persisted retained state (waiting/
180: // error events + session metadata) and, from now on, writes it back to disk
181: // on every Record so it survives a server restart. Best-effort: a missing or
182: // corrupt file is ignored, and persistence stays off if the dir can't be made.
183: func (t *Tracker) EnablePersistence() {
184: 	dir, err := config.Dir()
185: 	if err != nil {
186: 		return
187: 	}
188: 	if err := os.MkdirAll(dir, 0o755); err != nil {
189: 		return
190: 	}
191: 	t.mu.Lock()
192: 	t.path = filepath.Join(dir, "toolevents.json")
193: 	t.load()
194: 	t.mu.Unlock()
195: }
196: 
197: // load reads persisted state from disk. Caller must hold t.mu.
198: func (t *Tracker) load() {
199: 	data, err := os.ReadFile(t.path)
200: 	if err != nil {
201: 		return
202: 	}
203: 	var st persistedState
204: 	if err := json.Unmarshal(data, &st); err != nil {
205: 		return
206: 	}
207: 	for _, evt := range st.Events {
208: 		if evt == nil {
209: 			continue
210: 		}
211: 		t.events[PaneKey{Host: evt.Host, Session: eventSessionKey(evt.SessionID, evt.Session), Window: evt.Window, Pane: evt.Pane}] = evt
212: 	}
213: 	for k, arts := range st.Artifacts {
214: 		if len(arts) == 0 {
215: 			continue
216: 		}
217: 		dup := make([]*FileArtifact, 0, len(arts))
218: 		for _, art := range arts {
219: 			if art == nil {
220: 				continue
221: 			}
222: 			dup = append(dup, art)
223: 		}
224: 		if len(dup) > 0 {
225: 			t.artifacts[k] = dup
226: 		}
227: 	}
228: 	for k, v := range st.SessionMeta {
229: 		t.sessionMeta[k] = v
230: 	}
231: }
232: 
233: // persist snapshots retained state under the read lock and writes it to disk.
234: // No-op when persistence is disabled. ponytail: writes the whole snapshot on
235: // every Record (mirrors auth's per-call save); add a dirty-flag if event rate
236: // ever makes this I/O-bound.
237: func (t *Tracker) persist() {
238: 	t.mu.RLock()
239: 	if t.path == "" {
240: 		t.mu.RUnlock()
241: 		return
242: 	}
243: 	st := persistedState{
244: 		Events:      make([]*Event, 0, len(t.events)),
245: 		Artifacts:   make(map[string][]*FileArtifact, len(t.artifacts)),
246: 		SessionMeta: make(map[string]SessionMeta, len(t.sessionMeta)),
247: 	}
248: 	for _, evt := range t.events {
249: 		st.Events = append(st.Events, evt)
250: 	}
251: 	for k, arts := range t.artifacts {
252: 		if len(arts) == 0 {
253: 			continue
254: 		}
255: 		dup := make([]*FileArtifact, 0, len(arts))
256: 		for _, art := range arts {
257: 			if art == nil {
258: 				continue
259: 			}
260: 			dupArt := *art
261: 			dup = append(dup, &dupArt)
262: 		}
263: 		if len(dup) > 0 {
264: 			st.Artifacts[k] = dup
265: 		}
266: 	}
267: 	for k, v := range t.sessionMeta {
268: 		st.SessionMeta[k] = v
269: 	}
270: 	path := t.path
271: 	t.mu.RUnlock()
272: 
273: 	data, err := json.Marshal(st)
274: 	if err != nil {
275: 		return
276: 	}
277: 	_ = os.WriteFile(path, data, 0o600)
278: }
279: 
280: // Record stores a new event and broadcasts it to subscribers
281: func (t *Tracker) Record(evt *Event) {
282: 	evt.Timestamp = time.Now()
283: 
284: 	log := logrus.WithFields(logrus.Fields{
285: 		"tool":          evt.Tool,
286: 		"status":        evt.Status,
287: 		"session":       evt.Session,
288: 		"window":        evt.Window,
289: 		"pane":          evt.Pane,
290: 		"host":          evt.Host,
291: 		"message":       evt.Message,
292: 		"auto_detected": evt.AutoDetected,
293: 	})
294: 	log.Debug("recording tool event")
295: 
296: 	key := PaneKey{
297: 		Host:    evt.Host,
298: 		Session: eventSessionKey(evt.SessionID, evt.Session),
299: 		Window:  evt.Window,
300: 		Pane:    evt.Pane,
301: 	}
302: 	sessionKey := evt.Host + "\x00" + evt.Session
303: 
304: 	t.mu.Lock()
305: 	if evt.Status == StatusCompleted || evt.Status == StatusActive {
306: 		// Completed and active events clear the tracking — active is transient
307: 		// and only serves to signal that waiting/error state should be dismissed
308: 		_, existed := t.events[key]
309: 		delete(t.events, key)
310: 		log.WithFields(logrus.Fields{
311: 			"action": "clear", "had_existing": existed, "tracked_count": len(t.events),
312: 		}).Trace("tracker: cleared event (active/completed)")
313: 	} else {
314: 		t.events[key] = evt
315: 		log.WithField("tracked_count", len(t.events)).Trace("tracker: stored event (waiting/error)")
316: 	}
317: 
318: 	// Track last activity for tools without native waiting detection.
319: 	// The inactivity promoter uses this to generate synthetic "waiting"
320: 	// events when a tool goes quiet. Auto-detected events are excluded —
321: 	// only hook-based activity should trigger the inactivity timer,
322: 	// since we can't tell if an auto-detected agent is working or idle.
323: 	if !nativeWaitingTools[evt.Tool] && !evt.AutoDetected {
324: 		switch evt.Status {
325: 		case StatusActive:
326: 			t.lastActive[key] = evt
327: 			log.Trace("tracker: added to lastActive for inactivity promotion")
328: 		default:
329: 			// Any explicit waiting/error/completed clears the inactivity tracker
330: 			delete(t.lastActive, key)
331: 			log.Trace("tracker: cleared from lastActive")
332: 		}
333: 	} else if evt.AutoDetected {
334: 		log.Trace("tracker: skipping lastActive (auto-detected)")
335: 	}
336: 
337: 	// Maintain activePanes for stuck detection. Only local panes (Host=="")
338: 	// with a pane ID, driven by hook events (not auto-detected). Unlike
339: 	// lastActive, this includes native-waiting tools (Claude/Pi/OpenCode):
340: 	// those tools clear their tracked event on "active", so a hung agent
341: 	// mid-tool would otherwise be invisible. A "stuck" event itself does not
342: 	// clear activePanes (the agent still claims to be working); any output
343: 	// or new tool event refreshes lastProgress and unflags it.
344: 	if evt.Host == "" && evt.Pane != "" && !evt.AutoDetected {
345: 		switch evt.Status {
346: 		case StatusActive:
347: 			t.activePanes[evt.Pane] = &activeState{evt: evt, lastProgress: evt.Timestamp}
348: 			log.Trace("tracker: tracking active pane for stuck detection")
349: 		case StatusStuck:
350: 			// keep the entry; the monitor sets flagged itself
351: 		default:
352: 			// waiting/error/completed mean the agent no longer claims to be working
353: 			delete(t.activePanes, evt.Pane)
354: 			log.Trace("tracker: cleared active pane (non-active status)")
355: 		}
356: 	}
357: 
358: 	// Authoritative active-turn tracking for the frontend "working" badge.
359: 	// Hook "active" opens a turn; any terminal status closes it. Stuck keeps
360: 	// the turn open (the agent still claims to be working).
361: 	if !evt.AutoDetected {
362: 		switch evt.Status {
363: 		case StatusActive:
364: 			t.activeTurns[key] = evt
365: 		case StatusStuck:
366: 			// keep the turn open
367: 		default:
368: 			delete(t.activeTurns, key)
369: 		}
370: 	}
371: 
372: 	meta := t.sessionMeta[sessionKey]
373: 	if evt.Tool != "" {
374: 		meta.Tool = evt.Tool
375: 	}
376: 	if evt.CWD != "" {
377: 		meta.CWD = evt.CWD
378: 	}
379: 	if evt.AgentSessionID != "" {
380: 		meta.AgentSessionID = evt.AgentSessionID
381: 	}
382: 	if evt.Message != "" && !evt.AutoDetected {
383: 		meta.Message = evt.Message
384: 	}
385: 	if evt.UserPrompt != "" && meta.UserPrompt == "" {
386: 		meta.UserPrompt = evt.UserPrompt // set once
387: 	}
388: 	if evt.AgentMessage != "" {
389: 		meta.LastAgentMessage = evt.AgentMessage
390: 	}
391: 	if meta != (SessionMeta{}) {
392: 		t.sessionMeta[sessionKey] = meta
393: 	}
394: 	t.mu.Unlock()
395: 	if len(evt.Artifacts) > 0 {
396: 		t.storeArtifacts(evt.Host, evt.Session, evt.Artifacts)
397: 	}
398: 
399: 	// Broadcast to subscribers
400: 	t.subMu.RLock()
401: 	defer t.subMu.RUnlock()
402: 	sent := 0
403: 	for _, ch := range t.subscribers {
404: 		select {
405: 		case ch <- evt:
406: 			sent++
407: 		default:
408: 			log.Debug("tool event subscriber channel full, dropping")
409: 		}
410: 	}
411: 	log.WithField("subscribers", sent).Trace("tool event broadcast complete")
412: 
413: 	t.persist()
414: }
415: 
416: // RecordArtifacts stores server-detected file artifacts for a session (the
417: // tier-2 regex-scanner path, as opposed to Record's tier-1 hook path) and
418: // broadcasts them to subscribers as a Kind:"artifact" event. Unlike Record,
419: // this never touches t.events/t.lastActive/t.activePanes — there is no real
420: // tool-call lifecycle here, just "some files were seen and verified to exist".
421: func (t *Tracker) RecordArtifacts(session string, arts []*FileArtifact) {
422: 	if len(arts) == 0 {
423: 		return
424: 	}
425: 	t.storeArtifacts("", session, arts)
426: 
427: 	evt := &Event{Kind: "artifact", Session: session, Artifacts: arts, Timestamp: time.Now()}
428: 	t.subMu.RLock()
429: 	sent := 0
430: 	for _, ch := range t.subscribers {
431: 		select {
432: 		case ch <- evt:
433: 			sent++
434: 		default:
435: 			logrus.Debug("tool event subscriber channel full, dropping")
436: 		}
437: 	}
438: 	t.subMu.RUnlock()
439: 	logrus.WithField("subscribers", sent).Trace("artifact broadcast complete")
440: 	t.persist()
441: }
