448: // GetActivePaneEvents returns events for locally-tracked hook-based active panes.
449: // Active hook events clear t.events, so they are invisible to GetAll. This method
450: // exposes them so the reconciler can detect process exits for panes that sent
451: // an active hook but never sent a subsequent waiting/completed hook.
452: // RetainedWaitingForPane returns the retained waiting event for a local pane,
453: // or nil if the pane has no outstanding waiting event. Used by the silence
454: // monitor's reaper to clear stale native-agent waiting (e.g. Claude) once the
455: // input dialog is dismissed, since some agents emit no hook on cancel.
456: func (t *Tracker) RetainedWaitingForPane(paneID string) *Event {
457: 	t.mu.RLock()
458: 	defer t.mu.RUnlock()
459: 	for _, evt := range t.events {
460: 		if evt.Pane == paneID && evt.Status == StatusWaiting {
461: 			return evt
462: 		}
463: 	}
464: 	return nil
465: }
