467: func (t *Tracker) GetActivePaneEvents() []*Event {
468: 	t.mu.RLock()
469: 	defer t.mu.RUnlock()
470: 	events := make([]*Event, 0, len(t.activePanes))
471: 	for _, as := range t.activePanes {
472: 		events = append(events, as.evt)
473: 	}
474: 	return events
475: }
