477: // ActiveTurns returns the events for panes with an in-progress hook-based
478: // agent turn, pruning stale ones. The frontend rebuilds its "working" badge
479: // state from this so a dropped "completed" WS frame self-heals on the next
480: // periodic refresh.
481: func (t *Tracker) ActiveTurns() []*Event {
482: 	t.mu.Lock()
483: 	defer t.mu.Unlock()
484: 
485: 	now := time.Now()
486: 	turns := make([]*Event, 0, len(t.activeTurns))
487: 	for key, evt := range t.activeTurns {
488: 		if now.Sub(evt.Timestamp) > StaleTimeout {
489: 			delete(t.activeTurns, key)
490: 			continue
491: 		}
492: 		turns = append(turns, evt)
493: 	}
494: 	return turns
495: }
