497: // GetAll returns all currently tracked (non-completed) events, pruning stale ones.
498: func (t *Tracker) GetAll() []*Event {
499: 	t.mu.Lock()
500: 	defer t.mu.Unlock()
501: 
502: 	now := time.Now()
503: 	events := make([]*Event, 0, len(t.events))
504: 	for key, evt := range t.events {
505: 		if now.Sub(evt.Timestamp) > StaleTimeout {
506: 			delete(t.events, key)
507: 			continue
508: 		}
509: 		events = append(events, evt)
510: 	}
511: 	return events
