514: // Clear removes a specific event by session/window/pane, matching either the
515: // durable SessionID or the session name so a rename cannot orphan a retained
516: // in-flight event addressed by its stable identity.
517: func (t *Tracker) Clear(host, session string, window int, pane string) {
518: 	t.mu.Lock()
519: 	// Scan for events that share the pane and correlate by stable id or name
520: 	// (storage prefers SessionID when present, so an exact key built from the
521: 	// name alone may miss a rekeyed entry).
522: 	for k, evt := range t.events {
523: 		if evt.Pane != pane || evt.Window != window || evt.Host != host {
524: 			continue
525: 		}
526: 		if evt.SessionID == session || evt.Session == session {
527: 			delete(t.events, k)
528: 		}
529: 	}
530: 	// Exact-position delete for directly-constructed legacy keys.
531: 	delete(t.events, PaneKey{Host: host, Session: session, Window: window, Pane: pane})
532: 	t.mu.Unlock()
533: }
