535: // ClearAll removes all tracked events
536: func (t *Tracker) ClearAll() {
537: 	t.mu.Lock()
538: 	t.events = make(map[PaneKey]*Event)
539: 	t.activeTurns = make(map[PaneKey]*Event)
540: 	t.mu.Unlock()
541: }
