543: // artifactSessionKey intentionally ignores host, matching GetForSession's
544: // precedent: callers (the frontend, notify clients) key off session name
545: // alone, and requiring an exact host match caused artifacts to silently
546: // vanish whenever the caller didn't know the internal host fingerprint
547: // (e.g. a plain GET /api/artifacts?session=... with no host param).
548: func artifactSessionKey(_, session string) string {
549: 	return session
550: }
