552: func (t *Tracker) storeArtifacts(host, session string, arts []*FileArtifact) {
553: 	if len(arts) == 0 {
554: 		return
555: 	}
556: 	key := artifactSessionKey(host, session)
557: 	t.mu.Lock()
558: 	defer t.mu.Unlock()
559: 
560: 	cur := t.artifacts[key]
561: 	for _, art := range arts {
562: 		if art == nil || art.Path == "" {
563: 			continue
564: 		}
565: 		updated := false
566: 		for i := range cur {
567: 			existing := cur[i]
568: 			if existing == nil || existing.Path != art.Path {
569: 				continue
570: 			}
571: 			existing.Size = art.Size
572: 			existing.ModTime = art.ModTime
573: 			if art.DisplayPath != "" {
574: 				existing.DisplayPath = art.DisplayPath
575: 			}
576: 			if art.Name != "" {
577: 				existing.Name = art.Name
578: 			}
579: 			if art.Tool != "" {
580: 				existing.Tool = art.Tool
581: 			}
582: 			if art.Source != "" {
583: 				existing.Source = art.Source
584: 			}
585: 			cur = append(cur[:i], cur[i+1:]...)
586: 			cur = append(cur, existing)
587: 			updated = true
588: 			break
589: 		}
590: 		if updated {
591: 			continue
592: 		}
593: 		dup := *art
594: 		cur = append(cur, &dup)
595: 		if len(cur) > maxArtifactsPerSession {
596: 			cur = cur[len(cur)-maxArtifactsPerSession:]
597: 		}
598: 	}
599: 	if len(cur) == 0 {
600: 		delete(t.artifacts, key)
601: 		return
602: 	}
603: 	t.artifacts[key] = cur
604: }
605: 
606: func (t *Tracker) GetArtifacts(host, session string) []*FileArtifact {
607: 	t.mu.RLock()
608: 	defer t.mu.RUnlock()
609: 	arts := t.artifacts[artifactSessionKey(host, session)]
610: 	if len(arts) == 0 {
611: 		return nil
612: 	}
613: 	out := make([]*FileArtifact, 0, len(arts))
614: 	for _, art := range arts {
615: 		if art == nil {
616: 			continue
617: 		}
618: 		dup := *art
619: 		out = append(out, &dup)
620: 	}
621: 	return out
622: }
