630: // GetForSession returns events for a specific session. The argument may be
631: // the durable SessionID or the session name; the stable id takes precedence
632: // so a rename (which changes only the name) does not lose correlation.
633: func (t *Tracker) GetForSession(session string) []*Event {
634: 	t.mu.RLock()
635: 	defer t.mu.RUnlock()
636: 
637: 	var events []*Event
638: 	for key, evt := range t.events {
639: 		if key.Session == session || evt.SessionID == session || evt.Session == session {
640: 			events = append(events, evt)
