646: // Subscribe returns a channel that receives tool events
647: func (t *Tracker) Subscribe() chan *Event {
648: 	ch := make(chan *Event, 64)
649: 	t.subMu.Lock()
650: 	t.subscribers = append(t.subscribers, ch)
651: 	t.subMu.Unlock()
652: 	return ch
653: }
