655: // Unsubscribe removes a subscriber
656: func (t *Tracker) Unsubscribe(ch chan *Event) {
657: 	t.subMu.Lock()
658: 	defer t.subMu.Unlock()
659: 	for i, sub := range t.subscribers {
660: 		if sub == ch {
661: 			t.subscribers = append(t.subscribers[:i], t.subscribers[i+1:]...)
662: 			close(ch)
663: 			return
664: 		}
665: 	}
666: }
