668: // DefaultInactivityTimeout is how long a non-native-waiting tool can be quiet
669: // before the tracker promotes it to "waiting". This balances responsiveness
670: // (catching idle agents quickly) with avoiding false positives during normal
671: // tool use bursts.
672: const DefaultInactivityTimeout = 30 * time.Second
673: 
674: // RunInactivityPromoter starts a background goroutine that checks for tools
675: // without native waiting support that have gone quiet. If a tool's last
676: // "active" event is older than the timeout, a synthetic "waiting" event is
677: // recorded. This only affects tools NOT in nativeWaitingTools (e.g. copilot,
678: // codex, opencode) and never interferes with Claude's explicit waiting hooks.
679: func (t *Tracker) RunInactivityPromoter(ctx context.Context, timeout time.Duration) {
680: 	log := logrus.WithField("component", "inactivity-promoter")
681: 	log.WithField("timeout", timeout).Info("starting inactivity promoter")
682: 
683: 	// Check at half the timeout interval for responsiveness
684: 	interval := timeout / 2
685: 	if interval < 5*time.Second {
686: 		interval = 5 * time.Second
687: 	}
688: 
689: 	ticker := time.NewTicker(interval)
690: 	defer ticker.Stop()
691: 
692: 	for {
693: 		select {
694: 		case <-ctx.Done():
695: 			log.Info("stopping inactivity promoter")
696: 			return
697: 		case <-ticker.C:
698: 			t.promoteInactive(timeout, log)
699: 		}
700: 	}
701: }
702: 
703: // promoteInactive checks lastActive entries and promotes stale ones to waiting.
704: func (t *Tracker) promoteInactive(timeout time.Duration, log *logrus.Entry) {
705: 	now := time.Now()
706: 
707: 	t.mu.Lock()
708: 	var toPromote []*Event
709: 	for key, evt := range t.lastActive {
710: 		if now.Sub(evt.Timestamp) > timeout {
711: 			toPromote = append(toPromote, evt)
712: 			delete(t.lastActive, key)
713: 		}
714: 	}
715: 	t.mu.Unlock()
716: 
717: 	for _, evt := range toPromote {
718: 		log.WithFields(logrus.Fields{
719: 			"tool":    evt.Tool,
720: 			"session": evt.Session,
721: 			"window":  evt.Window,
722: 			"pane":    evt.Pane,
723: 		}).Debug("promoting inactive tool to waiting")
724: 
725: 		t.Record(&Event{
726: 			Tool:    evt.Tool,
727: 			Status:  StatusWaiting,
728: 			Host:    evt.Host,
729: 			Session: evt.Session,
730: 			Window:  evt.Window,
731: 			Pane:    evt.Pane,
732: 			Message: "May need attention",
733: 		})
734: 	}
735: }
