737: // RecordProgress refreshes the progress timestamp for an active pane. Called
738: // from the control-mode %output handler so that an agent producing terminal
739: // output (e.g. a long but healthy build) is not flagged as stuck. Also clears
740: // any prior stuck flag so the pane can be re-evaluated and the alert dismissed.
741: func (t *Tracker) RecordProgress(paneID string) {
742: 	t.mu.Lock()
743: 	as, ok := t.activePanes[paneID]
744: 	if !ok {
745: 		t.mu.Unlock()
746: 		return
747: 	}
748: 	now := time.Now()
749: 	as.lastProgress = now
750: 	wasFlagged := as.flagged
751: 	as.flagged = false
752: 	evt := as.evt
753: 	t.mu.Unlock()
754: 
755: 	// If we'd previously flagged this pane as stuck, output means it's alive
756: 	// again. Emit an active event to clear the stuck alert.
757: 	if wasFlagged {
758: 		t.Record(&Event{
759: 			Tool:    evt.Tool,
760: 			Status:  StatusActive,
761: 			Host:    evt.Host,
762: 			Session: evt.Session,
763: 			Window:  evt.Window,
764: 			Pane:    evt.Pane,
765: 		})
766: 	}
767: }
768: 
769: // DefaultStuckTimeout is how long a pane claiming "active" can go without any
770: // tool event or terminal output before the stuck monitor flags it. A genuinely
771: // busy agent emits tool events or output well within this window; silence this
772: // long usually means a hang, infinite loop, or a tool waiting on something that
773: // never arrives.
774: const DefaultStuckTimeout = 5 * time.Minute
775: 
776: // promptChecker reports whether captured pane content shows an input prompt.
777: // Used by the stuck monitor to avoid flagging a pane as stuck when it is
778: // actually waiting for user input (that's the silence monitor's job).
779: type promptChecker func(paneID string) (isPrompt bool, ok bool)
780: 
781: // RunStuckMonitor starts a background goroutine that flags local panes which
782: // claim to be "active" but have produced no tool events and no terminal output
783: // for longer than timeout, and are not sitting at an input prompt. When found,
784: // it records a synthetic "stuck" event. Pass a nil checkPrompt to skip the
785: // input-prompt guard (everything quiet is treated as stuck).
786: func (t *Tracker) RunStuckMonitor(ctx context.Context, timeout time.Duration, checkPrompt promptChecker) {
787: 	log := logrus.WithField("component", "stuck-monitor")
788: 	log.WithField("timeout", timeout).Info("starting stuck monitor")
789: 
790: 	interval := timeout / 4
791: 	if interval < 15*time.Second {
792: 		interval = 15 * time.Second
793: 	}
794: 
795: 	ticker := time.NewTicker(interval)
796: 	defer ticker.Stop()
797: 
798: 	for {
799: 		select {
800: 		case <-ctx.Done():
801: 			log.Info("stopping stuck monitor")
802: 			return
803: 		case <-ticker.C:
804: 			t.checkStuck(timeout, checkPrompt, log)
805: 		}
806: 	}
807: }
808: 
809: // checkStuck scans activePanes for entries quiet longer than timeout and
810: // records stuck events for them.
811: func (t *Tracker) checkStuck(timeout time.Duration, checkPrompt promptChecker, log *logrus.Entry) {
812: 	now := time.Now()
813: 
814: 	type candidate struct {
815: 		paneID string
816: 		evt    *Event
817: 	}
818: 	var candidates []candidate
819: 
820: 	t.mu.Lock()
821: 	for paneID, as := range t.activePanes {
822: 		if as.flagged {
823: 			continue
824: 		}
825: 		if now.Sub(as.lastProgress) > timeout {
826: 			candidates = append(candidates, candidate{paneID: paneID, evt: as.evt})
827: 		}
828: 	}
829: 	t.mu.Unlock()
830: 
831: 	for _, c := range candidates {
832: 		// Skip panes sitting at an input prompt: that's "waiting", not stuck.
833: 		if checkPrompt != nil {
834: 			if isPrompt, ok := checkPrompt(c.paneID); ok && isPrompt {
835: 				log.WithField("pane", c.paneID).Trace("quiet pane is at an input prompt, not stuck")
836: 				continue
837: 			}
838: 		}
839: 
840: 		t.mu.Lock()
841: 		as, ok := t.activePanes[c.paneID]
842: 		if !ok || as.flagged {
843: 			t.mu.Unlock()
844: 			continue
845: 		}
846: 		as.flagged = true
847: 		t.mu.Unlock()
848: 
849: 		log.WithFields(logrus.Fields{
850: 			"tool":    c.evt.Tool,
851: 			"session": c.evt.Session,
852: 			"window":  c.evt.Window,
853: 			"pane":    c.paneID,
854: 		}).Debug("flagging pane as stuck")
855: 
856: 		t.Record(&Event{
857: 			Tool:    c.evt.Tool,
858: 			Status:  StatusStuck,
859: 			Host:    c.evt.Host,
860: 			Session: c.evt.Session,
861: 			Window:  c.evt.Window,
862: 			Pane:    c.paneID,
863: 			Message: "No progress for a while, may be stuck",
864: 		})
865: 	}
