  3: export function useWebSocket(path: string, onMessage: (data: any) => void) {
  4:   const wsRef = useRef<WebSocket | null>(null)
  5:   const reconnectTimer = useRef<number | undefined>(undefined)
  6:   const hiddenRef = useRef(false)
  7:   const hasConnected = useRef(false)
  8:   const [connected, setConnected] = useState<boolean | null>(null) // null = initial connecting
  9:   // Keep a ref to the latest onMessage so the WebSocket always calls the current version
 10:   const onMessageRef = useRef(onMessage)
 11:   onMessageRef.current = onMessage
 12:   // Connection generation: once cleanup runs, callbacks from the old socket
 13:   // must not open a new connection or mutate React state.
 14:   const generationRef = useRef(0)
 15:   const disposedRef = useRef(false)
 16: 
 17:   useEffect(() => {
 18:     disposedRef.current = false
 19: 
 20:     function connect() {
 21:       if (disposedRef.current) return
 22:       generationRef.current++
 23:       const myGen = generationRef.current
 24: 
 25:       const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:'
 26:       const url = `${protocol}//${window.location.host}${path}`
 27:       const ws = new WebSocket(url)
 28:       wsRef.current = ws
 29: 
 30:       ws.onopen = () => {
 31:         if (disposedRef.current || generationRef.current !== myGen) return
 32:         hasConnected.current = true
 33:         setConnected(true)
 34:       }
 35: 
 36:       ws.onmessage = (evt) => {
 37:         if (disposedRef.current || generationRef.current !== myGen) return
 38:         try {
 39:           const data = JSON.parse(evt.data)
 40:           onMessageRef.current(data)
 41:         } catch {
 42:           // Non-JSON message, pass raw
 43:           onMessageRef.current(evt.data)
 44:         }
 45:       }
 46: 
 47:       ws.onclose = () => {
 48:         // Ignore close events from sockets that outlive their effect generation.
 49:         if (disposedRef.current || generationRef.current !== myGen) return
 50:         // Don't flash the disconnect banner if the page is just hidden
 51:         // or if we haven't established a connection yet (initial connect)
 52:         if (!hiddenRef.current && hasConnected.current) {
 53:           setConnected(false)
 54:         }
 55:         // If hidden (e.g. iPad app switch), defer reconnect until visible
 56:         if (hiddenRef.current) {
 57:           // Will be reconnected by onVisibilityChange when page becomes visible
 58:           return
 59:         }
 60:         reconnectTimer.current = window.setTimeout(connect, 2000)
 61:       }
 62: 
 63:       ws.onerror = (err) => {
 64:         if (disposedRef.current || generationRef.current !== myGen) return
 65:         console.error(`WS error: ${path}`, err)
 66:         ws.close()
 67:       }
 68:     }
 69: 
 70:     function onVisibilityChange() {
 71:       if (disposedRef.current) return
 72:       if (document.hidden) {
 73:         hiddenRef.current = true
 74:       } else {
 75:         hiddenRef.current = false
 76:         // If disconnected while hidden, reconnect immediately
 77:         if (wsRef.current?.readyState !== WebSocket.OPEN) {
 78:           if (reconnectTimer.current) {
 79:             clearTimeout(reconnectTimer.current)
 80:           }
 81:           connect()
 82:         }
 83:       }
 84:     }
 85: 
 86:     connect()
 87:     document.addEventListener('visibilitychange', onVisibilityChange)
 88:     window.addEventListener('pageshow', onVisibilityChange)
 89: 
 90:     return () => {
 91:       disposedRef.current = true
 92:       document.removeEventListener('visibilitychange', onVisibilityChange)
 93:       window.removeEventListener('pageshow', onVisibilityChange)
 94:       if (reconnectTimer.current) {
 95:         clearTimeout(reconnectTimer.current)
 96:       }
 97:       if (wsRef.current) {
 98:         wsRef.current.close()
 99:       }
100:     }
101:   }, [path])
102: 
103:   return { wsRef, connected }
104: }  1: package server
