 73: func TestDaemonAdapterSharesSnapshot(t *testing.T) {
 74: 	reg := &fakeRegistry{
 75: 		sessions: []pty.SessionInfo{
 76: 			{ID: "alpha", Cwd: "/tmp/alpha"},
 77: 			{ID: "beta", Cwd: "/tmp/beta"},
 78: 		},
 79: 	}
 80: 	adapter := &daemonAdapter{reg: reg}
 81: 
 82: 	// Both interface shapes can be assigned without a second conversion.
 83: 	var _ state.DaemonRegistry = adapter
 84: 	var _ peer.DaemonRegistry = adapter
 85: 
 86: 	first := adapter.refresh()
 87: 	if len(first) != 2 {
 88: 		t.Fatalf("refresh returned %d sessions, want 2", len(first))
 89: 	}
 90: 
 91: 	// List uses the cached snapshot; it does not call the registry again.
 92: 	list := adapter.List()
 93: 	if reg.listCalls != 1 {
 94: 		t.Fatalf("registry.List called %d times, want 1", reg.listCalls)
 95: 	}
 96: 	if len(list) != len(first) {
 97: 		t.Fatalf("List returned %d sessions, want %d", len(list), len(first))
 98: 	}
 99: 
100: 	// Mutating the returned slice must not affect later callers.
101: 	list[0].ID = "mutated"
102: 	if got := adapter.List()[0].ID; got != "alpha" {
103: 		t.Fatalf("shared slice was mutated through List copy: got %q", got)
104: 	}
105: }
