107: func TestExecuteReturnsAssemblyError(t *testing.T) {
108: 	// Lock the config directory so identity loading fails and we exercise the
109: 	// error path without starting a server.
110: 	dir := t.TempDir()
111: 	badFile := fmt.Sprintf("%s/.config", dir)
112: 	if err := os.WriteFile(badFile, []byte("x"), 0o600); err == nil {
113: 		t.Setenv("HOME", dir)
114: 	}
115: 
116: 	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
117: 	defer cancel()
118: 	if err := Execute(ctx, &cli.Command{}); err == nil {
119: 		t.Fatal("expected Execute to return an assembly error")
120: 	}
121: }
