123: // TestRefreshDaemonState_ClassifiesBeforePublishing verifies that crash
124: // classification/cleanup runs before the live state snapshot is published.
125: // A crashed session must not appear as live in the same refresh cycle.
126: func TestRefreshDaemonState_ClassifiesBeforePublishing(t *testing.T) {
127: 	var order []string
128: 	reg := &fakeRegistry{sessions: []pty.SessionInfo{{ID: "live"}}}
129: 	adapter := &daemonAdapter{reg: reg}
130: 
131: 	rt := &Runtime{
132: 		adapter:  adapter,
133: 		stateMgr: state.NewManager(),
134: 		detectCrashesFn: func() []pty.LifecycleRecord {
135: 			order = append(order, "classify")
136: 			return []pty.LifecycleRecord{{ID: "crashed"}}
137: 		},
138: 	}
139: 
140: 	rt.refreshDaemonState()
141: 
142: 	if len(order) != 1 || order[0] != "classify" {
143: 		t.Fatalf("expected classify call, got %v", order)
144: 	}
145: 	if reg.listCalls != 1 {
146: 		t.Fatalf("expected adapter.List after classify, listCalls=%d", reg.listCalls)
147: 	}
148: 
149: 	sessions := rt.stateMgr.GetSessions()
150: 	if len(sessions) != 1 || sessions[0].Name != "live" {
151: 		t.Fatalf("expected only live session in state, got %+v", sessions)
152: 	}
