 38: // Runtime assembles the server's long-lived dependencies and exposes explicit
 39: // Start/Ready/Stop lifecycle control. It owns the goroutines that used to be
 40: // launched inline in Execute, so startup order, readiness, and cancellation are
 41: // all visible in one place.
 42: type Runtime struct {
 43: 	ctx    context.Context
 44: 	cancel context.CancelFunc
 45: 
 46: 	ready chan struct{}
 47: 	opts  *server.Options
 48: 
 49: 	// Core stores / registries
 50: 	stateMgr   *state.Manager
 51: 	tracker    *toolevents.Tracker
 52: 	actTracker *activity.Tracker
 53: 	daemonReg  *pty.Registry
 54: 	adapter    *daemonAdapter
 55: 
 56: 	// Tool-event monitors
 57: 	reconciler     *toolevents.Reconciler
 58: 	detector       *toolevents.Detector
 59: 	silenceMonitor *toolevents.SilenceMonitor
 60: 
 61: 	// Identity / peers
 62: 	peerMgr    *peer.Manager
 63: 	supervisor *peer.LinkSupervisor
 64: 	identity   *identity.Identity
 65: 
 66: 	// Optional subsystems
 67: 	wikiSup         *wikilite.Supervisor
 68: 	schedulerRunner *scheduler.Runner
 69: 	pushSender      *webpush.Sender
 70: 	sessionMgr      *auth.SessionManager
 71: 
 72: 	// Helpers
 73: 	fgProvider ForegroundProvider
 74: 	hub        *ws.Hub
 75: 
 76: 	// Dormant v2 store (Task 3). It is opened here but not wired into the
 77: 	// active session/workspace source of truth yet.
 78: 	v2store *state.Store
 79: 
 80: 	// Task 5 v2 catalog and reconciler (shadow mode behind TERMYARD_V2_STATE).
 81: 	v2Catalog    *state.Catalog
 82: 	v2Reconciler *state.Reconciler
 83: 
 84: 	// Task 7 v2 local command service.
 85: 	v2CommandSvc *state.SessionCommandService
 86: 
 87: 	// Task 9 v2 remote create coordinator.
 88: 	v2RemoteCreate *state.RemoteCreateCoordinator
 89: 
 90: 	// Task 10 durable v2 browser state stream.
 91: 	v2StateStream *ws.StateStreamHub
 92: 
 93: 	// Test hook: if set, overrides DetectAndCleanupCrashes in runDaemonRefresh.
 94: 	detectCrashesFn func() []pty.LifecycleRecord
 95: }
 96: 
 97: // newRuntime builds the dependency graph without starting any monitors. All
 98: // construction-time errors are returned synchronously.
 99: func newRuntime(c *cli.Command) (*Runtime, error) {
100: 	rt := &Runtime{
101: 		stateMgr:   state.NewManager(),
102: 		tracker:    toolevents.NewTracker(),
103: 		actTracker: activity.NewTracker(),
104: 		ready:      make(chan struct{}),
105: 		fgProvider: newForegroundProvider(),
106: 	}
107: 	rt.tracker.EnablePersistence()
108: 
109: 	rt.daemonReg = pty.NewRegistry(defaultSessionDir())
110: 	if lcStore, err := pty.NewLifecycleStore(pty.DefaultStateDir()); err != nil {
111: 		logrus.WithError(err).Warn("failed to create lifecycle store -- crash recovery disabled")
112: 	} else {
113: 		rt.daemonReg.SetLifecycleStore(lcStore)
114: 		if crashed := rt.daemonReg.DetectAndCleanupCrashes(); len(crashed) > 0 {
115: 			logrus.WithField("count", len(crashed)).Warn("detected crashed sessions from previous run")
116: 		}
117: 	}
118: 
119: 	rt.adapter = &daemonAdapter{reg: rt.daemonReg}
120: 	rt.stateMgr.SetDaemonRegistry(rt.adapter)
121: 
122: 	rt.reconciler = toolevents.NewReconciler(rt.tracker, rt.lookupPane, 3*time.Second)
123: 	rt.detector = toolevents.NewDetector(rt.tracker, rt.listPanes, 5*time.Second)
124: 	rt.silenceMonitor = toolevents.NewSilenceMonitor(rt.tracker, rt.detector, rt.adapter)
125: 
126: 	attrsStore, err := sessionattrs.NewStore()
127: 	if err != nil {
128: 		logrus.WithError(err).Warn("failed to load session-attrs store, sync disabled")
129: 		attrsStore = nil
130: 	}
131: 
132: 	orderStore, err := sessionorder.NewStore()
133: 	if err != nil {
134: 		logrus.WithError(err).Warn("failed to load session-order store, sync disabled")
135: 		orderStore = nil
136: 	}
137: 
138: 	groupStore, err := groupsync.NewStore()
139: 	if err != nil {
140: 		logrus.WithError(err).Warn("failed to load groups store, sync disabled")
141: 		groupStore = nil
142: 	}
143: 
144: 	prefStore, err := preferences.NewStore()
145: 	if err != nil {
146: 		logrus.WithError(err).Warn("failed to load preferences, using defaults")
147: 		prefStore = nil
148: 	}
149: 
150: 	applyNamerFromPrefs := func(p *preferences.Preferences) {
151: 		cfg := namer.Configure(p.AINaming.Enabled, p.AINaming.Endpoint, p.AINaming.APIKey, p.AINaming.Model)
152: 		n := namer.New(cfg)
153: 		rt.stateMgr.SetNamer(n)
154: 		if n.Enabled() {
155: 			logrus.Info("AI session namer enabled")
156: 		} else {
157: 			logrus.Debug("AI session namer disabled")
158: 		}
159: 	}
160: 	if prefStore != nil {
161: 		applyNamerFromPrefs(prefStore.Get())
162: 	}
163: 
164: 	schedulerStore, err := scheduler.NewStore()
165: 	if err != nil {
166: 		logrus.WithError(err).Warn("failed to load scheduler store, schedules disabled")
167: 		schedulerStore = nil
168: 	}
169: 
170: 	var (
171: 		authEnabled   bool
172: 		passwordStore *auth.PasswordStore
173: 		authLimiter   *auth.Limiter
174: 		notifyToken   string
175: 	)
176: 	if !c.Bool("no-auth") {
177: 		var err error
178: 		passwordStore, err = auth.NewPasswordStore()
179: 		if err != nil {
180: 			return nil, fmt.Errorf("failed to initialize auth: %w", err)
181: 		}
182: 		rt.sessionMgr = auth.NewSessionManager(24 * time.Hour)
183: 		authEnabled = true
184: 		authLimiter = auth.NewLimiter()
185: 
186: 		notifyToken, err = auth.LoadOrCreateNotifyToken()
187: 		if err != nil {
188: 			logrus.WithError(err).Warn("failed to load notify token; TCP notify fallback unavailable")
189: 		}
190: 
191: 		if !passwordStore.HasPassword() {
192: 			logrus.Info("no password set -- open the dashboard in your browser to complete setup")
193: 		}
194: 	}
195: 
196: 	hostname, _ := os.Hostname()
197: 	nodeIdentity, err := identity.LoadOrCreate(hostname)
198: 	if err != nil {
199: 		return nil, fmt.Errorf("failed to load identity: %w", err)
200: 	}
201: 	logrus.WithField("name", nodeIdentity.Name).WithField("fingerprint", nodeIdentity.Fingerprint()).Info("node identity loaded")
202: 	rt.identity = nodeIdentity
203: 
204: 	// v2 state store is dormant by default. Opening it requires an explicit
205: 	// opt-in so integration tests and production processes do not touch real
206: 	// data until Task 3+ wiring is enabled.
207: 	if os.Getenv("TERMYARD_V2_STATE") == "1" {
208: 		if v2Dir, err := config.V2StateDir(); err != nil {
209: 			logrus.WithError(err).Warn("failed to determine v2 state directory")
210: 		} else if rt.v2store, err = state.OpenStore(v2Dir, nodeIdentity.Fingerprint(), state.StoreOptions{}); err != nil {
211: 			logrus.WithError(err).Warn("failed to open v2 state store")
212: 		} else {
213: 			rt.v2Catalog = state.NewCatalog(rt.v2store.Owner(), rt.v2store)
214: 			if err := rt.v2Catalog.Load(); err != nil {
215: 				logrus.WithError(err).Warn("failed to load v2 catalog")
216: 			} else {
217: 				enricher := &v2RuntimeEnricher{adapter: rt.adapter}
218: 				rt.v2Reconciler = state.NewReconciler(rt.v2Catalog, rt.daemonReg, enricher, state.ReconcilerOptions{DisablePendingCreates: true})
219: 				rt.v2CommandSvc = state.NewSessionCommandService(rt.v2Catalog, rt.daemonReg, enricher, state.SessionCommandServiceOptions{Owner: rt.v2Catalog.Owner()})
220: 				rt.v2RemoteCreate = state.NewRemoteCreateCoordinator(rt.v2Catalog, rt.daemonReg, state.RemoteCreateCoordinatorOptions{Owner: rt.v2Catalog.Owner()})
221: 				rt.stateMgr.EnableV2Shadow(rt.v2Catalog, rt.v2Reconciler, enricher)
222: 				rt.v2StateStream = ws.NewStateStreamHub(rt.v2Catalog, nil)
223: 				logrus.WithField("owner", rt.v2Catalog.Owner()).Info("v2 catalog shadow enabled")
224: 			}
225: 		}
226: 	}
227: 
228: 	peerStore, err := identity.NewPeerStore()
229: 	if err != nil {
230: 		return nil, fmt.Errorf("failed to load peer store: %w", err)
231: 	}
232: 
233: 	rt.peerMgr = peer.NewManager(nodeIdentity, peerStore, rt.stateMgr)
234: 	if rt.v2RemoteCreate != nil {
235: 		rt.peerMgr.SetRemoteCreateCoordinator(rt.v2RemoteCreate)
236: 	}
237: 	if rt.v2store != nil {
238: 		rt.peerMgr.SetRemoteStore(rt.v2store)
239: 		if err := rt.peerMgr.LoadRemoteCatalogCache(); err != nil {
240: 			logrus.WithError(err).Warn("failed to load remote catalog cache")
241: 		}
242: 	}
243: 	rt.detector.SetHost(rt.peerMgr.LocalID(), rt.peerMgr.LocalName())
244: 	rt.silenceMonitor.SetHost(rt.peerMgr.LocalID(), rt.peerMgr.LocalName())
245: 	rt.reconciler.SetHost(rt.peerMgr.LocalID(), rt.peerMgr.LocalName())
246: 
247: 	launchSvc := &sessionlaunch.Service{
248: 		DaemonReg: rt.daemonReg,
249: 		StateMgr:  rt.stateMgr,
250: 		Attrs: sessionlaunch.AttrStoreFunc(func(key, scheduleID string) (sessionlaunch.ScheduleAttr, error) {
251: 			if attrsStore == nil {
252: 				return sessionlaunch.ScheduleAttr{}, fmt.Errorf("session attrs store not available")
253: 			}
254: 			attr, err := attrsStore.SetScheduleID(key, scheduleID)
255: 			if err != nil {
256: 				return sessionlaunch.ScheduleAttr{}, err
257: 			}
258: 			return sessionlaunch.ScheduleAttr{
259: 				Background: attr.Background,
260: 				Hidden:     attr.Hidden,
261: 				ScheduleID: attr.ScheduleID,
262: 				UpdatedAt:  attr.UpdatedAt,
263: 			}, nil
264: 		}),
265: 		Identity: nodeIdentity,
266: 		Refresh:  rt.refreshSessionsFunc,
267: 		Remote: func(ctx context.Context, req sessionlaunch.Request) (sessionlaunch.Result, error) {
268: 			peerConn := rt.peerMgr.GetPeerConnection(req.Host)
269: 			if peerConn == nil {
270: 				return sessionlaunch.Result{}, sessionlaunch.ErrPeerUnavailable
271: 			}
272: 			params, _ := json.Marshal(map[string]string{
273: 				"name":            req.Name,
274: 				"path":            req.Path,
275: 				"command":         req.Command,
276: 				"worktree_branch": req.WorktreeBranch,
277: 				"schedule_id":     req.ScheduleID,
278: 			})
279: 			msg, _ := peer.NewMessage(peer.MsgSessionAction, peer.SessionActionPayload{
280: 				Action: "new",
281: 				Params: params,
282: 			})
283: 			if !peerConn.Enqueue(msg) {
284: 				return sessionlaunch.Result{}, sessionlaunch.ErrPeerQueueFull
285: 			}
286: 			return sessionlaunch.Result{Name: req.Name, Host: req.Host}, nil
287: 		},
288: 		Fanout: func(key string, attr sessionlaunch.ScheduleAttr) {
289: 			if rt.peerMgr == nil || nodeIdentity == nil {
290: 				return
291: 			}
292: 			msg, err := peer.NewMessage(peer.MsgSessionAttrsDelta, peer.SessionAttrsDeltaPayload{
293: 				Origin: nodeIdentity.Fingerprint(),
294: 				Key:    key,
295: 				Attr: peer.SessionAttr{
296: 					Background: attr.Background,
297: 					Hidden:     attr.Hidden,
298: 					ScheduleID: attr.ScheduleID,
299: 					UpdatedAt:  attr.UpdatedAt,
300: 				},
301: 			})
302: 			if err != nil {
303: 				return
304: 			}
305: 			for _, pc := range rt.peerMgr.ConnectedPeers() {
306: 				pc.Enqueue(msg)
307: 			}
308: 		},
309: 		Names: func(host string) []string {
310: 			if host != "" && rt.peerMgr != nil && !rt.peerMgr.IsLocal(host) {
311: 				sessions := rt.peerMgr.GetAllSessions()
312: 				names := make([]string, 0, len(sessions))
313: 				for _, s := range sessions {
314: 					if s != nil && s.Host == host {
315: 						names = append(names, s.Name)
316: 					}
317: 				}
318: 				return names
319: 			}
320: 			if rt.stateMgr != nil {
321: 				sessions := rt.stateMgr.GetSessions()
322: 				names := make([]string, 0, len(sessions))
323: 				for _, s := range sessions {
324: 					if s != nil {
325: 						names = append(names, s.Name)
326: 					}
327: 				}
328: 				return names
329: 			}
330: 			return nil
331: 		},
332: 	}
333: 
334: 	streamReg := peer.NewStreamRegistry()
335: 	captureReg := peer.NewCaptureRegistry()
336: 	fileReadReg := peer.NewFileReadRegistry()
337: 
338: 	deps := peer.SessionDeps{
339: 		Manager:      rt.peerMgr,
340: 		LocalMgr:     rt.stateMgr,
341: 		Identity:     nodeIdentity,
342: 		ActTracker:   rt.actTracker,
343: 		ToolTracker:  rt.tracker,
344: 		PeerStore:    peerStore,
345: 		DaemonReg:    rt.adapter,
346: 		Launch:       launchSvc,
347: 		StreamReg:    streamReg,
348: 		CaptureReg:   captureReg,
349: 		FileReadReg:  fileReadReg,
350: 		V2CommandSvc:            rt.v2CommandSvc,
351: 		RemoteCreateCoordinator: rt.v2RemoteCreate,
352: 	}
353: 
354: 	peerHandler := peer.NewHandler(deps, streamReg)
355: 
356: 	rt.supervisor = peer.NewLinkSupervisor(deps)
357: 
358: 	rt.wikiSup = wikilite.NewSupervisor()
359: 
360: 	rt.hub = ws.NewHub(rt.stateMgr, rt.tracker)
361: 	rt.hub.SetActivityTracker(rt.actTracker, rt.peerMgr, rt.peerMgr.LocalID(), false)
362: 
363: 	var (
364: 		pushKeys  *webpush.VAPIDKeys
365: 		pushStore *webpush.Store
366: 	)
367: 	vapidKeys, err := webpush.LoadOrCreateKeys()
368: 	if err != nil {
369: 		logrus.WithError(err).Warn("failed to load VAPID keys, push notifications will be unavailable")
370: 	} else {
371: 		pushKeys = vapidKeys
372: 		pushStore = webpush.NewStore()
373: 		rt.pushSender = webpush.NewSender(pushKeys, pushStore, rt.tracker)
374: 	}
375: 
376: 	rt.opts = &server.Options{
377: 		Port:             int(c.Int("port")),
378: 		SocketPath:       c.String("socket"),
379: 		TLSCert:          c.String("tls-cert"),
380: 		TLSKey:           c.String("tls-key"),
381: 		TLSAuto:          c.Bool("tls"),
382: 		StateMgr:         rt.stateMgr,
383: 		Tracker:          rt.tracker,
384: 		ActivityTracker:  rt.actTracker,
385: 		PushKeys:         pushKeys,
386: 		PushStore:        pushStore,
387: 		PrefStore:        prefStore,
388: 		AttrsStore:       attrsStore,
389: 		OrderStore:       orderStore,
390: 		GroupStore:       groupStore,
391: 		AuthEnabled:      authEnabled,
392: 		DebugPprof:       c.Bool("debug-pprof"),
393: 		PasswordStore:    passwordStore,
394: 		SessionMgr:       rt.sessionMgr,
395: 		AuthLimiter:      authLimiter,
396: 		NotifyToken:      notifyToken,
397: 		Identity:         nodeIdentity,
398: 		PeerStore:        peerStore,
399: 		PeerMgr:          rt.peerMgr,
400: 		PeerHandler:      peerHandler,
401: 		StreamReg:        streamReg,
402: 		CaptureReg:       captureReg,
403: 		FileReadReg:      fileReadReg,
404: 		LinkSupervisor:   rt.supervisor,
405: 		Detector:         rt.detector,
406: 		PortForwardStore: portforward.NewStore(),
407: 		SchedulerStore:   schedulerStore,
408: 		WikiLite:         rt.wikiSup,
409: 		DaemonReg:        rt.daemonReg,
410: 		Launch:           launchSvc,
411: 		CWDResolver:      rt.adapter,
412: 		RefreshSessions:  rt.refreshSessionsFunc,
413: 		OnDaemonOutput: func(paneID string) {
414: 			rt.silenceMonitor.RecordOutput(paneID)
415: 		},
416: 		OnPrefsChanged: applyNamerFromPrefs,
417: 		Hub:            rt.hub,
418: 	}
419: 	launchSvc.Hub = rt.hub
420: 	if rt.v2CommandSvc != nil {
421: 		rt.opts.V2CommandSvc = rt.v2CommandSvc
422: 		rt.opts.V2Catalog = rt.v2Catalog
423: 		rt.opts.V2StateStream = rt.v2StateStream
424: 		launchSvc.V2Commander = rt.v2CommandSvc
425: 	}
426: 
427: 	if schedulerStore != nil {
428: 		rt.schedulerRunner = scheduler.NewRunner(schedulerStore, rt.stateMgr, rt.peerMgr, func(req scheduler.CreateSessionReq) error {
429: 			_, err := launchSvc.Create(rt.ctx, sessionlaunch.Request{
430: 				Name:           req.Name,
431: 				Host:           req.Host,
432: 				Path:           req.Path,
433: 				Command:        req.Command,
434: 				AgentType:      req.AgentType,
435: 				WorktreeBranch: req.WorktreeBranch,
436: 				ScheduleID:     req.ScheduleID,
437: 				CommandID:      req.CommandID,
438: 			})
439: 			if err != nil {
440: 				return err
441: 			}
442: 			return nil
443: 		}, logrus.WithField("component", "scheduler"))
444: 		rt.schedulerRunner.SetCapEnforcer(func(job scheduler.Job) {
445: 			server.EnforceScheduleCap(rt.opts, job.ID, job.MaxConcurrency-1)
446: 		})
447: 		if rt.v2Catalog != nil {
448: 			rt.schedulerRunner.Owner = rt.v2Catalog.Owner().String()
449: 		}
450: 		rt.opts.SchedulerRunner = rt.schedulerRunner
451: 	}
452: 
453: 	return rt, nil
454: }
455: 
456: // Start launches all background monitors. It returns immediately; callers wait
457: // on Ready() before treating the runtime as up.
458: func (rt *Runtime) Start(parent context.Context) error {
459: 	if parent == nil {
460: 		parent = context.Background()
461: 	}
462: 	rt.ctx, rt.cancel = context.WithCancel(parent)
463: 
464: 	// Note: the WebSocket hub is constructed above but intentionally not
465: 	// started here. server.Run owns starting hub.Run after Ready() so that
466: 	// there is a single hub goroutine and a single path to cancel it.
467: 	go rt.peerMgr.Run(rt.ctx)
468: 	rt.supervisor.Start(rt.ctx)
469: 	rt.wikiSup.Start(rt.ctx)
470: 
471: 	if rt.pushSender != nil {
472: 		go rt.pushSender.Run(rt.ctx)
473: 	}
474: 
475: 	if rt.sessionMgr != nil {
476: 		go func() {
477: 			ticker := time.NewTicker(time.Minute)
478: 			defer ticker.Stop()
479: 			for {
480: 				select {
481: 				case <-rt.ctx.Done():
482: 					return
483: 				case <-ticker.C:
484: 					rt.sessionMgr.Cleanup()
485: 				}
486: 			}
487: 		}()
488: 	}
489: 
490: 	go rt.tracker.RunInactivityPromoter(rt.ctx, toolevents.DefaultInactivityTimeout)
491: 	go rt.tracker.RunStuckMonitor(rt.ctx, toolevents.DefaultStuckTimeout, rt.checkPrompt)
492: 
493: 	go rt.reconciler.Run(rt.ctx)
494: 	go rt.detector.Run(rt.ctx)
495: 	go rt.silenceMonitor.Run(rt.ctx)
496: 	go runShellNameWatcher(rt.ctx, rt.stateMgr, rt.adapter, rt.fgProvider)
497: 
498: 	go rt.runDaemonRefresh(rt.ctx)
499: 
500: 	if rt.v2Reconciler != nil {
501: 		go rt.v2Reconciler.Run(rt.ctx)
502: 	}
503: 	if rt.v2CommandSvc != nil {
504: 		go rt.v2CommandSvc.Run(rt.ctx)
505: 	}
506: 	if rt.v2RemoteCreate != nil {
507: 		go rt.v2RemoteCreate.Run(rt.ctx)
508: 	}
509: 
510: 	if rt.schedulerRunner != nil {
511: 		go rt.schedulerRunner.Run(rt.ctx)
512: 	}
513: 
514: 	close(rt.ready)
515: 	return nil
516: }
517: 
518: // Ready returns a channel that is closed once Start has finished launching the
519: // runtime's background goroutines. The HTTP server can safely begin using opts.
520: func (rt *Runtime) Ready() <-chan struct{} {
521: 	return rt.ready
522: }
523: 
524: // Stop cancels the runtime context and stops all monitors started by Start.
525: func (rt *Runtime) Stop() {
526: 	if rt.cancel != nil {
527: 		rt.cancel()
528: 	}
529: 	if rt.v2StateStream != nil {
530: 		rt.v2StateStream.Close()
531: 	}
532: }
