539: // refreshSessionsFunc builds a model.Session snapshot from daemon metadata and
540: // pushes it to the state manager. It is a narrow helper for the launch service
541: // and recovery callbacks.
542: func (rt *Runtime) refreshSessionsFunc() {
543: 	rt.refreshSessions(rt.adapter.List())
