546: func (rt *Runtime) refreshSessions(infos []pty.SessionInfo) {
547: 	sessions := make([]*model.Session, 0, len(infos))
548: 	for _, d := range infos {
549: 		var created time.Time
550: 		if t, err := time.Parse(time.RFC3339, d.Created); err == nil {
551: 			created = t
552: 		}
553: 		sessions = append(sessions, &model.Session{
554: 			Name:        d.ID,
555: 			Created:     created,
556: 			Backend:     "daemon",
557: 			ProjectPath: d.Cwd,
558: 			Windows: []*model.Window{{
559: 				ID:     "daemon-" + d.ID,
560: 				Name:   "shell",
561: 				Active: true,
562: 				Panes: []*model.Pane{{
563: 					ID:          model.SessionRef{Session: d.ID, Window: 0, Pane: 0}.PaneID(),
564: 					Active:      true,
565: 					CurrentPath: d.Cwd,
566: 				}},
567: 			}},
568: 		})
569: 	}
570: 	rt.stateMgr.UpdateSessions(sessions)
571: }
