573: // classifyAndCleanupCrashes is the crash-detection half of the refresh cycle.
574: // It uses the test hook if present, otherwise the real lifecycle store.
575: func (rt *Runtime) classifyAndCleanupCrashes() {
576: 	var crashed []pty.LifecycleRecord
577: 	if rt.detectCrashesFn != nil {
578: 		crashed = rt.detectCrashesFn()
579: 	} else if lcStore := rt.daemonReg.LifecycleStore(); lcStore != nil {
580: 		crashed = rt.daemonReg.DetectAndCleanupCrashes()
581: 	}
582: 	if len(crashed) > 0 {
583: 		logrus.WithField("count", len(crashed)).Warn("detected newly crashed sessions")
584: 	}
585: }
