587: // refreshDaemonState runs one classify-then-publish cycle.  Crash detection
588: // happens first so a crashed session is never broadcast as live in the same
589: // cycle.
590: func (rt *Runtime) refreshDaemonState() {
591: 	rt.classifyAndCleanupCrashes()
592: 	rt.refreshSessions(rt.adapter.refresh())
593: }
