595: // runDaemonRefresh keeps an up-to-date snapshot of daemon sessions and runs
596: // crash detection on the same cadence as state discovery.
597: func (rt *Runtime) runDaemonRefresh(ctx context.Context) {
598: 	ticker := time.NewTicker(2 * time.Second)
599: 	defer ticker.Stop()
600: 
601: 	// One immediate refresh so tests see state without waiting for the tick.
602: 	// Classify first so the initial snapshot cannot publish crash state as live.
603: 	rt.refreshDaemonState()
604: 
605: 	for {
606: 		select {
607: 		case <-ctx.Done():
608: 			return
609: 		case <-ticker.C:
610: 			rt.refreshDaemonState()
611: 		}
612: 	}
613: }
