615: // listPanes returns the current daemon panes for the agent detector, using the
616: // shared snapshot rather than re-scanning the registry.
617: func (rt *Runtime) listPanes() []toolevents.PaneInfo {
618: 	infos := rt.adapter.List()
619: 	out := make([]toolevents.PaneInfo, 0, len(infos))
620: 	for _, d := range infos {
621: 		pid := d.ShellPid
622: 		if pid == 0 {
623: 			pid = d.Pid
624: 		}
625: 		out = append(out, toolevents.PaneInfo{
626: 			PaneID:  model.SessionRef{Session: d.ID, Window: 0, Pane: 0}.PaneID(),
627: 			Session: d.ID,
628: 			Window:  0,
629: 			PID:     pid,
630: 		})
631: 	}
632: 	return out
633: }
