635: // lookupPane resolves a pane identifier to live pane state for the reconciler.
636: func (rt *Runtime) lookupPane(paneID string) toolevents.PaneState {
637: 	ref, err := model.ParseSessionRef(paneID)
638: 	if err != nil {
639: 		return toolevents.PaneState{Exists: false}
640: 	}
641: 	for _, d := range rt.adapter.List() {
642: 		if d.ID == ref.Session {
643: 			pid := d.ShellPid
644: 			if pid == 0 {
645: 				pid = d.Pid
646: 			}
647: 			return toolevents.PaneState{Exists: true, CurrentCommand: d.Shell, PID: pid}
648: 		}
649: 	}
650: 	return toolevents.PaneState{Exists: false}
651: }
