653: // checkPrompt guards the stuck monitor: it reports whether a pane is sitting at
654: // an input prompt so we do not flag it stuck.
655: func (rt *Runtime) checkPrompt(paneID string) (bool, bool) {
656: 	ref, err := model.ParseSessionRef(paneID)
657: 	if err != nil {
658: 		return false, false
659: 	}
660: 	if text, err := rt.adapter.Capture(ref.Session); err == nil {
661: 		return toolevents.DetectPrompt(text).IsPrompt, true
662: 	}
663: 	return false, false
664: }
