666: // registryView is the subset of pty.Registry used by the adapter, kept narrow
667: // so tests can substitute a fake without implementing the full API.
668: type registryView interface {
669: 	Create(name, shell, cwd string, cols, rows uint16) error
670: 	Kill(name string) error
671: 	Capture(name string) (string, error)
672: 	CaptureTail(name string, maxBytes int) (string, error)
673: 	SocketPath(name string) string
674: 	List() []pty.SessionInfo
675: 	IsSessionDead(name string) bool
676: 	CrashedSessions() []pty.LifecycleRecord
677: 	GenerationFor(name string) string
678: }
679: 
680: // daemonAdapter wraps a registryView and presents one immutable snapshot to
681: // both the state and peer packages. It collapses the previous peerDaemonAdapter
682: // and daemonRegAdapter into a single conversion.
683: type daemonAdapter struct {
684: 	reg  registryView
685: 	mu   sync.RWMutex
686: 	snap []pty.SessionInfo
687: }
688: 
689: // refresh captures a new snapshot from the registry and stores it locally.
690: func (a *daemonAdapter) refresh() []pty.SessionInfo {
691: 	infos := a.reg.List()
692: 	a.mu.Lock()
693: 	a.snap = infos
694: 	a.mu.Unlock()
695: 	return infos
696: }
697: 
698: // List returns the last refreshed snapshot. Consumers receive a shallow copy so
699: // one caller cannot mutate the shared slice.
700: func (a *daemonAdapter) List() []pty.SessionInfo {
701: 	a.mu.RLock()
702: 	defer a.mu.RUnlock()
703: 	out := make([]pty.SessionInfo, len(a.snap))
704: 	copy(out, a.snap)
705: 	return out
706: }
