848: // v2RuntimeEnricher supplies live runtime fields for v2 catalog records
849: // without mutating persisted state.
850: type v2RuntimeEnricher struct {
851: 	adapter *daemonAdapter
852: }
853: 
854: func (e *v2RuntimeEnricher) Enrich(ref state.SessionRef, rec state.LocalSessionRecord) state.SessionRuntime {
855: 	var rt state.SessionRuntime
856: 	for _, d := range e.adapter.List() {
857: 		if d.ID != string(ref.Session) {
858: 			continue
859: 		}
860: 		rt.DaemonPID = d.Pid
861: 		rt.ShellPID = d.ShellPid
862: 		rt.CurrentCommand = d.Shell
863: 		rt.CurrentPath = d.Cwd
864: 
865: 		pid := d.ShellPid
866: 		if pid == 0 {
867: 			pid = d.Pid
868: 		}
869: 		if pid > 0 {
870: 			if liveCwd, err := os.Readlink(fmt.Sprintf("/proc/%d/cwd", pid)); err == nil && liveCwd != "" {
871: 				rt.CurrentPath = liveCwd
872: 			}
873: 		}
874: 		if content, err := e.adapter.CaptureTail(d.ID, 64*1024); err == nil {
875: 			rt.PromptPreview = model.ExtractPromptPreview(content)
876: 		}
877: 		rt.LastActivity = time.Now()
878: 		break
879: 	}
880: 	return rt
