 24: // executeSessionDaemon is the action for the hidden "session-daemon" command.
 25: func executeSessionDaemon(ctx context.Context, c *cli.Command) error {
 26: 	cfg := pty.DaemonConfig{
 27: 		ID:          c.String("id"),
 28: 		Shell:       c.String("shell"),
 29: 		Cwd:         c.String("cwd"),
 30: 		SocketDir:   c.String("socket-dir"),
 31: 		StateDir:    c.String("state-dir"),
 32: 		SystemdUnit: c.String("systemd-unit"),
 33: 		BufferSize:  int(c.Int("buffer-size")),
 34: 		Owner:       c.String("owner"),
 35: 		SessionID:   c.String("session-id"),
 36: 		Generation:  c.String("generation"),
 37: 		CommandID:   c.String("command-id"),
 38: 	}
 39: 
 40: 	// Parse terminal size.
 41: 	cols, _ := strconv.ParseUint(c.String("cols"), 10, 16)
 42: 	rows, _ := strconv.ParseUint(c.String("rows"), 10, 16)
 43: 	if cols > 0 {
 44: 		cfg.Cols = uint16(cols)
 45: 	}
 46: 	if rows > 0 {
 47: 		cfg.Rows = uint16(rows)
 48: 	}
 49: 
 50: 	return pty.RunDaemon(cfg)
 51: }
