 53: // executeSessionCreate implements "termyard session create".
 54: func executeSessionCreate(ctx context.Context, c *cli.Command) error {
 55: 	name := c.String("name")
 56: 	if name == "" {
 57: 		return fmt.Errorf("--name is required")
 58: 	}
 59: 
 60: 	shell := c.String("shell")
 61: 	cwd := c.String("cwd")
 62: 
 63: 	cols, _ := strconv.ParseUint(c.String("cols"), 10, 16)
 64: 	rows, _ := strconv.ParseUint(c.String("rows"), 10, 16)
 65: 
 66: 	// Derive socket dir if not set.
 67: 	socketDir := c.String("socket-dir")
 68: 	if socketDir == "" {
 69: 		socketDir = defaultSessionDir()
 70: 	}
 71: 
 72: 	reg := pty.NewRegistry(socketDir)
 73: 	if err := reg.Create(name, shell, cwd, uint16(cols), uint16(rows)); err != nil {
 74: 		return err
 75: 	}
 76: 
 77: 	fmt.Printf("Session %q created.\n", name)
 78: 	return nil
 79: }
