 81: // executeSessionList implements "termyard session list".
 82: func executeSessionList(ctx context.Context, c *cli.Command) error {
 83: 	socketDir := c.String("socket-dir")
 84: 	if socketDir == "" {
 85: 		socketDir = defaultSessionDir()
 86: 	}
 87: 
 88: 	reg := pty.NewRegistry(socketDir)
 89: 	sessions := reg.List()
 90: 
 91: 	if c.Bool("json") {
 92: 		enc := json.NewEncoder(os.Stdout)
 93: 		enc.SetIndent("", "  ")
 94: 		return enc.Encode(sessions)
 95: 	}
 96: 
 97: 	if len(sessions) == 0 {
 98: 		fmt.Println("No active sessions.")
 99: 		return nil
100: 	}
101: 
102: 	fmt.Printf("%-32s %-8s %-20s %s\n", "ID", "PID", "CREATED", "SHELL")
103: 	fmt.Println("----------------------------------------------------------------------")
104: 	for _, s := range sessions {
105: 		fmt.Printf("%-32s %-8d %-20s %s\n", s.ID, s.Pid, s.Created, s.Shell)
106: 	}
107: 	return nil
108: }
