134: func executeSessionCapture(ctx context.Context, c *cli.Command) error {
135: 	if c.NArg() < 1 {
136: 		return fmt.Errorf("session name is required")
137: 	}
138: 	name := c.Args().First()
139: 
140: 	socketDir := c.String("socket-dir")
141: 	if socketDir == "" {
142: 		socketDir = defaultSessionDir()
143: 	}
144: 
145: 	reg := pty.NewRegistry(socketDir)
146: 	text, err := reg.Capture(name)
147: 	if err != nil {
148: 		return err
149: 	}
150: 
151: 	lines := int(c.Int("lines"))
152: 	if lines > 0 {
153: 		parts := splitLastLines(text, lines)
154: 		text = parts
155: 	}
156: 
157: 	fmt.Print(text)
158: 	return nil
159: }
160: 
161: // splitLastLines returns the last n lines of text.
162: func splitLastLines(text string, n int) string {
163: 	var lines []string
164: 	start := 0
165: 	for i, ch := range text {
166: 		if ch == '\n' {
167: 			lines = append(lines, text[start:i+1])
168: 			start = i + 1
169: 		}
170: 	}
171: 	if start < len(text) {
172: 		lines = append(lines, text[start:])
173: 	}
174: 	if len(lines) <= n {
175: 		return text
176: 	}
177: 	result := ""
178: 	for _, l := range lines[len(lines)-n:] {
179: 		result += l
180: 	}
181: 	return result
182: }
