 9: // Dir returns the termyard config directory (~/.config/termyard).
10: // It does not create the directory; callers create it with the perm
11: // they require.
12: func Dir() (string, error) {
13: 	home, err := os.UserHomeDir()
14: 	if err != nil {
15: 		return "", err
16: 	}
17: 	return filepath.Join(home, ".config", "termyard"), nil
18: }
19: 
20: // DataDir returns the termyard data directory. The path respects
21: // $XDG_DATA_HOME when set; otherwise it falls back to ~/.local/share/termyard.
22: func DataDir() (string, error) {
23: 	if dir := os.Getenv("XDG_DATA_HOME"); dir != "" {
24: 		return filepath.Join(dir, "termyard"), nil
25: 	}
26: 	home, err := os.UserHomeDir()
27: 	if err != nil {
28: 		return "", err
29: 	}
30: 	return filepath.Join(home, ".local", "share", "termyard"), nil
31: }
32: 
33: // V2StateDir returns the directory for the v2 atomic state store. The v2 store
34: // is dormant by default; callers open it only when they are ready to use it.
35: func V2StateDir() (string, error) {
36: 	dataDir, err := DataDir()
37: 	if err != nil {
38: 		return "", err
39: 	}
40: 	return filepath.Join(dataDir, "v2"), nil
41: }
42: 
43: // WriteJSON marshals v with indentation and writes it to path with perm.
44: // It preserves existing non-atomic MarshalIndent + os.WriteFile behavior.
45: func WriteJSON(path string, v any, perm os.FileMode) error {
46: 	data, err := json.MarshalIndent(v, "", "  ")
47: 	if err != nil {
48: 		return err
49: 	}
50: 	return os.WriteFile(path, data, perm)
