 474: }
 475: 
 476: // Identity returns this node's identity (for protocol/auth).
 477: func (m *Manager) Identity() *identity.Identity {
 478: 	return m.identity
 479: }
 480: 
 481: // PeerStore returns this manager's peer store.
 482: func (m *Manager) PeerStore() *identity.PeerStore {
 483: 	return m.peerStore
