 491: // SetRemoteStore wires the app-state store used to persist remote catalog
 492: // caches. It is safe to call before any peer connects.
 493: func (m *Manager) SetRemoteStore(store *state.Store) {
 494: 	m.catalogMu.Lock()
 495: 	defer m.catalogMu.Unlock()
 496: 	m.remoteStore = store
 497: }
 498: 
 499: // RegisterPeer registers a newly connected peer
 500: func (m *Manager) RegisterPeer(id, name, publicKey string, conn *PeerConnection) {
 501: 	m.RegisterPeerWithAddress(id, name, publicKey, "", conn)
 502: }
 503: 
 504: // RegisterPeerWithAddress registers a newly connected peer with its address.
 505: func (m *Manager) RegisterPeerWithAddress(id, name, publicKey, address string, conn *PeerConnection) {
 506: 	m.mu.Lock()
 507: 	m.hosts[id] = &HostState{
 508: 		ID:        id,
 509: 		Name:      name,
 510: 		PublicKey: publicKey,
 511: 		Address:   address,
 512: 		Connected: true,
 513: 		LastSeen:  time.Now(),
 514: 		Conn:      conn,
 515: 	}
 516: 	m.mu.Unlock()
 517: 
 518: 	// A new connection is a new snapshot-stream generation: reset the
 519: 	// revision baseline so a restarted peer's re-emitted snapshots are
 520: 	// accepted even though their revisions are lower than the last ones seen
 521: 	// on the previous connection.
 522: 	m.resetRemoteRevisions(id)
 523: 
 524: 	m.broadcast(state.StateEvent{
 525: 		Type:     "peer-connected",
 526: 		Host:     id,
 527: 		HostName: name,
 528: 	})
 529: 
 530: 	logrus.WithFields(logrus.Fields{
 531: 		"peer": name,
 532: 		"id":   id,
 533: 	}).Info("peer connected")
 534: }
 535: 
 536: // TryRegisterPeer atomically registers a peer iff no live connection exists
 537: // for the same fingerprint. Returns true on success. Used by session.runSession
 538: // to close the simultaneous-initiate race window.
 539: func (m *Manager) TryRegisterPeer(id, name, publicKey, address string, conn *PeerConnection) bool {
 540: 	m.mu.Lock()
 541: 	if h, ok := m.hosts[id]; ok && h.Conn != nil {
 542: 		m.mu.Unlock()
 543: 		return false
 544: 	}
 545: 	m.hosts[id] = &HostState{
 546: 		ID:        id,
 547: 		Name:      name,
 548: 		PublicKey: publicKey,
 549: 		Address:   address,
 550: 		Connected: true,
 551: 		LastSeen:  time.Now(),
 552: 		Conn:      conn,
 553: 	}
 554: 	m.mu.Unlock()
 555: 
 556: 	m.resetRemoteRevisions(id)
 557: 
 558: 	m.broadcast(state.StateEvent{
 559: 		Type:     "peer-connected",
 560: 		Host:     id,
 561: 		HostName: name,
 562: 	})
 563: 
 564: 	logrus.WithFields(logrus.Fields{
 565: 		"peer": name,
 566: 		"id":   id,
 567: 	}).Info("peer connected")
 568: 	return true
 569: }
 570: 
 571: // UnregisterPeer marks the peer offline unconditionally. Prefer
 572: // UnregisterPeerConn to prevent a stale connection from unregistering a
 573: // replacement.
 574: func (m *Manager) UnregisterPeer(id string) {
 575: 	m.UnregisterPeerConn(id, nil)
 576: }
 577: 
 578: // UnregisterPeerConn marks the peer offline only if conn is the currently
 579: // registered connection. A nil conn acts as an unconditional unregister.
 580: func (m *Manager) UnregisterPeerConn(id string, conn *PeerConnection) {
 581: 	m.mu.Lock()
 582: 	h, ok := m.hosts[id]
 583: 	if ok {
 584: 		if conn != nil && h.Conn != conn {
 585: 			m.mu.Unlock()
 586: 			logrus.WithFields(logrus.Fields{
 587: 				"peer": h.Name,
 588: 				"id":   id,
 589: 			}).Debug("stale connection ignored during unregister")
 590: 			return
 591: 		}
 592: 		h.Connected = false
 593: 		h.Conn = nil
 594: 		h.LastSeen = time.Now()
 595: 	}
 596: 	m.mu.Unlock()
 597: 
 598: 	if ok {
 599: 		m.broadcast(state.StateEvent{
 600: 			Type:     "peer-disconnected",
 601: 			Host:     id,
 602: 			HostName: h.Name,
 603: 		})
 604: 
 605: 		logrus.WithFields(logrus.Fields{
 606: 			"peer": h.Name,
 607: 			"id":   id,
 608: 		}).Info("peer disconnected")
 609: 	}
 610: }
 611: 
 612: // RemoveHost fully removes a host from the aggregated state (used on forget,
 613: // where we must not keep the peer's sessions lingering until prune).
 614: func (m *Manager) RemoveHost(id string) {
 615: 	if id == m.localID {
 616: 		return
 617: 	}
 618: 	m.mu.Lock()
 619: 	h, ok := m.hosts[id]
 620: 	if ok {
 621: 		delete(m.hosts, id)
 622: 	}
 623: 	m.mu.Unlock()
 624: 
 625: 	if ok {
 626: 		m.forgetRemoteCatalogsForPeer(id)
 627: 		m.broadcast(state.StateEvent{
 628: 			Type:     "peer-disconnected",
 629: 			Host:     id,
 630: 			HostName: h.Name,
 631: 		})
 632: 		logrus.WithFields(logrus.Fields{
 633: 			"peer": h.Name,
 634: 			"id":   id,
 635: 		}).Info("host removed")
 636: 	}
 637: }
 638: 
 639: // bindRemoteOwner enforces the ownership binding: one owner per peer and one
 640: // peer per owner. The first snapshot a peer publishes establishes its sole
 641: // owner; a later snapshot from the same peer under a different owner, or a
 642: // second peer claiming an already-bound owner, is a spoof and is dropped.
 643: // Caller must hold catalogMu. The v2 catalog Owner is a random base32 id, NOT
 644: // the peer fingerprint, so an explicit cross-peer binding map is the sound
 645: // integrity mechanism here.
 646: func (m *Manager) bindRemoteOwner(peerID string, owner state.OwnerID) bool {
 647: 	if peerID == "" || owner == "" {
 648: 		return false
 649: 	}
 650: 	if p, ok := m.ownerPeer[owner]; ok && p != peerID {
 651: 		logrus.WithFields(logrus.Fields{"peer": peerID, "owner": string(owner), "boundPeer": p}).Warn("dropping v2 snapshot: owner already bound to another peer")
 652: 		return false
 653: 	}
 654: 	if o, ok := m.peerOwner[peerID]; ok && o != owner {
 655: 		logrus.WithFields(logrus.Fields{"peer": peerID, "owner": string(owner), "boundOwner": string(o)}).Warn("dropping v2 snapshot: peer switched owners")
 656: 		return false
 657: 	}
 658: 	m.peerOwner[peerID] = owner
 659: 	m.ownerPeer[owner] = peerID
 660: 	return true
 661: }
 662: 
 663: // UpdateRemoteCatalog replaces the cached catalog for the snapshot's owner.
 664: // The previous cache (if any) is overwritten, not merged. The owner must be
 665: // the peer's bound owner and the revision must be increasing within the
 666: // peer's current connection (stale/delayed snapshots are rejected). If a
 667: // remote store is wired, the complete set of accepted remote catalogs is
 668: // persisted.
 669: func (m *Manager) UpdateRemoteCatalog(peerID string, snap state.OwnerCatalogSnapshot) {
 670: 	m.catalogMu.Lock()
 671: 	if !m.bindRemoteOwner(peerID, snap.Owner) {
 672: 		m.catalogMu.Unlock()
 673: 		return
 674: 	}
 675: 	rs := m.remoteRevs[peerID]
 676: 	if rs == nil {
 677: 		rs = &remoteRevisionState{catalog: -1}
 678: 		m.remoteRevs[peerID] = rs
 679: 	}
 680: 	if rs.catalog >= 0 && snap.Revision <= rs.catalog {
 681: 		m.catalogMu.Unlock()
 682: 		logrus.WithFields(logrus.Fields{"peer": peerID, "rev": snap.Revision, "last": rs.catalog}).Debug("dropping stale v2 catalog snapshot")
 683: 		return
 684: 	}
 685: 	rs.catalog = snap.Revision
 686: 	m.remoteCatalogs[snap.Owner] = remoteCatalogCache{
 687: 		Owner:      snap.Owner,
 688: 		PeerID:     peerID,
 689: 		Snapshot:   snap,
 690: 		ReceivedAt: time.Now(),
 691: 		CatalogRev: snap.Revision,
 692: 	}
 693: 	m.catalogMu.Unlock()
 694: 	m.persistRemoteCatalogs()
 695: }
 696: 
 697: // UpdateRemoteWorkspace replaces the cached workspace for owner. The owner
 698: // must be the peer's bound owner, and the workspace revision must be
 699: // increasing within the current connection (keyed per layout id).
 700: func (m *Manager) UpdateRemoteWorkspace(peerID string, rec state.WorkspaceRecord) {
 701: 	m.catalogMu.Lock()
 702: 	if !m.bindRemoteOwner(peerID, rec.Owner) {
 703: 		m.catalogMu.Unlock()
 704: 		return
 705: 	}
 706: 	rs := m.remoteRevs[peerID]
 707: 	if rs == nil {
 708: 		rs = &remoteRevisionState{catalog: -1}
 709: 		m.remoteRevs[peerID] = rs
 710: 	}
 711: 	if rs.workspace == nil {
 712: 		rs.workspace = make(map[state.LayoutID]int64)
 713: 	}
 714: 	if last, seen := rs.workspace[rec.ID]; seen && rec.Revision <= last {
 715: 		m.catalogMu.Unlock()
 716: 		logrus.WithFields(logrus.Fields{"peer": peerID, "layout": string(rec.ID), "rev": rec.Revision, "last": last}).Debug("dropping stale v2 workspace snapshot")
 717: 		return
 718: 	}
 719: 	rs.workspace[rec.ID] = rec.Revision
 720: 	cache := m.remoteCatalogs[rec.Owner]
 721: 	cache.Owner = rec.Owner
 722: 	cache.PeerID = peerID
 723: 	cache.Workspace = &rec
 724: 	cache.ReceivedAt = time.Now()
 725: 	cache.WorkspaceRev = rec.Revision
 726: 	m.remoteCatalogs[rec.Owner] = cache
 727: 	m.catalogMu.Unlock()
 728: 	m.persistRemoteCatalogs()
 729: }
 730: 
 731: // RemoteCatalogSnapshot returns the latest cached catalog for owner, if any.
 732: func (m *Manager) RemoteCatalogSnapshot(owner state.OwnerID) (state.OwnerCatalogSnapshot, bool) {
 733: 	m.catalogMu.RLock()
 734: 	defer m.catalogMu.RUnlock()
 735: 	c, ok := m.remoteCatalogs[owner]
 736: 	if !ok {
 737: 		return state.OwnerCatalogSnapshot{}, false
 738: 	}
 739: 	return cloneOwnerCatalogSnapshot(c.Snapshot), true
 740: }
 741: 
 742: // RemoteWorkspaceSnapshot returns the latest cached workspace for owner, if any.
 743: func (m *Manager) RemoteWorkspaceSnapshot(owner state.OwnerID) (*state.WorkspaceRecord, bool) {
 744: 	m.catalogMu.RLock()
 745: 	defer m.catalogMu.RUnlock()
 746: 	c, ok := m.remoteCatalogs[owner]
 747: 	if !ok || c.Workspace == nil {
 748: 		return nil, false
 749: 	}
 750: 	w := *c.Workspace
 751: 	return &w, true
 752: }
 753: 
 754: // ForgetRemoteCatalog removes the cached catalog and workspace for owner.
 755: func (m *Manager) ForgetRemoteCatalog(owner state.OwnerID) {
 756: 	m.catalogMu.Lock()
 757: 	delete(m.remoteCatalogs, owner)
 758: 	m.catalogMu.Unlock()
 759: 	m.persistRemoteCatalogs()
 760: }
 761: 
 762: // SetRemoteCreateCoordinator wires the v2 owner-side remote create coordinator.
 763: func (m *Manager) SetRemoteCreateCoordinator(c *state.RemoteCreateCoordinator) {
 764: 	m.v2RemoteCreate = c
 765: }
 766: 
 767: // WorkspaceAuthority returns the owning owner for layout and, when the owner is
 768: // remote, the peer ID that last advertised it. The empty peerID means this node
 769: // is the authority.
 770: func (m *Manager) WorkspaceAuthority(layout state.LayoutID) (state.OwnerID, string, error) {
 771: 	if cat := m.localMgr.V2Catalog(); cat != nil {
 772: 		if rec, ok := cat.Layout(layout); ok {
 773: 			return rec.Owner, "", nil
 774: 		}
 775: 	}
 776: 	m.catalogMu.RLock()
 777: 	defer m.catalogMu.RUnlock()
 778: 	for owner, cache := range m.remoteCatalogs {
 779: 		for _, l := range cache.Snapshot.Layouts {
 780: 			if l.ID == layout {
 781: 				return owner, cache.PeerID, nil
 782: 			}
 783: 		}
 784: 		if cache.Workspace != nil && cache.Workspace.ID == layout {
 785: 			return owner, cache.PeerID, nil
 786: 		}
 787: 	}
 788: 	return "", "", state.StateError{Code: state.ErrUnknownLayout, Field: "layout", Detail: fmt.Sprintf("workspace authority not found for layout %q", layout)}
 789: }
 790: 
 791: // IsWorkspaceOwnerOnline reports whether owner is reachable for v2 commands.
 792: func (m *Manager) IsWorkspaceOwnerOnline(owner state.OwnerID) bool {
 793: 	if owner == state.OwnerID(m.localID) {
 794: 		return true
 795: 	}
 796: 	peerID := m.peerIDForOwner(owner)
 797: 	if peerID == "" {
 798: 		return false
 799: 	}
 800: 	pc := m.GetPeerConnection(peerID)
 801: 	return pc != nil && pc.HasV2()
 802: }
 803: 
 804: // ProxyWorkspaceCommand routes a workspace command to the layout's owner.
 805: // Local authority applies directly; remote authority is sent over the v2
 806: // command RPC. Legacy or offline owners return typed errors.
 807: func (m *Manager) ProxyWorkspaceCommand(ctx context.Context, cmd state.WorkspaceCommand) error {
 808: 	owner, peerID, err := m.WorkspaceAuthority(cmd.Layout)
 809: 	if err != nil {
 810: 		return err
 811: 	}
 812: 	if owner == state.OwnerID(m.localID) {
 813: 		cat := m.localMgr.V2Catalog()
 814: 		if cat == nil {
 815: 			return fmt.Errorf("v2 catalog not enabled")
 816: 		}
 817: 		return cat.ApplyWorkspaceCommand(cmd)
 818: 	}
 819: 	pc := m.GetPeerConnection(peerID)
 820: 	if pc == nil {
 821: 		return state.StateError{Code: state.ErrWorkspaceOwnerOffline, Field: "owner", Detail: fmt.Sprintf("workspace owner %q is offline", owner)}
 822: 	}
 823: 	if !pc.HasV2() {
 824: 		return state.StateError{Code: state.ErrLegacyPeerUnsupported, Field: "peer_id", Detail: fmt.Sprintf("peer %q does not support v2 workspace commands", peerID)}
 825: 	}
 826: 	return m.SendWorkspaceCommand(ctx, peerID, cmd)
 827: }
 828: 
 829: // RequestRemoteCreate routes a remote create to the workspace owner. The local
 830: // owner path runs directly in the coordinator; remote owners are reached over
 831: // the v2 remote-create RPC.
 832: func (m *Manager) RequestRemoteCreate(ctx context.Context, owner state.OwnerID, req state.RemoteCreateRequest) (state.RemoteCreateResult, error) {
 833: 	if owner == "" || owner == state.OwnerID(m.localID) {
 834: 		if m.v2RemoteCreate == nil {
 835: 			return state.RemoteCreateResult{}, fmt.Errorf("remote create coordinator not available")
 836: 		}
 837: 		return m.v2RemoteCreate.ExecuteRemoteCreate(ctx, req)
 838: 	}
 839: 	peerID := m.peerIDForOwner(owner)
 840: 	if peerID == "" {
 841: 		return state.RemoteCreateResult{}, state.StateError{Code: state.ErrWorkspaceOwnerOffline, Field: "owner", Detail: fmt.Sprintf("workspace owner %q is offline", owner)}
 842: 	}
 843: 	pc := m.GetPeerConnection(peerID)
 844: 	if pc == nil {
 845: 		return state.RemoteCreateResult{}, state.StateError{Code: state.ErrWorkspaceOwnerOffline, Field: "owner", Detail: fmt.Sprintf("workspace owner %q is offline", owner)}
 846: 	}
 847: 	if !pc.HasV2() {
 848: 		return state.RemoteCreateResult{}, state.StateError{Code: state.ErrLegacyPeerUnsupported, Field: "peer_id", Detail: fmt.Sprintf("peer %q does not support v2 remote creates", peerID)}
 849: 	}
 850: 	return m.SendRemoteCreate(ctx, peerID, req)
 851: }
 852: 
 853: func (m *Manager) peerIDForOwner(owner state.OwnerID) string {
 854: 	m.catalogMu.RLock()
 855: 	defer m.catalogMu.RUnlock()
 856: 	if c, ok := m.remoteCatalogs[owner]; ok {
 857: 		return c.PeerID
 858: 	}
 859: 	return ""
 860: }
 861: 
 862: // LoadRemoteCatalogCache loads persisted remote catalogs into memory. It is
 863: // idempotent and ignores missing sidecar files.
 864: func (m *Manager) LoadRemoteCatalogCache() error {
 865: 	if m.remoteStore == nil {
 866: 		return nil
 867: 	}
 868: 	catalogs, err := m.remoteStore.LoadRemoteCatalogs()
 869: 	if err != nil {
 870: 		return err
 871: 	}
 872: 	m.catalogMu.Lock()
 873: 	defer m.catalogMu.Unlock()
 874: 	for _, c := range catalogs {
 875: 		m.remoteCatalogs[c.Owner] = remoteCatalogCache{
 876: 			Owner:      c.Owner,
 877: 			Snapshot:   c,
 878: 			ReceivedAt: time.Now(),
 879: 			CatalogRev: c.Revision,
 880: 		}
 881: 	}
 882: 	return nil
 883: }
 884: 
 885: func (m *Manager) persistRemoteCatalogs() {
 886: 	m.catalogMu.RLock()
 887: 	store := m.remoteStore
 888: 	if store == nil {
 889: 		m.catalogMu.RUnlock()
 890: 		return
 891: 	}
 892: 	catalogs := make([]state.OwnerCatalogSnapshot, 0, len(m.remoteCatalogs))
 893: 	for _, c := range m.remoteCatalogs {
 894: 		catalogs = append(catalogs, cloneOwnerCatalogSnapshot(c.Snapshot))
 895: 	}
 896: 	m.catalogMu.RUnlock()
 897: 
 898: 	sort.Slice(catalogs, func(i, j int) bool { return catalogs[i].Owner < catalogs[j].Owner })
 899: 	if err := store.SaveRemoteCatalogs(catalogs); err != nil {
 900: 		logrus.WithError(err).Warn("failed to persist remote catalog caches")
 901: 	}
 902: }
 903: 
 904: func (m *Manager) forgetRemoteCatalogsForPeer(peerID string) {
 905: 	m.catalogMu.Lock()
 906: 	for owner, c := range m.remoteCatalogs {
 907: 		if c.PeerID == peerID {
 908: 			delete(m.remoteCatalogs, owner)
 909: 		}
 910: 	}
 911: 	// Clear the ownership binding so a subsequently re-added peer starts
 912: 	// clean instead of being latched to a stale owner.
 913: 	if owner, ok := m.peerOwner[peerID]; ok {
 914: 		delete(m.ownerPeer, owner)
 915: 		delete(m.peerOwner, peerID)
 916: 	}
 917: 	m.catalogMu.Unlock()
 918: 	// Persist the removal so a forgotten peer does not reappear after a
 919: 	// restart (the sidecar is written from the in-memory map).
 920: 	m.persistRemoteCatalogs()
 921: }
 922: 
 923: // resetRemoteRevisions clears the per-connection revision baseline for a
 924: // peer. Called whenever a new connection registers.
 925: func (m *Manager) resetRemoteRevisions(peerID string) {
 926: 	m.catalogMu.Lock()
 927: 	delete(m.remoteRevs, peerID)
 928: 	m.catalogMu.Unlock()
 929: }
 930: 
 931: func cloneOwnerCatalogSnapshot(s state.OwnerCatalogSnapshot) state.OwnerCatalogSnapshot {
 932: 	sessions := make([]state.LocalSessionRecord, len(s.Sessions))
 933: 	copy(sessions, s.Sessions)
 934: 	layouts := make([]state.LayoutRecord, len(s.Layouts))
 935: 	copy(layouts, s.Layouts)
 936: 	return state.OwnerCatalogSnapshot{
 937: 		Owner:    s.Owner,
 938: 		Revision: s.Revision,
 939: 		Sessions: sessions,
 940: 		Layouts:  layouts,
 941: 	}
 942: }
 943: 
 944: // UpdatePeerSessions updates a peer's session list
 945: func (m *Manager) UpdatePeerSessions(id string, sessions []*model.Session) {
 946: 	m.mu.Lock()
 947: 	h, ok := m.hosts[id]
 948: 	if ok {
 949: 		h.Sessions = sessions
 950: 		h.LastSeen = time.Now()
 951: 	}
 952: 	m.mu.Unlock()
 953: 
 954: 	if ok {
 955: 		m.broadcast(state.StateEvent{
 956: 			Type:     "sessions-changed",
 957: 			Host:     id,
 958: 			HostName: h.Name,
 959: 		})
 960: 	}
 961: }
 962: 
 963: // UpdatePeerVersion updates a peer's reported version
 964: func (m *Manager) UpdatePeerVersion(id, version string) {
 965: 	m.mu.Lock()
 966: 	defer m.mu.Unlock()
 967: 	if h, ok := m.hosts[id]; ok {
 968: 		h.Version = version
 969: 	}
 970: }
 971: 
 972: // UpdatePeerActivity updates a peer's activity snapshots
 973: func (m *Manager) UpdatePeerActivity(id string, snapshots []*activity.Snapshot) {
 974: 	m.mu.Lock()
 975: 	if h, ok := m.hosts[id]; ok {
 976: 		h.Activity = snapshots
 977: 		h.LastSeen = time.Now()
 978: 	}
 979: 	m.mu.Unlock()
 980: }
 981: 
 982: // UpdatePeerStats updates a peer's system stats
 983: func (m *Manager) UpdatePeerStats(id string, stats map[string]interface{}) {
 984: 	m.mu.Lock()
 985: 	if h, ok := m.hosts[id]; ok {
 986: 		h.Stats = stats
 987: 		h.LastSeen = time.Now()
 988: 	}
 989: 	m.mu.Unlock()
 990: }
 991: 
 992: // HasLiveConnection reports whether a connected peer connection exists for id.
 993: func (m *Manager) HasLiveConnection(id string) bool {
 994: 	m.mu.RLock()
 995: 	defer m.mu.RUnlock()
 996: 	if h, ok := m.hosts[id]; ok {
 997: 		return h.Conn != nil
 998: 	}
 999: 	return false
1000: }
1001: 
1002: // GetPeerAddress returns a connected peer's stored listening address.
1003: 
1004: // GetPeerConnection returns the connection for a specific peer
1005: func (m *Manager) GetPeerConnection(id string) *PeerConnection {
1006: 	m.mu.RLock()
1007: 	defer m.mu.RUnlock()
1008: 
1009: 	if h, ok := m.hosts[id]; ok && h.Conn != nil {
1010: 		return h.Conn
1011: 	}
1012: 	return nil
1013: }
1014: 
1015: // GetPeerAddress returns a connected peer's stored listening address.
1016: func (m *Manager) GetPeerAddress(id string) string {
1017: 	m.mu.RLock()
1018: 	defer m.mu.RUnlock()
1019: 	if h, ok := m.hosts[id]; ok {
1020: 		return h.Address
1021: 	}
1022: 	return ""
1023: }
1024: 
1025: // ConnectedPeers returns every currently-connected remote peer connection.
1026: // The local host is skipped. Used for fan-out broadcasts (e.g. layout sync).
1027: func (m *Manager) ConnectedPeers() []*PeerConnection {
1028: 	m.mu.RLock()
1029: 	defer m.mu.RUnlock()
1030: 
1031: 	out := make([]*PeerConnection, 0, len(m.hosts))
1032: 	for id, h := range m.hosts {
1033: 		if id == m.localID {
1034: 			continue
1035: 		}
1036: 		if h.Conn != nil {
1037: 			out = append(out, h.Conn)
1038: 		}
1039: 	}
1040: 	return out
1041: }
1042: 
1043: // GetAllActivity returns activity snapshots from all remote peers (not local)
1044: func (m *Manager) GetAllActivity() []*activity.Snapshot {
1045: 	m.mu.RLock()
1046: 	defer m.mu.RUnlock()
1047: 
1048: 	var all []*activity.Snapshot
1049: 	for id, h := range m.hosts {
1050: 		if id == m.localID {
1051: 			continue
1052: 		}
1053: 		all = append(all, h.Activity...)
1054: 	}
1055: 	return all
1056: }
1057: 
1058: // GetHostName returns the display name for a host ID
1059: func (m *Manager) GetHostName(id string) string {
1060: 	m.mu.RLock()
1061: 	defer m.mu.RUnlock()
1062: 	if h, ok := m.hosts[id]; ok {
1063: 		return h.Name
1064: 	}
1065: 	return ""
1066: }
1067: 
1068: // HasHost returns true if a host with the given ID is known
1069: func (m *Manager) HasHost(id string) bool {
1070: 	m.mu.RLock()
1071: 	defer m.mu.RUnlock()
1072: 	_, ok := m.hosts[id]
1073: 	return ok
1074: }
1075: 
1076: // IsLocal returns true if the given host ID is this node
1077: func (m *Manager) IsLocal(hostID string) bool {
1078: 	return hostID == "" || hostID == m.localID
1079: }
1080: 
1081: // pruneOffline marks long-offline peers as offline. It deliberately does not
1082: // delete v2 remote catalog caches; those are retained through reconnects and
1083: // only dropped on explicit forget.
1084: func (m *Manager) pruneOffline() {
1085: 	m.mu.Lock()
1086: 	defer m.mu.Unlock()
1087: 
1088: 	now := time.Now()
1089: 	for id, h := range m.hosts {
1090: 		if id == m.localID {
1091: 			continue
1092: 		}
1093: 		if !h.Connected && now.Sub(h.LastSeen) > OfflineTimeout {
1094: 			// Keep the host entry so its cached catalog remains addressable by
1095: 			// peer ID; only mark it as stale.
1096: 			h.Connected = false
1097: 			logrus.WithFields(logrus.Fields{
1098: 				"peer": h.Name,
1099: 				"id":   id,
1100: 			}).Debug("peer offline timeout reached; catalog retained")
1101: 		}
1102: 	}
1103: }  1: package peer
