 13: // Message types sent from peer to hub over control WebSocket
 14: const (
 15: 	// MsgAuth is the challenge-response auth message
 16: 	MsgAuth = "auth"
 17: 	// MsgStateUpdate is a full session state snapshot
 18: 	MsgStateUpdate = "state-update"
 19: 	// MsgStateEvent is an incremental state change
 20: 	MsgStateEvent = "state-event"
 21: 	// MsgToolEvent forwards a local tool event
 22: 	MsgToolEvent = "tool-event"
 23: 	// MsgActivityUpdate sends periodic activity data
 24: 	MsgActivityUpdate = "activity-update"
 25: 	// MsgStats sends system stats
 26: 	MsgStats = "stats"
 27: 	// MsgCapturePaneResult returns a capture-pane snapshot to the hub.
 28: 	MsgCapturePaneResult = "capture-pane-result"
 29: )
 30: 
 31: // Message types sent from hub to peer over control WebSocket
 32: const (
 33: 	// MsgChallenge is the auth challenge from hub
 34: 	MsgChallenge = "challenge"
 35: 	// MsgAuthOK indicates successful authentication
 36: 	MsgAuthOK = "auth-ok"
 37: 	// MsgAuthFail indicates failed authentication
 38: 	MsgAuthFail = "auth-fail"
 39: 	// MsgPeerState is aggregated state from all other peers
 40: 	MsgPeerState = "peer-state"
 41: 	// MsgPeerConnected notifies that a new peer joined
 42: 	MsgPeerConnected = "peer-connected"
 43: 	// MsgPeerDisconnected notifies that a peer left
 44: 	MsgPeerDisconnected = "peer-disconnected"
 45: 	// MsgSessionAction forwards an API action to the peer
 46: 	MsgSessionAction = "session-action"
 47: 	// MsgRequestState asks the peer for a full state refresh
 48: 	MsgRequestState = "request-state"
 49: 	// MsgV2CatalogSnapshot carries a full v2 owner catalog snapshot.
 50: 	MsgV2CatalogSnapshot = "v2-catalog-snapshot"
 51: 	// MsgV2WorkspaceSnapshot carries a full v2 owner workspace snapshot.
 52: 	MsgV2WorkspaceSnapshot = "v2-workspace-snapshot"
 53: 	// MsgV2CommandRequest is a reliable command RPC request.
 54: 	MsgV2CommandRequest = "v2-command-request"
 55: 	// MsgV2CommandReply is a reliable command RPC reply.
 56: 	MsgV2CommandReply = "v2-command-reply"
 57: 	// MsgForget notifies the receiver that the sender is forgetting them.
 58: 	// Receiver should remove sender from its peer store and close the link.
 59: 	MsgForget = "forget"
 60: 	// MsgSessionAttrsSnapshot carries the full shared session-attribute map
 61: 	// (background/hidden per session key) to a freshly-connected peer for
 62: 	// per-key last-write-wins reconciliation.
 63: 	MsgSessionAttrsSnapshot = "session-attrs-snapshot"
 64: 	// MsgSessionAttrsDelta carries a single-key shared session-attribute
 65: 	// update across paired peers. Per-key LWW by UpdatedAt.
 66: 	MsgSessionAttrsDelta = "session-attrs-delta"
 67: 	// MsgSessionOrderSnapshot carries the full shared session-order map
 68: 	// (rank per session key) to a freshly-connected peer for per-key LWW
 69: 	// reconciliation.
 70: 	MsgSessionOrderSnapshot = "session-order-snapshot"
 71: 	// MsgSessionOrderDelta carries a single-key shared session-order update
 72: 	// across paired peers. Per-key LWW by UpdatedAt.
 73: 	MsgSessionOrderDelta = "session-order-delta"
 74: 	// MsgGroupSnapshot carries the full shared group map to a freshly-connected
 75: 	// peer for field-level LWW reconciliation.
 76: 	MsgGroupSnapshot = "group-snapshot"
 77: 	// MsgGroupDelta carries a single group update across paired peers.
 78: 	MsgGroupDelta = "group-delta"
 79: 	// MsgCapturePane asks a peer to capture its primary pane's visible buffer.
 80: 	MsgCapturePane = "capture-pane"
 81: )
