372: // NewMessage creates a Message with a typed payload
373: func NewMessage(msgType string, payload interface{}) (*Message, error) {
374: 	data, err := json.Marshal(payload)
375: 	if err != nil {
376: 		return nil, err
377: 	}
378: 	return &Message{
379: 		Type:    msgType,
380: 		Payload: json.RawMessage(data),
381: 	}, nil
