 15: // sendInitialPeerState pushes a snapshot containing only the local host
 16: // (transitivity off, see plan §3.5).
 17: func sendInitialPeerState(pc *PeerConnection, deps SessionDeps, remotePeerID string) {
 18: 	hosts := deps.Manager.GetHostsForPeer(remotePeerID)
 19: 	msg, err := NewMessage(MsgPeerState, PeerStatePayload{Hosts: hosts})
 20: 	if err != nil {
 21: 		return
 22: 	}
 23: 	pc.Enqueue(msg)
 24: }
 25: 
 26: func sendStateUpdate(pc *PeerConnection, deps SessionDeps) {
 27: 	sessions := deps.LocalMgr.GetSessions()
 28: 	msg, err := NewMessage(MsgStateUpdate, StateUpdatePayload{Sessions: sessions, Version: common.VERSION})
 29: 	if err != nil {
 30: 		return
 31: 	}
 32: 	pc.Enqueue(msg)
 33: }
 34: 
 35: // handleStateMessage processes peer-state and session-state control messages.
 36: func handleStateMessage(peerID string, msg *Message, pc *PeerConnection, deps SessionDeps, log *logrus.Entry) {
 37: 	switch msg.Type {
 38: 	case MsgStateUpdate:
 39: 		var p StateUpdatePayload
 40: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
 41: 			log.WithError(err).Debug("invalid state-update")
 42: 			return
 43: 		}
 44: 		deps.Manager.UpdatePeerSessions(peerID, p.Sessions)
 45: 		if p.Version != "" {
 46: 			deps.Manager.UpdatePeerVersion(peerID, p.Version)
 47: 		}
 48: 
 49: 	case MsgStateEvent:
 50: 		var p StateEventPayload
 51: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
 52: 			return
 53: 		}
 54: 		if p.EventType == "session-renamed" && deps.BrowserHub != nil {
 55: 			newName := ""
 56: 			switch data := p.Data.(type) {
 57: 			case map[string]any:
 58: 				if v, ok := data["new_name"].(string); ok {
 59: 					newName = v
 60: 				}
 61: 			case map[string]string:
 62: 				newName = data["new_name"]
 63: 			}
 64: 			if p.Session != "" && newName != "" {
 65: 				deps.BrowserHub.BroadcastJSON(map[string]interface{}{
 66: 					"type":    "session-renamed",
 67: 					"host":    peerID,
 68: 					"session": p.Session,
 69: 					"data": map[string]string{
 70: 						"new_name": newName,
 71: 					},
 72: 				})
 73: 			}
 74: 		}
 75: 		deps.Manager.UpdatePeerSessions(peerID, getPeerSessions(deps.Manager, peerID))
 76: 
 77: 	case MsgActivityUpdate:
 78: 		var p ActivityUpdatePayload
 79: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
 80: 			return
 81: 		}
 82: 		for _, s := range p.Snapshots {
 83: 			s.Host = peerID
 84: 		}
 85: 		deps.Manager.UpdatePeerActivity(peerID, p.Snapshots)
 86: 
 87: 	case MsgStats:
 88: 		var p StatsPayload
 89: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
 90: 			return
 91: 		}
 92: 		deps.Manager.UpdatePeerStats(peerID, p.Stats)
 93: 
 94: 	case MsgPeerState:
 95: 		var p PeerStatePayload
 96: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
 97: 			return
 98: 		}
 99: 		for _, host := range p.Hosts {
100: 			if deps.Manager.IsLocal(host.ID) {
101: 				continue
102: 			}
103: 			deps.Manager.UpdatePeerSessions(host.ID, host.Sessions)
104: 			if host.Online && !deps.Manager.HasHost(host.ID) {
105: 				deps.Manager.RegisterPeer(host.ID, host.Name, "", nil)
106: 			}
107: 		}
108: 
109: 	case MsgPeerConnected:
110: 		var p PeerNotifyPayload
111: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
112: 			return
113: 		}
114: 		deps.Manager.RegisterPeer(p.ID, p.Name, "", nil)
115: 
116: 	case MsgPeerDisconnected:
117: 		var p PeerNotifyPayload
118: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
119: 			return
120: 		}
121: 		deps.Manager.UnregisterPeer(p.ID)
122: 
123: 	case MsgRequestState:
124: 		sendStateUpdate(pc, deps)
125: 	}
126: }
127: 
128: func getPeerSessions(m *Manager, peerID string) []*model.Session {
129: 	m.mu.RLock()
130: 	defer m.mu.RUnlock()
131: 	if h, ok := m.hosts[peerID]; ok {
132: 		out := make([]*model.Session, len(h.Sessions))
133: 		for i, s := range h.Sessions {
134: 			out[i] = copySession(s)
135: 		}
136: 		return out
137: 	}
138: 	return nil
139: }
