141: func sendInitialV2Catalog(pc *PeerConnection, deps SessionDeps) {
142: 	if deps.Manager == nil || deps.Manager.localMgr == nil {
143: 		return
144: 	}
145: 	if !deps.Manager.localMgr.V2Enabled() {
146: 		return
147: 	}
148: 	catalog := deps.Manager.localMgr.V2Catalog()
149: 	if catalog == nil {
150: 		return
151: 	}
152: 	snap := catalog.LocalCatalogSnapshot()
153: 	payload := V2CatalogSnapshotPayload{
154: 		Owner:    snap.Owner,
155: 		Revision: snap.Revision,
156: 		Sessions: snap.Sessions,
157: 		Layouts:  snap.Layouts,
158: 	}
159: 	msg, err := NewMessage(MsgV2CatalogSnapshot, payload)
160: 	if err != nil {
161: 		return
162: 	}
163: 	pc.EnqueueV2CatalogSnapshot(msg)
164: }
