166: func sendInitialV2Workspace(pc *PeerConnection, deps SessionDeps) {
167: 	if deps.Manager == nil || deps.Manager.localMgr == nil {
168: 		return
169: 	}
170: 	if !deps.Manager.localMgr.V2Enabled() {
171: 		return
172: 	}
173: 	catalog := deps.Manager.localMgr.V2Catalog()
174: 	if catalog == nil {
175: 		return
176: 	}
177: 	// Send the first layout as a complete workspace snapshot. The
178: 	// per-connection subscriber below forwards updates after each accepted
179: 	// command so the remote cache never sees intermediate steps.
180: 	layouts := catalog.Layouts()
181: 	if len(layouts) == 0 {
182: 		return
183: 	}
184: 	snap, err := catalog.WorkspaceSnapshot(layouts[0].ID)
185: 	if err != nil {
186: 		return
187: 	}
188: 	msg, err := NewMessage(MsgV2WorkspaceSnapshot, V2WorkspaceSnapshotPayload{
189: 		Owner:     snap.Record.Owner,
190: 		Revision:  snap.Record.Revision,
191: 		Workspace: snap.Record,
192: 	})
193: 	if err != nil {
194: 		return
195: 	}
196: 	pc.EnqueueV2WorkspaceSnapshot(msg)
197: }
