199: // handleV2Message routes v2 catalog, workspace, and command messages.
200: func handleV2Message(peerID string, msg *Message, pc *PeerConnection, deps SessionDeps, log *logrus.Entry) {
201: 	switch msg.Type {
202: 	case MsgV2CatalogSnapshot:
203: 		var p V2CatalogSnapshotPayload
204: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
205: 			log.WithError(err).Debug("invalid v2 catalog snapshot")
206: 			return
207: 		}
208: 		deps.Manager.UpdateRemoteCatalog(peerID, state.OwnerCatalogSnapshot{
209: 			Owner:    p.Owner,
210: 			Revision: p.Revision,
211: 			Sessions: p.Sessions,
212: 			Layouts:  p.Layouts,
213: 		})
214: 
215: 	case MsgV2WorkspaceSnapshot:
216: 		var p V2WorkspaceSnapshotPayload
217: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
218: 			log.WithError(err).Debug("invalid v2 workspace snapshot")
219: 			return
220: 		}
221: 		deps.Manager.UpdateRemoteWorkspace(peerID, p.Workspace)
222: 
223: 	case MsgV2CommandRequest:
224: 		var p V2CommandRequestPayload
225: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
226: 			log.WithError(err).Debug("invalid v2 command request")
227: 			return
228: 		}
229: 		handleV2CommandRequest(peerID, p, pc, deps, log)
230: 
231: 	case MsgV2CommandReply:
232: 		var p V2CommandReplyPayload
233: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
234: 			log.WithError(err).Debug("invalid v2 command reply")
235: 			return
236: 		}
237: 		deps.Manager.deliverCommandReply(p)
238: 	}
239: }
