241: func handleV2CommandRequest(peerID string, req V2CommandRequestPayload, pc *PeerConnection, deps SessionDeps, log *logrus.Entry) {
242: 	reply := V2CommandReplyPayload{ID: req.ID}
243: 	switch req.Kind {
244: 	case V2CommandKindSession:
245: 		handleV2SessionCommandRequest(req, pc, deps, &reply)
246: 	case V2CommandKindWorkspace:
247: 		handleV2WorkspaceCommandRequest(req, pc, deps, &reply)
248: 	case V2CommandKindRemoteCreate:
249: 		handleV2RemoteCreateRequest(req, pc, deps, &reply)
250: 	default:
251: 		reply.Error = fmt.Sprintf("unknown command kind %q", req.Kind)
252: 	}
253: 	sendV2CommandReply(pc, reply)
254: }
255: 
256: func handleV2SessionCommandRequest(req V2CommandRequestPayload, pc *PeerConnection, deps SessionDeps, reply *V2CommandReplyPayload) {
257: 	if deps.V2CommandSvc == nil {
258: 		reply.Error = "v2 command service unavailable"
259: 		return
260: 	}
261: 	var cmd state.SessionCommand
262: 	if err := json.Unmarshal(req.Command, &cmd); err != nil {
263: 		reply.Error = "malformed command"
264: 		return
265: 	}
266: 	res, err := deps.V2CommandSvc.ExecuteSessionCommand(context.Background(), cmd)
267: 	if err != nil {
268: 		reply.Error = err.Error()
269: 		return
270: 	}
271: 	reply.Handled = true
272: 	data, err := json.Marshal(res)
273: 	if err != nil {
274: 		reply.Error = "failed to encode result"
275: 		return
276: 	}
277: 	reply.Result = data
278: }
279: 
280: func handleV2WorkspaceCommandRequest(req V2CommandRequestPayload, pc *PeerConnection, deps SessionDeps, reply *V2CommandReplyPayload) {
281: 	cat := deps.LocalMgr.V2Catalog()
282: 	if cat == nil {
283: 		reply.Error = "v2 catalog not enabled"
284: 		return
285: 	}
286: 	var cmd state.WorkspaceCommand
287: 	if err := json.Unmarshal(req.Command, &cmd); err != nil {
288: 		reply.Error = "malformed workspace command"
289: 		return
290: 	}
291: 	if err := cat.ApplyWorkspaceCommand(cmd); err != nil {
292: 		reply.Error = err.Error()
293: 		return
294: 	}
295: 	reply.Handled = true
296: }
297: 
298: func handleV2RemoteCreateRequest(req V2CommandRequestPayload, pc *PeerConnection, deps SessionDeps, reply *V2CommandReplyPayload) {
299: 	if deps.RemoteCreateCoordinator == nil {
300: 		reply.Error = "remote create coordinator unavailable"
301: 		return
302: 	}
303: 	var r state.RemoteCreateRequest
304: 	if err := json.Unmarshal(req.Command, &r); err != nil {
305: 		reply.Error = "malformed remote create request"
306: 		return
307: 	}
308: 	res, err := deps.RemoteCreateCoordinator.ExecuteRemoteCreate(context.Background(), r)
309: 	if err != nil {
310: 		reply.Error = err.Error()
311: 		return
312: 	}
313: 	reply.Handled = true
314: 	data, err := json.Marshal(res)
315: 	if err != nil {
316: 		reply.Error = "failed to encode remote create result"
317: 		return
318: 	}
319: 	reply.Result = data
320: }
