322: func sendV2CommandReply(pc *PeerConnection, reply V2CommandReplyPayload) {
323: 	msg, err := NewMessage(MsgV2CommandReply, reply)
324: 	if err != nil {
325: 		return
326: 	}
327: 	data, err := json.Marshal(msg)
328: 	if err != nil {
329: 		return
330: 	}
331: 	pc.enqueue(pc.lo, wireFrame{data: data})
