 34: func TestHandleFileReadNotFound(t *testing.T) {
 35: 	pc := NewPeerConnection("peer", 1)
 36: 	deps := SessionDeps{}
 37: 	msg, err := NewMessage(MsgFileRead, FileReadPayload{
 38: 		Token:   "t",
 39: 		Path:    "/no/such/file",
 40: 		Session: "",
 41: 	})
 42: 	if err != nil {
 43: 		t.Fatal(err)
 44: 	}
 45: 
 46: 	handleStreamMessage("peer", msg, pc, deps, logrus.NewEntry(logrus.New()))
 47: 
 48: 	select {
 49: 	case f := <-pc.LoLane():
 50: 		var msg Message
 51: 		if err := json.Unmarshal(f.data, &msg); err != nil {
 52: 			t.Fatal(err)
 53: 		}
 54: 		if msg.Type != MsgFileReadResult {
 55: 			t.Fatalf("expected %s, got %s", MsgFileReadResult, msg.Type)
 56: 		}
 57: 		var res FileReadResultPayload
 58: 		if err := json.Unmarshal(msg.Payload, &res); err != nil {
 59: 			t.Fatal(err)
 60: 		}
 61: 		if res.Error == "" {
 62: 			t.Fatal("expected error for missing file")
 63: 		}
 64: 	case <-time.After(time.Second):
 65: 		t.Fatal("timeout waiting for file-read result")
 66: 	}
