108: // recordingDaemonReg captures the socket key (and generation lookup) passed to
109: // SocketPath/GenerationFor so tests can assert the resolved daemon key.
110: type recordingDaemonReg struct {
111: 	mu           sync.Mutex
112: 	socketKey    string
113: 	generationID string
114: 	genReturn    string
115: }
116: 
117: func (r *recordingDaemonReg) Create(name, shell, cwd string, cols, rows uint16) error { return nil }
118: func (r *recordingDaemonReg) Kill(name string) error                                  { return nil }
119: func (r *recordingDaemonReg) Capture(name string) (string, error)                     { return "", nil }
120: func (r *recordingDaemonReg) List() []pty.SessionInfo                                 { return nil }
121: func (r *recordingDaemonReg) GenerationFor(name string) string {
122: 	r.mu.Lock()
123: 	defer r.mu.Unlock()
124: 	r.generationID = name
125: 	return r.genReturn
126: }
127: func (r *recordingDaemonReg) SocketPath(name string) string {
128: 	r.mu.Lock()
129: 	defer r.mu.Unlock()
130: 	r.socketKey = name
131: 	return ""
132: }
133: func (r *recordingDaemonReg) lastSocketKey() string {
134: 	r.mu.Lock()
135: 	defer r.mu.Unlock()
136: 	return r.socketKey
137: }
138: func (r *recordingDaemonReg) lastGenerationFor() string {
139: 	r.mu.Lock()
140: 	defer r.mu.Unlock()
141: 	return r.generationID
142: }
