144: func waitForSocketKey(t *testing.T, r *recordingDaemonReg, want string) {
145: 	t.Helper()
146: 	deadline := time.Now().Add(2 * time.Second)
147: 	for time.Now().Before(deadline) {
148: 		if r.lastSocketKey() == want {
149: 			return
150: 		}
151: 		time.Sleep(10 * time.Millisecond)
152: 	}
153: 	t.Fatalf("SocketPath never called with %q (last %q)", want, r.lastSocketKey())
154: }
