156: // TestOpenTerminal_NameOnlyPayloadResolvesDaemonKey is a same-process peer
157: // roundtrip: a name-only OpenTerminalPayload (no SessionID -- the pre-v2 /
158: // display-name path) must still resolve a daemon socket key by falling back to
159: // the session name instead of passing an empty SessionID to SocketPath.
160: func TestOpenTerminal_NameOnlyPayloadResolvesDaemonKey(t *testing.T) {
161: 	tmpHome := t.TempDir()
162: 	t.Setenv("HOME", tmpHome)
163: 	_ = os.MkdirAll(filepath.Join(tmpHome, ".config", "termyard"), 0o700)
164: 
165: 	dialerID, err := identity.Generate("dialer")
166: 	if err != nil {
167: 		t.Fatal(err)
168: 	}
169: 	store, err := identity.NewPeerStore()
170: 	if err != nil {
171: 		t.Fatal(err)
172: 	}
173: 	if err := store.Add(identity.Peer{Name: "dialer", PublicKey: dialerID.PublicKey, Enabled: true, InitiatedByUs: true}); err != nil {
174: 		t.Fatal(err)
175: 	}
176: 
177: 	reg := NewStreamRegistry()
178: 	handler := NewHandler(SessionDeps{PeerStore: store}, reg)
179: 	mux := http.NewServeMux()
180: 	mux.HandleFunc("/ws/peer-stream", handler.HandlePeerStream)
181: 	srv := httptest.NewServer(mux)
182: 	defer srv.Close()
183: 	addr := mustHostPort(t, srv.URL)
184: 
185: 	hostID := dialerID.Fingerprint()
186: 
187: 	// Name-only payload (display name, no SessionID). The host must fall back
188: 	// to the display name as its daemon key instead of SocketPath("").
189: 	t.Run("name-only payload", func(t *testing.T) {
190: 		rec := &recordingDaemonReg{}
191: 		pc := NewPeerConnection(hostID, 8)
192: 		pc.Role = RoleDialer
193: 
194: 		mgr := NewManager(dialerID, store, state.NewManager())
195: 		mgr.RegisterPeerWithAddress(hostID, "dialer", dialerID.PublicKey, addr, pc)
196: 
197: 		token := NewToken()
198: 		reg.Register(token, NewPendingStream("OPEN-NAME-ONLY", "", 0, 0, "", "", hostID))
199: 
200: 		payload := OpenTerminalPayload{StreamID: "OPEN-NAME-ONLY", Session: "legacy-display-name", Cols: 80, Rows: 24, Token: token}
201: 		deps := SessionDeps{Manager: mgr, Identity: dialerID, DaemonReg: rec}
202: 		go handleOpenTerminal(payload, pc, deps, logrus.NewEntry(logrus.New()))
203: 
204: 		waitForSocketKey(t, rec, "legacy-display-name")
205: 		// No GenerationFor lookup happens for a name-only payload.
206: 		if rec.lastGenerationFor() != "" {
207: 			t.Fatalf("unexpected generation lookup for name-only payload: %q", rec.lastGenerationFor())
208: 		}
209: 	})
210: 
211: 	// Stable payload (immutable SessionID) must prefer the SessionID as the
212: 	// daemon key, even when a display name is also present. The generation
213: 	// gate looks the current generation up by the same SessionID key.
214: 	t.Run("sessionID payload", func(t *testing.T) {
215: 		rec := &recordingDaemonReg{genReturn: "gen-current"}
216: 		pc := NewPeerConnection(hostID, 8)
217: 		pc.Role = RoleDialer
218: 
219: 		mgr := NewManager(dialerID, store, state.NewManager())
220: 		mgr.RegisterPeerWithAddress(hostID, "dialer", dialerID.PublicKey, addr, pc)
221: 
222: 		token := NewToken()
223: 		reg.Register(token, NewPendingStream("OPEN-STABLE", "", 0, 0, "", "", hostID))
224: 
225: 		payload := OpenTerminalPayload{StreamID: "OPEN-STABLE", Session: "display-name", SessionID: "stable-session-id-abc", Generation: "gen-current", Cols: 80, Rows: 24, Token: token}
226: 		deps := SessionDeps{Manager: mgr, Identity: dialerID, DaemonReg: rec}
227: 		go handleOpenTerminal(payload, pc, deps, logrus.NewEntry(logrus.New()))
228: 
229: 		waitForSocketKey(t, rec, "stable-session-id-abc")
230: 		// The generation lookup must use the SessionID, not the display name.
231: 		if got := rec.lastGenerationFor(); got != "stable-session-id-abc" {
232: 			t.Fatalf("generation lookup used %q, want the SessionID", got)
233: 		}
234: 	})
