 22: // handleStreamMessage routes terminal and file-stream control messages.
 23: func handleStreamMessage(peerID string, msg *Message, pc *PeerConnection, deps SessionDeps, log *logrus.Entry) {
 24: 	switch msg.Type {
 25: 	case MsgOpenTerminal:
 26: 		var p OpenTerminalPayload
 27: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
 28: 			log.WithError(err).Debug("invalid open-terminal")
 29: 			return
 30: 		}
 31: 		go handleOpenTerminal(p, pc, deps, log)
 32: 
 33: 	case MsgCapturePane:
 34: 		var p CapturePanePayload
 35: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
 36: 			log.WithError(err).Debug("invalid capture-pane")
 37: 			return
 38: 		}
 39: 		go handleCapturePane(p, pc, deps, log)
 40: 
 41: 	case MsgCapturePaneResult:
 42: 		var p CapturePaneResultPayload
 43: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
 44: 			return
 45: 		}
 46: 		if deps.CaptureReg != nil {
 47: 			deps.CaptureReg.Deliver(p.Token, CaptureResult{Text: p.Text, Error: p.Error})
 48: 		}
 49: 
 50: 	case MsgFileRead:
 51: 		var p FileReadPayload
 52: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
 53: 			log.WithError(err).Debug("invalid file-read")
 54: 			return
 55: 		}
 56: 		go handleFileRead(p, pc, deps, log)
 57: 
 58: 	case MsgOpenUpload:
 59: 		var p OpenUploadPayload
 60: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
 61: 			log.WithError(err).Debug("invalid open-upload")
 62: 			return
 63: 		}
 64: 		go handleOpenUpload(p, pc, deps, log)
 65: 
 66: 	case MsgFileReadResult:
 67: 		var p FileReadResultPayload
 68: 		if err := json.Unmarshal(msg.Payload, &p); err != nil {
 69: 			return
 70: 		}
 71: 		if deps.FileReadReg != nil {
 72: 			deps.FileReadReg.Deliver(p.Token, FileReadResult{
 73: 				Data: p.Data, ContentType: p.ContentType,
 74: 				FileName: p.FileName, Error: p.Error,
 75: 			})
 76: 		}
 77: 	}
 78: }
