 80: // handleOpenTerminal is the host end of a per-terminal data connection.
 81: func handleOpenTerminal(p OpenTerminalPayload, pc *PeerConnection, deps SessionDeps, log *logrus.Entry) {
 82: 	log = log.WithFields(logrus.Fields{"stream": p.StreamID, "session": p.Session})
 83: 	dial := pc.Role == RoleDialer
 84: 	var conn *websocket.Conn
 85: 	if deps.Manager == nil || deps.DaemonReg == nil || deps.Identity == nil {
 86: 		return
 87: 	}
 88: 	if dial {
 89: 		addr := deps.Manager.GetPeerAddress(pc.HostID)
 90: 		c, err := DialPeerStream(context.Background(), addr, deps.Identity, p.Token)
 91: 		if err != nil {
 92: 			log.WithError(err).Debug("host data-conn dial failed")
 93: 			return
 94: 		}
 95: 		conn = c
 96: 	} else {
 97: 		if deps.StreamReg == nil || deps.Manager == nil || deps.DaemonReg == nil {
 98: 			return
 99: 		}
100: 		ps := NewPendingStream(p.StreamID, p.Session, p.Cols, p.Rows, deps.Manager.LocalID(), p.ViewerHostID, pc.HostID)
101: 		deps.StreamReg.Register(p.Token, ps)
102: 		c, ok := ps.WaitResolved(streamSetupTimeout)
103: 		if !ok {
104: 			return
105: 		}
106: 		conn = c
107: 	}
108: 	defer conn.Close()
109: 	// Enable write compression with fastest level so PTY host→viewer output
110: 	// (the bulk direction) is compressed on the wire.
111: 	conn.EnableWriteCompression(true)
112: 	if err := conn.SetCompressionLevel(flate.BestSpeed); err != nil {
113: 		log.WithError(err).Debug("set compression level ignored")
114: 	}
115: 
116: 	// Resolve the daemon socket key. The immutable SessionID wins when the
117: 	// viewer supplied a stable identity; legacy name-only payloads (pre-v2
118: 	// peers or browsers that only know the display name) fall back to the
119: 	// session name, which is the daemon key for non-v2 sessions.
120: 	daemonKey := p.SessionID
121: 	if daemonKey == "" {
122: 		daemonKey = p.Session
123: 	}
124: 
125: 	// Generation-gated attach: when the viewer supplied a stable identity
126: 	// (session id + generation), refuse the bridge before streaming if the
127: 	// current generation differs. This is what stops a stale browser tab from
128: 	// splicing onto a recovered/restarted daemon over the peer relay.
129: 	if p.SessionID != "" || p.Generation != "" {
130: 		current := ""
131: 		if deps.DaemonReg != nil {
132: 			current = deps.DaemonReg.GenerationFor(daemonKey)
133: 		}
134: 		if current == "" {
135: 			log.WithField("generation", p.Generation).Debug("daemon attach refused: no current generation")
136: 			return
137: 		}
138: 		if p.Generation != "" && p.Generation != current {
139: 			log.WithFields(logrus.Fields{"want": p.Generation, "current": current}).Debug("daemon attach refused: stale generation")
140: 			return
141: 		}
142: 	}
143: 
144: 	socketPath := deps.DaemonReg.SocketPath(daemonKey)
145: 	ds, err := pty.NewDaemonSession(socketPath)
146: 	if err != nil {
147: 		log.WithError(err).Debug("failed to connect to daemon socket")
148: 		return
149: 	}
150: 	defer ds.Close()
151: 	_ = ds.Resize(p.Cols, p.Rows)
152: 	ws.BridgeDirectPTY(conn, ds, p.Session, deps.ActTracker, log, false)
153: }
