155: // handleCapturePane captures the daemon ring buffer for the requested session.
156: func handleCapturePane(p CapturePanePayload, pc *PeerConnection, deps SessionDeps, log *logrus.Entry) {
157: 	res := CapturePaneResultPayload{Token: p.Token}
158: 	if deps.DaemonReg == nil {
159: 		res.Error = "daemon registry unavailable"
160: 	} else if text, err := deps.DaemonReg.Capture(p.Session); err != nil {
161: 		res.Error = err.Error()
162: 	} else {
163: 		res.Text = model.LastLines(text, p.Lines)
164: 	}
165: 	msg, err := NewMessage(MsgCapturePaneResult, res)
166: 	if err != nil {
167: 		log.WithError(err).Debug("capture-pane result marshal failed")
168: 		return
169: 	}
170: 	pc.Enqueue(msg)
171: }
