173: // maxFileReadSize caps the file content sent over peer relay (10 MB).
174: const maxFileReadSize = 10 << 20
175: 
176: // handleFileRead reads a local file and sends its content back over the
177: // control link. Relative paths resolve against the session's active pane CWD.
178: func handleFileRead(p FileReadPayload, pc *PeerConnection, deps SessionDeps, log *logrus.Entry) {
179: 	res := FileReadResultPayload{Token: p.Token}
180: 
181: 	path := p.Path
182: 	if !filepath.IsAbs(path) {
183: 		base := ""
184: 		if p.Session != "" && deps.DaemonReg != nil {
185: 			for _, s := range deps.DaemonReg.List() {
186: 				if s.ID == p.Session {
187: 					base = s.Cwd
188: 					break
189: 				}
190: 			}
191: 		}
192: 		if base == "" {
193: 			res.Error = "cannot resolve relative path: no active pane cwd"
194: 			if msg, err := NewMessage(MsgFileReadResult, res); err == nil {
195: 				pc.Enqueue(msg)
196: 			}
197: 			return
198: 		}
199: 		path = filepath.Clean(filepath.Join(base, path))
200: 	} else {
201: 		path = filepath.Clean(path)
202: 	}
203: 
204: 	info, err := os.Stat(path)
205: 	if err != nil {
206: 		res.Error = "not found"
207: 		if msg, err := NewMessage(MsgFileReadResult, res); err == nil {
208: 			pc.Enqueue(msg)
209: 		}
210: 		return
211: 	}
212: 	if info.IsDir() {
213: 		res.Error = "path is a directory"
214: 		if msg, err := NewMessage(MsgFileReadResult, res); err == nil {
215: 			pc.Enqueue(msg)
216: 		}
217: 		return
218: 	}
219: 	if info.Size() > maxFileReadSize {
220: 		res.Error = "file too large"
221: 		if msg, err := NewMessage(MsgFileReadResult, res); err == nil {
222: 			pc.Enqueue(msg)
223: 		}
224: 		return
225: 	}
226: 
227: 	f, err := os.Open(path)
228: 	if err != nil {
229: 		res.Error = err.Error()
230: 		if msg, err := NewMessage(MsgFileReadResult, res); err == nil {
231: 			pc.Enqueue(msg)
232: 		}
233: 		return
234: 	}
235: 	defer f.Close()
236: 
237: 	data, err := io.ReadAll(f)
238: 	if err != nil {
239: 		res.Error = err.Error()
240: 		if msg, err := NewMessage(MsgFileReadResult, res); err == nil {
241: 			pc.Enqueue(msg)
242: 		}
243: 		return
244: 	}
245: 
246: 	res.Data = base64.StdEncoding.EncodeToString(data)
247: 	res.FileName = filepath.Base(path)
248: 
249: 	// Detect content type.
250: 	ext := filepath.Ext(path)
251: 	ct := mime.TypeByExtension(ext)
252: 	if ct == "" {
253: 		ct = http.DetectContentType(data)
254: 	}
255: 	res.ContentType = ct
256: 
257: 	msg, err := NewMessage(MsgFileReadResult, res)
258: 	if err != nil {
259: 		log.WithError(err).Debug("file-read result marshal failed")
260: 		return
261: 	}
262: 	pc.Enqueue(msg)
