 17: // Lifecycle states for session daemons.
 18: const (
 19: 	LifecycleStarting             = "starting"
 20: 	LifecycleActive               = "active"
 21: 	LifecycleTerminationRequested = "termination_requested"
 22: 	LifecycleCleanlyEnded         = "cleanly_ended"
 23: 	LifecycleCrashed              = "crashed"
 24: 	LifecycleRecovered            = "recovered"
 25: 	LifecycleDismissed            = "dismissed"
 26: )
 27: 
 28: // terminalLifecycleStates are states where the daemon is no longer live.
 29: var terminalLifecycleStates = map[string]bool{
 30: 	LifecycleTerminationRequested: true,
 31: 	LifecycleCleanlyEnded:         true,
 32: 	LifecycleDismissed:            true,
