 35: // LifecycleRecord holds durable state for a session daemon.
 36: // Written as a JSON file under the lifecycle store directory.
 37: type LifecycleRecord struct {
 38: 	ID            string    `json:"id"`
 39: 	State         string    `json:"state"`
 40: 	Shell         string    `json:"shell"`
 41: 	Cwd           string    `json:"cwd"`
 42: 	Cols          uint16    `json:"cols"`
 43: 	Rows          uint16    `json:"rows"`
 44: 	CreatedAt     time.Time `json:"created_at"`
 45: 	UpdatedAt     time.Time `json:"updated_at"`
 46: 	DaemonPID     int       `json:"daemon_pid"`
 47: 	SystemdUnit   string    `json:"systemd_unit,omitempty"` // systemd scope unit name (for cleanup)
 48: 	Generation    string    `json:"generation"`
 49: 	ProcStartTime int64     `json:"proc_start_time,omitempty"` // /proc/pid/stat field 22 (starttime in clock ticks)
 50: 
 51: 	// Stable identity fields support the v2 binding handshake. They are
 52: 	// immutable for a given lifecycle record and are empty for legacy
 53: 	// daemons created before the v2 transition.
 54: 	Owner     string `json:"owner,omitempty"`
 55: 	SessionID string `json:"session_id,omitempty"`
 56: 	DaemonKey string `json:"daemon_key,omitempty"`
 57: 	CommandID string `json:"command_id,omitempty"`
 58: }
 59: 
 60: // LifecycleStore persists LifecycleRecord files to a durable directory.
 61: // All writes are atomic (write .tmp + rename).  Files are mode 0600.
 62: type LifecycleStore struct {
 63: 	dir string
 64: }
 65: 
 66: // DefaultStateDir returns the platform-appropriate state directory for
 67: // lifecycle records, respecting XDG_STATE_HOME.
 68: func DefaultStateDir() string {
 69: 	if d := os.Getenv("XDG_STATE_HOME"); d != "" {
 70: 		return filepath.Join(d, "termyard", "sessions")
 71: 	}
 72: 	home, err := os.UserHomeDir()
 73: 	if err == nil && home != "" {
 74: 		return filepath.Join(home, ".local", "state", "termyard", "sessions")
 75: 	}
 76: 	return filepath.Join(os.TempDir(), "termyard-state")
 77: }
 78: 
 79: // NewLifecycleStore creates a lifecycle store rooted at dir.  The directory
 80: // is created (mode 0700) if it does not exist.
 81: func NewLifecycleStore(dir string) (*LifecycleStore, error) {
 82: 	if err := os.MkdirAll(dir, 0700); err != nil {
 83: 		return nil, fmt.Errorf("create lifecycle store dir %s: %w", dir, err)
 84: 	}
 85: 	return &LifecycleStore{dir: dir}, nil
 86: }
 87: 
 88: // Dir returns the store directory.
 89: func (s *LifecycleStore) Dir() string { return s.dir }
 90: 
 91: // path returns the full path for a session's lifecycle file.
 92: func (s *LifecycleStore) path(id string) string {
 93: 	return filepath.Join(s.dir, id+".lifecycle.json")
 94: }
 95: 
 96: // NewGeneration returns a random 8-byte hex nonce for lifecycle records.
 97: func NewGeneration() string {
 98: 	b := make([]byte, 8)
 99: 	if _, err := rand.Read(b); err != nil {
100: 		// crypto/rand is extremely unlikely to fail; fall back to
101: 		// a time-based value that is still unique within a machine.
102: 		return fmt.Sprintf("%x", time.Now().UnixNano())
103: 	}
104: 	return hex.EncodeToString(b)
105: }
106: 
107: // RecordActive creates (or overwrites) a lifecycle record in state "active".
108: // The write is atomic: data is written to a .tmp file then renamed into place.
109: func (s *LifecycleStore) RecordActive(rec LifecycleRecord) error {
110: 	rec.State = LifecycleActive
111: 	rec.UpdatedAt = time.Now()
112: 	if rec.CreatedAt.IsZero() {
113: 		rec.CreatedAt = rec.UpdatedAt
114: 	}
115: 	if rec.Generation == "" {
116: 		rec.Generation = NewGeneration()
117: 	}
118: 	if rec.DaemonKey == "" {
119: 		rec.DaemonKey = rec.ID
120: 	}
121: 	return s.writeAtomic(rec)
122: }
123: 
124: // Transition performs a compare-and-swap state transition.
125: // It returns an error if the current state does not match fromState (except
126: // when fromState is empty, which bypasses the check).
127: // The .json file is atomically updated.
128: func (s *LifecycleStore) Transition(id, fromState, toState string) error {
129: 	current, err := s.Get(id)
130: 	if err != nil {
131: 		return fmt.Errorf("get record for %s: %w", id, err)
132: 	}
133: 	if fromState != "" && current.State != fromState {
134: 		return fmt.Errorf("expected state %q for %s, got %q", fromState, id, current.State)
135: 	}
136: 	current.State = toState
137: 	current.UpdatedAt = time.Now()
138: 	return s.writeAtomic(*current)
139: }
140: 
141: // Get reads the lifecycle record for a session.
142: func (s *LifecycleStore) Get(id string) (*LifecycleRecord, error) {
143: 	p := s.path(id)
144: 	data, err := os.ReadFile(p)
145: 	if err != nil {
146: 		return nil, err
147: 	}
148: 	var rec LifecycleRecord
149: 	if err := json.Unmarshal(data, &rec); err != nil {
150: 		return nil, fmt.Errorf("parse lifecycle record %s: %w", p, err)
151: 	}
152: 	return &rec, nil
153: }
154: 
155: // ListByState returns all lifecycle records whose State field matches state.
156: func (s *LifecycleStore) ListByState(state string) []LifecycleRecord {
157: 	entries, err := filepath.Glob(filepath.Join(s.dir, "*.lifecycle.json"))
158: 	if err != nil {
159: 		return nil
160: 	}
161: 
162: 	var out []LifecycleRecord
163: 	for _, p := range entries {
164: 		data, err := os.ReadFile(p)
165: 		if err != nil {
166: 			continue
167: 		}
168: 		var rec LifecycleRecord
169: 		if json.Unmarshal(data, &rec) != nil {
170: 			continue
171: 		}
172: 		if rec.State == state {
173: 			out = append(out, rec)
174: 		}
175: 	}
176: 	return out
177: }
178: 
179: // Remove deletes the lifecycle file for a session.
180: func (s *LifecycleStore) Remove(id string) error {
181: 	return os.Remove(s.path(id))
182: }
