184: // procStartTime reads field 22 (starttime) from /proc/<pid>/stat.
185: // Returns 0 if the file cannot be read or parsed.
186: func procStartTime(pid int) int64 {
187: 	data, err := os.ReadFile(fmt.Sprintf("/proc/%d/stat", pid))
188: 	if err != nil {
189: 		return 0
190: 	}
191: 	// Fields are space-separated; field 2 (comm) is in parens and may
192: 	// contain spaces, so find the last ')' first.
193: 	s := string(data)
194: 	idx := strings.LastIndex(s, ")")
195: 	if idx < 0 || idx+2 >= len(s) {
196: 		return 0
197: 	}
198: 	fields := strings.Fields(s[idx+2:])
199: 	// starttime is field 22 in stat (1-indexed), which is fields[19]
200: 	// after skipping the first 3 fields (state, ppid, pgrp at positions 3-5).
201: 	// After ')' we have fields starting at position 3, so starttime is at index 19.
202: 	if len(fields) < 20 {
203: 		return 0
204: 	}
205: 	v, err := strconv.ParseInt(fields[19], 10, 64)
206: 	if err != nil {
207: 		return 0
208: 	}
209: 	return v
210: }
211: 
212: // DetectCrashes finds records in state "active" whose daemon process is no
213: // longer alive, transitions them to "crashed", and returns the affected
214: // records (in their new "crashed" state).
215: //
216: // Process liveness is checked with syscall.Kill(pid, 0), guarded by
217: // /proc/<pid>/stat start time to prevent PID-reuse false negatives.
218: func (s *LifecycleStore) DetectCrashes() []LifecycleRecord {
219: 	actives := s.ListByState(LifecycleActive)
220: 
221: 	var crashed []LifecycleRecord
222: 	for _, rec := range actives {
223: 		if rec.DaemonPID <= 0 {
224: 			continue
225: 		}
226: 		if processAlive(rec.DaemonPID) {
227: 			// PID exists, but is it the same process? Check start time.
228: 			if rec.ProcStartTime > 0 {
229: 				current := procStartTime(rec.DaemonPID)
230: 				if current > 0 && current != rec.ProcStartTime {
231: 					// PID was reused by a different process — treat as dead.
232: 					logrus.WithFields(logrus.Fields{
233: 						"id":               rec.ID,
234: 						"daemon_pid":       rec.DaemonPID,
235: 						"expected_start":   rec.ProcStartTime,
236: 						"actual_start":     current,
237: 					}).Warn("PID reused by different process — treating as crashed")
238: 				} else {
239: 					continue // same process, still alive
240: 				}
241: 			} else {
242: 				continue // no start time recorded, trust PID
243: 			}
244: 		}
245: 		// Process is dead — transition to crashed.
246: 		logrus.WithFields(logrus.Fields{
247: 			"id":         rec.ID,
248: 			"daemon_pid": rec.DaemonPID,
249: 		}).Warn("daemon process died — marking session as crashed")
250: 		if err := s.Transition(rec.ID, LifecycleActive, LifecycleCrashed); err != nil {
251: 			logrus.WithError(err).WithField("id", rec.ID).Warn("failed to transition to crashed")
252: 			continue
253: 		}
254: 		rec.State = LifecycleCrashed
255: 		rec.UpdatedAt = time.Now()
256: 		crashed = append(crashed, rec)
257: 	}
258: 	return crashed
259: }
260: 
261: // writeAtomic writes rec to a .tmp file and then renames it into place,
262: // guaranteeing an all-or-nothing update.
263: func (s *LifecycleStore) writeAtomic(rec LifecycleRecord) error {
264: 	p := s.path(rec.ID)
265: 	tmp := p + ".tmp"
266: 
267: 	data, err := json.MarshalIndent(rec, "", "  ")
268: 	if err != nil {
269: 		return fmt.Errorf("marshal lifecycle record: %w", err)
270: 	}
271: 
272: 	if err := os.WriteFile(tmp, data, 0600); err != nil {
273: 		return fmt.Errorf("write temp file: %w", err)
274: 	}
275: 	if err := os.Rename(tmp, p); err != nil {
276: 		os.Remove(tmp) // best-effort cleanup
277: 		return fmt.Errorf("rename temp file: %w", err)
278: 	}
279: 	return nil
