 98: // Validate checks that mutually-required option groups are consistent.
 99: // It returns an aggregate error describing all missing dependencies.
100: func (o *Options) Validate() error {
101: 	if o == nil {
102: 		return errors.New("server options are nil")
103: 	}
104: 
105: 	var errs []error
106: 
107: 	if o.AuthEnabled {
108: 		if o.PasswordStore == nil {
109: 			errs = append(errs, errors.New("auth enabled but PasswordStore is nil"))
110: 		}
111: 		if o.SessionMgr == nil {
112: 			errs = append(errs, errors.New("auth enabled but SessionMgr is nil"))
113: 		}
114: 	}
115: 
116: 	if o.PeerMgr != nil {
117: 		if o.Identity == nil {
118: 			errs = append(errs, errors.New("PeerMgr configured but Identity is nil"))
119: 		}
120: 		if o.PeerStore == nil {
121: 			errs = append(errs, errors.New("PeerMgr configured but PeerStore is nil"))
122: 		}
123: 		if o.LinkSupervisor == nil {
124: 			errs = append(errs, errors.New("PeerMgr configured but LinkSupervisor is nil"))
125: 		}
126: 	}
127: 
128: 	if o.SchedulerStore != nil && o.Launch == nil {
129: 		errs = append(errs, errors.New("SchedulerStore configured but Launch is nil"))
130: 	}
131: 
132: 	if o.SchedulerRunner != nil && o.SchedulerStore == nil {
133: 		errs = append(errs, errors.New("SchedulerRunner configured but SchedulerStore is nil"))
134: 	}
135: 
136: 	if o.PortForwardStore != nil && (o.Port < 1 || o.Port > 65535) {
137: 		errs = append(errs, fmt.Errorf("PortForwardStore configured but Port %d is invalid", o.Port))
138: 	}
139: 
140: 	if len(errs) == 1 {
141: 		return errs[0]
142: 	}
143: 	if len(errs) > 1 {
144: 		out := "server options validation failed:"
145: 		for _, e := range errs {
146: 			out += "\n- " + e.Error()
147: 		}
148: 		return errors.New(out)
149: 	}
150: 	return nil
