288: function sessionKeyFromLeaves(state: WorkspaceStateWithStreaks): string[] {
289:   const tree = state.view.paneTree
290:   if (!tree) return []
291:   const leaves: string[] = []
292:   walk(tree)
293:   return leaves
294: 
295:   function walk(node: { type: 'leaf'; sessionKey: string } | { type: 'split'; first: typeof node; second: typeof node }) {
296:     if (node.type === 'leaf') leaves.push(node.sessionKey)
297:     else {
298:       walk(node.first)
299:       walk(node.second)
300:     }
301:   }
