 56: export type WorkspaceAction =
 57:   | { type: 'connection'; live: boolean; livenessUnknown: boolean }
 58:   | { type: 'sessions/snapshot'; sessions: Session[]; generation: number; now: number }
 59:   | { type: 'sessions/event'; event: SessionEvent; generation: number }
 60:   | { type: 'optimistic/add'; session: Session; now?: number }
 61:   | { type: 'optimistic/remove'; name: string; host?: string }
 62:   | { type: 'sessions/remove'; key: string }
 63:   | { type: 'groups/snapshot'; groups: GroupRecordMap; generation?: number }
 64:   | { type: 'groups/delta'; groups: GroupRecordMap; generation?: number }
 65:   | { type: 'view/select'; key: string }
 66:   | { type: 'view/navigate'; view?: View; sessionKey?: string | null }
 67:   | { type: 'view/openSettings'; open: boolean }
 68:   | { type: 'view/setSingleView'; sessionKey: string | null }
 69:   | { type: 'view/setCurrentView'; view: View }
 70:   | { type: 'view/close'; sessionKey: string }
