 72:   | { type: 'view/split'; targetKey: string; direction: 'h' | 'v'; newKey: string; newFirst?: boolean }
 73:   | { type: 'view/move'; sourceKey: string; targetKey: string; edge: 'left' | 'right' | 'top' | 'bottom' }
