107: const STUB_TTL_MS = 6000
108: const WIKI_HISTORY_MAX = 20
109: 
110: export function sessionKey(session: Session): string {
111:   return session.host ? `${session.host}/${session.name}` : session.name
112: }
113: 
114: export function parseSessionKey(key: string): { host: string; name: string } {
115:   const idx = key.indexOf('/')
116:   if (idx === -1) return { host: '', name: key }
117:   return { host: key.substring(0, idx), name: key.substring(idx + 1) }
118: }
