120: export interface WorkspaceStateWithStreaks extends WorkspaceState {
121:   missingStreaks: Record<string, MissingStreak>
122: }
123: 
124: export function createInitialWorkspaceState(input?: {
125:   view?: Partial<WorkspaceView>
126:   activeGroupId?: string
127: }): WorkspaceStateWithStreaks {
128:   const groupId = input?.activeGroupId ?? randomId()
129:   return {
130:     sessions: [],
131:     loading: true,
132:     optimistic: {},
133:     connection: {
134:       live: false,
135:       livenessUnknown: true,
136:     },
137:     transportGeneration: 0,
138:     groups: {},
139:     groupsLoaded: false,
140:     missingStreaks: {},
141:     view: {
142:       currentView: 'overview',
143:       settingsOpen: false,
144:       paneTree: null,
145:       activeKey: null,
146:       singleView: null,
147:       activeGroupId: groupId,
148:       ...input?.view,
149:     },
150:     wiki: {
151:       target: null,
152:       history: [],
153:     },
154:   }
155: }
156: 
157: function randomId() {
158:   return Math.random().toString(36).slice(2)
159: }
160: 
161: function matchesKey(s: Session, key: string): boolean {
162:   return sessionKey(s) === key
163: }
164: 
165: function matchesNameHost(s: Session, name: string, host?: string): boolean {
166:   if (host === undefined) return s.name === name
167:   return s.name === name && (s.host || '') === host
168: }
169: 
170: function reconcileSnapshot(
171:   state: WorkspaceState,
172:   sessions: Session[],
173:   now: number,
174: ): Session[] {
175:   const confirmed = new Set(sessions.map(s => s.name))
176:   const nextOptimistic: Record<string, number> = {}
177:   for (const [name, insertedAt] of Object.entries(state.optimistic)) {
178:     if (confirmed.has(name) || now - insertedAt > STUB_TTL_MS) continue
179:     nextOptimistic[name] = insertedAt
180:   }
181:   const kept = state.sessions.filter(s => nextOptimistic[s.name] !== undefined)
182:   const merged = [...kept]
183:   for (const s of sessions) {
184:     const idx = merged.findIndex(x => x.name === s.name && (x.host || '') === (s.host || ''))
185:     if (idx === -1) merged.push(s)
186:     else merged[idx] = s
187:   }
188:   return merged
189: }
190: 
191: function upsertSessionByKey(sessions: Session[], session: Session): Session[] {
192:   const idx = sessions.findIndex(s => s.name === session.name && (s.host || '') === (session.host || ''))
193:   if (idx === -1) return [...sessions, session]
194:   const copy = sessions.slice()
195:   copy[idx] = session
196:   return copy
197: }
198: 
199: function removeSessionByKey(sessions: Session[], key: string): Session[] {
200:   return sessions.filter(s => sessionKey(s) !== key)
201: }
202: 
203: function applyRenameToWiki(wiki: WikiState, oldKey: string, newKey: string): WikiState {
204:   const { host: oldHost, name: oldName } = parseSessionKey(oldKey)
205:   const { host: newHost, name: newName } = parseSessionKey(newKey)
206:   const rebuild = (t: WikiTarget | null): WikiTarget | null => {
207:     if (!t || t.session !== oldName || (t.hostId ?? '') !== oldHost) return t
208:     return { ...t, session: newName, hostId: newHost || undefined }
209:   }
210:   return {
211:     target: rebuild(wiki.target),
212:     history: wiki.history.map(rebuild).filter((t): t is WikiTarget => t !== null),
213:   }
214: }
