216: function selectViewKey(view: WorkspaceView, key: string): WorkspaceView {
217:   if (view.paneTree && findLeaf(view.paneTree, key)) {
218:     return { ...view, currentView: 'session', singleView: null, activeKey: key }
219:   }
220:   return { ...view, currentView: 'session', singleView: key }
221: }
222: 
223: function navigateTo(view: WorkspaceView, targetView?: View, sessionKey?: string | null): WorkspaceView {
224:   if (targetView === 'settings') {
225:     return { ...view, currentView: 'overview', settingsOpen: true }
226:   }
227:   if (sessionKey) return selectViewKey(view, sessionKey)
228:   return { ...view, currentView: targetView ?? 'overview' }
229: }
230: 
231: function closePane(view: WorkspaceView, sessionKey: string): WorkspaceView {
232:   if (!view.paneTree) return view
233:   const nextTree = removeLeaf(view.paneTree, sessionKey)
234:   if (nextTree === null) {
235:     return { ...view, paneTree: null, activeKey: null }
236:   }
237:   const nextActive =
238:     sessionKey === view.activeKey ? getLeaves(nextTree)[0] ?? null : view.activeKey
239:   return { ...view, paneTree: nextTree, activeKey: nextActive }
240: }
241: 
242: function removeFromLayout(view: WorkspaceView, sessionKey: string): WorkspaceView {
243:   const next = closePane(view, sessionKey)
244:   return { ...next, singleView: next.singleView === sessionKey ? null : next.singleView }
245: }
246: 
247: function splitPane(
248:   view: WorkspaceView,
249:   targetKey: string,
250:   direction: 'h' | 'v',
251:   newKey: string,
252:   newFirst?: boolean,
253: ): WorkspaceView {
254:   if (!view.paneTree) {
255:     if (targetKey) {
256:       const base = popOut(targetKey)
257:       if (base.type === 'leaf' && base.sessionKey === targetKey) {
258:         return {
259:           ...view,
260:           paneTree: splitLeaf(base, targetKey, direction, newKey),
261:           activeKey: newKey,
262:           currentView: 'session',
263:           singleView: null,
264:         }
265:       }
266:     }
267:     return { ...view, paneTree: popOut(newKey), activeKey: newKey, currentView: 'session', singleView: null }
268:   }
269:   if (findLeaf(view.paneTree, newKey)) {
270:     return { ...view, activeKey: newKey, currentView: 'session', singleView: null }
271:   }
272:   if (findLeaf(view.paneTree, targetKey)) {
273:     const nextTree = newFirst
274:       ? insertBesideLeaf(view.paneTree, targetKey, direction, newKey, true)
275:       : splitLeaf(view.paneTree, targetKey, direction, newKey)
276:     return { ...view, paneTree: nextTree, activeKey: newKey, currentView: 'session', singleView: null }
277:   }
278:   return { ...view, currentView: 'session', singleView: newKey }
279: }
