281: function movePaneView(
282:   view: WorkspaceView,
283:   sourceKey: string,
284:   targetKey: string,
285:   edge: 'left' | 'right' | 'top' | 'bottom',
286: ): WorkspaceView {
287:   if (!view.paneTree) return view
288:   const nextTree = movePane(view.paneTree, sourceKey, targetKey, edge)
289:   return { ...view, paneTree: nextTree }
290: }
291: 
292: function swapPaneView(view: WorkspaceView, a: string, b: string): WorkspaceView {
293:   if (!view.paneTree) return view
294:   return { ...view, paneTree: swapLeaves(view.paneTree, a, b) }
295: }
