302: export function workspaceReducer(
303:   stateArg: WorkspaceStateWithStreaks,
304:   action: WorkspaceAction,
305: ): WorkspaceStateWithStreaks {
306:   let state = stateArg
307: 
308:   // Transport generation gate: ignore stale transport actions.
309:   if ('generation' in action && typeof action.generation === 'number') {
310:     if (action.generation < state.transportGeneration) {
311:       return state
312:     }
313:     state = { ...state, transportGeneration: action.generation }
314:   }
315: 
316:   switch (action.type) {
317:     case 'connection': {
318:       return {
319:         ...state,
320:         connection: { live: action.live, livenessUnknown: action.livenessUnknown },
321:       }
322:     }
323: 
324:     case 'sessions/snapshot': {
325:       const merged = reconcileSnapshot(state, action.sessions, action.now)
326:       const notEmpty = action.sessions.length > 0
327:       const connection = notEmpty
328:         ? { ...state.connection, livenessUnknown: false }
329:         : state.connection
330:       return {
331:         ...state,
332:         sessions: merged,
333:         loading: false,
334:         connection,
335:       }
336:     }
337: 
338:     case 'sessions/event': {
339:       const { event } = action
340:       if (event.type === 'session-added') {
341:         const name = event.session || ''
342:         const existing = state.sessions.find(s => s.name === name && (s.host || '') === (event.host || ''))
343:         if (existing) return state
344:         const stub = state.sessions.find(
345:           s => s.name === name && (s.host || '') === (event.host || '') && !s.id,
346:         )
347:         if (stub) return state
348:         return state
349:       }
350:       if (event.type === 'session-removed') {
351:         const key = event.host ? `${event.host}/${event.session}` : event.session || ''
352:         return {
353:           ...state,
354:           sessions: removeSessionByKey(state.sessions, key),
355:         }
356:       }
357:       if (event.type === 'session-renamed') {
358:         const oldName = event.session || ''
359:         const newName = event.data?.new_name || ''
360:         if (!oldName || !newName) return state
361:         const oldKey = event.host ? `${event.host}/${oldName}` : oldName
362:         const newKey = event.host ? `${event.host}/${newName}` : newName
363:         const idx = state.sessions.findIndex(s => sessionKey(s) === oldKey)
364:         if (idx === -1) return state
365:         const renamed = { ...state.sessions[idx], name: newName }
366:         const sessions = [...state.sessions.slice(0, idx), renamed, ...state.sessions.slice(idx + 1)]
367:         let view = state.view
368:         if (view.paneTree && findLeaf(view.paneTree, oldKey)) {
369:           if (findLeaf(view.paneTree, newKey)) {
370:             view = { ...view, paneTree: removeLeaf(view.paneTree, oldKey) ?? view.paneTree }
371:           } else {
372:             view = { ...view, paneTree: replaceLeaf(view.paneTree, oldKey, newKey) }
373:           }
374:         }
375:         view = {
376:           ...view,
377:           activeKey: view.activeKey === oldKey ? newKey : view.activeKey,
378:           singleView: view.singleView === oldKey ? newKey : view.singleView,
379:         }
380:         return {
381:           ...state,
382:           sessions,
383:           view,
384:           wiki: applyRenameToWiki(state.wiki, oldKey, newKey),
385:         }
386:       }
387:       if (event.type === 'sessions-changed') {
388:         return state
389:       }
390:       return state
391:     }
392: 
393:     case 'optimistic/add': {
394:       const session = action.session
395:       const nextOptimistic = { ...state.optimistic, [session.name]: action.now ?? Date.now() }
396:       return {
397:         ...state,
398:         optimistic: nextOptimistic,
399:         sessions: upsertSessionByKey(state.sessions, session),
400:       }
401:     }
402: 
403:     case 'optimistic/remove': {
404:       const nextOptimistic = { ...state.optimistic }
405:       delete nextOptimistic[action.name]
406:       return {
407:         ...state,
408:         optimistic: nextOptimistic,
409:         sessions: state.sessions.filter(s => !matchesNameHost(s, action.name, action.host)),
410:       }
411:     }
412: 
413:     case 'sessions/remove': {
414:       return { ...state, sessions: removeSessionByKey(state.sessions, action.key) }
415:     }
416: 
417:     case 'groups/snapshot': {
418:       // A full server snapshot is authoritative: absent groups are removed.
419:       return {
420:         ...state,
421:         groups: action.groups,
422:         groupsLoaded: true,
423:       }
424:     }
425: 
426:     case 'groups/delta': {
427:       // Deltas merge into the existing map.
428:       return {
429:         ...state,
430:         groups: { ...state.groups, ...action.groups },
431:         groupsLoaded: true,
432:       }
433:     }
434: 
435:     case 'view/select': {
436:       return { ...state, view: selectViewKey(state.view, action.key) }
437:     }
438: 
439:     case 'view/navigate': {
440:       return { ...state, view: navigateTo(state.view, action.view, action.sessionKey) }
441:     }
442: 
443:     case 'view/openSettings': {
444:       return { ...state, view: { ...state.view, settingsOpen: action.open } }
445:     }
446: 
447:     case 'view/setSingleView': {
448:       return { ...state, view: { ...state.view, singleView: action.sessionKey } }
449:     }
450: 
451:     case 'view/setCurrentView': {
452:       return { ...state, view: { ...state.view, currentView: action.view } }
453:     }
454: 
455:     case 'view/close': {
456:       return { ...state, view: closePane(state.view, action.sessionKey) }
457:     }
458: 
459:     case 'view/removeFromLayout': {
460:       return { ...state, view: removeFromLayout(state.view, action.sessionKey) }
461:     }
462: 
463:     case 'view/split': {
464:       return {
465:         ...state,
466:         view: splitPane(state.view, action.targetKey, action.direction, action.newKey, action.newFirst),
467:       }
468:     }
469: 
470:     case 'view/move': {
471:       return { ...state, view: movePaneView(state.view, action.sourceKey, action.targetKey, action.edge) }
472:     }
473: 
474:     case 'view/swap': {
475:       return { ...state, view: swapPaneView(state.view, action.a, action.b) }
476:     }
477: 
478:     case 'view/setPaneTree': {
479:       return { ...state, view: { ...state.view, paneTree: action.tree } }
480:     }
481: 
482:     case 'view/setActiveGroup': {
483:       const { groupId, tree, focusKey } = action
484:       return {
485:         ...state,
486:         view: {
487:           ...state.view,
488:           activeGroupId: groupId,
489:           paneTree: tree ?? state.view.paneTree,
490:           activeKey:
491:             focusKey !== undefined
492:               ? focusKey
493:               : state.view.activeGroupId === groupId
494:                 ? state.view.activeKey
495:                 : null,
496:           singleView: null,
497:           currentView: 'session',
498:         },
499:       }
500:     }
501: 
502:     case 'view/setActiveKey': {
503:       return { ...state, view: { ...state.view, activeKey: action.key } }
504:     }
505: 
506:     case 'view/dissolveToSingle': {
507:       const leaves = state.view.paneTree ? getLeaves(state.view.paneTree) : []
508:       if (leaves.length !== 1) return state
509:       return {
510:         ...state,
511:         view: {
512:           ...state.view,
513:           paneTree: null,
514:           singleView: leaves[0] ?? null,
515:           activeKey: null,
516:           currentView: 'session',
517:         },
518:       }
519:     }
520: 
521:     case 'view/promoteNextGroup': {
522:       const entries = Object.entries(state.groups).sort(([, a], [, b]) => {
523:         const ar = a.rank ?? ''
524:         const br = b.rank ?? ''
525:         if (!ar && br) return 1
526:         if (ar && !br) return -1
527:         if (ar !== br) return ar.localeCompare(br)
528:         return 0
529:       })
530:       const next = entries.find(([id]) => id !== state.view.activeGroupId)
531:       if (!next) {
532:         return {
533:           ...state,
534:           view: {
535:             ...state.view,
536:             paneTree: null,
537:             activeKey: null,
538:             singleView: null,
539:             currentView: 'overview',
540:           },
541:         }
542:       }
543:       const [nextId, nextGroup] = next
544:       const leaves = getLeaves(nextGroup.tree)
545:       return {
546:         ...state,
547:         view: {
548:           ...state.view,
549:           activeGroupId: nextId,
550:           paneTree: nextGroup.tree,
551:           activeKey: leaves[0] ?? null,
552:           singleView: null,
553:           currentView: 'session',
554:         },
555:       }
556:     }
557: 
558:     case 'view/pruneMissing': {
559:       const { validKeys, now } = action
560:       const live = state.connection.live && !state.connection.livenessUnknown
561:       if (!state.view.paneTree) {
562:         return {
563:           ...state,
564:           view: {
565:             ...state.view,
566:             singleView: validKeys.includes(state.view.singleView ?? '') ? state.view.singleView : null,
567:           },
568:           missingStreaks: {},
569:         }
570:       }
571:       const streaks = { ...(state.missingStreaks || {}) }
572:       const leaves = getLeaves(state.view.paneTree)
573:       const toRemove: string[] = []
574:       for (const key of leaves) {
575:         if (validKeys.includes(key)) {
576:           delete streaks[key]
577:           continue
578:         }
579:         const prev = streaks[key]
580:         if (!prev) {
581:           streaks[key] = { count: 1, last: now }
582:           continue
583:         }
584:         if (now - prev.last < 1000) continue
585:         if (prev.count + 1 >= 2) {
586:           if (live) toRemove.push(key)
587:           delete streaks[key]
588:         } else {
589:           streaks[key] = { count: prev.count + 1, last: now }
590:         }
591:       }
592:       if (toRemove.length === 0) {
593:         return {
594:           ...state,
595:           view: {
596:             ...state.view,
597:             singleView: validKeys.includes(state.view.singleView ?? '') ? state.view.singleView : null,
598:           },
599:           missingStreaks: streaks,
600:         }
601:       }
602:       let tree: PaneTree | null = state.view.paneTree
603:       for (const key of toRemove) {
604:         if (tree === null) break
605:         tree = removeLeaf(tree, key)
606:       }
607:       const remainingLeaves = tree ? getLeaves(tree) : []
608:       const activeKey =
609:         tree && state.view.activeKey && toRemove.includes(state.view.activeKey)
610:           ? remainingLeaves[0] ?? null
611:           : state.view.activeKey
612:       return {
613:         ...state,
614:         view: {
615:           ...state.view,
616:           paneTree: tree,
617:           activeKey,
618:           singleView: validKeys.includes(state.view.singleView ?? '') ? state.view.singleView : null,
619:         },
620:         missingStreaks: streaks,
621:       }
622:     }
623: 
624:     case 'rename': {
625:       const { oldKey, newKey } = action
626:       if (!oldKey || !newKey || oldKey === newKey) return state
627:       let sessions = state.sessions
628:       const idx = state.sessions.findIndex(s => sessionKey(s) === oldKey)
629:       if (idx !== -1) {
630:         sessions = [
631:           ...state.sessions.slice(0, idx),
632:           { ...state.sessions[idx], name: parseSessionKey(newKey).name },
633:           ...state.sessions.slice(idx + 1),
634:         ]
635:       }
636:       let view = state.view
637:       if (view.paneTree && findLeaf(view.paneTree, oldKey)) {
638:         if (findLeaf(view.paneTree, newKey)) {
639:           view = { ...view, paneTree: removeLeaf(view.paneTree, oldKey) ?? view.paneTree }
640:         } else {
641:           view = { ...view, paneTree: replaceLeaf(view.paneTree, oldKey, newKey) }
642:         }
643:       }
644:       view = {
645:         ...view,
646:         activeKey: view.activeKey === oldKey ? newKey : view.activeKey,
647:         singleView: view.singleView === oldKey ? newKey : view.singleView,
648:       }
649:       return {
650:         ...state,
651:         sessions,
652:         view,
653:         wiki: applyRenameToWiki(state.wiki, oldKey, newKey),
654:       }
655:     }
656: 
657:     case 'wiki/open': {
658:       const history = [action.target, ...state.wiki.history.filter(t => t.path !== action.target.path)].slice(0, WIKI_HISTORY_MAX)
659:       return { ...state, wiki: { target: action.target, history } }
660:     }
661: 
662:     case 'wiki/close': {
663:       return { ...state, wiki: { ...state.wiki, target: null } }
664:     }
665: 
666:     case 'restore': {
667:       const s = action.snapshot
668:       return {
669:         ...state,
670:         ...s,
671:         view: { ...state.view, ...(s.view ?? {}) },
672:         wiki: { ...state.wiki, ...(s.wiki ?? {}) },
673:       }
674:     }
675: 
676:     case 'legacy/migrate': {
677:       return state
678:     }
679: 
680:     default:
681:       return state
682:   }
683: }
