685: // Legacy migration planner. Pure: given local legacy data and current server
686: // groups/order, return the sync operations needed to upload missing ranks.
687: export function planLegacyMigration(
688:   legacy: LegacyMigrationInput,
689:   currentGroups: GroupRecordMap,
690:   currentSessionOrder: Record<string, string>,
691:   activeGroupId: string,
692:   activeTree?: PaneTree | null,
693:   activeName?: string,
694: ): {
695:   groupRanks: { id: string; rank: string; tree?: PaneTree; name?: string }[]
696:   sessionRanks: { key: string; rank: string }[]
697:   order: string[]
698: } {
699:   const orderIds =
700:     Array.isArray(legacy.order) && legacy.order.length > 0
701:       ? legacy.order.filter((id): id is string => typeof id === 'string')
702:       : [activeGroupId, ...legacy.groups.map(g => g.id)]
703:   const uniqueOrder = orderIds.filter((id, idx, all) => id && all.indexOf(id) === idx)
704:   const legacyById = new Map(legacy.groups.map(g => [g.id, g]))
705: 
706:   const groupRanks: { id: string; rank: string; tree?: PaneTree; name?: string }[] = []
707:   let prevRank: string | null = null
708:   for (const id of uniqueOrder) {
709:     const serverGroup = currentGroups[id]
710:     if (serverGroup?.rank) {
711:       prevRank = serverGroup.rank
712:       continue
713:     }
714:     const rank = generateKeyBetween(prevRank, null)
715:     const localGroup =
716:       id === activeGroupId && activeTree
717:         ? { id, tree: activeTree, name: activeName }
718:         : legacyById.get(id)
719:     groupRanks.push({
720:       id,
721:       rank,
722:       ...(localGroup?.tree ? { tree: localGroup.tree } : {}),
723:       ...(localGroup?.name ? { name: localGroup.name } : {}),
724:     })
725:     prevRank = rank
726:   }
727: 
728:   const sessionRanks: { key: string; rank: string }[] = []
729:   let prevSessionRank: string | null = null
730:   const sessionIds = Array.isArray(legacy.sessionOrder)
731:     ? legacy.sessionOrder.filter((id): id is string => typeof id === 'string')
732:     : []
733:   for (const key of sessionIds) {
734:     if (currentSessionOrder[key]) {
735:       prevSessionRank = currentSessionOrder[key]
736:       continue
737:     }
738:     const rank = generateKeyBetween(prevSessionRank, null)
739:     sessionRanks.push({ key, rank })
740:     prevSessionRank = rank
741:   }
742: 
743:   return { groupRanks, sessionRanks, order: uniqueOrder }
744: }  1: package pty
