 10: func TestReadSystemdUnit_FromLifecycleRecord(t *testing.T) {
 11: 	dir := t.TempDir()
 12: 
 13: 	store, err := NewLifecycleStore(dir)
 14: 	if err != nil {
 15: 		t.Fatal(err)
 16: 	}
 17: 
 18: 	reg := NewRegistry(t.TempDir())
 19: 	reg.SetLifecycleStore(store)
 20: 
 21: 	// Write a lifecycle record with systemd unit.
 22: 	lr := LifecycleRecord{
 23: 		ID:          "test-session",
 24: 		State:       LifecycleActive,
 25: 		DaemonPID:   12345,
 26: 		SystemdUnit: "termyard-session-test-session-123.scope",
 27: 	}
 28: 	if err := store.RecordActive(lr); err != nil {
 29: 		t.Fatal(err)
 30: 	}
 31: 
 32: 	got := reg.readSystemdUnit("test-session")
 33: 	if got != "termyard-session-test-session-123.scope" {
 34: 		t.Errorf("readSystemdUnit = %q, want %q", got, "termyard-session-test-session-123.scope")
 35: 	}
 36: }
