136: func TestIsSessionDead(t *testing.T) {
137: 	stateDir := t.TempDir()
138: 	store, err := NewLifecycleStore(stateDir)
139: 	if err != nil {
140: 		t.Fatal(err)
141: 	}
142: 	reg := NewRegistry(t.TempDir())
143: 	reg.SetLifecycleStore(store)
144: 
145: 	if err := store.RecordActive(LifecycleRecord{ID: "alive", DaemonPID: 999999}); err != nil {
146: 		t.Fatal(err)
147: 	}
148: 	// RecordActive forces state=active, so write terminal-state records directly
149: 	// via the atomic writer to set the exact state we need to exercise.
150: 	for _, s := range []string{LifecycleCleanlyEnded, LifecycleTerminationRequested, LifecycleDismissed, LifecycleCrashed} {
151: 		id := "ended"
152: 		switch s {
153: 		case LifecycleTerminationRequested:
154: 			id = "killed"
155: 		case LifecycleDismissed:
156: 			id = "dismissed"
157: 		case LifecycleCrashed:
158: 			id = "crashed"
159: 		}
160: 		if err := store.writeAtomic(LifecycleRecord{ID: id, State: s}); err != nil {
161: 			t.Fatal(err)
162: 		}
163: 	}
164: 
165: 	tests := []struct {
166: 		name string
167: 		want bool
168: 	}{
169: 		{"alive", false},
170: 		{"ended", true},
171: 		{"killed", true},
172: 		{"dismissed", true},
173: 		{"crashed", false}, // preserved for recovery, not dead
174: 		{"missing", false}, // no record
175: 	}
176: 	for _, tc := range tests {
177: 		if got := reg.IsSessionDead(tc.name); got != tc.want {
178: 			t.Errorf("IsSessionDead(%q) = %v, want %v", tc.name, got, tc.want)
179: 		}
180: 	}
181: }
