183: func TestIsSessionDead_NoLifecycleStore(t *testing.T) {
184: 	reg := NewRegistry(t.TempDir())
185: 	// Conservative: no store configured → never claim dead.
186: 	if reg.IsSessionDead("anything") {
187: 		t.Errorf("expected false with no lifecycle store")
188: 	}
189: }
