191: // TestDetectAndCleanupCrashes verifies that crashed sessions are detected and
192: // their systemd scopes are stopped (best-effort). The scope-stop is a fire-and-
193: // forget operation; this test confirms the lifecycle transition is correct.
194: func TestDetectAndCleanupCrashes(t *testing.T) {
195: 	sockDir := t.TempDir()
196: 	stateDir := t.TempDir()
197: 
198: 	store, err := NewLifecycleStore(stateDir)
199: 	if err != nil {
200: 		t.Fatal(err)
201: 	}
202: 
203: 	reg := NewRegistry(sockDir)
204: 	reg.SetLifecycleStore(store)
205: 
206: 	// Write an active lifecycle record with a systemd unit.
207: 	lr := LifecycleRecord{
208: 		ID:          "crash-test",
209: 		State:       LifecycleActive,
210: 		DaemonPID:   999999, // non-existent PID → detected as crashed
211: 		SystemdUnit: "termyard-session-crash-test-123.scope",
212: 		Shell:       "/bin/bash",
213: 		Cwd:         "/tmp",
214: 		Cols:        120,
215: 		Rows:        40,
216: 	}
217: 	if err := store.RecordActive(lr); err != nil {
218: 		t.Fatal(err)
219: 	}
220: 
221: 	// Verify initial state.
222: 	rec, err := store.Get("crash-test")
223: 	if err != nil {
224: 		t.Fatal(err)
225: 	}
226: 	if rec.State != LifecycleActive {
227: 		t.Fatalf("expected state active, got %s", rec.State)
228: 	}
229: 
230: 	// Detect and clean up.
231: 	crashed := reg.DetectAndCleanupCrashes()
232: 	if len(crashed) != 1 {
233: 		t.Fatalf("expected 1 crashed session, got %d", len(crashed))
234: 	}
235: 	if crashed[0].ID != "crash-test" {
236: 		t.Errorf("expected crashed ID 'crash-test', got %s", crashed[0].ID)
237: 	}
238: 
239: 	// Verify state transitioned to crashed.
240: 	rec, err = store.Get("crash-test")
241: 	if err != nil {
242: 		t.Fatal(err)
243: 	}
244: 	if rec.State != LifecycleCrashed {
245: 		t.Errorf("expected state crashed, got %s", rec.State)
246: 	}
247: }
