259: // TestDismissSessionLocked_StopsScope verifies that dismiss stops the systemd
260: // scope before removing files. The scope-stop is fire-and-forget; we verify the
261: // files are removed and the lifecycle state is dismissed.
262: func TestDismissSessionLocked_StopsScope(t *testing.T) {
263: 	sockDir := t.TempDir()
264: 	stateDir := t.TempDir()
265: 
266: 	store, err := NewLifecycleStore(stateDir)
267: 	if err != nil {
268: 		t.Fatal(err)
269: 	}
270: 
271: 	reg := NewRegistry(sockDir)
272: 	reg.SetLifecycleStore(store)
273: 
274: 	// Create the socket file and metadata sidecar (simulating a crashed session).
275: 	sockPath := reg.SocketPath("dismiss-test")
276: 	if f, err := os.Create(sockPath); err != nil {
277: 		t.Fatal(err)
278: 	} else {
279: 		f.Close()
280: 	}
281: 	meta := sessionMeta{
282: 		ID:          "dismiss-test",
283: 		Pid:         12345,
284: 		ShellPid:    12346,
285: 		SystemdUnit: "termyard-session-dismiss-test-456.scope",
286: 	}
287: 	data, _ := json.Marshal(meta)
288: 	if err := os.WriteFile(reg.metadataPath("dismiss-test"), data, 0600); err != nil {
289: 		t.Fatal(err)
290: 	}
291: 
292: 	// Write lifecycle record in crashed state.
293: 	lr := LifecycleRecord{
294: 		ID:          "dismiss-test",
295: 		State:       LifecycleCrashed,
296: 		DaemonPID:   12345,
297: 		SystemdUnit: "termyard-session-dismiss-test-456.scope",
298: 	}
299: 	if err := store.RecordActive(lr); err != nil {
300: 		t.Fatal(err)
301: 	}
302: 	// Overwrite state to crashed (RecordActive sets active).
303: 	if err := store.Transition("dismiss-test", LifecycleActive, LifecycleCrashed); err != nil {
304: 		t.Fatal(err)
305: 	}
306: 
307: 	// Dismiss.
308: 	if err := reg.DismissSession("dismiss-test"); err != nil {
309: 		t.Fatal(err)
310: 	}
311: 
312: 	// Verify files are removed.
313: 	if _, err := os.Stat(sockPath); !os.IsNotExist(err) {
314: 		t.Error("socket file should be removed after dismiss")
315: 	}
316: 	if _, err := os.Stat(reg.metadataPath("dismiss-test")); !os.IsNotExist(err) {
317: 		t.Error("metadata file should be removed after dismiss")
318: 	}
319: 
320: 	// Verify lifecycle state is dismissed.
321: 	rec, err := store.Get("dismiss-test")
322: 	if err != nil {
323: 		t.Fatal(err)
324: 	}
325: 	if rec.State != LifecycleDismissed {
326: 		t.Errorf("expected state dismissed, got %s", rec.State)
327: 	}
328: }
