348: // TestDismissSession_NonCrashedIsNotKilled verifies that dismissing a
349: // non-crashed (active) session returns an error and does NOT stop its
350: // systemd scope. This is the regression test for the bug where
351: // dismissSessionLocked called stopSystemdScope before validating state.
352: func TestDismissSession_NonCrashedIsNotKilled(t *testing.T) {
353: 	sockDir := t.TempDir()
354: 	stateDir := t.TempDir()
355: 
356: 	store, err := NewLifecycleStore(stateDir)
357: 	if err != nil {
358: 		t.Fatal(err)
359: 	}
360: 
361: 	reg := NewRegistry(sockDir)
362: 	reg.SetLifecycleStore(store)
363: 
364: 	// Capture which units are stopped.
365: 	var stoppedUnits []string
366: 	reg.stopUnitFn = func(unit string) {
367: 		stoppedUnits = append(stoppedUnits, unit)
368: 	}
369: 
370: 	// Create socket and metadata files (simulating a live session).
371: 	if f, err := os.Create(reg.SocketPath("live-session")); err != nil {
372: 		t.Fatal(err)
373: 	} else {
374: 		f.Close()
375: 	}
376: 	meta := sessionMeta{
377: 		ID:          "live-session",
378: 		Pid:         12345,
379: 		SystemdUnit: "termyard-session-live-session-999.scope",
380: 	}
381: 	data, _ := json.Marshal(meta)
382: 	if err := os.WriteFile(reg.metadataPath("live-session"), data, 0600); err != nil {
383: 		t.Fatal(err)
384: 	}
385: 
386: 	// Write lifecycle record in ACTIVE state (not crashed).
387: 	lr := LifecycleRecord{
388: 		ID:          "live-session",
389: 		DaemonPID:   12345,
390: 		SystemdUnit: "termyard-session-live-session-999.scope",
391: 	}
392: 	if err := store.RecordActive(lr); err != nil {
393: 		t.Fatal(err)
394: 	}
395: 
396: 	// Attempt to dismiss — must fail because state is active, not crashed.
397: 	err = reg.DismissSession("live-session")
398: 	if err == nil {
399: 		t.Fatal("expected error dismissing active session, got nil")
400: 	}
401: 
402: 	// No systemd scope must have been stopped.
403: 	if len(stoppedUnits) > 0 {
404: 		t.Errorf("expected 0 scope stops, got %d: %v", len(stoppedUnits), stoppedUnits)
405: 	}
406: 
407: 	// Files must still exist (not cleaned up).
408: 	if _, err := os.Stat(reg.SocketPath("live-session")); os.IsNotExist(err) {
409: 		t.Error("socket file should still exist after failed dismiss")
410: 	}
411: 	if _, err := os.Stat(reg.metadataPath("live-session")); os.IsNotExist(err) {
412: 		t.Error("metadata file should still exist after failed dismiss")
413: 	}
414: }
