643: // TestLifecycleStore_DoesNotPolluteDefaultStateDir is a regression guard:
644: // benchmark and comparison tests must write lifecycle records only into their
645: // own isolated directories, never into the user's real state directory.
646: func TestLifecycleStore_DoesNotPolluteDefaultStateDir(t *testing.T) {
647: 	realDefault := DefaultStateDir()
648: 
649: 	controlled := t.TempDir()
650: 	t.Setenv("XDG_STATE_HOME", controlled)
651: 
652: 	isolated := t.TempDir()
653: 	reg := NewRegistry(t.TempDir())
654: 	store, err := NewLifecycleStore(isolated)
655: 	if err != nil {
656: 		t.Fatal(err)
657: 	}
658: 	reg.SetLifecycleStore(store)
659: 
660: 	const id = "lifecycle-isolation-probe"
661: 	if err := store.RecordActive(LifecycleRecord{ID: id, DaemonPID: 999999}); err != nil {
662: 		t.Fatal(err)
663: 	}
664: 
665: 	// The record must land only in the explicitly-provided state directory.
666: 	if _, err := os.Stat(filepath.Join(isolated, id+".lifecycle.json")); err != nil {
667: 		t.Fatalf("expected record in isolated dir: %v", err)
668: 	}
669: 
670: 	// It must NOT appear in the real default state directory.
671: 	entries, err := os.ReadDir(realDefault)
672: 	if err != nil && !os.IsNotExist(err) {
673: 		t.Fatalf("failed to read real default dir: %v", err)
674: 	}
675: 	for _, e := range entries {
676: 		if e.Name() == id+".lifecycle.json" {
677: 			t.Fatalf("lifecycle probe leaked into real state dir %s", realDefault)
678: 		}
679: 	}
680: }
