 24: // TestRouteTableSnapshot pins the current HTTP/WS route set and auth policy
 25: // using the real router construction. It builds the router with auth enabled
 26: // and walks chi routes, then asserts that public routes stay public and
 27: // protected routes require a session cookie.
 28: func TestRouteTableSnapshot(t *testing.T) {
 29: 	dir := t.TempDir()
 30: 	t.Setenv("HOME", dir)
 31: 
 32: 	ps, err := auth.NewPasswordStore()
 33: 	if err != nil {
 34: 		t.Fatalf("NewPasswordStore: %v", err)
 35: 	}
 36: 	if err := ps.SetPassword("hunter1234!"); err != nil {
 37: 		t.Fatalf("SetPassword: %v", err)
 38: 	}
 39: 	sm := auth.NewSessionManager(time.Hour)
 40: 	tracker := toolevents.NewTracker()
 41: 
 42: 	opts := &Options{
 43: 		AuthEnabled:      true,
 44: 		Port:             7654,
 45: 		PasswordStore:    ps,
 46: 		SessionMgr:       sm,
 47: 		AuthLimiter:      auth.NewLimiter(),
 48: 		NotifyToken:      "notify-token-test",
 49: 		Tracker:          tracker,
 50: 		Hub:              ws.NewHub(state.NewManager(), tracker),
 51: 		PortForwardStore: portforward.NewStore(),
 52: 	}
 53: 
 54: 	ctx, cancel := context.WithCancel(context.Background())
 55: 	defer cancel()
 56: 
 57: 	r, _, err := BuildRouter(ctx, opts)
 58: 	if err != nil {
 59: 		t.Fatalf("BuildRouter: %v", err)
 60: 	}
