202: func diff(a, b []string) (missing, extra []string) {
203: 	ma := map[string]bool{}
204: 	mb := map[string]bool{}
205: 	for _, v := range a {
206: 		ma[v] = true
207: 	}
208: 	for _, v := range b {
209: 		mb[v] = true
210: 	}
211: 	for _, v := range a {
212: 		if !mb[v] {
213: 			missing = append(missing, v)
214: 		}
215: 	}
216: 	for _, v := range b {
217: 		if !ma[v] {
218: 			extra = append(extra, v)
219: 		}
220: 	}
221: 	return
222: }
