224: // TestProxyMethodsForwards requests verifies that /proxy/{port}/* now accepts
225: // GET, POST, PUT, PATCH and DELETE and forwards the method to the upstream.
226: func TestProxyMethodsForwarded(t *testing.T) {
227: 	called := make(map[string]bool)
228: 	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
229: 		called[r.Method+" "+r.URL.Path] = true
230: 		w.WriteHeader(http.StatusOK)
231: 	}))
232: 	defer upstream.Close()
233: 
234: 	port := strings.TrimPrefix(upstream.URL, "http://127.0.0.1:")
235: 
236: 	opts := &Options{Port: 7654, PortForwardStore: portforward.NewStore()}
237: 	r := chi.NewRouter()
238: 	registerProxyFileRoutes(r, opts)
239: 
240: 	for _, method := range []string{http.MethodGet, http.MethodPost, http.MethodPut, http.MethodPatch, http.MethodDelete} {
241: 		req := httptest.NewRequest(method, "/proxy/"+port+"/hello", nil)
242: 		rec := httptest.NewRecorder()
243: 		r.ServeHTTP(rec, req)
244: 		if rec.Code != http.StatusOK {
245: 			t.Errorf("%s proxy got status %d", method, rec.Code)
246: 		}
247: 		if !called[method+" /hello"] {
248: 			t.Errorf("%s upstream was not called", method)
249: 		}
250: 	}
251: }
