253: // TestProxyHTMLRewriteCap verifies that HTML bodies larger than maxHTMLRewrite
254: // pass through unchanged while small HTML bodies are still rewritten.
255: func TestProxyHTMLRewriteCap(t *testing.T) {
256: 	rw := makeHTMLRewriter(1234)
257: 
258: 	// Large body: one byte over the cap should be forwarded unchanged.
259: 	large := bytes.Repeat([]byte("x"), maxHTMLRewrite+1)
260: 	resp := &http.Response{
261: 		Header:     http.Header{"Content-Type": []string{"text/html"}},
262: 		Body:       io.NopCloser(bytes.NewReader(large)),
263: 		StatusCode: http.StatusOK,
264: 	}
265: 	if err := rw(resp); err != nil {
266: 		t.Fatalf("large body rewrite error: %v", err)
267: 	}
268: 	out, err := io.ReadAll(resp.Body)
269: 	if err != nil {
270: 		t.Fatalf("read large body: %v", err)
271: 	}
272: 	if !bytes.Equal(out, large) {
273: 		t.Errorf("large body was modified: got %d bytes, want %d bytes", len(out), len(large))
274: 	}
275: 
276: 	// Small body with an absolute path should be rewritten.
277: 	small := []byte(`<html><a href="/foo">link</a></html>`)
278: 	resp = &http.Response{
279: 		Header:     http.Header{"Content-Type": []string{"text/html"}},
280: 		Body:       io.NopCloser(bytes.NewReader(small)),
281: 		StatusCode: http.StatusOK,
282: 	}
283: 	if err := rw(resp); err != nil {
284: 		t.Fatalf("small body rewrite error: %v", err)
285: 	}
286: 	out, err = io.ReadAll(resp.Body)
287: 	if err != nil {
288: 		t.Fatalf("read small body: %v", err)
289: 	}
290: 	if !bytes.Contains(out, []byte("/proxy/1234/foo")) {
291: 		t.Errorf("small body not rewritten: %s", string(out))
292: 	}
