 21: // registerAPIRoutes mounts the /api tree, including public auth/version/tool
 22: // endpoints, the protected session/peer/scheduler group, and portforwards.
 23: func registerAPIRoutes(r chi.Router, opts *Options, hub *ws.Hub, coordinator *groupNamingCoordinator) {
 24: 	r.Route("/api", func(r chi.Router) {
 25: 		// Public auth endpoints (no middleware)
 26: 		r.Get("/auth/status", auth.StatusHandler(opts.AuthEnabled, opts.PasswordStore))
 27: 		if opts.AuthEnabled {
 28: 			r.Post("/auth/setup", auth.SetupHandler(opts.PasswordStore, opts.SessionMgr, opts.AuthLimiter))
 29: 			r.Post("/auth/login", auth.LoginHandler(opts.PasswordStore, opts.SessionMgr, opts.AuthLimiter))
 30: 			r.Post("/auth/logout", auth.LogoutHandler(opts.SessionMgr))
 31: 			r.Get("/auth/check", auth.CheckHandler(opts.SessionMgr))
 32: 		}
 33: 
 34: 		bootstrapLimit := func(next http.Handler) http.Handler {
 35: 			return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
 36: 				if opts.AuthLimiter == nil {
 37: 					next.ServeHTTP(w, r)
 38: 					return
 39: 				}
 40: 				if ok, retry := opts.AuthLimiter.Allow("bootstrap", auth.ClientIP(r)); !ok {
 41: 					seconds := int(retry.Seconds())
 42: 					if seconds < 1 {
 43: 						seconds = 1
 44: 					}
 45: 					w.Header().Set("Content-Type", "application/json")
 46: 					w.Header().Set("Retry-After", fmt.Sprintf("%d", seconds))
 47: 					w.WriteHeader(http.StatusTooManyRequests)
 48: 					fmt.Fprintf(w, `{"error":"rate limit","retry_after":%d}`, seconds)
 49: 					return
 50: 				}
 51: 				next.ServeHTTP(w, r)
 52: 			})
 53: 		}
 54: 
 55: 		// Peer bootstrap endpoint -- password-authenticated (no session cookie).
 56: 		// Lets two nodes establish mutual trust via the dashboard password.
 57: 		r.With(bootstrapLimit).Post("/peers/bootstrap", func(w http.ResponseWriter, r *http.Request) {
 58: 			handlePeersBootstrap(w, r, opts)
 59: 		})
 60: 
 61: 		// Version endpoint -- public, no auth required
 62: 		r.Get("/version", func(w http.ResponseWriter, r *http.Request) {
 63: 			w.Header().Set("Content-Type", "application/json")
 64: 			json.NewEncoder(w).Encode(map[string]string{
 65: 				"version": common.VERSION,
 66: 				"commit":  common.COMMIT,
 67: 			})
 68: 		})
 69: 		// Tool event ingest. Unix-socket requests are trusted; TCP requests must
 70: 		// present the local notify bearer token when auth is enabled.
 71: 		r.Post("/tool-event", func(w http.ResponseWriter, r *http.Request) {
 72: 			if !auth.IsUnixSocket(r) && opts.AuthEnabled {
 73: 				if !auth.ValidBearer(r, opts.NotifyToken) {
 74: 					w.Header().Set("Content-Type", "application/json")
 75: 					w.WriteHeader(http.StatusUnauthorized)
 76: 					fmt.Fprintf(w, `{"error":"unauthorized"}`)
 77: 					return
 78: 				}
 79: 			}
 80: 
 81: 			body, err := io.ReadAll(io.LimitReader(r.Body, 16384))
 82: 			if err != nil {
 83: 				http.Error(w, "bad request", http.StatusBadRequest)
 84: 				return
 85: 			}
 86: 
 87: 			var evt toolevents.Event
 88: 			if err := json.Unmarshal(body, &evt); err != nil {
 89: 				logrus.WithError(err).WithField("request_id", chimiddleware.GetReqID(r.Context())).Trace("tool-event API: JSON parse failed")
 90: 				http.Error(w, "invalid JSON", http.StatusBadRequest)
 91: 				return
 92: 			}
 93: 
 94: 			if evt.Tool == "" || evt.Status == "" || evt.Session == "" {
 95: 				logrus.WithFields(logrus.Fields{
 96: 					"tool":       evt.Tool,
 97: 					"status":     evt.Status,
 98: 					"session":    evt.Session,
 99: 					"request_id": chimiddleware.GetReqID(r.Context()),
100: 				}).Trace("tool-event API: missing required fields")
101: 				http.Error(w, "tool, status, and session are required", http.StatusBadRequest)
102: 				return
103: 			}
104: 
105: 			// Stamp local host identity when running in multi-host mode
106: 			if opts.PeerMgr != nil && evt.Host == "" {
107: 				evt.Host = opts.PeerMgr.LocalID()
108: 				evt.HostName = opts.PeerMgr.LocalName()
109: 			}
110: 			if len(evt.Files) > 0 {
111: 				cwd := toolevents.ResolveSessionCWD(opts.CWDResolver, evt.Session)
112: 				evt.Artifacts = toolevents.EnrichArtifacts(evt.Files, cwd, evt.Tool, "hook")
113: 			}
114: 
115: 			logrus.WithFields(logrus.Fields{
116: 				"tool":       evt.Tool,
117: 				"status":     evt.Status,
118: 				"session":    evt.Session,
119: 				"window":     evt.Window,
120: 				"pane":       evt.Pane,
121: 				"request_id": chimiddleware.GetReqID(r.Context()),
122: 				"host":       evt.Host,
123: 			}).Debug("received tool event via API")
124: 
125: 			opts.Tracker.Record(&evt)
126: 			if opts.StateMgr != nil {
127: 				opts.StateMgr.UpdateSessionMetadataFromEvent(&evt)
128: 			}
129: 			w.WriteHeader(http.StatusNoContent)
130: 		})
131: 
132: 		// Protected API routes
133: 		r.Group(func(r chi.Router) {
134: 			if opts.AuthEnabled {
135: 				r.Use(auth.Middleware(opts.SessionMgr))
136: 			}
137: 
138: 			registerSessionsRoutes(r, opts, hub, coordinator)
139: 			registerSchedulerRoutes(r, opts)
140: 			registerPeerRoutes(r, opts)
141: 			registerStateV2Routes(r, opts)
142: 		})
143: 		// Port forward registry (local single-host).
144: 		r.Group(func(r chi.Router) {
145: 			if opts.AuthEnabled {
146: 				r.Use(auth.Middleware(opts.SessionMgr))
147: 			}
148: 			r.Get("/portforwards", func(w http.ResponseWriter, r *http.Request) {
149: 				if opts.PortForwardStore == nil {
150: 					http.Error(w, "port forwarding not available", http.StatusServiceUnavailable)
151: 					return
152: 				}
153: 				w.Header().Set("Content-Type", "application/json")
154: 				_ = json.NewEncoder(w).Encode(opts.PortForwardStore.List())
155: 			})
156: 			r.Post("/portforwards", func(w http.ResponseWriter, r *http.Request) {
157: 				if opts.PortForwardStore == nil {
158: 					http.Error(w, "port forwarding not available", http.StatusServiceUnavailable)
159: 					return
160: 				}
161: 				var req struct {
162: 					Port         int              `json:"port"`
163: 					Label        string           `json:"label"`
164: 					Mode         portforward.Mode `json:"mode"`
165: 					ExternalPort int              `json:"external_port"`
166: 				}
167: 				if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.Port < 1 || req.Port > 65535 {
168: 					http.Error(w, "port (1-65535) required", http.StatusBadRequest)
169: 					return
170: 				}
171: 				if req.Mode == "" {
172: 					req.Mode = portforward.ModeProxy
173: 				}
174: 				if err := opts.PortForwardStore.Add(req.Port, req.Label, req.Mode, req.ExternalPort); err != nil {
175: 					http.Error(w, err.Error(), http.StatusBadGateway)
176: 					return
177: 				}
178: 				w.Header().Set("Content-Type", "application/json")
179: 				w.WriteHeader(http.StatusCreated)
180: 				_ = json.NewEncoder(w).Encode(opts.PortForwardStore.List())
181: 			})
182: 			r.Delete("/portforward/{port}", func(w http.ResponseWriter, r *http.Request) {
183: 				if opts.PortForwardStore == nil {
184: 					http.Error(w, "port forwarding not available", http.StatusServiceUnavailable)
185: 					return
186: 				}
187: 				port, err := strconv.Atoi(chi.URLParam(r, "port"))
188: 				if err != nil {
189: 					http.Error(w, "invalid port", http.StatusBadRequest)
190: 					return
191: 				}
192: 				opts.PortForwardStore.Remove(port)
193: 				w.WriteHeader(http.StatusNoContent)
194: 			})
195: 		})
196: 
197: 		// PTY benchmark: compare direct PTY throughput and latency
198: 		r.Get("/pty-benchmark", func(w http.ResponseWriter, r *http.Request) {
199: 			handlePTYBenchmark(w, r, opts)
200: 		})
201: 	})
