  36: // registerSessionsRoutes mounts the protected session/activity/stats/sync
  37: // endpoints under /api. Callers must apply auth middleware separately.
  38: func registerSessionsRoutes(r chi.Router, opts *Options, hub *ws.Hub, coordinator *groupNamingCoordinator) {
  39: 
  40: 	// Agent status -- check which agents are installed/configured
  41: 	r.Get("/agent-status", func(w http.ResponseWriter, r *http.Request) {
  42: 		w.Header().Set("Content-Type", "application/json")
  43: 		json.NewEncoder(w).Encode(agentcheck.CheckAgents())
  44: 	})
  45: 	r.Get("/update", func(w http.ResponseWriter, r *http.Request) {
  46: 		handleUpdateStatus(w, r)
  47: 	})
  48: 	r.Post("/update/apply", func(w http.ResponseWriter, r *http.Request) {
  49: 		handleUpdateApply(w, r, opts)
  50: 	})
  51: 	r.Post("/update/check", func(w http.ResponseWriter, r *http.Request) {
  52: 		handleUpdateCheck(w, r, opts)
  53: 	})
  54: 
  55: 	r.Get("/sessions", func(w http.ResponseWriter, r *http.Request) {
  56: 		var sessions []*model.Session
  57: 		if opts.PeerMgr != nil {
  58: 			sessions = opts.PeerMgr.GetAllSessions()
  59: 		} else {
  60: 			sessions = opts.StateMgr.GetSessions()
  61: 		}
  62: 		localHost := ""
  63: 		if opts.PeerMgr != nil {
  64: 			localHost = opts.PeerMgr.LocalID()
  65: 		}
  66: 		enrichSessionsFromTracker(sessions, opts.Tracker, localHost)
  67: 		w.Header().Set("Content-Type", "application/json")
  68: 		json.NewEncoder(w).Encode(sessions)
  69: 	})
  70: 
  71: 	r.Get("/hosts", func(w http.ResponseWriter, r *http.Request) {
  72: 		if opts.PeerMgr != nil {
  73: 			w.Header().Set("Content-Type", "application/json")
  74: 			json.NewEncoder(w).Encode(opts.PeerMgr.GetHosts())
  75: 		} else {
  76: 			w.Header().Set("Content-Type", "application/json")
  77: 			json.NewEncoder(w).Encode([]interface{}{})
  78: 		}
  79: 	})
  80: 
  81: 	// Read-only snapshot of a session's primary pane visible buffer.
  82: 	// Works for local and remote (peer) sessions; no PTY attach.
  83: 	r.Get("/pane-capture", func(w http.ResponseWriter, r *http.Request) {
  84: 		session := r.URL.Query().Get("session")
  85: 		if session == "" {
  86: 			http.Error(w, "session is required", http.StatusBadRequest)
  87: 			return
  88: 		}
  89: 		lines := 40
  90: 		if v, err := strconv.Atoi(r.URL.Query().Get("lines")); err == nil && v > 0 {
  91: 			lines = v
  92: 		}
  93: 		host := r.URL.Query().Get("host")
  94: 
  95: 		// Remote peer -- request capture over the control link.
  96: 		if host != "" && opts.PeerMgr != nil && !opts.PeerMgr.IsLocal(host) {
  97: 			if opts.CaptureReg == nil {
  98: 				http.Error(w, "capture unavailable", http.StatusInternalServerError)
  99: 				return
 100: 			}
 101: 			peerConn := opts.PeerMgr.GetPeerConnection(host)
 102: 			if peerConn == nil {
 103: 				http.Error(w, "peer not connected", http.StatusBadGateway)
 104: 				return
 105: 			}
 106: 			token := peer.NewToken()
 107: 			msg, err := peer.NewMessage(peer.MsgCapturePane, peer.CapturePanePayload{
 108: 				Token: token, Session: session, Lines: lines,
 109: 			})
 110: 			if err != nil {
 111: 				http.Error(w, "internal error", http.StatusInternalServerError)
 112: 				return
 113: 			}
 114: 			// Register before enqueue so a fast reply cannot be dropped.
 115: 			ch, cancel := opts.CaptureReg.Register(token)
 116: 			defer cancel()
 117: 			if !peerConn.Enqueue(msg) {
 118: 				http.Error(w, "peer send queue full", http.StatusBadGateway)
 119: 				return
 120: 			}
 121: 			select {
 122: 			case res := <-ch:
 123: 				if res.Error != "" {
 124: 					http.Error(w, "capture failed: "+res.Error, http.StatusInternalServerError)
 125: 					return
 126: 				}
 127: 				w.Header().Set("Content-Type", "application/json")
 128: 				json.NewEncoder(w).Encode(map[string]string{"text": res.Text})
 129: 			case <-time.After(3 * time.Second):
 130: 				http.Error(w, "peer capture timed out", http.StatusGatewayTimeout)
 131: 			}
 132: 			return
 133: 		}
 134: 
 135: 		// Local session -- capture from daemon registry.
 136: 		if opts.DaemonReg == nil {
 137: 			http.Error(w, "daemon registry unavailable", http.StatusInternalServerError)
 138: 			return
 139: 		}
 140: 		text, err := opts.DaemonReg.Capture(session)
 141: 		if err != nil {
 142: 			http.Error(w, "capture failed: "+err.Error(), http.StatusInternalServerError)
 143: 			return
 144: 		}
 145: 		w.Header().Set("Content-Type", "application/json")
 146: 		json.NewEncoder(w).Encode(map[string]string{"text": model.LastLines(text, lines)})
 147: 	})
