 149: 	r.Post("/session/new", func(w http.ResponseWriter, r *http.Request) {
 150: 		var req struct {
 151: 			Name           string `json:"name"`
 152: 			Host           string `json:"host,omitempty"`
 153: 			Path           string `json:"path,omitempty"`
 154: 			Command        string `json:"command,omitempty"`
 155: 			AgentType      string `json:"agent_type,omitempty"`
 156: 			WorktreeBranch string `json:"worktree_branch,omitempty"`
 157: 			ScheduleID     string `json:"schedule_id,omitempty"`
 158: 			Backend        string `json:"backend,omitempty"`
 159: 		}
 160: 		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
 161: 			http.Error(w, "invalid JSON", http.StatusBadRequest)
 162: 			return
 163: 		}
 164: 		if opts.Launch == nil {
 165: 			http.Error(w, "launch service unavailable", http.StatusServiceUnavailable)
 166: 			return
 167: 		}
 168: 		localHost := ""
 169: 		if opts.PeerMgr != nil {
 170: 			localHost = opts.PeerMgr.LocalID()
 171: 		}
 172: 		launchReq := sessionlaunch.Request{
 173: 			Name:           req.Name,
 174: 			Host:           req.Host,
 175: 			Path:           req.Path,
 176: 			Command:        req.Command,
 177: 			AgentType:      req.AgentType,
 178: 			WorktreeBranch: req.WorktreeBranch,
 179: 			ScheduleID:     req.ScheduleID,
 180: 			LocalHost:      localHost,
 181: 		}
 182: 		if req.Host == "" || opts.PeerMgr == nil || opts.PeerMgr.IsLocal(req.Host) {
 183: 			launchReq.Fallback = fmt.Sprintf("shell-%d", time.Now().UnixMilli())
 184: 		}
 185: 		res, err := opts.Launch.Create(r.Context(), launchReq)
 186: 		if err != nil {
 187: 			switch {
 188: 			case errors.Is(err, sessionlaunch.ErrInvalidInput):
 189: 				http.Error(w, err.Error(), http.StatusBadRequest)
 190: 			case errors.Is(err, sessionlaunch.ErrPeerUnavailable), errors.Is(err, sessionlaunch.ErrPeerQueueFull):
 191: 				http.Error(w, err.Error(), http.StatusBadGateway)
 192: 			default:
 193: 				http.Error(w, err.Error(), http.StatusInternalServerError)
 194: 			}
 195: 			return
 196: 		}
 197: 		w.Header().Set("Content-Type", "application/json")
 198: 		json.NewEncoder(w).Encode(map[string]string{"name": res.Name})
 199: 	})
