 201: 	r.Post("/session/display-name", func(w http.ResponseWriter, r *http.Request) {
 202: 		var req struct {
 203: 			Session     string `json:"session"`
 204: 			DisplayName string `json:"display_name"`
 205: 			Clear       bool   `json:"clear,omitempty"`
 206: 			Host        string `json:"host,omitempty"`
 207: 		}
 208: 		if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.Session == "" {
 209: 			http.Error(w, "session is required", http.StatusBadRequest)
 210: 			return
 211: 		}
 212: 
 213: 		// Remote host -- forward via peer connection. The new label propagates
 214: 		// back through the peer's state update broadcast.
 215: 		if req.Host != "" && opts.PeerMgr != nil && !opts.PeerMgr.IsLocal(req.Host) {
 216: 			peerConn := opts.PeerMgr.GetPeerConnection(req.Host)
 217: 			if peerConn == nil {
 218: 				http.Error(w, "peer not connected", http.StatusBadGateway)
 219: 				return
 220: 			}
 221: 			params, _ := json.Marshal(map[string]any{
 222: 				"session":      req.Session,
 223: 				"display_name": req.DisplayName,
 224: 				"clear":        req.Clear,
 225: 			})
 226: 			msg, _ := peer.NewMessage(peer.MsgSessionAction, peer.SessionActionPayload{
 227: 				Action: "set-display-name",
 228: 				Params: params,
 229: 			})
 230: 			if peerConn.Enqueue(msg) {
 231: 				w.WriteHeader(http.StatusNoContent)
 232: 			} else {
 233: 				http.Error(w, "peer send queue full", http.StatusBadGateway)
 234: 			}
 235: 			return
 236: 		}
 237: 
 238: 		if opts.V2CommandSvc != nil && opts.V2Catalog != nil {
 239: 			ref, ok := opts.V2CommandSvc.LookupRefByDisplayName(req.Session)
 240: 			if !ok {
 241: 				http.Error(w, "session not found", http.StatusNotFound)
 242: 				return
 243: 			}
 244: 			label := req.DisplayName
 245: 			if req.Clear {
 246: 				label = string(ref.Session)
 247: 			}
 248: 			params, _ := json.Marshal(state.LabelParams{Label: label})
 249: 			if _, err := opts.V2CommandSvc.ExecuteSessionCommand(r.Context(), state.SessionCommand{
 250: 				ID:     state.NewCommandID(),
 251: 				Ref:    ref,
 252: 				Action: state.ActionLabel,
 253: 				Params: params,
 254: 			}); err != nil {
 255: 				http.Error(w, err.Error(), http.StatusInternalServerError)
 256: 				return
 257: 			}
 258: 			w.WriteHeader(http.StatusNoContent)
 259: 			return
 260: 		}
 261: 
 262: 		if opts.StateMgr == nil {
 263: 			http.Error(w, "state manager unavailable", http.StatusInternalServerError)
 264: 			return
 265: 		}
 266: 		// clear=true resets to AI/auto naming; otherwise mark user-set.
 267: 		opts.StateMgr.SetDisplayName(req.Session, req.DisplayName, !req.Clear)
 268: 		w.WriteHeader(http.StatusNoContent)
 269: 	})
