 271: 	// Manually (re)generate an AI display name for a session on demand.
 272: 	// Bypasses the one-shot guard and clears any prior manual name.
 273: 	r.Post("/session/regenerate-name", func(w http.ResponseWriter, r *http.Request) {
 274: 		var req struct {
 275: 			Session string `json:"session"`
 276: 			Host    string `json:"host,omitempty"`
 277: 		}
 278: 		if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.Session == "" {
 279: 			http.Error(w, "session is required", http.StatusBadRequest)
 280: 			return
 281: 		}
 282: 
 283: 		// Remote host -- name it here (the peer process may have no namer
 284: 		// configured) and forward the chosen name to the peer to apply. The
 285: 		// applied name propagates back via the peer's state update.
 286: 		if req.Host != "" && opts.PeerMgr != nil && !opts.PeerMgr.IsLocal(req.Host) {
 287: 			peerConn := opts.PeerMgr.GetPeerConnection(req.Host)
 288: 			if peerConn == nil {
 289: 				http.Error(w, "peer not connected", http.StatusBadGateway)
 290: 				return
 291: 			}
 292: 			if opts.StateMgr == nil {
 293: 				http.Error(w, "state manager unavailable", http.StatusInternalServerError)
 294: 				return
 295: 			}
 296: 
 297: 			// Find the target session and its siblings on that host.
 298: 			nc := namer.Context{Kind: namer.KindShell}
 299: 			found := false
 300: 			for _, s := range opts.PeerMgr.GetAllSessions() {
 301: 				if s.Host != req.Host {
 302: 					continue
 303: 				}
 304: 				if s.Name == req.Session {
 305: 					found = true
 306: 					nc.Workdir = s.ProjectPath
 307: 					nc.Current = s.DisplayName
 308: 					nc.Agent = s.AgentType
 309: 					nc.UserPrompt = s.UserPrompt
 310: 					nc.AgentMsg = s.LastAgentMessage
 311: 					if s.AgentType != "" {
 312: 						nc.Kind = namer.KindAgent
 313: 					}
 314: 				} else {
 315: 					label := s.DisplayName
 316: 					if label == "" {
 317: 						label = s.Name
 318: 					}
 319: 					nc.Taken = append(nc.Taken, label)
 320: 				}
 321: 			}
 322: 			if !found {
 323: 				http.Error(w, "session not found on host", http.StatusNotFound)
 324: 				return
 325: 			}
 326: 
 327: 			ctx, cancel := context.WithTimeout(r.Context(), 12*time.Second)
 328: 			name, err := opts.StateMgr.GenerateName(ctx, nc)
 329: 			cancel()
 330: 			if err != nil {
 331: 				http.Error(w, err.Error(), http.StatusServiceUnavailable)
 332: 				return
 333: 			}
 334: 
 335: 			params, _ := json.Marshal(map[string]string{"session": req.Session, "name": name})
 336: 			msg, _ := peer.NewMessage(peer.MsgSessionAction, peer.SessionActionPayload{
 337: 				Action: "regenerate-name",
 338: 				Params: params,
 339: 			})
 340: 			if !peerConn.Enqueue(msg) {
 341: 				http.Error(w, "peer send queue full", http.StatusBadGateway)
 342: 				return
 343: 			}
 344: 			w.Header().Set("Content-Type", "application/json")
 345: 			json.NewEncoder(w).Encode(map[string]string{"name": name})
 346: 			return
 347: 		}
 348: 
 349: 		if opts.StateMgr == nil {
 350: 			http.Error(w, "state manager unavailable", http.StatusInternalServerError)
 351: 			return
 352: 		}
 353: 		name, err := opts.StateMgr.RegenerateName(req.Session)
 354: 		if err != nil {
 355: 			http.Error(w, err.Error(), http.StatusServiceUnavailable)
 356: 			return
 357: 		}
 358: 		w.Header().Set("Content-Type", "application/json")
 359: 		json.NewEncoder(w).Encode(map[string]string{"name": name})
 360: 	})
