 362: 	// AI-name a layout group from its member session labels. Groups are
 363: 	// a frontend-only concept, so this is stateless: it returns a name,
 364: 	// the client persists it.
 365: 	r.Post("/group/name", func(w http.ResponseWriter, r *http.Request) {
 366: 		var req struct {
 367: 			ID      string              `json:"id,omitempty"`
 368: 			Members []namer.GroupMember `json:"members"`
 369: 			Current string              `json:"current,omitempty"`
 370: 		}
 371: 		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
 372: 			http.Error(w, "invalid JSON", http.StatusBadRequest)
 373: 			return
 374: 		}
 375: 
 376: 		// Explicit force path: name a persisted group from its tree and persist
 377: 		// the result server-side. Preferred by new clients.
 378: 		if req.ID != "" && coordinator != nil {
 379: 			group, err := coordinator.Force(r.Context(), req.ID)
 380: 			if err != nil {
 381: 				http.Error(w, err.Error(), http.StatusBadRequest)
 382: 				return
 383: 			}
 384: 			w.Header().Set("Content-Type", "application/json")
 385: 			json.NewEncoder(w).Encode(map[string]interface{}{"name": group.Name, "group": group})
 386: 			return
 387: 		}
 388: 
 389: 		// Legacy stateless path: clients send members and persist the name
 390: 		// themselves. Kept for one release for older callers.
 391: 		if len(req.Members) == 0 {
 392: 			http.Error(w, "members is required", http.StatusBadRequest)
 393: 			return
 394: 		}
 395: 		if opts.StateMgr == nil {
 396: 			http.Error(w, "state manager unavailable", http.StatusInternalServerError)
 397: 			return
 398: 		}
 399: 		name, err := opts.StateMgr.GenerateGroupName(req.Members, req.Current)
 400: 		if err != nil {
 401: 			http.Error(w, err.Error(), http.StatusServiceUnavailable)
 402: 			return
 403: 		}
 404: 		w.Header().Set("Content-Type", "application/json")
 405: 		json.NewEncoder(w).Encode(map[string]string{"name": name})
 406: 	})
