 421: 		}
 422: 
 423: 		// Remote host -- forward via peer connection
 424: 		if req.Host != "" && opts.PeerMgr != nil && !opts.PeerMgr.IsLocal(req.Host) {
 425: 			peerConn := opts.PeerMgr.GetPeerConnection(req.Host)
 426: 			if peerConn == nil {
 427: 				http.Error(w, "peer not connected", http.StatusBadGateway)
