 442: 			}
 443: 			return
 444: 		}
 445: 
 446: 		// Daemon sessions can't be renamed at the OS level; update display name only.
 447: 		opts.StateMgr.SetDisplayName(req.OldName, req.NewName, true)
 448: 		if opts.RefreshSessions != nil {
