 494: 	r.Post("/session/kill", func(w http.ResponseWriter, r *http.Request) {
 495: 		var req struct {
 496: 			ID             string `json:"id,omitempty"`
 497: 			Name           string `json:"name"`
 498: 			Host           string `json:"host,omitempty"`
 499: 			RemoveWorktree bool   `json:"remove_worktree,omitempty"`
 500: 		}
 501: 		if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.Name == "" {
 502: 			http.Error(w, "name is required", http.StatusBadRequest)
 503: 			return
 504: 		}
 505: 
 506: 		// Remote host -- forward via peer connection
 507: 		if req.Host != "" && opts.PeerMgr != nil && !opts.PeerMgr.IsLocal(req.Host) {
 508: 			peerConn := opts.PeerMgr.GetPeerConnection(req.Host)
 509: 			if peerConn == nil {
 510: 				http.Error(w, "peer not connected", http.StatusBadGateway)
 511: 				return
 512: 			}
 513: 			params, _ := json.Marshal(map[string]string{"id": req.ID, "name": req.Name})
 514: 			msg, _ := peer.NewMessage(peer.MsgSessionAction, peer.SessionActionPayload{
 515: 				Action: "kill",
 516: 				Params: params,
 517: 			})
 518: 			if peerConn.Enqueue(msg) {
 519: 				w.WriteHeader(http.StatusNoContent)
 520: 			} else {
 521: 				http.Error(w, "peer send queue full", http.StatusBadGateway)
 522: 			}
 523: 			return
 524: 		}
 525: 
 526: 		// v2 local command path.
 527: 		if opts.V2CommandSvc != nil && opts.V2Catalog != nil {
 528: 			ref, ok := opts.V2CommandSvc.LookupRefByDisplayName(req.Name)
 529: 			if !ok {
 530: 				http.Error(w, "session not found", http.StatusNotFound)
 531: 				return
 532: 			}
 533: 			if _, err := opts.V2CommandSvc.ExecuteSessionCommand(r.Context(), state.SessionCommand{
 534: 				ID:     state.NewCommandID(),
 535: 				Ref:    ref,
 536: 				Action: state.ActionKill,
 537: 			}); err != nil {
 538: 				http.Error(w, err.Error(), http.StatusInternalServerError)
 539: 				return
 540: 			}
 541: 			w.WriteHeader(http.StatusNoContent)
 542: 			return
 543: 		}
 544: 
 545: 		// Legacy local session kill.
 546: 		// Capture worktree path before state is cleared.
 547: 		var worktreePath string
 548: 		if req.RemoveWorktree && opts.StateMgr != nil {
 549: 			worktreePath = opts.StateMgr.GetSessionProjectPath(req.Name)
 550: 		}
 551: 
 552: 		// Transition lifecycle state before killing so the daemon
 553: 		// records this as an intentional termination, not a crash.
 554: 		if opts.DaemonReg != nil && opts.DaemonReg.LifecycleStore() != nil {
 555: 			_ = opts.DaemonReg.LifecycleStore().Transition(req.Name, "active", "termination_requested")
 556: 		}
 557: 		// Kill daemon session.
 558: 		if opts.DaemonReg != nil {
 559: 			if err := opts.DaemonReg.Kill(req.Name); err != nil {
 560: 				logrus.WithError(err).WithField("session", req.Name).Warn("daemon kill failed")
 561: 			}
 562: 		}
 563: 		if opts.StateMgr != nil {
 564: 			opts.StateMgr.RemoveSession(req.Name)
 565: 		}
 566: 
 567: 		// Remove the linked worktree if requested. Non-fatal -- session is
 568: 		// already gone; log and continue.
 569: 		if req.RemoveWorktree && worktreePath != "" {
 570: 			if err := git.RemoveWorktree(worktreePath); err != nil {
 571: 				logrus.WithError(err).WithField("path", worktreePath).Warn("git worktree remove failed")
 572: 			}
 573: 		}
 574: 
 575: 		w.WriteHeader(http.StatusNoContent)
 576: 	})
