 578: 	// Crashed sessions recovery endpoints
 579: 	r.Get("/crashed-sessions", func(w http.ResponseWriter, r *http.Request) {
 580: 		if opts.V2Catalog != nil {
 581: 			var out []map[string]string
 582: 			for _, rec := range opts.V2Catalog.Sessions() {
 583: 				if rec.Phase != state.SessionPhaseCrashed {
 584: 					continue
 585: 				}
 586: 				name := rec.Compat.Name
 587: 				if name == "" {
 588: 					name = string(rec.ID)
 589: 				}
 590: 				out = append(out, map[string]string{
 591: 					"id":         name,
 592: 					"shell":      rec.Compat.Shell,
 593: 					"cwd":        rec.Compat.Cwd,
 594: 					"generation": rec.Compat.Generation,
 595: 				})
 596: 			}
 597: 			w.Header().Set("Content-Type", "application/json")
 598: 			json.NewEncoder(w).Encode(out)
 599: 			return
 600: 		}
 601: 		if opts.DaemonReg == nil {
 602: 			w.Header().Set("Content-Type", "application/json")
 603: 			json.NewEncoder(w).Encode([]interface{}{})
 604: 			return
 605: 		}
 606: 		crashed := opts.DaemonReg.CrashedSessions()
 607: 		w.Header().Set("Content-Type", "application/json")
 608: 		json.NewEncoder(w).Encode(crashed)
 609: 	})
