 629: 				return
 630: 			}
 631: 			params, _ := json.Marshal(state.RecoverParams{Shell: body.Shell, Cwd: body.Cwd})
 632: 			if _, err := opts.V2CommandSvc.ExecuteSessionCommand(r.Context(), state.SessionCommand{
 633: 				ID:     state.NewCommandID(),
 634: 				Ref:    ref,
 635: 				Action: state.ActionRecover,
 636: 				Params: params,
 637: 			}); err != nil {
 638: 				http.Error(w, "recover failed: "+err.Error(), http.StatusInternalServerError)
 639: 				return
 640: 			}
 641: 			if opts.RefreshSessions != nil {
 642: 				opts.RefreshSessions()
 643: 			}
 644: 			w.Header().Set("Content-Type", "application/json")
 645: 			json.NewEncoder(w).Encode(map[string]string{"ok": "true", "session": id})
 646: 			return
 647: 		}
