 649: 		if opts.DaemonReg == nil {
 650: 			http.Error(w, "daemon registry unavailable", http.StatusServiceUnavailable)
 651: 			return
 652: 		}
 653: 		if err := opts.DaemonReg.RecoverSession(id, body.Shell, body.Cwd); err != nil {
 654: 			http.Error(w, "recover failed: "+err.Error(), http.StatusInternalServerError)
 655: 			return
 656: 		}
 657: 		if opts.RefreshSessions != nil {
