 712: 	// Tool event query/management (auth-protected)
 713: 	r.Get("/tool-events", func(w http.ResponseWriter, r *http.Request) {
 714: 		session := r.URL.Query().Get("session")
 715: 		var events []*toolevents.Event
 716: 		if session != "" {
 717: 			events = opts.Tracker.GetForSession(session)
 718: 		} else {
 719: 			events = opts.Tracker.GetAll()
 720: 		}
 721: 
 722: 		// Merge in auto-detected agents that don't have a tracked event.
 723: 		// These are "active" agents found via process-tree inspection
 724: 		// (e.g. codex/copilot running as node).
 725: 		if opts.Detector != nil {
 726: 			tracked := make(map[string]bool)
 727: 			for _, evt := range events {
 728: 				if evt.Pane != "" {
 729: 					tracked[evt.Pane] = true
 730: 				}
 731: 			}
 732: 			for paneID, tool := range opts.Detector.DetectedPanes() {
 733: 				if tracked[paneID] {
 734: 					continue
 735: 				}
 736: 				info := opts.Detector.PaneInfo(paneID)
 737: 				if session != "" && info.Session != session {
 738: 					continue
 739: 				}
 740: 				evt := &toolevents.Event{
 741: 					Tool:         tool,
 742: 					Status:       toolevents.StatusActive,
 743: 					Session:      info.Session,
 744: 					Window:       info.Window,
 745: 					Pane:         paneID,
 746: 					Message:      "auto-detected",
 747: 					AutoDetected: true,
 748: 				}
 749: 				// Stamp local host identity so frontend session key matching works
 750: 				if opts.PeerMgr != nil {
 751: 					evt.Host = opts.PeerMgr.LocalID()
 752: 					evt.HostName = opts.PeerMgr.LocalName()
 753: 				}
 754: 				events = append(events, evt)
 755: 			}
 756: 		}
 757: 
 758: 		w.Header().Set("Content-Type", "application/json")
 759: 		json.NewEncoder(w).Encode(events)
 760: 	})
