 828: 	// Stats endpoint -- aggregate overview data
 829: 	r.Get("/stats", func(w http.ResponseWriter, r *http.Request) {
 830: 		sessions := opts.StateMgr.GetSessions()
 831: 		// Enumerate panes from daemon registry.
 832: 		var allPanes []*model.Pane
 833: 		if opts.DaemonReg != nil {
 834: 			for _, d := range opts.DaemonReg.List() {
 835: 				allPanes = append(allPanes, &model.Pane{
 836: 					ID:             d.ID + ":0.0",
 837: 					CurrentCommand: d.Shell,
 838: 					CurrentPath:    d.Cwd,
 839: 				})
 840: 			}
 841: 		}
 842: 
 843: 		agentCommands := map[string]bool{
 844: 			"claude": true, "codex": true, "copilot": true, "opencode": true,
 845: 		}
 846: 		totalWindows := 0
 847: 		attachedSessions := 0
 848: 		agentPanes := 0
 849: 		for _, s := range sessions {
 850: 			if s.Attached {
 851: 				attachedSessions++
 852: 			}
 853: 			totalWindows += len(s.Windows)
 854: 		}
 855: 
 856: 		// Build a set of panes with known agent tool events (from hooks
 857: 		// or process-tree detection). This catches agents like codex and
 858: 		// copilot that show up as "node" in pane_current_command.
 859: 		toolEvents := opts.Tracker.GetAll()
 860: 		agentEventPanes := make(map[string]bool)
 861: 		for _, evt := range toolEvents {
 862: 			if evt.Pane != "" {
 863: 				agentEventPanes[evt.Pane] = true
 864: 			}
 865: 		}
 866: 		// Also include panes detected via process tree inspection
 867: 		if opts.Detector != nil {
 868: 			for paneID := range opts.Detector.DetectedPanes() {
 869: 				agentEventPanes[paneID] = true
 870: 			}
 871: 		}
 872: 
 873: 		for _, p := range allPanes {
 874: 			if agentCommands[p.CurrentCommand] || agentEventPanes[p.ID] {
 875: 				agentPanes++
 876: 			}
 877: 		}
 878: 		waitingAgents := 0
 879: 		errorAgents := 0
 880: 		stuckAgents := 0
 881: 		for _, evt := range toolEvents {
 882: 			switch evt.Status {
 883: 			case "waiting":
 884: 				waitingAgents++
 885: 			case "error":
 886: 				errorAgents++
 887: 			case "stuck":
 888: 				stuckAgents++
 889: 			}
 890: 		}
 891: 
 892: 		result := map[string]interface{}{
 893: 			"sessions": map[string]int{
 894: 				"total":    len(sessions),
 895: 				"attached": attachedSessions,
 896: 				"detached": len(sessions) - attachedSessions,
 897: 			},
 898: 			"windows":     totalWindows,
 899: 			"panes":       len(allPanes),
 900: 			"agent_panes": agentPanes,
 901: 			"agents": map[string]int{
 902: 				"active":  agentPanes,
 903: 				"waiting": waitingAgents,
 904: 				"stuck":   stuckAgents,
 905: 				"error":   errorAgents,
 906: 			},
 907: 			"processes": stats.ProcessCountsFromSessions(sessions),
 908: 			"system":    stats.SystemStats(),
 909: 		}
 910: 
 911: 		w.Header().Set("Content-Type", "application/json")
 912: 		json.NewEncoder(w).Encode(result)
 913: 	})
