1002: 	r.Put("/preferences", func(w http.ResponseWriter, r *http.Request) {
1003: 		if opts.PrefStore == nil {
1004: 			http.Error(w, "preferences not available", http.StatusServiceUnavailable)
1005: 			return
1006: 		}
1007: 		var prefs preferences.Preferences
1008: 		if err := json.NewDecoder(r.Body).Decode(&prefs); err != nil {
1009: 			http.Error(w, "invalid JSON", http.StatusBadRequest)
1010: 			return
1011: 		}
1012: 		// A masked API key means "keep the existing one"; restore it from
1013: 		// the store so the masked placeholder is never persisted.
1014: 		if prefs.AINaming.APIKey == preferences.APIKeyMask {
1015: 			prefs.AINaming.APIKey = opts.PrefStore.Get().AINaming.APIKey
1016: 		}
1017: 		// Defensive: never persist the mask itself, even if the store was
1018: 		// previously corrupted with it.
1019: 		if prefs.AINaming.APIKey == preferences.APIKeyMask {
1020: 			prefs.AINaming.APIKey = ""
1021: 		}
1022: 		if err := opts.PrefStore.Update(&prefs); err != nil {
1023: 			http.Error(w, err.Error(), http.StatusInternalServerError)
1024: 			return
1025: 		}
1026: 		if opts.OnPrefsChanged != nil {
1027: 			opts.OnPrefsChanged(&prefs)
1028: 		}
1029: 		// Echo a masked COPY; never mutate the stored struct (Update keeps
1030: 		// the pointer, so mutating prefs here would corrupt the store).
1031: 		echo := prefs
1032: 		if echo.AINaming.APIKey != "" {
1033: 			echo.AINaming.APIKey = preferences.APIKeyMask
1034: 		}
1035: 		w.Header().Set("Content-Type", "application/json")
1036: 		json.NewEncoder(w).Encode(&echo)
1037: 	})
