1101: 			http.Error(w, "session attrs not available", http.StatusServiceUnavailable)
1102: 			return
1103: 		}
1104: 		var body struct {
1105: 			Key        string `json:"key"`
1106: 			Background bool   `json:"background"`
1107: 			Hidden     bool   `json:"hidden"`
1108: 		}
1109: 		if err := json.NewDecoder(r.Body).Decode(&body); err != nil || body.Key == "" {
1110: 			http.Error(w, "key is required", http.StatusBadRequest)
1111: 			return
1112: 		}
1113: 		a, err := opts.AttrsStore.Set(body.Key, body.Background, body.Hidden)
1114: 		if err != nil {
1115: 			http.Error(w, err.Error(), http.StatusInternalServerError)
1116: 			return
1117: 		}
1118: 		hub.BroadcastJSON(map[string]interface{}{
1119: 			"type": "session-attrs-updated",
1120: 			"key":  body.Key,
1121: 		})
1122: 		fanoutAttrsDeltaToPeers(opts, body.Key, a)
1123: 		w.Header().Set("Content-Type", "application/json")
1124: 		json.NewEncoder(w).Encode(opts.AttrsStore.Sets())
1125: 	})
1126: 
1127: 	// Session-order endpoints -- server-authoritative, per-session rank map.
1128: 	r.Get("/session-order", func(w http.ResponseWriter, r *http.Request) {
1129: 		if opts.OrderStore == nil {
1130: 			http.Error(w, "session order not available", http.StatusServiceUnavailable)
1131: 			return
1132: 		}
1133: 		w.Header().Set("Content-Type", "application/json")
1134: 		json.NewEncoder(w).Encode(opts.OrderStore.Ranks())
1135: 	})
1136: 	r.Post("/session-order", func(w http.ResponseWriter, r *http.Request) {
1137: 		if opts.OrderStore == nil {
1138: 			http.Error(w, "session order not available", http.StatusServiceUnavailable)
1139: 			return
1140: 		}
1141: 		var body struct {
1142: 			Key  string `json:"key"`
1143: 			Rank string `json:"rank"`
1144: 		}
1145: 		if err := json.NewDecoder(r.Body).Decode(&body); err != nil || body.Key == "" {
1146: 			http.Error(w, "key is required", http.StatusBadRequest)
1147: 			return
1148: 		}
1149: 		order, err := opts.OrderStore.Set(body.Key, body.Rank)
1150: 		if err != nil {
1151: 			http.Error(w, err.Error(), http.StatusInternalServerError)
1152: 			return
1153: 		}
1154: 		if hub != nil {
1155: 			hub.BroadcastJSON(map[string]interface{}{"type": "session-order-updated", "key": body.Key})
1156: 		}
1157: 		fanoutOrderDeltaToPeers(opts, body.Key, order)
1158: 		w.Header().Set("Content-Type", "application/json")
1159: 		json.NewEncoder(w).Encode(opts.OrderStore.Ranks())
1160: 	})
1161: 
1162: 	// Group endpoints -- server-authoritative, durable field-LWW records.
1163: 	r.Get("/groups", func(w http.ResponseWriter, r *http.Request) {
1164: 		if opts.GroupStore == nil {
1165: 			http.Error(w, "groups not available", http.StatusServiceUnavailable)
1166: 			return
1167: 		}
1168: 		w.Header().Set("Content-Type", "application/json")
1169: 		json.NewEncoder(w).Encode(opts.GroupStore.Live())
1170: 	})
1171: 	r.Post("/groups", func(w http.ResponseWriter, r *http.Request) {
1172: 		if opts.GroupStore == nil {
1173: 			http.Error(w, "groups not available", http.StatusServiceUnavailable)
1174: 			return
1175: 		}
1176: 		var body struct {
1177: 			ID   string          `json:"id"`
1178: 			Op   string          `json:"op"`
1179: 			Tree json.RawMessage `json:"tree,omitempty"`
1180: 			Name string          `json:"name,omitempty"`
1181: 			Mode string          `json:"mode,omitempty"`
1182: 			Rank string          `json:"rank,omitempty"`
1183: 		}
1184: 		if err := json.NewDecoder(r.Body).Decode(&body); err != nil || body.ID == "" || body.Op == "" {
1185: 			http.Error(w, "id and op are required", http.StatusBadRequest)
1186: 			return
1187: 		}
1188: 		var (
1189: 			group groupsync.Group
1190: 			err   error
1191: 		)
1192: 		switch body.Op {
1193: 		case "tree":
1194: 			if len(body.Tree) == 0 {
1195: 				http.Error(w, "tree is required", http.StatusBadRequest)
1196: 				return
1197: 			}
1198: 			before, _ := opts.GroupStore.Get(body.ID)
1199: 			group, err = opts.GroupStore.SetTree(body.ID, body.Tree)
1200: 			if err == nil && coordinator != nil {
1201: 				coordinator.ObserveTreeMutation(body.ID, before, group)
1202: 			}
1203: 		case "name":
1204: 			mode := groupsync.NameModeManual
1205: 			if body.Mode != "" {
1206: 				switch body.Mode {
1207: 				case string(groupsync.NameModeAuto), string(groupsync.NameModeManual):
1208: 					mode = groupsync.NameMode(body.Mode)
1209: 				default:
1210: 					http.Error(w, "invalid mode", http.StatusBadRequest)
1211: 					return
1212: 				}
1213: 			}
1214: 			group, err = opts.GroupStore.SetName(body.ID, body.Name, mode)
1215: 		case "ai-name":
1216: 			if coordinator == nil {
1217: 				http.Error(w, "group naming unavailable", http.StatusServiceUnavailable)
1218: 				return
1219: 			}
1220: 			group, err = coordinator.Force(r.Context(), body.ID)
1221: 			if err != nil {
1222: 				code := http.StatusInternalServerError
1223: 				msg := err.Error()
1224: 				switch {
1225: 				case strings.Contains(msg, "not found"):
1226: 					code = http.StatusNotFound
1227: 				case strings.Contains(msg, "needs at least 2 members"),
1228: 					strings.Contains(msg, "is deleted"),
1229: 					strings.Contains(msg, "malformed tree"),
1230: 					strings.Contains(msg, "membership changed during naming"),
1231: 					strings.Contains(msg, "disappeared during naming"):
1232: 					code = http.StatusUnprocessableEntity
1233: 				case strings.Contains(msg, "state manager unavailable"),
1234: 					strings.Contains(msg, "generation failed"),
1235: 					strings.Contains(msg, "persist group name"):
1236: 					code = http.StatusServiceUnavailable
1237: 				}
1238: 				http.Error(w, msg, code)
1239: 				return
1240: 			}
1241: 		case "rank":
1242: 			group, err = opts.GroupStore.SetRank(body.ID, body.Rank)
1243: 		case "delete":
1244: 			group, err = opts.GroupStore.Delete(body.ID)
1245: 		default:
1246: 			http.Error(w, "invalid op", http.StatusBadRequest)
1247: 			return
1248: 		}
1249: 		if err != nil {
1250: 			http.Error(w, err.Error(), http.StatusInternalServerError)
1251: 			return
1252: 		}
1253: 		if hub != nil {
1254: 			hub.BroadcastJSON(map[string]interface{}{"type": "groups-updated", "id": body.ID, "op": body.Op})
1255: 		}
1256: 		fanoutGroupDeltaToPeers(opts, body.ID, groupsync.Group(group))
1257: 		w.Header().Set("Content-Type", "application/json")
1258: 		json.NewEncoder(w).Encode(opts.GroupStore.Live())
1259: 	})
1260: 
1261: }
