1263: func registerWSRoutes(r chi.Router, opts *Options, hub *ws.Hub) {
1264: 	ptyHandler := ws.NewPTYTerminalHandler(opts.ActivityTracker, opts.Tracker)
1265: 
1266: 	daemonWS := func(w http.ResponseWriter, req *http.Request) {
1267: 		// Route remote sessions through PTY relay
1268: 		hostID := req.URL.Query().Get("host")
1269: 		if opts.PeerMgr != nil && hostID != "" && !opts.PeerMgr.IsLocal(hostID) {
1270: 			handleRemoteSession(w, req, opts, hostID)
1271: 			return
1272: 		}
1273: 		handleDaemonSession(w, req, opts)
1274: 	}
1275: 
1276: 	if opts.AuthEnabled {
1277: 		authMw := auth.Middleware(opts.SessionMgr)
1278: 		r.With(authMw).Get("/ws/events", hub.HandleEvents)
1279: 		r.With(authMw).Get("/ws/session", daemonWS)
1280: 		r.With(authMw).Get("/ws/direct-session", ptyHandler.HandleDirectSession)
1281: 		r.With(authMw).Get("/ws/daemon-session", daemonWS)
1282: 		if opts.V2StateStream != nil {
1283: 			r.With(authMw).Get("/ws/v2/state", opts.V2StateStream.HandleState)
1284: 		}
1285: 	} else {
1286: 		r.Get("/ws/events", hub.HandleEvents)
1287: 		r.Get("/ws/session", daemonWS)
1288: 		r.Get("/ws/direct-session", ptyHandler.HandleDirectSession)
1289: 		r.Get("/ws/daemon-session", daemonWS)
1290: 		if opts.V2StateStream != nil {
1291: 			r.Get("/ws/v2/state", opts.V2StateStream.HandleState)
1292: 		}
1293: 	}
1294: }
1295: 
1296: func handleRemoteSession(w http.ResponseWriter, r *http.Request, opts *Options, hostID string) {
1297: 	sessionName := r.URL.Query().Get("name")
1298: 	if sessionName == "" {
1299: 		http.Error(w, "missing session name", http.StatusBadRequest)
1300: 		return
1301: 	}
1302: 
1303: 	cols := uint16(80)
1304: 	rows := uint16(24)
1305: 	if c := r.URL.Query().Get("cols"); c != "" {
1306: 		if v, err := strconv.ParseUint(c, 10, 16); err == nil && v > 0 {
1307: 			cols = uint16(v)
1308: 		}
1309: 	}
1310: 	if rv := r.URL.Query().Get("rows"); rv != "" {
1311: 		if v, err := strconv.ParseUint(rv, 10, 16); err == nil && v > 0 {
1312: 			rows = uint16(v)
1313: 		}
1314: 	}
1315: 
1316: 	if opts.PeerMgr == nil {
1317: 		http.Error(w, "peer not connected", http.StatusBadGateway)
1318: 		return
1319: 	}
1320: 	peerConn := opts.PeerMgr.GetPeerConnection(hostID)
1321: 	if peerConn == nil {
1322: 		http.Error(w, "peer not connected", http.StatusBadGateway)
1323: 		return
1324: 	}
1325: 
1326: 	if !peerConn.HasCapability(peer.CapPerStream) {
1327: 		http.Error(w, "peer does not support per-stream terminal connections -- upgrade the peer first", http.StatusUpgradeRequired)
1328: 		return
1329: 	}
1330: 
1331: 	upgrader := websocket.Upgrader{
1332: 		CheckOrigin:    ws.CheckSameOrigin,
1333: 		ReadBufferSize: 1024, WriteBufferSize: 1024 * 32,
1334: 	}
1335: 	browserWS, err := upgrader.Upgrade(w, r, nil)
1336: 	if err != nil {
1337: 		return
1338: 	}
1339: 	defer browserWS.Close()
1340: 	// Forward the stable identity (immutable SessionID + generation) when the
1341: 	// browser supplied it. The receiving peer prefers the SessionID as its
1342: 	// daemon socket key and only falls back to the legacy `name` when no
1343: 	// SessionID was carried (a v2 session is routed stably; a pre-v2 peer/label
1344: 	// keeps working over the name path).
1345: 	sessionID := r.URL.Query().Get("sessionID")
1346: 	generation := r.URL.Query().Get("generation")
1347: 	ok := serveViewerPerStream(browserWS, peerConn, opts, hostID, sessionName, sessionID, generation, cols, rows)
1348: 	if !ok {
1349: 		// Write a close frame so the browser knows this is a terminal failure,
1350: 		// not a normal closure. Use application-level close code 4000 + reason.
1351: 		_ = browserWS.WriteMessage(websocket.CloseMessage,
1352: 			websocket.FormatCloseMessage(4000, "per-stream setup failed"))
1353: 	}
1354: }
1355: 
1356: func serveViewerPerStream(browserWS *websocket.Conn, peerConn *peer.PeerConnection, opts *Options, hostID, session, sessionID, generation string, cols, rows uint16) bool {
1357: 	if opts == nil || opts.PeerMgr == nil || opts.Identity == nil || opts.StreamReg == nil {
1358: 		return false
1359: 	}
1360: 	streamID := peer.GenerateStreamID()
1361: 	token := peer.NewToken()
1362: 	log := logrus.WithFields(logrus.Fields{"stream": streamID, "session": session, "host": hostID})
1363: 	openMsg, _ := peer.NewMessage(peer.MsgOpenTerminal, peer.OpenTerminalPayload{
1364: 		StreamID:     streamID,
1365: 		Session:      session,
1366: 		SessionID:    sessionID,
1367: 		Generation:   generation,
1368: 		Cols:         cols,
1369: 		Rows:         rows,
1370: 		Token:        token,
1371: 		ViewerHostID: opts.PeerMgr.LocalID(),
1372: 	})
1373: 
1374: 	dial := peerConn.Role == peer.RoleDialer
1375: 	var conn *websocket.Conn
1376: 	if dial {
1377: 		addr := opts.PeerMgr.GetPeerAddress(hostID)
1378: 		c, err := peer.DialPeerStream(context.Background(), addr, opts.Identity, token)
1379: 		if err != nil {
1380: 			log.WithError(err).Debug("viewer data-conn dial failed")
1381: 			return false
1382: 		}
1383: 		conn = c
1384: 		if !peerConn.EnqueueHi(openMsg) {
1385: 			conn.Close()
1386: 			return false
1387: 		}
1388: 	} else {
1389: 		ps := peer.NewPendingStream(streamID, session, cols, rows, hostID, opts.PeerMgr.LocalID(), hostID)
1390: 		opts.StreamReg.Register(token, ps)
1391: 		if !peerConn.EnqueueHi(openMsg) {
1392: 			return false
1393: 		}
1394: 		c, ok := ps.WaitResolved(peer.StreamSetupTimeout())
1395: 		if !ok {
1396: 			return false
1397: 		}
1398: 		conn = c
1399: 	}
1400: 	defer conn.Close()
1401: 	// Viewer writes (browser input) stay uncompressed for role clarity.
1402: 	conn.EnableWriteCompression(false)
1403: 	ws.SpliceConns(browserWS, conn, log)
1404: 	return true
1405: }
1406: 
1407: // handleDaemonSession upgrades to WebSocket and bridges a session daemon
1408: // (direct PTY with persistence) to the browser. Query params: name=<id>, cols=<>, rows=<>.
1409: //
1410: // Stable re-keying: when `sessionID` (immutable SessionID) and `generation`
1411: // are supplied, the attach is routed by the immutable SessionID and validated
1412: // against the current generation (from the v2 catalog, when present) BEFORE
1413: // any PTY bytes stream. A mismatched or superseded generation returns a typed
1414: // JSON error so an open terminal can never attach to a stale daemon generation.
1415: func handleDaemonSession(w http.ResponseWriter, r *http.Request, opts *Options) {
1416: 	if opts.DaemonReg == nil {
1417: 		http.Error(w, "daemon sessions not available", http.StatusServiceUnavailable)
1418: 		return
1419: 	}
1420: 
1421: 	cols, _ := strconv.ParseUint(r.URL.Query().Get("cols"), 10, 16)
1422: 	rows, _ := strconv.ParseUint(r.URL.Query().Get("rows"), 10, 16)
1423: 	if cols == 0 {
1424: 		cols = 120
1425: 	}
1426: 	if rows == 0 {
1427: 		rows = 40
1428: 	}
1429: 
1430: 	replayGated := r.URL.Query().Get("replay") == "1"
1431: 
1432: 	// v2 stable-attach path: key the daemon lookup by immutable SessionID and
1433: 	// gate on generation. Legacy clients keep routing by `name`.
1434: 	if idParam := r.URL.Query().Get("sessionID"); idParam != "" || r.URL.Query().Get("generation") != "" {
1435: 		handleDaemonSessionStable(w, r, opts, idParam, uint16(cols), uint16(rows), replayGated)
1436: 		return
1437: 	}
1438: 
1439: 	name := r.URL.Query().Get("name")
1440: 	if name == "" {
1441: 		http.Error(w, "missing name", http.StatusBadRequest)
1442: 		return
1443: 	}
1444: 
1445: 	socketPath := opts.DaemonReg.SocketPath(name)
1446: 	sess, err := pty.NewDaemonSession(socketPath)
1447: 	if err != nil {
1448: 		http.Error(w, "daemon connect: "+err.Error(), http.StatusInternalServerError)
1449: 		return
1450: 	}
1451: 
1452: 	// Resize to match browser.
1453: 	sess.Resize(uint16(cols), uint16(rows))
1454: 
1455: 	upgrader := websocket.Upgrader{
1456: 		CheckOrigin:    ws.CheckSameOrigin,
1457: 		ReadBufferSize: 1024, WriteBufferSize: 1024 * 32,
1458: 	}
1459: 	conn, err := upgrader.Upgrade(w, r, nil)
1460: 	if err != nil {
1461: 		sess.Close()
1462: 		return
1463: 	}
1464: 	defer conn.Close()
1465: 
1466: 	log := logrus.WithFields(logrus.Fields{"session": name, "backend": "daemon"})
1467: 	paneID := name + ":0.0"
1468: 	var onOutput func()
1469: 	if opts.OnDaemonOutput != nil {
1470: 		onOutput = func() { opts.OnDaemonOutput(paneID) }
1471: 	}
1472: 	ws.BridgeDirectPTY(conn, sess, name, opts.ActivityTracker, log, replayGated, onOutput)
1473: 
1474: 	// The bridge returned: either this tab disconnected (daemon still alive)
1475: 	// or the daemon/shell exited (Ctrl+D, kill, crash). Reconcile discovery now
1476: 	// instead of waiting up to 2s for the ticker, so a dead session disappears
1477: 	// from the sidebar and its terminal view unmounts promptly. A live daemon
1478: 	// simply stays in the list, so this is a no-op for tab disconnects.
1479: 	if opts.RefreshSessions != nil {
1480: 		opts.RefreshSessions()
1481: 	}
1482: }
1483: 
1484: // daemonAttachCode is a stable, typed reject reason for generation-gated
1485: // daemon attach. It mirrors the v2 wire error vocabulary where possible.
1486: type daemonAttachCode string
1487: 
1488: const (
1489: 	daemonAttachNotFound          daemonAttachCode = "not_found"
1490: 	daemonAttachGenerationChanged daemonAttachCode = "generation_changed"
1491: 	daemonAttachNotReady          daemonAttachCode = "not_ready"
1492: )
1493: 
1494: // handleDaemonSessionStable validates a stable-identity attach request against
1495: // the current daemon generation and, when it matches, bridges the daemon PTY
1496: // exactly like the legacy name-keyed path. The immutable SessionID is the
1497: // daemon key (DaemonKey defaults to SessionID), so rename never changes the
1498: // route; only a generation change (recovery/restart) or a missing/starting
1499: // session can reject the attach.
1500: func handleDaemonSessionStable(w http.ResponseWriter, r *http.Request, opts *Options, sessionID string, cols, rows uint16, replayGated bool) {
1501: 	sid := state.SessionID(sessionID)
1502: 	if !validSessionIDQuery(sid) {
1503: 		writeDaemonAttachError(w, daemonAttachNotFound, http.StatusBadRequest, "missing or invalid sessionID")
1504: 		return
1505: 	}
1506: 
1507: 	requestedGen := r.URL.Query().Get("generation")
1508: 
1509: 	// Resolve the current generation. Prefer the v2 catalog when it is
1510: 	// configured (it is authoritative for created sessions); otherwise ask the
1511: 	// daemon registry via its lifecycle record.
1512: 	currentGen := ""
1513: 	phaseOK := true
1514: 	if opts.V2Catalog != nil {
1515: 		if rec, ok := opts.V2Catalog.Session(sid); ok {
1516: 			currentGen = rec.Compat.Generation
1517: 			phaseOK = rec.Phase == state.SessionPhaseActive || rec.Phase == state.SessionPhaseStarting
1518: 		}
1519: 	}
1520: 	if currentGen == "" && opts.DaemonReg != nil {
1521: 		currentGen = opts.DaemonReg.GenerationFor(string(sid))
1522: 	}
1523: 
1524: 	// A requested generation that differs from the live one is a stale attach:
1525: 	// the browser must reconnect with the current generation before any bytes
1526: 	// stream. This is what lets recovery change generation and re-key the open
1527: 	// terminal instead of silently splicing onto an old daemon.
1528: 	if requestedGen != "" && currentGen != "" && requestedGen != currentGen {
1529: 		writeDaemonAttachError(w, daemonAttachGenerationChanged, http.StatusConflict, "session generation changed; reconnect with current generation")
1530: 		return
1531: 	}
1532: 
1533: 	// Session record exists but is not in an attachable phase (pending/crashed/
1534: 	// cleanly ended/dismissed) and no stable generation matches yet.
1535: 	if !phaseOK && currentGen == "" {
1536: 		writeDaemonAttachError(w, daemonAttachNotReady, http.StatusServiceUnavailable, "session is not ready for attach")
1537: 		return
1538: 	}
1539: 
1540: 	socketPath := opts.DaemonReg.SocketPath(string(sid))
1541: 	sess, err := pty.NewDaemonSession(socketPath)
1542: 	if err != nil {
1543: 		http.Error(w, "daemon connect: "+err.Error(), http.StatusInternalServerError)
1544: 		return
1545: 	}
1546: 
1547: 	sess.Resize(cols, rows)
1548: 
1549: 	upgrader := websocket.Upgrader{
1550: 		CheckOrigin:    ws.CheckSameOrigin,
1551: 		ReadBufferSize: 1024, WriteBufferSize: 1024 * 32,
1552: 	}
1553: 	conn, err := upgrader.Upgrade(w, r, nil)
1554: 	if err != nil {
1555: 		sess.Close()
1556: 		return
1557: 	}
1558: 	defer conn.Close()
1559: 
1560: 	log := logrus.WithFields(logrus.Fields{"session_id": string(sid), "generation": currentGen, "backend": "daemon"})
1561: 	paneID := string(sid) + ":0.0"
1562: 	var onOutput func()
1563: 	if opts.OnDaemonOutput != nil {
1564: 		onOutput = func() { opts.OnDaemonOutput(paneID) }
1565: 	}
1566: 	ws.BridgeDirectPTY(conn, sess, string(sid), opts.ActivityTracker, log, replayGated, onOutput)
1567: 
1568: 	if opts.RefreshSessions != nil {
1569: 		opts.RefreshSessions()
1570: 	}
1571: }
1572: 
1573: // validSessionIDQuery reports whether sid is a canonical SessionID (lowercase
1574: // base32 per pkg/state/ids.go). Anything else -- including path separators,
1575: // ".." sequences, control characters, or over-long values -- is rejected
1576: // before it can be used as a daemon socket key.
1577: func validSessionIDQuery(sid state.SessionID) bool {
1578: 	return sid.Validate() == nil
1579: }
1580: 
1581: func writeDaemonAttachError(w http.ResponseWriter, code daemonAttachCode, status int, msg string) {
1582: 	w.Header().Set("Content-Type", "application/json")
1583: 	w.WriteHeader(status)
1584: 	_ = json.NewEncoder(w).Encode(map[string]string{"code": string(code), "message": msg})
1585: }
1586: 
1587: func enrichSessionsFromTracker(sessions []*model.Session, tracker *toolevents.Tracker, localHost string) {
1588: 	if tracker == nil {
1589: 		return
1590: 	}
1591: 	for _, session := range sessions {
1592: 		meta := tracker.SessionMetaFor(session.Host, session.Name)
1593: 		// Agent-derived fields (tool, prompt, last message) are only valid while
1594: 		// the agent still runs; suppress them once it exits. Checked lazily/once.
1595: 		aliveChecked := false
1596: 		aliveVal := false
1597: 		alive := func() bool {
1598: 			if !aliveChecked {
1599: 				aliveVal = shouldResurrectAgentMeta(session, localHost)
1600: 				aliveChecked = true
1601: 			}
1602: 			return aliveVal
1603: 		}
1604: 		if session.AgentType == "" && meta.Tool != "" && alive() {
1605: 			session.AgentType = string(meta.Tool)
1606: 		}
1607: 		if session.ProjectPath == "" && meta.CWD != "" {
1608: 			session.ProjectPath = meta.CWD
1609: 		}
1610: 		if session.PromptPreview == "" && meta.Message != "" {
1611: 			session.PromptPreview = meta.Message
1612: 		}
1613: 		if session.AgentSessionID == "" && meta.AgentSessionID != "" {
1614: 			session.AgentSessionID = meta.AgentSessionID
1615: 		}
1616: 		if session.UserPrompt == "" && meta.UserPrompt != "" && alive() {
1617: 			session.UserPrompt = meta.UserPrompt
1618: 		}
1619: 		if session.LastAgentMessage == "" && meta.LastAgentMessage != "" && alive() {
1620: 			session.LastAgentMessage = meta.LastAgentMessage
1621: 		}
1622: 	}
1623: }
1624: 
1625: // shouldResurrectAgentMeta reports whether this host may repopulate a session's
1626: // agent-derived fields from its own tool-event tracker. It is only allowed for
1627: // LOCAL sessions whose agent process is still running: if the process is gone
1628: // the identity is stale (agent exited, pane reverted to a shell or a command
1629: // like a dev server) and must not be resurrected. REMOTE (peer) sessions are
1630: // never resurrected here -- the origin host is authoritative and relays the
1631: // correct state; this host's tracker is only a mirror and may hold a stale tool
1632: // entry that would otherwise revive a tag the origin already cleared.
1633: func shouldResurrectAgentMeta(session *model.Session, localHost string) bool {
1634: 	if session.Host != "" && session.Host != localHost {
1635: 		return false
1636: 	}
1637: 	for _, win := range session.Windows {
1638: 		for _, pane := range win.Panes {
1639: 			if pane.PID <= 0 {
1640: 				continue
1641: 			}
1642: 			if _, ok := toolevents.DetectAgentInProcessTree(pane.PID); ok {
1643: 				return true
1644: 			}
1645: 		}
1646: 	}
1647: 	return false
1648: }  1: // Package sessionlaunch provides the single, tested path for creating local
  2: // daemon sessions and dispatching remote session launches to peers.
