 22: // Typed launch errors. HTTP/router layers map these to status codes without
 23: // switching on error strings.
 24: var (
 25: 	ErrInvalidInput    = errors.New("invalid session launch input")
 26: 	ErrPeerUnavailable = errors.New("peer not connected")
