 32: // Request carries everything needed to launch one session.
 33: type Request struct {
 34: 	Name           string
 35: 	Host           string // empty, the current node ID, or a remote target host ID
 36: 	Path           string
 37: 	Command        string
 38: 	AgentType      string
 39: 	WorktreeBranch string
 40: 	ScheduleID     string
 41: 	LocalHost      string // the current node ID, used both for target classification (local vs remote) and for local schedule-metadata key construction
 42: 	Fallback       string // used only for local requests when a name cannot be derived
 43: 	CommandID      string // stable command id for v2 state commands (optional)
 44: 
 45: 	Cols uint16
 46: 	Rows uint16
 47: }
 48: 
 49: // Result reports the session that was launched.
 50: type Result struct {
 51: 	Name   string
 52: 	Host   string
 53: 	Path   string
 54: 	Remote bool
 55: }
