 68: // ScheduleAttr is the metadata snapshot the launch service stores and fans out.
 69: type ScheduleAttr struct {
 70: 	Background bool
 71: 	Hidden     bool
 72: 	ScheduleID string
 73: 	UpdatedAt  time.Time
 74: }
 75: 
 76: // AttrStoreFunc lets callers satisfy ScheduleAttrStore with a plain function.
 77: type AttrStoreFunc func(key, scheduleID string) (ScheduleAttr, error)
 78: 
 79: // SetScheduleID implements ScheduleAttrStore.
 80: func (f AttrStoreFunc) SetScheduleID(key, scheduleID string) (ScheduleAttr, error) {
 81: 	return f(key, scheduleID)
