 99: // RemoteLauncher dispatches a launch for a non-local host. A nil launcher
100: // means remote launching is unavailable.
101: type RemoteLauncher func(ctx context.Context, req Request) (Result, error)
102: 
103: // PeerFanout broadcasts a single-key schedule-attribute delta to other peers.
104: // nil skips fan-out.
105: type PeerFanout func(key string, attr ScheduleAttr)
