134: // Create validates, resolves, and launches one session.
135: func (s *Service) Create(ctx context.Context, req Request) (Result, error) {
136: 	req = s.normalize(req)
137: 	if err := s.validate(req); err != nil {
138: 		return Result{}, err
139: 	}
140: 
141: 	if req.Host != "" && req.Host != req.LocalHost {
142: 		return s.createRemote(ctx, req)
143: 	}
144: 	req.Host = ""
145: 	return s.createLocal(ctx, req)
146: }
