148: func (s *Service) normalize(req Request) Request {
149: 	req.Name = strings.TrimSpace(req.Name)
150: 	req.Host = strings.TrimSpace(req.Host)
151: 	req.Path = strings.TrimSpace(req.Path)
152: 	req.Command = strings.TrimSpace(req.Command)
153: 	req.AgentType = strings.TrimSpace(req.AgentType)
154: 	req.WorktreeBranch = strings.TrimSpace(req.WorktreeBranch)
155: 	return req
156: }
157: 
158: func (s *Service) validate(req Request) error {
159: 	name := strings.TrimSpace(req.Name)
160: 	if name == "" {
161: 		name = defaultSessionName(req.Command, req.Path)
162: 	}
163: 	if name == "" {
164: 		name = strings.TrimSpace(req.Fallback)
165: 	}
166: 	if name == "" {
167: 		return fmt.Errorf("%w: name or path is required", ErrInvalidInput)
168: 	}
169: 	if err := model.ValidateSessionName(name); err != nil {
170: 		return fmt.Errorf("%w: %w", ErrInvalidInput, err)
171: 	}
172: 	return nil
173: }
