175: func (s *Service) createRemote(ctx context.Context, req Request) (Result, error) {
176: 	if s.Remote == nil {
177: 		return Result{}, fmt.Errorf("%w: %s", ErrPeerUnavailable, req.Host)
178: 	}
179: 
180: 	req.Name = s.resolveName(req)
181: 
182: 	res, err := s.Remote(ctx, req)
183: 	if err != nil {
184: 		return Result{}, err
185: 	}
186: 	res.Remote = true
187: 
188: 	if s.Attrs != nil && req.ScheduleID != "" {
189: 		key := sessionKey(req.Host, res.Name)
190: 		attr, err := s.Attrs.SetScheduleID(key, req.ScheduleID)
191: 		if err != nil {
192: 			logrus.WithError(err).Warn("failed to store schedule id for remote session")
193: 		} else {
194: 			if s.Fanout != nil {
195: 				s.Fanout(key, attr)
196: 			}
197: 			if s.Hub != nil {
198: 				s.Hub.BroadcastJSON(map[string]interface{}{"type": "session-attrs-updated", "key": key})
199: 			}
200: 		}
201: 	}
202: 
203: 	return res, nil
204: }
