206: func (s *Service) createLocal(ctx context.Context, req Request) (Result, error) {
207: 	req.Name = s.resolveName(req)
208: 
209: 	if s.V2Commander != nil {
210: 		return s.createLocalV2(ctx, req)
211: 	}
212: 
213: 	cwd, err := s.prepareLocalPath(req)
214: 	if err != nil {
215: 		return Result{}, err
216: 	}
217: 
218: 	if err := s.daemonCreate(ctx, req.Name, req.Command, cwd, req.Cols, req.Rows); err != nil {
219: 		if cwd != req.Path && req.Path != "" {
220: 			_ = git.RemoveWorktree(cwd)
221: 		}
222: 		return Result{}, err
223: 	}
224: 
225: 	if s.StateMgr != nil && req.AgentType != "" {
226: 		s.StateMgr.SetSessionAgentType(req.Name, req.AgentType)
227: 	}
228: 
229: 	if s.Attrs != nil && req.ScheduleID != "" {
230: 		key := sessionKey(req.LocalHost, req.Name)
231: 		attr, err := s.Attrs.SetScheduleID(key, req.ScheduleID)
232: 		if err != nil {
233: 			logrus.WithError(err).Warn("failed to store schedule id")
234: 		} else {
235: 			if s.Fanout != nil {
236: 				s.Fanout(key, attr)
237: 			}
238: 			if s.Hub != nil {
239: 				s.Hub.BroadcastJSON(map[string]interface{}{"type": "session-attrs-updated", "key": key})
240: 			}
241: 		}
242: 	}
243: 
244: 	if s.Refresh != nil {
245: 		s.Refresh()
246: 	}
247: 
248: 	return Result{Name: req.Name, Host: req.Host, Path: cwd}, nil
249: }
