251: func (s *Service) createLocalV2(ctx context.Context, req Request) (Result, error) {
252: 	cmdID := state.CommandID(req.CommandID)
253: 	if cmdID == "" {
254: 		cmdID = state.NewCommandID()
255: 	}
256: 	params, _ := json.Marshal(state.CreateParams{
257: 		Name:           req.Name,
258: 		Shell:          req.Command,
259: 		Cwd:            req.Path,
260: 		WorktreeBranch: req.WorktreeBranch,
261: 		Cols:           req.Cols,
262: 		Rows:           req.Rows,
263: 		AgentType:      req.AgentType,
264: 	})
265: 	res, err := s.V2Commander.ExecuteSessionCommand(ctx, state.SessionCommand{
266: 		ID:     cmdID,
267: 		Ref:    state.SessionRef{},
268: 		Action: state.ActionCreate,
269: 		Params: params,
270: 	})
271: 	if err != nil {
272: 		return Result{}, err
273: 	}
274: 	if s.StateMgr != nil && req.AgentType != "" {
275: 		s.StateMgr.SetSessionAgentType(res.DisplayName, req.AgentType)
276: 	}
277: 	if s.Attrs != nil && req.ScheduleID != "" {
278: 		key := sessionKey(req.LocalHost, res.DisplayName)
279: 		attr, err := s.Attrs.SetScheduleID(key, req.ScheduleID)
280: 		if err != nil {
281: 			logrus.WithError(err).Warn("failed to store schedule id")
282: 		} else {
283: 			if s.Fanout != nil {
284: 				s.Fanout(key, attr)
285: 			}
286: 			if s.Hub != nil {
287: 				s.Hub.BroadcastJSON(map[string]interface{}{"type": "session-attrs-updated", "key": key})
288: 			}
289: 		}
290: 	}
291: 	if s.Refresh != nil {
292: 		s.Refresh()
293: 	}
294: 	return Result{Name: res.DisplayName, Host: req.Host, Path: res.Path}, nil
295: }
