297: func (s *Service) prepareLocalPath(req Request) (string, error) {
298: 	cwd := req.Path
299: 	if cwd == "~" {
300: 		cwd = ""
301: 	}
302: 
303: 	if req.WorktreeBranch != "" && cwd != "" {
304: 		expanded := expandPath(cwd)
305: 		sanitized := strings.ReplaceAll(req.WorktreeBranch, "/", "-")
306: 		worktreesDir := filepath.Join(expanded, ".worktrees")
307: 		if err := os.MkdirAll(worktreesDir, 0755); err != nil {
308: 			return "", fmt.Errorf("%w: mkdir .worktrees: %w", ErrWorktree, err)
309: 		}
310: 		destPath := filepath.Join(worktreesDir, sanitized)
311: 		if err := git.CreateWorktree(expanded, req.WorktreeBranch, destPath); err != nil {
312: 			return "", fmt.Errorf("%w: git worktree add: %w", ErrWorktree, err)
313: 		}
314: 		cwd = destPath
315: 	}
316: 
317: 	return cwd, nil
318: }
