320: func (s *Service) daemonCreate(ctx context.Context, name, command, cwd string, cols, rows uint16) error {
321: 	shell := command
322: 	if shell == "" || shell == "shell" {
323: 		shell = ""
324: 	}
325: 	if err := s.DaemonReg.Create(name, shell, cwd, cols, rows); err != nil {
326: 		return fmt.Errorf("%w: %w", ErrSpawn, err)
327: 	}
328: 	return nil
329: }
