331: func (s *Service) resolveName(req Request) string {
332: 	name := strings.TrimSpace(req.Name)
333: 	if name == "" {
334: 		name = defaultSessionName(req.Command, req.Path)
335: 	}
336: 	if name == "" {
337: 		name = strings.TrimSpace(req.Fallback)
338: 	}
339: 	if name == "" {
340: 		return ""
341: 	}
342: 	existing := []string(nil)
343: 	if s.Names != nil {
344: 		existing = s.Names(req.Host)
345: 	}
346: 	return ensureUniqueSessionName(name, existing)
347: }
348: 
349: func sessionKey(host, name string) string {
350: 	if host != "" {
351: 		return host + "/" + name
352: 	}
353: 	return name
354: }
355: 
356: func expandPath(p string) string {
357: 	if strings.HasPrefix(p, "~") {
358: 		if home, err := os.UserHomeDir(); err == nil && home != "" {
359: 			p = home + p[1:]
360: 		}
361: 	}
362: 	if !filepath.IsAbs(p) {
363: 		if home, err := os.UserHomeDir(); err == nil {
364: 			p = filepath.Join(home, p)
365: 		}
366: 	}
367: 	return p
368: }
369: 
370: func defaultSessionName(command, projectPath string) string {
371: 	base := strings.TrimSpace(command)
372: 	if idx := strings.IndexByte(base, ' '); idx >= 0 {
373: 		base = base[:idx]
374: 	}
375: 	base = strings.Trim(base, `"'`)
376: 	base = strings.TrimSpace(base)
377: 	if base == "" {
378: 		base = "session"
379: 	}
380: 	if projectPath == "" {
381: 		return ""
382: 	}
383: 
384: 	projectBase := strings.TrimSpace(projectPath)
385: 	projectBase = strings.TrimRight(projectBase, "/")
386: 	if idx := strings.LastIndex(projectBase, "/"); idx >= 0 {
387: 		projectBase = projectBase[idx+1:]
388: 	}
389: 	projectBase = sanitizeSessionSegment(projectBase)
390: 	if projectBase == "" {
391: 		projectBase = "workspace"
392: 	}
393: 
394: 	return sanitizeSessionSegment(base) + "-" + projectBase
395: }
396: 
397: func ensureUniqueSessionName(name string, existing []string) string {
398: 	name = strings.TrimSpace(name)
399: 	if name == "" {
400: 		return ""
401: 	}
402: 
403: 	used := make(map[string]struct{}, len(existing))
404: 	for _, candidate := range existing {
405: 		candidate = strings.TrimSpace(candidate)
406: 		if candidate != "" {
407: 			used[candidate] = struct{}{}
408: 		}
409: 	}
410: 
411: 	if _, exists := used[name]; !exists {
412: 		return name
413: 	}
414: 
415: 	for i := 2; ; i++ {
416: 		candidate := fmt.Sprintf("%s-%d", name, i)
417: 		if _, exists := used[candidate]; !exists {
418: 			return candidate
419: 		}
420: 	}
421: }
422: 
423: func sanitizeSessionSegment(value string) string {
424: 	value = strings.ToLower(strings.TrimSpace(value))
425: 	if value == "" {
426: 		return ""
427: 	}
428: 	var b strings.Builder
429: 	lastDash := false
430: 	for _, r := range value {
431: 		switch {
432: 		case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
433: 			b.WriteRune(r)
434: 			lastDash = false
435: 		case r == '-', r == '_', r == '.', r == '/', r == ' ':
436: 			if !lastDash {
437: 				b.WriteByte('-')
438: 				lastDash = true
439: 			}
440: 		}
441: 	}
442: 	return strings.Trim(b.String(), "-")
443: }  1: package state
