 16: // UpdateSessions takes a snapshot of sessions from discovery, diffs against
 17: // previous state, and broadcasts changes.
 18: func (m *Manager) UpdateSessions(sessions []*model.Session) {
 19: 	// Load full details for each session
 20: 	for _, session := range sessions {
 21: 		if err := m.loadSessionDetails(session); err != nil {
 22: 			logrus.WithError(err).WithField("session", session.Name).Warn("failed to load session details")
 23: 		}
 24: 	}
 25: 
 26: 	m.mu.Lock()
 27: 	// Build new map
 28: 	newMap := make(map[string]*model.Session, len(sessions))
 29: 	for _, s := range sessions {
 30: 		newMap[s.Name] = s
 31: 	}
 32: 
 33: 	// --- Mass-removal safety guards ---
 34: 	// These protect against transient discovery failures (e.g. socket directory
 35: 	// temporarily unreadable) that would otherwise wipe every tracked session
 36: 	// from state, violating the "sessions must not disappear without explicit
 37: 	// user action" guarantee.
 38: 
 39: 	// Guard 1: if ALL sessions vanished from discovery, this is almost always a
 40: 	// transient discovery failure, so skip the cycle — UNLESS every vanished
 41: 	// session is individually confirmed dead (clean exit, intentional kill, or
 42: 	// dismiss). That exception covers the "killed the last session" case: the
 43: 	// daemon removes its socket on exit, discovery returns empty, and without
 44: 	// this the dead session would linger in the sidebar forever as
 45: 	// "disconnected — reconnecting".
 46: 	allDead := false
 47: 	if len(m.sessions) > 0 && len(newMap) == 0 {
 48: 		allDead = m.daemonReg != nil
 49: 		if allDead {
 50: 			for name := range m.sessions {
 51: 				if !m.daemonReg.IsSessionDead(name) {
 52: 					allDead = false
 53: 					break
 54: 				}
 55: 			}
 56: 		}
 57: 		if !allDead {
 58: 			logrus.Warn("state: all sessions disappeared from discovery — skipping removal (likely transient)")
 59: 			m.mu.Unlock()
 60: 			return
 61: 		}
 62: 		logrus.Info("state: all sessions disappeared from discovery and are confirmed dead — removing")
 63: 	}
 64: 
 65: 	// Compute which sessions would be removed (deferred action so we can guard).
 66: 	removed := make([]string, 0)
 67: 	for name := range m.sessions {
 68: 		if _, ok := newMap[name]; !ok {
 69: 			removed = append(removed, name)
 70: 		}
 71: 	}
 72: 
 73: 	// Guard 2: don't remove more than 50% of sessions in one cycle (unless we
 74: 	// only had 2 or fewer — a single intentional kill would look like 50%).
 75: 	// Removing 1-2 sessions is fine; removing MOST sessions is almost certainly
 76: 	// a discovery bug, not real session death. Skip when Guard 1 already
 77: 	// confirmed every vanished session is genuinely dead.
 78: 	if !allDead && len(removed) > len(m.sessions)/2 && len(m.sessions) > 2 {
 79: 		logrus.WithFields(logrus.Fields{
 80: 			"current":      len(m.sessions),
 81: 			"would_remove": len(removed),
 82: 		}).Warn("state: would remove majority of sessions — skipping removal (likely transient)")
 83: 		m.mu.Unlock()
 84: 		return
 85: 	}
 86: 
 87: 	// Now perform the actual removals. A session that vanishes from discovery
 88: 	// (e.g. killed outside termyard's UI) must also have its metadata dropped,
 89: 	// otherwise a later session reusing the same name inherits stale state.
 90: 	for _, name := range removed {
 91: 		delete(m.meta, name)
 92: 		m.evictPreview(name)
 93: 		m.mu.Unlock()
 94: 		m.broadcast(StateEvent{Type: "session-removed", Session: name})
 95: 		m.mu.Lock()
 96: 	}
 97: 
 98: 	// Detect added sessions
 99: 	for name := range newMap {
100: 		if _, ok := m.sessions[name]; !ok {
101: 			m.mu.Unlock()
102: 			m.broadcast(StateEvent{Type: "session-added", Session: name})
103: 			m.mu.Lock()
104: 		}
105: 	}
106: 
107: 	m.sessions = newMap
108: 	m.mu.Unlock()
109: 
110: 	// Persist name changes when sessions were removed so the on-disk names file
111: 	// does not resurrect stale labels for a future same-name session after restart.
112: 	if len(removed) > 0 {
113: 		m.saveNames()
114: 	}
115: 
116: 	// Shadow-mode v2 comparison: log mismatches but do not change legacy state.
117: 	if m.v2Enabled {
118: 		m.compareV2Shadow()
119: 	}
120: 
121: 	// Broadcast a general refresh event
122: 	m.broadcast(StateEvent{Type: "sessions-changed"})
123: }
124: 
125: // loadSessionDetails fills in windows and panes for a session.
126: func (m *Manager) loadSessionDetails(session *model.Session) error {
127: 	// All sessions are daemon-backed now.
128: 	m.loadDaemonSessionDetails(session)
129: 
130: 	// Detect linked git worktrees so the UI can offer cleanup on kill.
131: 	if session.ProjectPath != "" {
132: 		if ok, err := git.IsWorktree(session.ProjectPath); err == nil {
133: 			session.IsWorktree = ok
134: 			if ok {
135: 				if root, err := git.FindMainWorktreeRoot(session.ProjectPath); err == nil {
136: 					session.WorktreeParent = root
137: 				}
138: 			}
139: 		} else {
140: 			logrus.WithError(err).WithField("path", session.ProjectPath).Debug("git worktree check failed")
141: 		}
142: 	}
143: 
144: 	return nil
145: }
146: 
147: // loadDaemonSessionDetails populates a daemon session with a synthetic
148: // single-window, single-pane structure using daemon registry metadata.
149: func (m *Manager) loadDaemonSessionDetails(session *model.Session) {
150: 	if m.daemonReg == nil {
151: 		m.applyMetadata(session)
152: 		return
153: 	}
154: 
155: 	// Find this session's daemon metadata.
156: 	var info *pty.SessionInfo
157: 	for _, di := range m.daemonReg.List() {
158: 		if di.ID == session.Name {
159: 			info = &di
160: 			break
161: 		}
162: 	}
163: 
164: 	cwd := ""
165: 	pid := 0
166: 	if info != nil {
167: 		cwd = info.Cwd
168: 		pid = info.ShellPid
169: 		if pid == 0 {
170: 			pid = info.Pid
171: 		}
172: 		// Try to read live CWD from the shell process.
173: 		if pid > 0 {
174: 			if liveCwd, err := os.Readlink(fmt.Sprintf("/proc/%d/cwd", pid)); err == nil && liveCwd != "" {
175: 				cwd = liveCwd
176: 			}
177: 		}
178: 	}
179: 
180: 	// Build synthetic pane.
181: 	pane := &model.Pane{
182: 		ID:          session.Name + ":0.0",
183: 		Active:      true,
184: 		CurrentPath: cwd,
185: 		PID:         pid,
186: 	}
187: 	win := &model.Window{
188: 		ID:     session.Name + ":0",
189: 		Name:   session.Name,
190: 		Index:  0,
191: 		Active: true,
192: 		Panes:  []*model.Pane{pane},
193: 	}
194: 	session.Windows = []*model.Window{win}
195: 
196: 	if cwd != "" {
197: 		session.ProjectPath = cwd
198: 	}
199: 
200: 	// Use cached prompt preview; refresh asynchronously so discovery never
201: 	// waits on an expensive full ring capture.
202: 	if preview := m.preview(session.Name); preview != "" {
203: 		session.PromptPreview = preview
204: 	}
205: 	if m.shouldRefreshPreview(session.Name) {
206: 		go m.refreshPreview(session.Name)
207: 	}
208: 
209: 	m.applyMetadata(session)
210: }
211: 
212: // sessionHasLiveAgent reports whether any pane in the session currently has a
213: // recognized coding agent process running in its tree. Used to distinguish a
214: // live agent (keep its identity) from a session that used to run one but has
215: // reverted to a shell or other process (drop the stale identity).
216: func sessionHasLiveAgent(windows []*model.Window) bool {
217: 	for _, win := range windows {
218: 		for _, pane := range win.Panes {
219: 			if pane.PID <= 0 {
220: 				continue
221: 			}
222: 			if _, ok := toolevents.DetectAgentInProcessTree(pane.PID); ok {
223: 				return true
224: 			}
225: 		}
226: 	}
227: 	return false
228: }
