230: func (m *Manager) applyMetadata(session *model.Session) {
231: 	m.mu.RLock()
232: 	meta := m.meta[session.Name]
233: 	m.mu.RUnlock()
234: 
235: 	if meta.ProjectPath != "" && session.ProjectPath == "" {
236: 		session.ProjectPath = meta.ProjectPath
237: 	}
238: 	// Agent-derived metadata (identity, prompt, last message, AI-generated name)
239: 	// is only valid while the agent still runs in the session. Once it exits and
240: 	// the pane reverts to a shell or another command (e.g. a `pnpm dev` server
241: 	// that fronts as `node`), those values are stale and must not render. The
242: 	// process-tree check is done lazily and cached so sessions without agent
243: 	// metadata never pay for it.
244: 	agentChecked := false
245: 	agentPresent := false
246: 	agentAlive := func() bool {
247: 		if !agentChecked {
248: 			agentPresent = sessionHasLiveAgent(session.Windows)
249: 			agentChecked = true
250: 		}
251: 		return agentPresent
252: 	}
253: 
254: 	if session.AgentType == "" && meta.AgentType != "" {
255: 		if agentAlive() {
256: 			session.AgentType = model.NormalizeAgentType(meta.AgentType)
257: 		} else {
258: 			m.mu.Lock()
259: 			stored := m.meta[session.Name]
260: 			stored.AgentType = ""
261: 			m.meta[session.Name] = stored
262: 			m.mu.Unlock()
263: 		}
264: 	}
265: 	if meta.PromptPreview != "" && session.PromptPreview == "" {
266: 		session.PromptPreview = meta.PromptPreview
267: 	}
268: 	if meta.AgentSessionID != "" {
269: 		session.AgentSessionID = meta.AgentSessionID
270: 	}
271: 	if meta.UserPrompt != "" && session.UserPrompt == "" && agentAlive() {
272: 		session.UserPrompt = meta.UserPrompt
273: 	}
274: 	if meta.LastAgentMessage != "" && agentAlive() {
275: 		session.LastAgentMessage = meta.LastAgentMessage
276: 	}
277: 	// A user-set name is kept always; an AI-generated name is suppressed once
278: 	// the agent that produced it is gone, so the session reverts to its raw name.
279: 	if meta.DisplayName != "" && (meta.UserSetName || agentAlive()) {
280: 		session.DisplayName = meta.DisplayName
281: 	}
282: 	session.UserSetName = meta.UserSetName
283: }
284: 
285: // UpdateSessionMetadataFromEvent stores stable metadata derived from agent
286: // hooks so it remains available after transient status events are cleared.
287: func (m *Manager) UpdateSessionMetadataFromEvent(evt *toolevents.Event) {
288: 	if evt == nil || evt.Session == "" {
289: 		return
290: 	}
291: 
292: 	m.mu.Lock()
293: 	meta := m.meta[evt.Session]
294: 	changed := false
295: 	if evt.CWD != "" {
296: 		if meta.ProjectPath != evt.CWD {
297: 			changed = true
298: 		}
299: 		meta.ProjectPath = evt.CWD
300: 	}
301: 	if evt.Tool != "" {
302: 		tool := string(evt.Tool)
303: 		if meta.AgentType != tool {
304: 			changed = true
305: 		}
306: 		meta.AgentType = tool
307: 	}
308: 	// Only update PromptPreview from meaningful (non-transient) messages.
309: 	// Transient active-phase labels like "Working" / "Using tool" must not
310: 	// clobber the last meaningful agent message shown in the sidebar.
311: 	if evt.Message != "" && (meta.PromptPreview == "" || evt.Status != toolevents.StatusActive) {
312: 		if meta.PromptPreview != evt.Message {
313: 			changed = true
314: 		}
315: 		meta.PromptPreview = evt.Message
316: 	}
317: 	if evt.AgentSessionID != "" {
318: 		if meta.AgentSessionID != evt.AgentSessionID {
319: 			changed = true
320: 		}
321: 		meta.AgentSessionID = evt.AgentSessionID
322: 	}
323: 	firstPrompt := false
324: 	nameRefresh := false
325: 	if evt.UserPrompt != "" {
326: 		if meta.UserPrompt == "" {
327: 			meta.UserPrompt = evt.UserPrompt // first message; sidebar display, set once
328: 			if !meta.NameAssigned && !meta.UserSetName {
329: 				firstPrompt = true
330: 			}
331: 		}
332: 		if meta.LastUserPrompt != evt.UserPrompt {
333: 			meta.LastUserPrompt = evt.UserPrompt // always track latest for AI naming
334: 			changed = true
335: 			// A new user prompt steers the work; re-name (debounced) unless the
336: 			// first-prompt pass below already handles it.
337: 			if !firstPrompt && !meta.UserSetName &&
338: 				time.Since(meta.LastNamedAt) > nameRefreshInterval {
339: 				nameRefresh = true
340: 			}
341: 		}
342: 	}
343: 	if evt.AgentMessage != "" && meta.LastAgentMessage != evt.AgentMessage {
344: 		meta.LastAgentMessage = evt.AgentMessage
345: 		changed = true
346: 		// Re-name on completed turns as the work evolves, debounced per session.
347: 		// firstPrompt / a fresh user prompt already cover the other naming passes.
348: 		if !firstPrompt && !nameRefresh && !meta.UserSetName && evt.Status == toolevents.StatusCompleted &&
349: 			time.Since(meta.LastNamedAt) > nameRefreshInterval {
350: 			nameRefresh = true
351: 		}
352: 	}
353: 
354: 	if !changed {
355: 		m.mu.Unlock()
356: 		return
357: 	}
358: 
359: 	m.meta[evt.Session] = meta
360: 	if session := m.sessions[evt.Session]; session != nil {
361: 		if session.ProjectPath == "" && meta.ProjectPath != "" {
362: 			session.ProjectPath = meta.ProjectPath
363: 		}
364: 		if session.AgentType == "" && meta.AgentType != "" {
365: 			session.AgentType = model.NormalizeAgentType(meta.AgentType)
366: 		}
367: 		if session.PromptPreview == "" && meta.PromptPreview != "" {
368: 			session.PromptPreview = meta.PromptPreview
369: 		}
370: 		if meta.AgentSessionID != "" {
371: 			session.AgentSessionID = meta.AgentSessionID
372: 		}
373: 		if session.UserPrompt == "" && meta.UserPrompt != "" {
374: 			session.UserPrompt = meta.UserPrompt
375: 		}
376: 		if meta.LastAgentMessage != "" {
377: 			session.LastAgentMessage = meta.LastAgentMessage
378: 		}
379: 	}
380: 	m.mu.Unlock()
381: 
382: 	m.broadcast(StateEvent{Type: "sessions-changed"})
383: 
384: 	if firstPrompt || nameRefresh {
385: 		go m.triggerAgentNaming(evt.Session)
386: 	} else if meta.DisplayName != "" || meta.UserSetName {
387: 		// Named session whose prompt/message changed without a re-name: persist so
388: 		// the namer has fresh context after a restart instead of a stale prompt.
389: 		go m.saveNames()
390: 	}
391: }
