393: // SetSessionAgentType explicitly stores an agent type for a session,
394: // overriding inference. Used when a session is created with a known preset.
395: func (m *Manager) SetSessionAgentType(sessionName, agentType string) {
396: 	m.mu.Lock()
397: 	meta := m.meta[sessionName]
398: 	meta.AgentType = agentType
399: 	m.meta[sessionName] = meta
400: 	if session := m.sessions[sessionName]; session != nil && session.AgentType == "" {
401: 		session.AgentType = agentType
402: 	}
403: 	m.mu.Unlock()
404: }
