406: // GetSessionProjectPath returns the ProjectPath for a session, or empty string if unknown.
407: func (m *Manager) GetSessionProjectPath(name string) string {
408: 	m.mu.RLock()
409: 	defer m.mu.RUnlock()
410: 	if s, ok := m.sessions[name]; ok {
411: 		return s.ProjectPath
412: 	}
413: 	if meta, ok := m.meta[name]; ok {
414: 		return meta.ProjectPath
415: 	}
416: 	return ""
417: }
