419: // GetSessions returns all tracked sessions with full details.
420: func (m *Manager) GetSessions() []*model.Session {
421: 	m.mu.RLock()
422: 	result := make([]*model.Session, 0, len(m.sessions))
423: 	for _, s := range m.sessions {
424: 		result = append(result, s)
425: 	}
426: 	m.mu.RUnlock()
427: 	return result
428: }
