430: // SnapshotForManifest returns deep copies of current tracked sessions.
431: func (m *Manager) SnapshotForManifest() []*model.Session {
432: 	m.mu.RLock()
433: 	defer m.mu.RUnlock()
434: 
435: 	out := make([]*model.Session, 0, len(m.sessions))
436: 	for _, s := range m.sessions {
437: 		if s == nil {
438: 			continue
439: 		}
440: 		out = append(out, deepCopySession(s))
441: 	}
442: 	return out
443: }
444: 
445: func deepCopySession(s *model.Session) *model.Session {
446: 	if s == nil {
447: 		return nil
448: 	}
449: 	copySession := *s
450: 	if len(s.Windows) > 0 {
451: 		copySession.Windows = make([]*model.Window, 0, len(s.Windows))
452: 		for _, win := range s.Windows {
453: 			if win == nil {
454: 				continue
455: 			}
456: 			copyWin := *win
457: 			if len(win.Panes) > 0 {
458: 				copyWin.Panes = make([]*model.Pane, 0, len(win.Panes))
459: 				for _, pane := range win.Panes {
460: 					if pane == nil {
461: 						continue
462: 					}
463: 					copyPane := *pane
464: 					copyWin.Panes = append(copyWin.Panes, &copyPane)
465: 				}
466: 			}
467: 			copySession.Windows = append(copySession.Windows, &copyWin)
468: 		}
469: 	}
470: 	return &copySession
471: }
