473: // RemoveSession removes a session from the in-memory state, broadcasting
474: // removal events. Use this when a session no longer exists but the
475: // state manager still holds a reference to it.
476: func (m *Manager) RemoveSession(name string) {
477: 	m.mu.Lock()
478: 	delete(m.sessions, name)
479: 	delete(m.meta, name)
480: 	m.evictPreview(name)
481: 	m.mu.Unlock()
482: 	m.saveNames()
483: 	m.broadcast(StateEvent{Type: "session-removed", Session: name})
484: 	m.broadcast(StateEvent{Type: "sessions-changed"})
