 31: // SessionAttrsSink is the slice of pkg/sessionattrs the session loop needs in
 32: // order to merge shared session-attribute updates received from paired peers.
 33: // Kept narrow so pkg/peer doesn't pull pkg/sessionattrs directly.
 34: type SessionAttrsSink interface {
 35: 	// ApplyRemoteDelta merges a single-key delta via per-key LWW. accepted=false
 36: 	// means the local copy was newer-or-equal and the delta was dropped.
 37: 	ApplyRemoteDelta(key string, background, hidden bool, scheduleID string, updatedAt time.Time) (accepted bool, err error)
 38: 	// ApplyRemoteSnapshot merges a full peer snapshot via per-key LWW, returning
 39: 	// the keys that changed locally.
 40: 	ApplyRemoteSnapshot(attrs map[string]SessionAttr) (changed []string, err error)
 41: 	// SnapshotAttrs returns the full local attribute map to seed a fresh peer.
 42: 	SnapshotAttrs() map[string]SessionAttr
 43: 	// SetScheduleID records the owning schedule for a session this node spawned
 44: 	// locally on behalf of a remote peer's scheduler, keyed by the local session
 45: 	// key, so the run groups in this node's own UI.
 46: 	SetScheduleID(key, scheduleID string) error
 47: }
 48: 
 49: // SessionOrderSink is the narrow slice of session-order storage the peer loop
 50: // needs.
 51: type SessionOrderSink interface {
 52: 	ApplyRemoteDelta(key, rank string, updatedAt time.Time) (accepted bool, err error)
 53: 	ApplyRemoteSnapshot(orders map[string]SessionOrder) (changed []string, err error)
 54: 	SnapshotOrders() map[string]SessionOrder
 55: }
 56: 
 57: // GroupSink is the narrow slice of group storage the peer loop needs.
 58: type GroupSink interface {
 59: 	ApplyRemoteDelta(id string, group Group) (accepted bool, err error)
 60: 	ApplyRemoteSnapshot(groups map[string]Group) (changed []string, err error)
 61: 	SnapshotGroups() map[string]Group
 62: }
