102: // connWriter serializes WebSocket writes from multiple goroutines.
103: type connWriter struct {
104: 	mu   sync.Mutex
105: 	conn *websocket.Conn
106: }
107: 
108: // writeFrame writes one pre-serialized frame. Bound the write so a stuck/
109: // half-open peer socket can't block the writer goroutine indefinitely and
110: // silently back up the send lanes.
111: func (w *connWriter) writeFrame(f wireFrame) error {
112: 	w.mu.Lock()
113: 	defer w.mu.Unlock()
114: 	_ = w.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
115: 	err := w.conn.WriteMessage(websocket.TextMessage, f.data)
116: 	_ = w.conn.SetWriteDeadline(time.Time{})
117: 	return err
118: }
119: 
120: func (w *connWriter) writeControl(messageType int, data []byte, deadline time.Time) error {
121: 	w.mu.Lock()
122: 	defer w.mu.Unlock()
123: 	return w.conn.WriteControl(messageType, data, deadline)
124: }
125: 
126: // runSession owns the post-auth lifetime of one peer connection. It blocks
127: // until conn is closed or ctx is canceled. Same code runs on both ends.
128: func runSession(
129: 	ctx context.Context,
130: 	role Role,
131: 	conn *websocket.Conn,
132: 	peerInfo identity.Peer,
133: 	address string,
134: 	caps []string,
135: 	deps SessionDeps,
136: ) error {
137: 	peerID := peerInfo.Fingerprint()
138: 	log := logrus.WithFields(logrus.Fields{"peer": peerInfo.Name, "id": peerID})
139: 
140: 	cw := &connWriter{conn: conn}
141: 
142: 	pc := NewPeerConnection(peerID, 64)
143: 	pc.Role = role
144: 	pc.Caps = append([]string(nil), caps...)
145: 	pc.initV2Lazy()
146: 
147: 	var unsubWorkspace func()
148: 
149: 	// Subscribe to complete workspace snapshots after each accepted command
150: 	// so remote peers see the whole layout, never intermediate steps.
151: 	if cat := deps.Manager.localMgr.V2Catalog(); cat != nil {
152: 		unsubWorkspace = cat.SubscribeWorkspace(func(layout state.LayoutID, rec state.WorkspaceRecord) {
153: 			payload := V2WorkspaceSnapshotPayload{Owner: rec.Owner, Revision: rec.Revision, Workspace: rec}
154: 			msg, err := NewMessage(MsgV2WorkspaceSnapshot, payload)
155: 			if err != nil {
156: 				return
157: 			}
158: 			pc.EnqueueV2WorkspaceSnapshot(msg)
159: 		})
160: 	}
161: 
162: 	if !deps.Manager.TryRegisterPeer(peerID, peerInfo.Name, peerInfo.PublicKey, address, pc) {
163: 		return fmt.Errorf("peer already connected")
164: 	}
165: 
166: 	sessionCtx, cancel := context.WithCancel(ctx)
167: 
168: 	// Teardown order is crucial:
169: 	//   1. cancel session ctx — stops background producers
170: 	//   2. close websocket — unblocks read loop on the other goroutine, drains pings
171: 	//   3. unregister from manager — stops new HTTP-side producers from finding pc
172: 	//   4. close pc — ends writer loop
173: 	//   5. wait for writer to drain
174: 	writerDone := make(chan struct{})
175: 	v2WritersDone := make(chan struct{})
176: 	defer func() {
177: 		if unsubWorkspace != nil {
178: 			unsubWorkspace()
179: 		}
180: 		cancel()
181: 		_ = conn.Close()
182: 		deps.Manager.UnregisterPeerConn(peerID, pc)
183: 		pc.Close()
184: 		if pc.catalogSlot != nil {
185: 			pc.catalogSlot.close()
186: 		}
187: 		if pc.workspaceSlot != nil {
188: 			pc.workspaceSlot.close()
189: 		}
190: 		if pc.cmdQueue != nil {
191: 			pc.cmdQueue.close()
192: 		}
193: 		<-v2WritersDone
194: 		<-writerDone
195: 	}()
196: 
197: 	// If parent ctx is canceled while we're in ReadJSON, close conn to unblock.
198: 	go func() {
199: 		select {
200: 		case <-sessionCtx.Done():
201: 			_ = conn.Close()
202: 		}
203: 	}()
204: 
205: 	// Liveness: ping/pong with 15s ping, 30s read deadline.
206: 	conn.SetPongHandler(func(string) error {
207: 		conn.SetReadDeadline(time.Now().Add(30 * time.Second))
208: 		return nil
209: 	})
210: 	conn.SetPingHandler(func(data string) error {
211: 		conn.SetReadDeadline(time.Now().Add(30 * time.Second))
212: 		return cw.writeControl(websocket.PongMessage, []byte(data), time.Now().Add(5*time.Second))
213: 	})
214: 	conn.SetReadDeadline(time.Now().Add(30 * time.Second))
215: 
216: 	// Writer goroutine drains the two priority lanes to conn, favouring the
217: 	// hi (interactive PTY) lane over the lo (bulky control-plane) lane so a fat
218: 	// state snapshot never delays a keystroke echo. The hi drain is capped per
219: 	// cycle: an unbounded burst would starve lo entirely under continuous PTY
220: 	// output, stranding lo-lane traffic (state sync, etc.). After the burst we
221: 	// fall to a fair select where lo gets an equal chance. Any write failure
222: 	// cancels the session so the read loop unblocks.
223: 	go func() {
224: 		defer close(writerDone)
225: 		hi, lo := pc.HiLane(), pc.LoLane()
226: 		const maxHiBurst = 64
227: 		for {
228: 			// Fast path: drain hi, but at most maxHiBurst frames before yielding.
229: 			burst := 0
230: 			for burst < maxHiBurst {
231: 				select {
232: 				case f := <-hi:
233: 					if err := cw.writeFrame(f); err != nil {
234: 						log.WithError(err).Debug("session write failed")
235: 						cancel()
236: 						return
237: 					}
238: 					burst++
239: 					continue
240: 				default:
241: 				}
242: 				break
243: 			}
244: 			// Block on hi, lo, or teardown. select picks a ready case at random,
245: 			// so lo can't be starved even when hi is continuously ready.
246: 			select {
247: 			case f := <-hi:
248: 				if err := cw.writeFrame(f); err != nil {
249: 					log.WithError(err).Debug("session write failed")
250: 					cancel()
251: 					return
252: 				}
253: 			case f := <-lo:
254: 				if err := cw.writeFrame(f); err != nil {
255: 					log.WithError(err).Debug("session write failed")
256: 					cancel()
257: 					return
258: 				}
259: 			case <-pc.Done():
260: 				return
261: 			}
262: 		}
263: 	}()
264: 
265: 	// Initial pushes — both sides advertise themselves.
266: 	sendStateUpdate(pc, deps)
267: 	sendInitialPeerState(pc, deps, peerID)
268: 	sendInitialSessionAttrs(pc, deps)
269: 	sendInitialSessionOrder(pc, deps)
270: 	sendInitialGroups(pc, deps)
271: 	if pc.HasV2() {
272: 		sendInitialV2Catalog(pc, deps)
273: 		sendInitialV2Workspace(pc, deps)
274: 	}
275: 
276: 	go func() {
277: 		defer close(v2WritersDone)
278: 		runV2Writers(sessionCtx, pc, log)
279: 	}()
280: 
281: 	// Background loops.
282: 	go pingLoop(sessionCtx, cw)
283: 	go periodicActivity(sessionCtx, pc, deps)
284: 	go periodicStats(sessionCtx, pc, deps)
285: 	go forwardStateEvents(sessionCtx, pc, deps)
286: 	go forwardToolEvents(sessionCtx, pc, deps, peerID)
287: 	go forwardPeerStateChanges(sessionCtx, pc, deps, peerID)
288: 
289: 	for {
290: 		_, raw, err := conn.ReadMessage()
291: 		if err != nil {
292: 			if !websocket.IsCloseError(err, websocket.CloseGoingAway, websocket.CloseNormalClosure) {
293: 				log.WithError(err).Debug("session read error")
294: 			}
295: 			return err
296: 		}
297: 		var msg Message
298: 		if err := json.Unmarshal(raw, &msg); err != nil {
299: 			log.WithError(err).Debug("session read error")
300: 			continue
301: 		}
302: 		if msg.Type == MsgForget {
303: 			log.Info("peer sent forget — removing")
304: 			if err := deps.PeerStore.RemoveByPublicKey(peerInfo.PublicKey); err != nil {
305: 				log.WithError(err).Debug("forget remove failed")
306: 			}
307: 			deps.Manager.RemoveHost(peerID)
308: 			return fmt.Errorf("peer forgot us")
309: 		}
310: 		handleSessionMessage(peerID, &msg, pc, deps, log)
311: 	}
312: }
313: 
314: func pingLoop(ctx context.Context, cw *connWriter) {
315: 	t := time.NewTicker(15 * time.Second)
316: 	defer t.Stop()
317: 	for {
318: 		select {
319: 		case <-ctx.Done():
320: 			return
321: 		case <-t.C:
322: 			if err := cw.writeControl(websocket.PingMessage, nil, time.Now().Add(5*time.Second)); err != nil {
323: 				return
324: 			}
325: 		}
326: 	}
327: }
328: 
329: func periodicActivity(ctx context.Context, pc *PeerConnection, deps SessionDeps) {
330: 	t := time.NewTicker(5 * time.Second)
331: 	defer t.Stop()
332: 	localID := deps.Manager.LocalID()
333: 	for {
334: 		select {
335: 		case <-ctx.Done():
336: 			return
337: 		case <-t.C:
338: 			snapshots := deps.ActTracker.GetAll()
339: 			for _, s := range snapshots {
340: 				if s.Host == "" {
341: 					s.Host = localID
342: 				}
343: 			}
344: 			msg, err := NewMessage(MsgActivityUpdate, ActivityUpdatePayload{Snapshots: snapshots})
345: 			if err != nil {
346: 				continue
347: 			}
348: 			pc.Enqueue(msg)
349: 		}
350: 	}
351: }
352: 
353: func collectStats(deps SessionDeps) map[string]interface{} {
354: 	s := stats.SystemStats()
355: 	sessions := deps.LocalMgr.GetSessions()
356: 	s["processes"] = stats.ProcessCountsFromSessions(sessions)
357: 	return s
358: }
359: 
360: func periodicStats(ctx context.Context, pc *PeerConnection, deps SessionDeps) {
361: 	// Send immediately.
362: 	if msg, err := NewMessage(MsgStats, StatsPayload{Stats: collectStats(deps)}); err == nil {
363: 		pc.Enqueue(msg)
364: 	}
365: 	t := time.NewTicker(30 * time.Second)
366: 	defer t.Stop()
367: 	for {
368: 		select {
369: 		case <-ctx.Done():
370: 			return
371: 		case <-t.C:
372: 			if msg, err := NewMessage(MsgStats, StatsPayload{Stats: collectStats(deps)}); err == nil {
373: 				pc.Enqueue(msg)
374: 			}
375: 		}
376: 	}
377: }
378: 
379: func forwardStateEvents(ctx context.Context, pc *PeerConnection, deps SessionDeps) {
380: 	ch := deps.LocalMgr.Subscribe()
381: 	defer deps.LocalMgr.Unsubscribe(ch)
382: 	for {
383: 		select {
384: 		case <-ctx.Done():
385: 			return
386: 		case evt, ok := <-ch:
387: 			if !ok {
388: 				return
389: 			}
390: 			msg, err := NewMessage(MsgStateEvent, StateEventPayload{
391: 				EventType: evt.Type,
392: 				Session:   evt.Session,
393: 				Data:      evt.Data,
394: 			})
395: 			if err != nil {
396: 				continue
397: 			}
398: 			pc.Enqueue(msg)
399: 			sendStateUpdate(pc, deps)
400: 		}
401: 	}
402: }
403: 
404: func forwardToolEvents(ctx context.Context, pc *PeerConnection, deps SessionDeps, remotePeerID string) {
405: 	ch := deps.ToolTracker.Subscribe()
406: 	defer deps.ToolTracker.Unsubscribe(ch)
407: 	for {
408: 		select {
409: 		case <-ctx.Done():
410: 			return
411: 		case evt, ok := <-ch:
412: 			if !ok {
413: 				return
414: 			}
415: 			// Don't echo the peer's own events back — this would create a
416: 			// ping-pong loop: peer A's event arrives, gets stamped Host=A,
417: 			// records locally, broadcasts to subscribers, and would forward
418: 			// straight back to A, which re-stamps and re-forwards forever.
419: 			if evt.Host == remotePeerID {
420: 				continue
421: 			}
422: 			// Only forward our own local-origin events; we don't transitively
423: 			// relay other peers' events.
424: 			if evt.Host != "" && evt.Host != deps.Manager.LocalID() {
425: 				continue
426: 			}
427: 			msg, err := NewMessage(MsgToolEvent, ToolEventPayload{Event: evt})
428: 			if err != nil {
429: 				continue
430: 			}
431: 			pc.Enqueue(msg)
432: 		}
433: 	}
434: }
435: 
436: // forwardPeerStateChanges pushes a peer-state snapshot whenever local state
437: // changes, so the remote sees our updated session list / activity / stats.
438: func forwardPeerStateChanges(ctx context.Context, pc *PeerConnection, deps SessionDeps, remotePeerID string) {
439: 	ch := deps.Manager.Subscribe()
440: 	defer deps.Manager.Unsubscribe(ch)
441: 	for {
442: 		select {
443: 		case <-ctx.Done():
444: 			return
445: 		case evt, ok := <-ch:
446: 			if !ok {
447: 				return
448: 			}
449: 			// Don't echo the peer's own events back.
450: 			if evt.Host == remotePeerID {
451: 				continue
452: 			}
453: 			// Only push peer-state when our local host changed; we don't
454: 			// transitively expose other peers.
455: 			if evt.Host != "" && evt.Host != deps.Manager.LocalID() {
456: 				continue
457: 			}
458: 			msg, err := NewMessage(MsgPeerState, PeerStatePayload{
459: 				Hosts: deps.Manager.GetHostsForPeer(remotePeerID),
460: 			})
461: 			if err != nil {
462: 				continue
463: 			}
464: 			pc.Enqueue(msg)
465: 		}
466: 	}
467: }
468: 
469: // handleSessionMessage dispatches messages received from the remote peer.
470: func handleSessionMessage(peerID string, msg *Message, pc *PeerConnection, deps SessionDeps, log *logrus.Entry) {
471: 	switch msg.Type {
472: 	case MsgStateUpdate,
473: 		MsgStateEvent,
474: 		MsgActivityUpdate,
475: 		MsgStats,
476: 		MsgPeerState,
477: 		MsgPeerConnected,
478: 		MsgPeerDisconnected,
479: 		MsgRequestState:
480: 		handleStateMessage(peerID, msg, pc, deps, log)
481: 
482: 	case MsgOpenTerminal,
483: 		MsgCapturePane,
484: 		MsgCapturePaneResult,
485: 		MsgFileRead,
486: 		MsgOpenUpload,
487: 		MsgFileReadResult:
488: 		handleStreamMessage(peerID, msg, pc, deps, log)
489: 
490: 	case MsgSessionAttrsSnapshot,
491: 		MsgSessionAttrsDelta,
492: 		MsgSessionOrderSnapshot,
493: 		MsgSessionOrderDelta,
494: 		MsgGroupSnapshot,
495: 		MsgGroupDelta:
496: 		handleAttrsMessage(peerID, msg, pc, deps, log)
497: 
498: 	case MsgSessionAction:
499: 		handleActionMessage(msg, pc, deps, log)
500: 
501: 	case MsgV2CatalogSnapshot,
502: 		MsgV2WorkspaceSnapshot,
503: 		MsgV2CommandRequest,
504: 		MsgV2CommandReply:
505: 		handleV2Message(peerID, msg, pc, deps, log)
506: 
507: 	default:
508: 		log.WithField("type", msg.Type).Debug("unknown session message")
509: 	}
