 23: // Frame types for the daemon wire protocol.
 24: const (
 25: 	FrameOutput        = 0x01 // daemon → client: raw PTY output
 26: 	FrameInput         = 0x02 // client → daemon: raw bytes to write to PTY
 27: 	FrameResize        = 0x03 // client → daemon: 4 bytes (cols u16 BE + rows u16 BE)
 28: 	FrameClose         = 0x04 // client → daemon: kill shell
 29: 	FrameReplay        = 0x05 // daemon → client: ring buffer contents on connect
 30: 	FrameQueryBuffer   = 0x06 // client → daemon: request ring buffer replay (0 payload)
 31: 	FrameQueryIdentity = 0x07 // client → daemon: request stable identity
 32: 	FrameIdentity      = 0x08 // daemon → client: stable identity payload
 33: )
 34: 
 35: // DaemonConfig configures a session daemon.
 36: type DaemonConfig struct {
 37: 	ID          string // daemon/socket identifier (legacy; now the daemon key)
 38: 	Shell       string // shell to spawn (default: $SHELL or /bin/bash)
 39: 	Cols, Rows  uint16 // initial terminal size
 40: 	Cwd         string // working directory
 41: 	SocketDir   string // directory for Unix sockets (default: /tmp/termyard-sessions-{uid}/)
 42: 	StateDir    string // directory for lifecycle state (default: XDG_STATE_HOME/termyard/sessions/)
 43: 	SystemdUnit string // systemd scope unit name for cleanup (empty if not using systemd)
 44: 	BufferSize  int    // ring buffer size in bytes (default: 8MB)
 45: 
 46: 	// Stable identity fields (v2). Empty values mean legacy mode; the daemon
 47: 	// still binds the socket using ID, and the registry falls back to
 48: 	// process/socket evidence for those sessions.
 49: 	Owner     string
 50: 	SessionID string
 51: 	Generation string
 52: 	CommandID string
 53: }
 54: 
 55: // RunDaemon is the entry point for a session daemon process.
 56: // It creates a PTY, spawns the shell, listens on a Unix socket,
 57: // and serves clients until the shell exits or Close is received.
 58: // sessionMeta is written as a JSON sidecar file alongside the socket.
 59: type sessionMeta struct {
 60: 	ID          string `json:"id"`
 61: 	Pid         int    `json:"pid"`
 62: 	ShellPid    int    `json:"shell_pid"`
 63: 	Shell       string `json:"shell"`
 64: 	Cwd         string `json:"cwd"`
 65: 	Created     string `json:"created"`
 66: 	Cols        uint16 `json:"cols"`
 67: 	Rows        uint16 `json:"rows"`
 68: 	SystemdUnit string `json:"systemd_unit,omitempty"`
 69: 
 70: 	// Stable identity fields (v2), omitted when running in legacy mode.
 71: 	Owner      string `json:"owner,omitempty"`
 72: 	SessionID  string `json:"session_id,omitempty"`
 73: 	Generation string `json:"generation,omitempty"`
 74: 	CommandID  string `json:"command_id,omitempty"`
 75: }
 76: 
 77: func RunDaemon(cfg DaemonConfig) error {
 78: 	// Ensure we're a session leader so we survive parent/server restarts.
 79: 	// Registry.Create sets Setsid on the child, but if someone starts us
 80: 	// directly (e.g. systemd, manual invocation) we need our own session.
 81: 	syscall.Setsid() // no-op if already a session leader
 82: 	signal.Ignore(syscall.SIGHUP)
 83: 
 84: 	if cfg.Shell == "" {
 85: 		cfg.Shell = os.Getenv("SHELL")
 86: 		if cfg.Shell == "" {
 87: 			cfg.Shell = "/bin/bash"
 88: 		}
 89: 	}
 90: 	if cfg.SocketDir == "" {
 91: 		cfg.SocketDir = fmt.Sprintf("/tmp/termyard-sessions-%d", os.Getuid())
 92: 	}
 93: 	if cfg.BufferSize <= 0 {
 94: 		cfg.BufferSize = 8 << 20 // 8 MB
 95: 	}
 96: 
 97: 	log := logrus.WithFields(logrus.Fields{
 98: 		"id":    cfg.ID,
 99: 		"shell": cfg.Shell,
100: 		"cols":  cfg.Cols,
101: 		"rows":  cfg.Rows,
102: 	})
103: 
104: 	// 1. Create PTY + spawn shell.
105: 	//
106: 	// When Shell is a bare interactive shell binary (bash/zsh/etc.), run it
107: 	// directly. Otherwise treat it as a command to run inside the user's default
108: 	// shell. The command is injected into the PTY after startup so the shell
109: 	// stays alive after the command exits (user lands at a shell prompt).
110: 	// This also handles commands with arguments like "pi -c" which exec.Command
111: 	// cannot spawn directly (it would look for a binary named "pi -c").
112: 	var cmd *exec.Cmd
113: 	var initCommand string // non-empty → inject into PTY after shell starts
114: 	if isInteractiveShell(cfg.Shell) {
115: 		cmd = exec.Command(cfg.Shell)
116: 	} else {
117: 		defaultShell := os.Getenv("SHELL")
118: 		if defaultShell == "" {
119: 			defaultShell = "/bin/bash"
120: 		}
121: 		cmd = exec.Command(defaultShell)
122: 		initCommand = cfg.Shell
123: 	}
124: 	cmd.Env = directLocaleEnv()
125: 	cmd.Env = append(cmd.Env, "TERM=xterm-256color")
126: 	cmd.Env = append(cmd.Env, "TERMYARD_SESSION="+cfg.ID)
127: 	cmd.Env = append(cmd.Env, "TERMYARD_PANE="+cfg.ID+":0.0")
128: 	// v2 stable identity environment variables.
129: 	if cfg.Owner != "" {
130: 		cmd.Env = append(cmd.Env, "TERMYARD_OWNER="+cfg.Owner)
131: 	}
132: 	if cfg.SessionID != "" {
133: 		cmd.Env = append(cmd.Env, "TERMYARD_SESSION_ID="+cfg.SessionID)
134: 	}
135: 	if cfg.Generation != "" {
136: 		cmd.Env = append(cmd.Env, "TERMYARD_GENERATION="+cfg.Generation)
137: 	}
138: 	if cfg.CommandID != "" {
139: 		cmd.Env = append(cmd.Env, "TERMYARD_COMMAND_ID="+cfg.CommandID)
140: 	}
141: 	if cfg.Cwd != "" {
142: 		cmd.Dir = cfg.Cwd
143: 	}
144: 
145: 	ptyFd, err := pty.StartWithSize(cmd, &pty.Winsize{
146: 		Cols: cfg.Cols,
147: 		Rows: cfg.Rows,
148: 	})
149: 	if err != nil {
150: 		return fmt.Errorf("start PTY: %w", err)
151: 	}
152: 	log.Info("started session daemon PTY")
153: 
154: 	// If a non-shell command was requested, inject it into the PTY now.
155: 	// The shell buffers the input and executes it once it shows its first
156: 	// prompt. A short delay lets the shell finish its rc-file sourcing so
157: 	// PATH and environment are fully set up before the command runs.
158: 	if initCommand != "" {
159: 		go func() {
160: 			time.Sleep(150 * time.Millisecond)
161: 			_, _ = ptyFd.Write([]byte(initCommand + "\n"))
162: 		}()
163: 	}
164: 
165: 	// 2. Ring buffer.
166: 	ring := newRingBuffer(cfg.BufferSize)
167: 
168: 	// 3. Listen on Unix socket.
169: 	socketPath := filepath.Join(cfg.SocketDir, cfg.ID+".sock")
170: 	metadataPath := filepath.Join(cfg.SocketDir, cfg.ID+".json")
171: 	if err := os.MkdirAll(cfg.SocketDir, 0700); err != nil {
172: 		ptyFd.Close()
173: 		cmd.Process.Kill()
174: 		return fmt.Errorf("create socket dir: %w", err)
175: 	}
176: 
177: 	// Check whether a live daemon is already bound to this socket.
178: 	// If we can connect to it, refuse to start — we must not steal an
179: 	// active session.  If the socket file exists but nobody is listening,
180: 	// it is a stale leftover and we can safely remove it.
181: 	if isDaemonAlive(socketPath) {
182: 		ptyFd.Close()
183: 		killProcessGroup(cmd.Process.Pid)
184: 		return fmt.Errorf("session %q is already active (socket %s is live)", cfg.ID, socketPath)
185: 	}
186: 	os.Remove(socketPath)   // remove stale socket
187: 	os.Remove(metadataPath) // remove stale metadata
188: 
189: 	ln, err := net.Listen("unix", socketPath)
190: 	if err != nil {
191: 		ptyFd.Close()
192: 		killProcessGroup(cmd.Process.Pid)
193: 		return fmt.Errorf("listen on %s: %w", socketPath, err)
194: 	}
195: 	defer os.Remove(socketPath)
196: 	defer os.Remove(metadataPath)
197: 
198: 	// Write metadata sidecar so Registry.List can discover sessions.
199: 	meta := sessionMeta{
200: 		ID:          cfg.ID,
201: 		Pid:         os.Getpid(),
202: 		ShellPid:    cmd.Process.Pid,
203: 		Shell:       cfg.Shell,
204: 		Cwd:         cfg.Cwd,
205: 		Created:     time.Now().Format(time.RFC3339),
206: 		Cols:        cfg.Cols,
207: 		Rows:        cfg.Rows,
208: 		SystemdUnit: cfg.SystemdUnit,
209: 		Owner:       cfg.Owner,
210: 		SessionID:   cfg.SessionID,
211: 		Generation:  cfg.Generation,
212: 		CommandID:   cfg.CommandID,
213: 	}
214: 	metaBytes, _ := json.Marshal(meta)
215: 	if err := os.WriteFile(metadataPath, metaBytes, 0600); err != nil {
216: 		ptyFd.Close()
217: 		killProcessGroup(cmd.Process.Pid)
218: 		ln.Close()
219: 		return fmt.Errorf("write metadata: %w", err)
220: 	}
221: 
222: 	// 3b. Set up durable lifecycle state so crashes can be detected.
223: 	stateDir := cfg.StateDir
224: 	if stateDir == "" {
225: 		stateDir = DefaultStateDir()
226: 	}
227: 	lifecycleStore, lcErr := NewLifecycleStore(stateDir)
228: 	if lcErr != nil {
229: 		log.WithError(lcErr).Warn("cannot create lifecycle store — crash detection disabled")
230: 	} else {
231: 		pid := os.Getpid()
232: 		gen := cfg.Generation
233: 		if gen == "" {
234: 			gen = NewGeneration()
235: 		}
236: 		lr := LifecycleRecord{
237: 			ID:            cfg.ID,
238: 			Shell:         cfg.Shell,
239: 			Cwd:           cfg.Cwd,
240: 			Cols:          cfg.Cols,
241: 			Rows:          cfg.Rows,
242: 			DaemonPID:     pid,
243: 			SystemdUnit:   cfg.SystemdUnit,
244: 			Generation:    gen,
245: 			ProcStartTime: procStartTime(pid),
246: 			Owner:         cfg.Owner,
247: 			SessionID:     cfg.SessionID,
248: 			DaemonKey:     cfg.ID,
249: 			CommandID:     cfg.CommandID,
250: 		}
251: 		if err := lifecycleStore.RecordActive(lr); err != nil {
252: 			log.WithError(err).Warn("failed to write lifecycle record")
253: 		} else {
254: 			log.WithField("state_dir", stateDir).Debug("lifecycle store ready")
255: 		}
256: 	}
257: 
258: 	log.WithField("socket", socketPath).Info("daemon listening")
259: 
260: 	// 4. Build and run the daemon.
261: 	d := &daemon{
262: 		config:         cfg,
263: 		ptyFd:          ptyFd,
264: 		cmd:            cmd,
265: 		ring:           ring,
266: 		ln:             ln,
267: 		socketPath:     socketPath,
268: 		log:            log,
269: 		lifecycleStore: lifecycleStore,
270: 		clients:        make(map[net.Conn]chan []byte),
271: 		shellDone:      make(chan struct{}),
272: 	}
273: 
274: 	// Handle SIGTERM from `systemctl --user stop <scope>` (KillMode=
275: 	// control-group sends SIGTERM to the whole cgroup). Without this the
276: 	// daemon ignores it and gets SIGKILLed after the 90s stop timeout,
277: 	// leaving a lingering `failed` scope. shutdown() is idempotent.
278: 	sigCh := make(chan os.Signal, 1)
279: 	signal.Notify(sigCh, syscall.SIGTERM)
280: 	go func() {
281: 		<-sigCh
282: 		log.Debug("received SIGTERM, shutting down")
283: 		d.shutdown()
284: 	}()
285: 
286: 	return d.run()
287: }
288: 
289: // ringBuffer is a simple circular byte buffer.
290: type ringBuffer struct {
291: 	buf  []byte
292: 	head int // next write position
293: 	tail int // oldest read position
294: 	size int // number of valid bytes
295: 	mu   sync.Mutex
296: }
297: 
298: func newRingBuffer(capacity int) *ringBuffer {
299: 	return &ringBuffer{buf: make([]byte, capacity)}
300: }
301: 
302: // Write appends data to the ring buffer, overwriting oldest data if full.
303: // Uses at most two slice copies instead of per-byte modulo.
304: func (r *ringBuffer) Write(data []byte) {
305: 	r.mu.Lock()
306: 	defer r.mu.Unlock()
307: 
308: 	if len(data) == 0 {
309: 		return
310: 	}
311: 
312: 	n := len(r.buf)
313: 	if n == 0 {
314: 		return
315: 	}
316: 
317: 	m := len(data)
318: 	if m > n {
319: 		data = data[m-n:]
320: 		m = n
321: 	}
322: 
323: 	// Number of free bytes before we must overwrite.
324: 	free := n - r.size
325: 	// How much of the write is new capacity vs overwrite.
326: 	used := min(m, free)
327: 	over := m - used
328: 
329: 	// (a) Fill any remaining capacity first.
330: 	if used > 0 {
331: 		dest := r.head
332: 		availToEnd := n - dest
333: 		if used <= availToEnd {
334: 			copy(r.buf[dest:], data[:used])
335: 			dest += used
336: 		} else {
337: 			copy(r.buf[dest:], data[:availToEnd])
338: 			copy(r.buf[0:], data[availToEnd:used])
339: 			dest = used - availToEnd
340: 		}
341: 		if dest >= n {
342: 			dest -= n
343: 		}
344: 		r.head = dest
345: 		r.size += used
346: 	}
347: 
348: 	if over <= 0 {
349: 		return
350: 	}
351: 
352: 	// (b) Overwrite the oldest region. The per-byte loop advances both head
353: 	// and tail together, so after overwriting m bytes the new tail equals the
354: 	// new head.
355: 	data = data[used:]
356: 	dest := r.head
357: 	availToEnd := n - dest
358: 	if over <= availToEnd {
359: 		copy(r.buf[dest:], data)
360: 		dest += over
361: 	} else {
362: 		copy(r.buf[dest:], data[:availToEnd])
363: 		copy(r.buf[0:], data[availToEnd:])
364: 		dest = over - availToEnd
365: 	}
366: 	if dest >= n {
367: 		dest -= n
368: 	}
369: 	r.head = dest
370: 	r.tail = dest
371: }
372: 
373: // Snapshot returns a copy of all buffered bytes in order (oldest first).
374: // Uses at most two copies instead of per-byte modulo.
375: func (r *ringBuffer) Snapshot() []byte {
376: 	r.mu.Lock()
377: 	defer r.mu.Unlock()
378: 	if r.size == 0 {
379: 		return nil
380: 	}
381: 	if r.size == len(r.buf) {
382: 		// Full buffer: [tail..end] + [0..head].
383: 		first := len(r.buf) - r.tail
384: 		out := make([]byte, len(r.buf))
385: 		copy(out, r.buf[r.tail:])
386: 		copy(out[first:], r.buf[:r.head])
387: 		return out
388: 	}
389: 	// Partial buffer is always contiguous from tail.
390: 	out := make([]byte, r.size)
391: 	copy(out, r.buf[r.tail:r.tail+r.size])
392: 	return out
393: }
394: 
395: // SnapshotTail returns the trailing maxBytes of the buffer in chronological
396: // order (oldest first among the tail). Uses at most two copies.
397: func (r *ringBuffer) SnapshotTail(maxBytes int) []byte {
398: 	r.mu.Lock()
399: 	defer r.mu.Unlock()
400: 
401: 	if r.size == 0 {
402: 		return nil
403: 	}
404: 	if maxBytes <= 0 {
405: 		return nil
406: 	}
407: 
408: 	if r.size <= maxBytes {
409: 		if r.size == len(r.buf) {
410: 			// Full buffer: [tail..end] + [0..head].
411: 			first := len(r.buf) - r.tail
412: 			out := make([]byte, len(r.buf))
413: 			copy(out, r.buf[r.tail:])
414: 			copy(out[first:], r.buf[:r.head])
415: 			return out
416: 		}
417: 		out := make([]byte, r.size)
418: 		copy(out, r.buf[r.tail:r.tail+r.size])
419: 		return out
420: 	}
421: 
422: 	// Return only the last maxBytes. Logical index i maps to
423: 	// physical buf[(tail+i)%n].
424: 	n := len(r.buf)
425: 	out := make([]byte, maxBytes)
426: 	start := r.size - maxBytes
427: 	startIdx := (r.tail + start) % n
428: 	first := n - startIdx
429: 	if first >= maxBytes {
430: 		copy(out, r.buf[startIdx:startIdx+maxBytes])
431: 	} else {
432: 		copy(out, r.buf[startIdx:])
433: 		copy(out[first:], r.buf[:maxBytes-first])
434: 	}
435: 	return out
436: }
437: 
438: // daemon manages the PTY, ring buffer, and client fan-out.
439: type daemon struct {
440: 	config     DaemonConfig
441: 	ptyFd      *os.File
442: 	cmd        *exec.Cmd
443: 	ring       *ringBuffer
444: 	ln         net.Listener
445: 	socketPath string
446: 	log        *logrus.Entry
447: 
448: 	lifecycleStore *LifecycleStore // durable lifecycle state
449: 
450: 	clientsMu sync.RWMutex
451: 	clients   map[net.Conn]chan []byte // per-client write channel
452: 
453: 	shellDone chan struct{}
454: 	closeOnce sync.Once
455: }
456: 
457: func (d *daemon) run() error {
458: 	defer func() {
459: 		if r := recover(); r != nil {
460: 			d.log.WithFields(logrus.Fields{
461: 				"panic": r,
462: 				"stack": string(debug.Stack()),
463: 			}).Error("daemon run accept loop panicked")
464: 		}
465: 	}()
466: 
467: 	// Goroutine: read PTY → ring buffer → broadcast.
468: 	go d.pumpPTY()
469: 
470: 	// Goroutine: wait for shell exit.
471: 	go d.waitShell()
472: 
473: 	// Accept loop.
474: 	for {
475: 		conn, err := d.ln.Accept()
476: 		if err != nil {
477: 			select {
478: 			case <-d.shellDone:
479: 				return nil
480: 			default:
481: 				return fmt.Errorf("accept: %w", err)
482: 			}
483: 		}
484: 		go d.handleClient(conn)
485: 	}
486: }
487: 
488: // pumpPTY reads from the PTY and fans out output to all clients.
489: func (d *daemon) pumpPTY() {
490: 	defer func() {
491: 		if r := recover(); r != nil {
492: 			d.log.WithFields(logrus.Fields{
493: 				"panic": r,
494: 				"stack": string(debug.Stack()),
495: 			}).Error("daemon pumpPTY panicked — shutting down")
496: 			d.shutdown()
497: 		}
498: 	}()
499: 
500: 	buf := make([]byte, 64*1024)
501: 	for {
502: 		n, err := d.ptyFd.Read(buf)
503: 		if n > 0 {
504: 			data := make([]byte, n)
505: 			copy(data, buf[:n])
506: 			d.ring.Write(data)
507: 			d.broadcast(data)
508: 		}
509: 		if err != nil {
510: 			if err != io.EOF {
511: 				d.log.WithError(err).Debug("PTY read error")
512: 			}
513: 			d.shutdown()
514: 			return
515: 		}
516: 	}
517: }
518: 
519: // waitShell waits for the shell process to exit, then shuts down.
520: func (d *daemon) waitShell() {
521: 	_ = d.cmd.Wait()
522: 	d.log.Debug("shell process exited")
523: 	d.shutdown()
524: }
525: 
526: // broadcast sends an Output frame to all connected clients.
527: // Uses per-client goroutines with buffered channels so a slow client
528: // never blocks the PTY pump.
529: func (d *daemon) broadcast(data []byte) {
530: 	frame := encodeFrame(FrameOutput, data)
531: 
532: 	d.clientsMu.RLock()
533: 	defer d.clientsMu.RUnlock()
534: 
535: 	for _, ch := range d.clients {
536: 		select {
537: 		case ch <- frame:
538: 		default:
539: 			// Client is too slow; drop this frame.
540: 		}
541: 	}
542: }
543: 
544: // handleClient serves a single client connection.
545: func (d *daemon) handleClient(conn net.Conn) {
546: 	defer func() {
547: 		if r := recover(); r != nil {
548: 			d.log.WithFields(logrus.Fields{
549: 				"panic": r,
550: 				"stack": string(debug.Stack()),
551: 			}).Error("daemon handleClient panicked — closing connection")
552: 			conn.Close()
553: 		}
554: 	}()
555: 
556: 	d.log.Debug("client connected")
557: 
558: 	writeCh := make(chan []byte, 256)
559: 	d.addClient(conn, writeCh)
560: 	defer func() {
561: 		d.removeClient(conn)
562: 		conn.Close()
563: 		d.log.Debug("client disconnected")
564: 	}()
565: 
566: 	// Start writer goroutine (reads from writeCh, writes to conn).
567: 	writerDone := make(chan struct{})
568: 	go func() {
569: 		defer close(writerDone)
570: 		for data := range writeCh {
571: 			if _, err := conn.Write(data); err != nil {
572: 				return
573: 			}
574: 		}
575: 	}()
576: 
577: 	// 1. Send replay on connect.
578: 	replay := d.ring.Snapshot()
579: 	if len(replay) > 0 {
580: 		frame := encodeFrame(FrameReplay, replay)
581: 		select {
582: 		case writeCh <- frame:
583: 		default:
584: 			// Client write buffer full on connect; disconnect.
585: 			return
586: 		}
587: 	}
588: 
589: 	// 2. Read frames from client.
590: 	header := make([]byte, 5)
591: 	for {
592: 		if _, err := io.ReadFull(conn, header); err != nil {
593: 			return
594: 		}
595: 		ftype := header[0]
596: 		plen := binary.BigEndian.Uint32(header[1:5])
597: 
598: 		if plen > 10*1024*1024 { // sanity: max 10 MiB per frame
599: 			return
600: 		}
601: 
602: 		var payload []byte
603: 		if plen > 0 {
604: 			payload = make([]byte, plen)
605: 			if _, err := io.ReadFull(conn, payload); err != nil {
606: 				return
607: 			}
608: 		}
609: 
610: 		switch ftype {
611: 		case FrameInput:
612: 			d.ptyFd.Write(payload)
613: 		case FrameResize:
614: 			if len(payload) == 4 {
615: 				cols := binary.BigEndian.Uint16(payload[0:2])
616: 				rows := binary.BigEndian.Uint16(payload[2:4])
617: 				_ = pty.Setsize(d.ptyFd, &pty.Winsize{Cols: cols, Rows: rows})
618: 			}
619: 		case FrameQueryBuffer:
620: 			// Send current ring buffer contents. A 4-byte big-endian uint32
621: 			// payload requests at most that many trailing bytes; an empty
622: 			// payload requests the full snapshot. New clients always receive
623: 			// a FrameReplay, including an empty one, so they never have to
624: 			// wait for a reply that will never come.
625: 			var replay []byte
626: 			if len(payload) == 4 {
627: 				maxBytes := int(binary.BigEndian.Uint32(payload))
628: 				replay = d.ring.SnapshotTail(maxBytes)
629: 			} else {
630: 				replay = d.ring.Snapshot()
631: 			}
632: 			frame := encodeFrame(FrameReplay, replay)
633: 			select {
634: 			case writeCh <- frame:
635: 			default:
636: 			}
637: 		case FrameQueryIdentity:
638: 			reply, err := ReadyInfo{
639: 				Owner:      d.config.Owner,
640: 				SessionID:  d.config.SessionID,
641: 				Generation: d.config.Generation,
642: 				DaemonPID:  os.Getpid(),
643: 				ShellPID:   d.cmd.Process.Pid,
644: 			}.Marshal()
645: 			if err != nil {
646: 				continue
647: 			}
648: 			frame := encodeFrame(FrameIdentity, reply)
649: 			select {
650: 			case writeCh <- frame:
651: 			default:
652: 			}
653: 		case FrameClose:
654: 			d.shutdown()
655: 			return
656: 		}
657: 	}
658: }
659: 
660: func (d *daemon) addClient(conn net.Conn, ch chan []byte) {
661: 	d.clientsMu.Lock()
662: 	d.clients[conn] = ch
663: 	d.clientsMu.Unlock()
664: }
665: 
666: func (d *daemon) removeClient(conn net.Conn) {
667: 	d.clientsMu.Lock()
668: 	if ch, ok := d.clients[conn]; ok {
669: 		delete(d.clients, conn)
670: 		close(ch)
671: 	}
672: 	d.clientsMu.Unlock()
673: }
674: 
675: // shutdown closes the PTY, kills the shell, and closes the listener.
676: // It also transitions the lifecycle record to cleanly_ended so the
677: // registry knows this was intentional, not a crash.
678: func (d *daemon) shutdown() {
679: 	d.closeOnce.Do(func() {
680: 		// Transition lifecycle before tearing down.
681: 		if d.lifecycleStore != nil {
682: 			if err := d.lifecycleStore.Transition(d.config.ID, LifecycleActive, LifecycleCleanlyEnded); err != nil {
683: 				d.log.WithError(err).Debug("lifecycle transition to cleanly_ended failed (may already be ended)")
684: 			}
685: 		}
686: 		d.ptyFd.Close()
687: 		// Kill the shell's entire process group so child processes
688: 		// (background jobs, pipelines, etc.) are not leaked as orphans.
689: 		// The shell is a session leader (pty.StartWithSize uses Setsid),
690: 		// so its PID equals its process group ID.  Negative PID targets
691: 		// the process group.  If the shell already exited this is a no-op.
692: 		killProcessGroup(d.cmd.Process.Pid)
693: 		d.ln.Close()
694: 		close(d.shellDone)
695: 		d.log.Debug("daemon shutdown complete")
696: 	})
697: }
698: 
699: // encodeFrame builds a wire-protocol frame.
700: func encodeFrame(ftype byte, payload []byte) []byte {
701: 	frame := make([]byte, 5+len(payload))
702: 	frame[0] = ftype
703: 	binary.BigEndian.PutUint32(frame[1:5], uint32(len(payload)))
704: 	copy(frame[5:], payload)
705: 	return frame
706: }
707: 
708: // isDaemonAlive returns true if a daemon is currently listening on socketPath.
709: // Used by RunDaemon to avoid stealing a live daemon's socket.
710: func isDaemonAlive(socketPath string) bool {
711: 	conn, err := net.DialTimeout("unix", socketPath, 500*time.Millisecond)
712: 	if err != nil {
713: 		return false
714: 	}
715: 	conn.Close()
716: 	return true
717: }
718: 
719: // isInteractiveShell returns true when name is a bare shell binary (no spaces,
720: // no arguments) that should be spawned directly as the session shell.
721: // Any other value — a command with arguments or a non-shell binary — should be
722: // wrapped inside a shell so the session outlives the command.
723: var knownShells = map[string]bool{
724: 	"bash": true, "zsh": true, "sh": true, "fish": true,
725: 	"dash": true, "tcsh": true, "csh": true, "ksh": true,
726: 	"mksh": true, "pdksh": true,
727: }
728: 
729: func isInteractiveShell(name string) bool {
730: 	if strings.ContainsAny(name, " \t") {
731: 		return false // has arguments — not a bare shell
732: 	}
733: 	return knownShells[filepath.Base(name)]
734: }
735: 
736: // killProcessGroup sends SIGKILL to the process group identified by pgid.
737: // If the process group no longer exists (e.g. shell already exited),
738: // this is silently ignored.
739: func killProcessGroup(pgid int) {
740: 	if pgid <= 0 {
741: 		return
742: 	}
743: 	// Negative PID sends the signal to the entire process group.
744: 	_ = syscall.Kill(-pgid, syscall.SIGKILL)
745: }   1: //
