  16: 
  17: let terminalCreateCount = 0
  18: let terminalDisposeCount = 0
  19: let addonCreateCount = 0
  20: let addonDisposeCount = 0
  21: let socketOpenCount = 0
  22: let socketCloseCount = 0
  23: let socketSendCount = 0
  24: let transferCallCount = 0
  25: 
  26: function resetCounters() {
  27:   terminalCreateCount = 0
  28:   terminalDisposeCount = 0
  29:   addonCreateCount = 0
