 211:   predict(_char: string) {}
 212:   clear() {}
 213:   dispose() { addonDisposeCount++ }
 214: }
 215: 
 216: // ── Fake WebSocket ───────────────────────────────────────────────────
 217: 
 218: class FakeWebSocket {
 219:   static CONNECTING = 0
 220:   static OPEN = 1
 221:   static CLOSED = 3
 222: 
 223:   readyState = FakeWebSocket.CONNECTING
 224:   binaryType = 'arraybuffer'
 225:   url: string
 226:   onopen: ((evt?: any) => void) | null = null
 227:   onclose: ((evt?: any) => void) | null = null
 228:   onerror: ((evt?: any) => void) | null = null
 229:   onmessage: ((evt?: any) => void) | null = null
 230: 
 231:   constructor(url: string) {
 232:     socketOpenCount++
 233:     this.url = url
 234:   }
 235: 
 236:   sent: any[] = []
 237:   send(data: any) { this.sent.push(data); socketSendCount++ }
 238:   close() {
 239:     socketCloseCount++
 240:     this.readyState = FakeWebSocket.CLOSED
 241:     this.onclose?.({ code: 1000, reason: '', wasClean: true })
 242:   }
 243: 
 244:   _open() {
 245:     this.readyState = FakeWebSocket.OPEN
 246:     this.onopen?.({})
 247:   }
 248:   _message(data: any) {
 249:     this.onmessage?.({ data })
 250:   }
 251: }
 252: 
 253: // ── Transfer ─────────────────────────────────────────────────────────
 254: 
 255: function fakeTransferNode(node: HTMLElement, dest: HTMLElement): { crossedDocument: boolean } {
 256:   transferCallCount++
 257:   // In tests we cannot call real jsdom appendChild with fake elements.
 258:   // Track the call for assertions; pool code only needs crossedDocument.
 259:   return { crossedDocument: false }
 260: }
 261: 
 262: // ── Factory ──────────────────────────────────────────────────────────
 263: 
 264: function createFakeFactory(): PoolFactory {
 265:   return {
 266:     createTerminal: (options) => new FakeTerminal(options) as unknown as any,
 267:     createFitAddon: () => new FakeFitAddon() as unknown as any,
 268:     createWebLinksAddon: () => new FakeWebLinksAddon() as unknown as any,
 269:     createClipboardAddon: () => new FakeClipboardAddon() as unknown as any,
 270:     createWebglAddon: () => new FakeWebglAddon() as unknown as any,
 271:     createImageAddon: () => new FakeImageAddon() as unknown as any,
 272:     createUnicodeGraphemesAddon: () => new FakeUnicodeGraphemesAddon() as unknown as any,
 273:     createPredictiveEcho: () => new FakePredictiveEcho() as unknown as any,
 274:     createWebSocket: (url) => new FakeWebSocket(url) as unknown as WebSocket,
 275:   }
 276: }
 277: 
 278: // ── Test helpers ──────────────────────────────────────────────────────
 279: 
 280: function defPrefs(overrides?: Partial<TerminalPrefs>): TerminalPrefs {
 281:   return {
 282:     theme: 'dark', fontFamily: 'Space Mono', fontSize: 13,
 283:     scrollback: 50000, renderer: 'dom',
 284:     unicodeGraphemes: false, predictiveEcho: false,
 285:     ...overrides,
 286:   }
 287: }
 288: 
 289: function defId(name = 'test-session', host?: string, backend?: string): PoolIdentity {
 290:   return { sessionName: name, hostId: host, backend }
 291: }
 292: 
 293: function defStableId(name = 'test-session', sessionId = 'sid-1', generation?: string, host?: string): PoolIdentity {
 294:   return {
 295:     sessionName: name, // display label, NOT part of canonical identity
 296:     hostId: host,
 297:     backend: 'daemon',
 298:     sessionId,
 299:     ownerId: host,
 300:     generation,
 301:   }
 302: }
 303: 
 304: function noopCbs(): CheckoutCallbacks {
 305:   return {
 306:     onConnectionChange: () => {},
 307:     onCtrlModifierChange: () => {},
 308:     onAltModifierChange: () => {},
 309:     onSelectionMenu: () => {},
 310:   }
 311: }
 312: 
 313: // Reach into private pool maps only for characterization assertions.
 314: function getEntry(pool: any, key: string): any | undefined {
 315:   return pool.entries.get(key)
 316: }
 317: function hasEntry(pool: any, key: string): boolean {
 318:   return pool.entries.has(key)
 319: }
 320: 
 321: // ── Suite ────────────────────────────────────────────────────────────
 322: 
 323: describe('TerminalPool', () => {
 324:   let pool: TerminalPool
 325: 
 326:   beforeEach(() => {
 327:     resetCounters()
 328:     pool = new TerminalPool(createFakeFactory())
 329:     __injectTransferNode(fakeTransferNode)
 330:   })
 331: 
 332:   afterEach(() => {
 333:     pool.reset()
 334:   })
 335: 
 336:   // ── Key normalization ──────────────────────────────────────────────
 337: 
 338:   it('normalizes keys: local session', () => {
 339:     expect(keyFor('mysession', undefined)).toBe('mysession')
 340:     expect(keyFor('mysession', '')).toBe('mysession')
 341:     expect(TerminalPool.keyFor('mysession')).toBe('mysession')
 342:   })
 343: 
 344:   it('normalizes keys: remote host', () => {
 345:     expect(keyFor('mysession', 'host123')).toBe('host123/mysession')
 346:   })
 347: 
 348:   // ── Cold checkout ──────────────────────────────────────────────────
 349: 
 350:   it('first checkout cold-creates one entry', () => {
 351:     const container = fakeEl()
 352:     const lease = pool.checkout(defId('s1'), defPrefs(), container, noopCbs())
 353:     expect(lease.key).toBe('s1')
 354:     expect(lease.generation).toBe(1)
 355:     expect(pool.size).toBe(1)
 356:     expect(terminalCreateCount).toBe(1)
 357:     expect(addonCreateCount).toBeGreaterThanOrEqual(4)
 358:     expect(socketOpenCount).toBe(1)
 359:   })
 360: 
 361:   // Registration-timing guard. Terminal.tsx registers the file-link provider in
 362:   // a useLayoutEffect immediately after connect(), reading termRef.current —
 363:   // which useTerminal assigns from getTerminalForPaste(lease) during checkout.
 364:   // If checkout ever became async, that ref would be null on the cold path and
 365:   // the provider would silently never register. Pin the synchronous contract.
 366:   it('cold checkout exposes the terminal synchronously (link-provider timing)', () => {
 367:     const container = fakeEl()
 368:     const lease = pool.checkout(defId('s1'), defPrefs(), container, noopCbs())
 369:     const term = pool.getTerminalForPaste(lease)
 370:     // Non-null the moment checkout returns: this is the property the
 371:     // link-provider registration depends on. (The fake factory does not model
 372:     // registerLinkProvider, so the method itself is not asserted here.)
 373:     expect(term).not.toBeNull()
 374:     expect(term).toBeDefined()
 375:   })
 376: 
 377:   it('warm re-checkout also exposes the terminal synchronously', () => {
 378:     const c1 = fakeEl()
 379:     const l1 = pool.checkout(defId('s1'), defPrefs(), c1, noopCbs())
 380:     const first = pool.getTerminalForPaste(l1)
 381:     pool.checkin(l1)
 382: 
 383:     const c2 = fakeEl()
 384:     const l2 = pool.checkout(defId('s1'), defPrefs(), c2, noopCbs())
 385:     const second = pool.getTerminalForPaste(l2)
 386:     expect(second).not.toBeNull()
 387:     // Same underlying terminal: a re-registered provider must target this one.
 388:     expect(second).toBe(first)
 389:   })
 390: 
 391:   it('cold checkout loads WebGL when prefs specify webgl', () => {
 392:     const container = fakeEl()
 393:     pool.checkout(defId('s1'), defPrefs({ renderer: 'webgl' }), container, noopCbs())
 394:     expect(terminalCreateCount).toBe(1)
 395:     expect(addonCreateCount).toBeGreaterThanOrEqual(5)
 396:   })
 397: 
 398:   // ── Checkin keeps resources alive ──────────────────────────────────
 399: 
 400:   it('checkin does not dispose terminal/addons/socket', () => {
 401:     const container = fakeEl()
 402:     const lease = pool.checkout(defId('s1'), defPrefs(), container, noopCbs())
 403:     const tdB = terminalDisposeCount, adB = addonDisposeCount, scB = socketCloseCount
 404:     pool.checkin(lease)
 405:     expect(terminalDisposeCount).toBe(tdB)
 406:     expect(addonDisposeCount).toBe(adB)
 407:     expect(socketCloseCount).toBe(scB)
 408:     expect(pool.size).toBe(1)
 409:   })
 410: 
 411:   // ── Warm checkout ──────────────────────────────────────────────────
 412: 
 413:   it('repeat checkout reuses terminal (no new creates)', () => {
 414:     const container = fakeEl()
 415:     const l1 = pool.checkout(defId('s1'), defPrefs(), container, noopCbs())
 416:     pool.checkin(l1)
 417:     const tcB = terminalCreateCount, scB = socketOpenCount
 418:     const l2 = pool.checkout(defId('s1'), defPrefs(), container, noopCbs())
 419:     expect(l2.key).toBe('s1')
 420:     expect(l2.generation).toBe(3)
 421:     expect(terminalCreateCount).toBe(tcB)
 422:     expect(socketOpenCount).toBe(scB)
 423:   })
 424: 
 425:   // ── Different host ─────────────────────────────────────────────────
 426: 
 427:   it('different host creates distinct entry', () => {
 428:     const container = fakeEl()
 429:     pool.checkout(defId('s1', 'hostA'), defPrefs(), container, noopCbs())
 430:     pool.checkout(defId('s1', 'hostB'), defPrefs(), container, noopCbs())
 431:     expect(pool.size).toBe(2)
 432:     expect(terminalCreateCount).toBe(2)
 433:   })
 434: 
 435:   // ── Backend mismatch ───────────────────────────────────────────────
 436: 
 437:   it('backend mismatch disposes old and recreates', () => {
 438:     const container = fakeEl()
 439:     const l = pool.checkout(defId('s1', undefined, 'daemon'), defPrefs(), container, noopCbs())
 440:     pool.checkin(l)
 441:     const tdB = terminalDisposeCount
 442:     pool.checkout(defId('s1', undefined, 'tmux'), defPrefs(), container, noopCbs())
 443:     expect(terminalDisposeCount).toBeGreaterThan(tdB)
 444:     expect(terminalCreateCount).toBe(2)
