 447:   // ── Exclusive lease ────────────────────────────────────────────────
 448: 
 449:   it('latest lease wins: stale checkin no-op', () => {
 450:     const container = fakeEl()
 451:     const l1 = pool.checkout(defId('s1'), defPrefs(), container, noopCbs())
 452:     const l2 = pool.checkout(defId('s1'), defPrefs(), container, noopCbs())
 453:     expect(l2.generation).toBeGreaterThan(l1.generation)
 454:     pool.checkin(l1) // stale
 455:     expect(pool.size).toBe(1)
 456:     pool.checkin(l2) // current
 457:     expect(pool.size).toBe(1)
