 483:     const l = pool.checkout(defId('s1'), defPrefs(), container, noopCbs())
 484:     // Open socket so sends can go through while lease is active
 485:     const entry = getEntry(pool, l.key)
 486:     ;(entry?.connection?.socket as unknown as FakeWebSocket)?._open()
 487:     // Send while active should work
 488:     const scBeforeCheckin = socketSendCount
 489:     pool.sendText(l, 'hello')
 490:     expect(socketSendCount).toBeGreaterThan(scBeforeCheckin)
 491: 
 492:     pool.checkin(l)
 493:     // After checkin, send should be rejected
 494:     const scAfterCheckin = socketSendCount
 495:     pool.sendText(l, 'hello')
 496:     expect(socketSendCount).toBe(scAfterCheckin)
 497:   })
