 499:   // ── Modifiers ──────────────────────────────────────────────────────
 500: 
 501:   it('stale sendImage rejected after checkin', async () => {
 502:     const container = fakeEl()
 503:     const l = pool.checkout(defId('s1'), defPrefs(), container, noopCbs())
 504:     const entry = getEntry(pool, l.key)
 505:     const ws = entry?.connection?.socket as unknown as FakeWebSocket
 506:     ws?._open()
 507: 
 508:     // Create a small fake file
 509:     const file = new File(['fake'], 'test.png', { type: 'image/png' })
 510: 
 511:     // Now checkin to invalidate lease
 512:     pool.checkin(l)
 513: 
 514:     const scB = socketSendCount
