 851:   function openSession(name = 's1', backend?: string) {
 852:     const container = fakeEl()
 853:     const id = defId(name, undefined, backend)
 854:     const l = pool.checkout(id, defPrefs(), container, noopCbs())
 855:     const entry = getEntry(pool, l.key)!
 856:     const ws = entry.connection.socket as unknown as FakeWebSocket
 857:     ws._open()
 858:     const term = entry.terminal as unknown as FakeTerminal
 859:     term.writes = []
 860:     return { l, entry, ws, term }
 861:   }
 862: 
 863:   function currentEntry(name: string) {
 864:     const entry = getEntry(pool, name)!
 865:     return {
 866:       entry,
 867:       ws: entry.connection.socket as unknown as FakeWebSocket,
 868:       term: entry.terminal as unknown as FakeTerminal,
 869:     }
 870:   }
