 28: // SessionInfo holds metadata about a running session daemon.
 29: type SessionInfo struct {
 30: 	ID       string
 31: 	Pid      int
 32: 	ShellPid int
 33: 	Shell    string
 34: 	Cwd      string
 35: 	Created  string // RFC3339
 36: 	Cols     uint16
 37: 	Rows     uint16
 38: 	Socket   string // full path to .sock file
 39: }
 40: 
 41: // validSessionID returns true if id is safe for use in file paths.
 42: // Rejects empty, contains path separators, dots-only, or control chars.
 43: func validSessionID(id string) bool {
 44: 	if id == "" || id == "." || id == ".." {
 45: 		return false
 46: 	}
 47: 	for _, c := range id {
 48: 		if c == '/' || c == '\\' || c == '\x00' {
 49: 			return false
 50: 		}
 51: 	}
 52: 	return true
 53: }
