 55: // Registry manages session daemon lifecycle: create, list, kill, capture.
 56: type Registry struct {
 57: 	dir       string // socket directory
 58: 	stateDir  string // optional override for DefaultStateDir() (tests)
 59: 	failMu    sync.Mutex
 60: 	failCount map[string]int // consecutive liveness failures per session
 61: 
 62: 	recoveryMu     sync.Mutex      // serializes recover/dismiss operations
 63: 	lifecycleStore *LifecycleStore // durable lifecycle state (may be nil)
 64: 
 65: 	// stopUnitFn is a test hook that, when non-nil, is called instead of
 66: 	// spawning a real systemctl process. The unit argument is the systemd
 67: 	// scope unit name to stop.
 68: 	stopUnitFn func(unit string)
 69: }
