 71: // NewRegistry creates a session registry using the given socket directory.
 72: // The directory is created with 0700 if it does not exist.
 73: func NewRegistry(dir string) *Registry {
 74: 	os.MkdirAll(dir, 0700)
 75: 	return &Registry{dir: dir, failCount: make(map[string]int)}
 76: }
