120: // Create spawns a session daemon as a fully detached subprocess.
121: // It waits up to 2s for the socket file to appear, then returns.
122: func (r *Registry) Create(name, shell, cwd string, cols, rows uint16) error {
123: 	log := logrus.WithFields(logrus.Fields{
124: 		"component": "registry",
125: 		"name":      name,
126: 		"shell":     shell,
127: 		"cwd":       cwd,
128: 	})
129: 
130: 	// Guard against duplicate names — the socket file would be overwritten,
131: 	// causing two terminals to share a single daemon.
132: 	if _, err := os.Stat(r.SocketPath(name)); err == nil {
133: 		return fmt.Errorf("session %q already exists", name)
134: 	}
135: 
136: 	exe, err := os.Executable()
137: 	if err != nil {
138: 		return fmt.Errorf("get executable: %w", err)
139: 	}
140: 
141: 	// Derive defaults in-process so the daemon gets explicit values.
142: 	if shell == "" {
143: 		shell = os.Getenv("SHELL")
144: 		if shell == "" {
145: 			shell = "/bin/bash"
146: 		}
147: 	}
148: 	if cols == 0 {
149: 		cols = 120
150: 	}
151: 	if rows == 0 {
152: 		rows = 40
153: 	}
154: 
155: 	args := []string{
156: 		"session-daemon",
157: 		"--id", name,
158: 		"--shell", shell,
159: 		"--cols", fmt.Sprintf("%d", cols),
160: 		"--rows", fmt.Sprintf("%d", rows),
161: 		"--cwd", cwd,
162: 		"--socket-dir", r.dir,
163: 	}
164: 
165: 	// Pass state dir for lifecycle persistence.
166: 	stateDir := r.stateDirOrDefault()
167: 	args = append(args, "--state-dir", stateDir)
168: 
169: 	// Try to wrap in a systemd user scope for cgroup isolation.
170: 	// Falls back to direct spawn if systemd-run is unavailable or
171: 	// the user session bus is not reachable.
172: 	var cmd *exec.Cmd
173: 	useSystemd := false
174: 	var systemdUnit string
175: 	if systemdRun, err := exec.LookPath("systemd-run"); err == nil {
176: 		// Verify user session bus is available (systemd-run --user needs it).
177: 		if os.Getenv("DBUS_SESSION_BUS_ADDRESS") != "" {
178: 			systemdUnit = fmt.Sprintf("termyard-session-%s-%d.scope", name, time.Now().UnixMilli())
179: 			scopeArgs := []string{
180: 				"--user", "--scope",
181: 				"--unit", systemdUnit,
182: 				"--",
183: 			}
184: 			fullArgs := append(scopeArgs, exe)
185: 			fullArgs = append(fullArgs, args...)
186: 			cmd = exec.Command(systemdRun, fullArgs...)
187: 			useSystemd = true
188: 		}
189: 	}
190: 	if cmd == nil {
191: 		cmd = exec.Command(exe, args...)
192: 	}
193: 
194: 	// Append --systemd-unit so the daemon stores it in metadata/lifecycle
195: 	// for later cleanup.
196: 	if systemdUnit != "" {
197: 		cmd.Args = append(cmd.Args, "--systemd-unit", systemdUnit)
198: 	}
199: 
200: 	cmd.SysProcAttr = &syscall.SysProcAttr{Setsid: true}
201: 	// Open /dev/null explicitly so the daemon doesn't inherit parent's
202: 	// fds (which may be pipes that close when the server restarts).
203: 	devNull, err := os.OpenFile(os.DevNull, os.O_RDWR, 0)
204: 	if err != nil {
205: 		return fmt.Errorf("open /dev/null: %w", err)
206: 	}
207: 	defer devNull.Close()
208: 	cmd.Stdin = devNull
209: 	cmd.Stdout = devNull
210: 	cmd.Stderr = devNull
211: 
212: 	if err := cmd.Start(); err != nil {
213: 		if useSystemd {
214: 			// systemd-run failed; retry with direct spawn.
215: 			log.WithError(err).Warn("systemd-run failed, falling back to direct spawn")
216: 			cmd = exec.Command(exe, args...)
217: 			cmd.SysProcAttr = &syscall.SysProcAttr{Setsid: true}
218: 			cmd.Stdin = devNull
219: 			cmd.Stdout = devNull
220: 			cmd.Stderr = devNull
221: 			if err := cmd.Start(); err != nil {
222: 				return fmt.Errorf("start daemon process: %w", err)
223: 			}
224: 		} else {
225: 			return fmt.Errorf("start daemon process: %w", err)
226: 		}
227: 	}
228: 
229: 	// Release the process handle so the daemon is fully independent.
230: 	// Don't wait for the socket to appear here — the terminal connects
231: 	// via NewDaemonSession, which retries the dial until the daemon is
232: 	// ready. Returning immediately lets the UI mount in parallel with
233: 	// the daemon's cold-start (and the systemd-run DBus round-trip).
234: 	if err := cmd.Process.Release(); err != nil {
235: 		log.WithError(err).Warn("failed to release daemon process handle")
236: 	}
237: 
238: 	log.WithField("socket", r.SocketPath(name)).Info("session daemon created")
239: 	return nil
240: }
241: 
242: // List scans the socket directory for *.sock files, reads their sidecar JSON,
243: // and checks liveness by attempting a connection.
244: // Stale socket+json files (where the daemon process is confirmed dead) are removed.
245: func (r *Registry) List() []SessionInfo {
246: 	entries, err := filepath.Glob(filepath.Join(r.dir, "*.sock"))
247: 	if err != nil {
248: 		return nil
249: 	}
250: 
251: 	type removal struct {
252: 		name   string
253: 		reason string
254: 	}
255: 
256: 	var (
257: 		out   []SessionInfo
258: 		stale []removal
259: 		total = len(entries)
260: 	)
261: 	// Track which entries we saw for later failure-count cleanup.
262: 	seen := make(map[string]bool, total)
263: 
264: 	for _, sockPath := range entries {
265: 		name := filepath.Base(sockPath[:len(sockPath)-len(".sock")])
266: 		seen[name] = true
267: 
268: 		conn, err := net.DialTimeout("unix", sockPath, 2*time.Second)
269: 		if err != nil {
270: 			// If the daemon process is provably gone, remove now instead of
271: 			// waiting out the 5-tick (~10s) grace window. This matters when a
272: 			// crash/SIGKILL leaves the .sock file behind: without this, the
273: 			// session lingers unreachable and the frontend shows its
274: 			// "Disconnected — Reconnecting" overlay for ~10s. A live-but-
275: 			// unreachable daemon still falls through to the grace below.
276: 			if pid := r.readDaemonPID(name); pid > 0 && !processAlive(pid) {
277: 				stale = append(stale, removal{name: name, reason: "daemon process dead"})
278: 				continue
279: 			}
280: 
281: 			r.failMu.Lock()
282: 			r.failCount[name]++
283: 			fails := r.failCount[name]
284: 			r.failMu.Unlock()
285: 
286: 			if fails < 5 {
287: 				logrus.WithFields(logrus.Fields{
288: 					"component": "registry",
289: 					"name":      name,
290: 					"fails":     fails,
291: 				}).Debug("daemon liveness check failed, will retry")
292: 				// Still include the session so it is not removed from
293: 				// state during the grace window. Metadata sidecar is
294: 				// readable regardless of socket health.
295: 			} else {
296: 				// Threshold reached. Before removing, verify the daemon
297: 				// process is actually dead (not just slow/overloaded).
298: 				pid := r.readDaemonPID(name)
299: 				if pid > 0 && processAlive(pid) {
300: 					logrus.WithFields(logrus.Fields{
301: 						"component": "registry",
302: 						"name":      name,
303: 						"pid":       pid,
304: 						"fails":     fails,
305: 					}).Warn("daemon process is alive but socket unreachable — keeping session")
306: 					r.failMu.Lock()
307: 					delete(r.failCount, name)
308: 					r.failMu.Unlock()
309: 				} else {
310: 					// Process is dead — safe to clean up.
311: 					stale = append(stale, removal{name: name, reason: "daemon process dead"})
312: 					continue
313: 				}
314: 			}
315: 		} else {
316: 			conn.Close()
317: 
318: 			// Reset failure counter on successful connect.
319: 			r.failMu.Lock()
320: 			delete(r.failCount, name)
321: 			r.failMu.Unlock()
322: 		}
323: 
324: 		info := SessionInfo{
325: 			ID:     name,
326: 			Socket: sockPath,
327: 		}
328: 
329: 		// Read metadata sidecar.
330: 		metaPath := r.metadataPath(name)
331: 		if data, err := os.ReadFile(metaPath); err == nil {
332: 			var meta sessionMeta
333: 			if json.Unmarshal(data, &meta) == nil {
334: 				info.Pid = meta.Pid
335: 				info.ShellPid = meta.ShellPid
336: 				info.Shell = meta.Shell
337: 				info.Cwd = meta.Cwd
338: 				info.Created = meta.Created
339: 				info.Cols = meta.Cols
340: 				info.Rows = meta.Rows
341: 			}
342: 		}
343: 
344: 		out = append(out, info)
345: 	}
346: 
347: 	// Mass-removal protection: if ALL entries would be removed (stale > 0
348: 	// and live == 0), skip staleness cleanup — this is almost certainly a
349: 	// transient system event (load spike, tmpfs issue, etc.) and we should
350: 	// not nuke every session in one go.
351: 	if len(out) == 0 && len(stale) > 0 {
352: 		logrus.WithFields(logrus.Fields{
353: 			"component": "registry",
354: 			"stale":     len(stale),
355: 			"total":     total,
356: 		}).Warn("all sessions appear stale — skipping removal (probable transient event)")
357: 		// Keep all sessions — do not clean up.
358: 		for _, s := range stale {
359: 			r.failMu.Lock()
360: 			delete(r.failCount, s.name)
361: 			r.failMu.Unlock()
362: 		}
363: 	} else {
364: 		for _, s := range stale {
365: 			r.removeStale(s.name, s.reason)
366: 			r.failMu.Lock()
367: 			delete(r.failCount, s.name)
368: 			r.failMu.Unlock()
369: 		}
370: 	}
371: 
372: 	// Clean up failure counters for sessions whose sockets disappeared
373: 	// (e.g. killed externally).
374: 	r.failMu.Lock()
375: 	for name := range r.failCount {
376: 		if !seen[name] {
377: 			delete(r.failCount, name)
378: 		}
379: 	}
380: 	r.failMu.Unlock()
381: 
382: 	return out
383: }
384: 
385: // IsSessionDead reports whether a session is confirmed to have terminated
386: // (cleanly exited, intentionally killed, or dismissed) according to the
387: // durable lifecycle store. The state manager uses this to distinguish a
388: // genuinely empty discovery (all sessions dead) from a transient discovery
389: // failure, so the last session can be removed instead of lingering in the
390: // sidebar as "disconnected — reconnecting" forever.
391: //
392: // Returns false when no lifecycle store is configured or no record exists —
393: // conservative, so the mass-removal guards keep protecting against transients
394: // in the pre-lifecycle / no-store cases.
395: func (r *Registry) IsSessionDead(name string) bool {
396: 	if r.lifecycleStore == nil {
397: 		return false
398: 	}
399: 	rec, err := r.lifecycleStore.Get(name)
400: 	if err != nil {
401: 		return false
402: 	}
403: 	switch rec.State {
404: 	case LifecycleCleanlyEnded, LifecycleTerminationRequested, LifecycleDismissed:
405: 		return true
406: 	}
407: 	return false
408: }
409: 
410: // readDaemonPID reads the metadata JSON sidecar and returns the daemon PID,
411: // or 0 if the file cannot be read or parsed.
412: func (r *Registry) readDaemonPID(name string) int {
413: 	metaPath := r.metadataPath(name)
414: 	data, err := os.ReadFile(metaPath)
415: 	if err != nil {
416: 		return 0
417: 	}
418: 	var meta sessionMeta
419: 	if json.Unmarshal(data, &meta) != nil {
420: 		return 0
421: 	}
422: 	return meta.Pid
423: }
424: 
425: // processAlive returns true if the process with the given PID exists.
426: func processAlive(pid int) bool {
427: 	err := syscall.Kill(pid, 0)
428: 	return err == nil
429: }
430: 
431: // removeStale removes a socket file and its metadata sidecar.
432: // If the lifecycle store is configured, this function checks whether the
433: // daemon exited intentionally (cleanly_ended, termination_requested, dismissed)
434: // or crashed (active state with dead process).  Crashed sessions are NOT
435: // deleted — they are left on disk for recovery.
436: // In all cleanup paths (including crash preservation), the associated
437: // systemd scope is stopped as a best-effort cleanup to prevent orphaned
438: // cgroups.
439: func (r *Registry) removeStale(name, reason string) {
440: 	sockPath := r.SocketPath(name)
441: 	metaPath := r.metadataPath(name)
442: 
443: 	// Check lifecycle store for crash detection.
444: 	if r.lifecycleStore != nil {
445: 		rec, err := r.lifecycleStore.Get(name)
446: 		if err == nil {
447: 			switch rec.State {
448: 			case LifecycleActive:
449: 				// The daemon process died but the lifecycle record
450: 				// was never transitioned out of active — this is a crash.
451: 				// Preserve the socket and metadata for recovery.
452: 				logrus.WithFields(logrus.Fields{
453: 					"component": "registry",
454: 					"name":      name,
455: 					"pid":       rec.DaemonPID,
456: 				}).Warn("daemon crashed — preserving session for recovery")
457: 				if transErr := r.lifecycleStore.Transition(name, LifecycleActive, LifecycleCrashed); transErr != nil {
458: 					logrus.WithError(transErr).WithField("name", name).Warn("failed to transition to crashed")
459: 				}
460: 				// Stop the systemd scope even though we preserve files.
461: 				// Use the exact unit from the record we already read.
462: 				r.stopSystemdUnit(rec.SystemdUnit)
463: 				// Do NOT delete socket/metadata — they are needed for recovery.
464: 				return
465: 
466: 			case LifecycleCleanlyEnded, LifecycleTerminationRequested, LifecycleDismissed:
467: 				// Intentionally terminated or dismissed — clean up normally.
468: 
469: 			case LifecycleCrashed:
470: 				// Already marked as crashed, keep preserved.
471: 				r.stopSystemdUnit(rec.SystemdUnit)
472: 				return
473: 
474: 			default:
475: 				// Unknown state — clean up cautiously.
476: 			}
477: 		}
478: 		// If no lifecycle record exists (pre-lifecycle daemon),
479: 		// fall through to normal cleanup.
480: 	}
481: 
482: 	// Stop systemd scope before removing files.
483: 	r.stopSystemdScope(name)
484: 
485: 	os.Remove(sockPath)
486: 	os.Remove(metaPath)
487: 	logrus.WithFields(logrus.Fields{
488: 		"component": "registry",
489: 		"name":      name,
490: 		"reason":    reason,
491: 	}).Info("removed stale session files")
492: }
493: 
494: // Kill sends a FrameClose to the daemon via its socket.
495: // It marks the session as intentionally terminated in the lifecycle store
496: // so the registry can distinguish explicit kills from crashes.
497: // If a systemd scope unit was recorded, it is stopped as a best-effort
498: // cleanup (in case the daemon process doesn't exit cleanly).
499: func (r *Registry) Kill(name string) error {
500: 	// Record intentional kill before sending FrameClose.
501: 	// If the daemon process dies without transitioning to cleanly_ended,
502: 	// the termination_requested state tells the registry this wasn't a crash.
503: 	if r.lifecycleStore != nil {
504: 		// Best-effort — ignore errors (the record may not exist yet or
505: 		// the state may already have changed).
506: 		_ = r.lifecycleStore.Transition(name, LifecycleActive, LifecycleTerminationRequested)
507: 	}
508: 
509: 	// Read the systemd unit once for cleanup, regardless of the path taken.
510: 	unit := r.readSystemdUnit(name)
511: 
512: 	socketPath := r.SocketPath(name)
513: 	conn, err := net.DialTimeout("unix", socketPath, 1*time.Second)
514: 	if err != nil {
515: 		// Socket unreachable — try to stop the systemd scope anyway.
516: 		r.stopSystemdUnit(unit)
517: 		return fmt.Errorf("dial daemon socket %s: %w", socketPath, err)
518: 	}
519: 	defer conn.Close()
520: 
521: 	frame := encodeFrame(FrameClose, nil)
522: 	if _, err := conn.Write(frame); err != nil {
523: 		// FrameClose failed — try to force-stop the systemd scope.
524: 		r.stopSystemdUnit(unit)
525: 		return fmt.Errorf("send close frame: %w", err)
526: 	}
527: 
528: 	// Best-effort: stop the systemd scope so it doesn't linger.
529: 	// The daemon should exit on its own after receiving FrameClose, but
530: 	// systemd scope cleanup is an extra safety net.
531: 	r.stopSystemdUnit(unit)
532: 	return nil
533: }
534: 
535: // Capture limits.
536: const (
537: 	captureMaxPayload  = 10 * 1024 * 1024 // sanity: max 10 MiB
538: 	captureDialTimeout = 1 * time.Second
539: 	captureReadTimeout = 10 * time.Second
540: 	captureTailTimeout = 2 * time.Second
541: )
542: 
543: // ErrCaptureTimeout is returned when a capture or tail capture exceeds its
544: // read deadline.
545: var ErrCaptureTimeout = errors.New("capture timeout")
546: 
547: // Capture connects to the daemon, sends FrameQueryBuffer, reads the
548: // FrameReplay response, and returns the text content.
549: // It preserves legacy byte-compatible output semantics.
550: func (r *Registry) Capture(name string) (string, error) {
551: 	socketPath := r.SocketPath(name)
552: 	conn, err := net.DialTimeout("unix", socketPath, captureDialTimeout)
553: 	if err != nil {
554: 		return "", fmt.Errorf("dial daemon socket %s: %w", socketPath, err)
555: 	}
556: 	defer conn.Close()
557: 	if err := conn.SetReadDeadline(time.Now().Add(captureReadTimeout)); err != nil {
558: 		return "", fmt.Errorf("set read deadline: %w", err)
559: 	}
560: 
561: 	payload, err := r.capturePayload(conn)
562: 	if err != nil {
563: 		if errors.Is(err, os.ErrDeadlineExceeded) {
564: 			return r.legacyCleanCapture(payload), ErrCaptureTimeout
565: 		}
566: 		return "", fmt.Errorf("capture %s: %w", name, err)
567: 	}
568: 	return r.legacyCleanCapture(payload), nil
569: }
570: 
571: // CaptureTail connects to the daemon and returns at most maxBytes of the
572: // trailing buffer content. It shares framing and cleaning logic with Capture
573: // but avoids reading (and duplicating) the full payload for bounded previews.
574: // The returned text is cleaned of ANSI sequences and control characters; the
575: // first line is stripped when it would start mid-line, and partial leading
576: // UTF-8 continuation bytes are removed.
577: func (r *Registry) CaptureTail(name string, maxBytes int) (string, error) {
578: 	if maxBytes <= 0 {
579: 		return "", nil
580: 	}
581: 
582: 	socketPath := r.SocketPath(name)
583: 	conn, err := net.DialTimeout("unix", socketPath, captureDialTimeout)
584: 	if err != nil {
585: 		return "", fmt.Errorf("dial daemon socket %s: %w", socketPath, err)
586: 	}
587: 	defer conn.Close()
588: 	if err := conn.SetReadDeadline(time.Now().Add(captureTailTimeout)); err != nil {
589: 		return "", fmt.Errorf("set read deadline: %w", err)
590: 	}
591: 
592: 	// Send bounded query so the daemon replies with at most maxBytes.
593: 	payload := make([]byte, 4)
594: 	binary.BigEndian.PutUint32(payload, uint32(maxBytes))
595: 	frame := encodeFrame(FrameQueryBuffer, payload)
596: 	if _, err := conn.Write(frame); err != nil {
597: 		return "", fmt.Errorf("send query buffer frame: %w", err)
598: 	}
599: 
600: 	// Read response header to validate length and frame type.
601: 	header := make([]byte, 5)
602: 	if _, err := io.ReadFull(conn, header); err != nil {
603: 		if errors.Is(err, os.ErrDeadlineExceeded) {
604: 			return "", ErrCaptureTimeout
605: 		}
606: 		return "", fmt.Errorf("read response header: %w", err)
607: 	}
608: 
609: 	ftype := header[0]
610: 	plen := binary.BigEndian.Uint32(header[1:5])
611: 
612: 	if plen > captureMaxPayload {
613: 		return "", fmt.Errorf("response too large: %d bytes", plen)
614: 	}
615: 
616: 	if ftype != FrameReplay {
617: 		return "", fmt.Errorf("unexpected frame type: %02x", ftype)
618: 	}
619: 
620: 	if plen == 0 {
621: 		return "", nil
622: 	}
623: 
624: 	// The daemon may be older and ignore the bounded query payload. If it
625: 	// returns a full replay, discard its head and retain only the tail.
626: 	readLen := int(plen)
627: 	if readLen > maxBytes {
628: 		if _, err := io.CopyN(io.Discard, conn, int64(readLen-maxBytes)); err != nil {
629: 			if errors.Is(err, os.ErrDeadlineExceeded) {
630: 				return "", ErrCaptureTimeout
631: 			}
632: 			return "", fmt.Errorf("skip replay head: %w", err)
633: 		}
634: 		readLen = maxBytes
635: 	}
636: 
637: 	buf := make([]byte, readLen)
638: 	if _, err := io.ReadFull(conn, buf); err != nil {
639: 		if errors.Is(err, os.ErrDeadlineExceeded) {
640: 			return "", ErrCaptureTimeout
641: 		}
642: 		return "", fmt.Errorf("read response payload: %w", err)
643: 	}
644: 
645: 	// A response shorter than the requested window is complete. A response
646: 	// equal to the window may be either a bounded tail or an old full replay.
647: 	if plen < uint32(maxBytes) {
648: 		return r.legacyCleanCapture(buf), nil
649: 	}
650: 	return r.cleanCapture(buf), nil
651: }
652: 
653: // capturePayload sends FrameQueryBuffer and reads the full FrameReplay payload.
654: // It returns the raw payload (not cleaned). On read-deadline timeout the
655: // captured bytes read so far are returned along with a timeout error so that
656: // callers can still use partial data if they choose.
657: func (r *Registry) capturePayload(conn net.Conn) ([]byte, error) {
658: 	// Send query.
659: 	frame := encodeFrame(FrameQueryBuffer, nil)
660: 	if _, err := conn.Write(frame); err != nil {
661: 		return nil, fmt.Errorf("send query buffer frame: %w", err)
662: 	}
663: 
664: 	// Read the response header.
665: 	header := make([]byte, 5)
666: 	if _, err := io.ReadFull(conn, header); err != nil {
667: 		return nil, fmt.Errorf("read response header: %w", err)
668: 	}
669: 
670: 	ftype := header[0]
671: 	plen := binary.BigEndian.Uint32(header[1:5])
672: 
673: 	if plen > captureMaxPayload {
674: 		return nil, fmt.Errorf("response too large: %d bytes", plen)
675: 	}
676: 
677: 	if ftype != FrameReplay {
678: 		return nil, fmt.Errorf("unexpected frame type: %02x", ftype)
679: 	}
680: 
681: 	payload := make([]byte, plen)
682: 	if plen > 0 {
683: 		if _, err := io.ReadFull(conn, payload); err != nil {
684: 			if errors.Is(err, os.ErrDeadlineExceeded) {
685: 				// Return what we managed to read before the deadline.
686: 				return payload, err
687: 			}
688: 			return nil, fmt.Errorf("read response payload: %w", err)
689: 		}
690: 	}
691: 
692: 	return payload, nil
693: }
694: 
695: // cleanCapture strips ANSI escape sequences and control chars so callers get
696: // clean text (like capture-pane). It also trims a partial leading UTF-8
697: // continuation byte and drops the first line when it starts mid-line.
698: func (r *Registry) cleanCapture(payload []byte) string {
699: 	if len(payload) == 0 {
700: 		return ""
701: 	}
702: 
703: 	// Strip any partial leading UTF-8 continuation byte; the prior bytes were
704: 	// discarded by tail capture or ended mid-run on the wire.
705: 	start := 0
706: 	for start < len(payload) && payload[start]&0xc0 == 0x80 {
707: 		start++
708: 	}
709: 	payload = payload[start:]
710: 
711: 	if len(payload) == 0 {
712: 		return ""
713: 	}
714: 
715: 	// Drop a leading partial line only when the bounded payload was
716: 	// actually truncated and starts with non-newline content that contains a
717: 	// newline. If payload starts with '\n', retain it. If no newline exists,
718: 	// retain content instead of returning empty.
719: 	if payload[0] != '\n' {
720: 		if nl := bytes.IndexByte(payload, '\n'); nl >= 0 {
721: 			payload = payload[nl+1:]
722: 		}
723: 	}
724: 
725: 	if len(payload) == 0 {
726: 		return ""
727: 	}
728: 
729: 	// Strip ANSI escape sequences and control chars.
730: 	clean := ansiRe.ReplaceAllString(string(payload), "")
731: 	clean = ctrlRe.ReplaceAllString(clean, "")
732: 	return clean
733: }
734: 
735: // legacyCleanCapture is the original Capture cleaning behavior, kept for
736: // compatibility. It does not strip partial leading bytes/lines.
737: func (r *Registry) legacyCleanCapture(payload []byte) string {
738: 	clean := ansiRe.ReplaceAllString(string(payload), "")
739: 	clean = ctrlRe.ReplaceAllString(clean, "")
740: 	return clean
741: }
742: 
743: // CrashedSessions returns lifecycle records for all sessions that crashed
744: // (state == "crashed").  Returns nil if no lifecycle store is configured.
745: func (r *Registry) CrashedSessions() []LifecycleRecord {
746: 	if r.lifecycleStore == nil {
747: 		return nil
748: 	}
749: 	return r.lifecycleStore.ListByState(LifecycleCrashed)
750: }
751: 
752: // DetectAndCleanupCrashes calls DetectCrashes on the lifecycle store and
753: // stops the systemd scope for each newly discovered crashed session.
754: // This prevents orphaned cgroups from accumulating across server restarts.
755: // Returns the list of newly crashed records (in "crashed" state).
756: func (r *Registry) DetectAndCleanupCrashes() []LifecycleRecord {
757: 	if r.lifecycleStore == nil {
758: 		return nil
759: 	}
760: 	crashed := r.lifecycleStore.DetectCrashes()
761: 	for _, rec := range crashed {
762: 		// Stop the exact unit from the crashed record — do NOT re-read
763: 		// lifecycle state via stopSystemdScope, which could pick up a
764: 		// concurrently-recovered record and kill the replacement scope.
765: 		r.stopSystemdUnit(rec.SystemdUnit)
766: 	}
767: 	return crashed
768: }
769: 
770: // RecoverSession re-spawns a daemon for a previously crashed session.
771: // It reads the saved shell/cwd from the lifecycle record, starts a new daemon,
772: // and transitions the state to "recovered".  The old stale socket and metadata
773: // files are cleaned up before the new daemon is spawned.
774: // Optional shellOverride and cwdOverride allow the user to choose a different
775: // shell or working directory at recovery time.
776: func (r *Registry) RecoverSession(id string, shellOverride ...string) error {
777: 	if !validSessionID(id) {
778: 		return fmt.Errorf("invalid session id: %q", id)
779: 	}
780: 	r.recoveryMu.Lock()
781: 	defer r.recoveryMu.Unlock()
782: 	if r.lifecycleStore == nil {
783: 		return fmt.Errorf("no lifecycle store configured")
784: 	}
785: 
786: 	rec, err := r.lifecycleStore.Get(id)
787: 	if err != nil {
788: 		return fmt.Errorf("get lifecycle record for %s: %w", id, err)
789: 	}
790: 	if rec.State != LifecycleCrashed {
791: 		return fmt.Errorf("session %s is in state %q, not crashed", id, rec.State)
792: 	}
793: 
794: 	shell := rec.Shell
795: 	cwd := rec.Cwd
796: 	if len(shellOverride) > 0 && shellOverride[0] != "" {
797: 		shell = shellOverride[0]
798: 	}
799: 	if len(shellOverride) > 1 && shellOverride[1] != "" {
800: 		cwd = shellOverride[1]
801: 	}
802: 
803: 	// Stop the old systemd scope before removing files and spawning
804: 	// the replacement.  The crashed session's scope may still have
805: 	// orphaned child processes (shell, background jobs).
806: 	// Use the exact unit from the crashed record — do not re-read.
807: 	r.stopSystemdUnit(rec.SystemdUnit)
808: 
809: 	// Transition to recovered BEFORE spawning — the new daemon will
810: 	// overwrite the lifecycle record with a fresh "active" state on
811: 	// startup, which is the correct final state.
812: 	if err := r.lifecycleStore.Transition(id, LifecycleCrashed, LifecycleRecovered); err != nil {
813: 		return fmt.Errorf("transition to recovered: %w", err)
814: 	}
815: 
816: 	// Clean up old stale files so the new daemon can claim the socket.
817: 	os.Remove(r.SocketPath(id))
818: 	os.Remove(r.metadataPath(id))
819: 
820: 	// Spawn a new daemon with the saved (or overridden) configuration.
821: 	if err := r.Create(id, shell, cwd, rec.Cols, rec.Rows); err != nil {
822: 		// Rollback lifecycle state on spawn failure.
823: 		_ = r.lifecycleStore.Transition(id, LifecycleRecovered, LifecycleCrashed)
824: 		return fmt.Errorf("re-spawn daemon for %s: %w", id, err)
825: 	}
826: 
827: 	logrus.WithFields(logrus.Fields{
828: 		"component": "registry",
829: 		"id":        id,
830: 		"shell":     shell,
831: 		"cwd":       cwd,
832: 	}).Info("recovered crashed session")
833: 
834: 	return nil
835: }
836: 
837: // DismissSession marks a crashed session as dismissed and cleans up its files.
838: func (r *Registry) DismissSession(id string) error {
839: 	if !validSessionID(id) {
840: 		return fmt.Errorf("invalid session id: %q", id)
841: 	}
842: 	r.recoveryMu.Lock()
843: 	defer r.recoveryMu.Unlock()
844: 	return r.dismissSessionLocked(id)
845: }
846: 
847: // dismissSessionLocked is the inner implementation; caller must hold recoveryMu.
848: func (r *Registry) dismissSessionLocked(id string) error {
849: 	if r.lifecycleStore == nil {
850: 		// No lifecycle store — clean up files only (no scope to stop).
851: 		os.Remove(r.SocketPath(id))
852: 		os.Remove(r.metadataPath(id))
853: 		return nil
854: 	}
855: 
856: 	rec, err := r.lifecycleStore.Get(id)
857: 	if err != nil {
858: 		// No lifecycle record — clean up files only (pre-lifecycle daemon).
859: 		os.Remove(r.SocketPath(id))
860: 		os.Remove(r.metadataPath(id))
861: 		return nil
862: 	}
863: 
864: 	// Guard: only crashed sessions can be dismissed.  Do NOT stop the
865: 	// scope before this check — a live session must not be killed just
866: 	// because someone asked to dismiss it.
867: 	if rec.State != LifecycleCrashed {
868: 		return fmt.Errorf("session %s is in state %q, not crashed", id, rec.State)
869: 	}
870: 
871: 	// Stop the exact systemd unit from the crashed record before
872: 	// cleaning up files.  We use the unit from the already-read record
873: 	// to avoid re-reading mutable lifecycle state.
874: 	r.stopSystemdUnit(rec.SystemdUnit)
875: 
876: 	if err := r.lifecycleStore.Transition(id, LifecycleCrashed, LifecycleDismissed); err != nil {
877: 		return fmt.Errorf("transition to dismissed: %w", err)
878: 	}
879: 
880: 	os.Remove(r.SocketPath(id))
881: 	os.Remove(r.metadataPath(id))
882: 	return nil
883: }
884: 
885: // DismissAll marks all crashed sessions as dismissed and cleans up their files.
886: func (r *Registry) DismissAll() error {
887: 	r.recoveryMu.Lock()
888: 	defer r.recoveryMu.Unlock()
889: 	crashed := r.CrashedSessions()
890: 	for _, rec := range crashed {
891: 		_ = r.dismissSessionLocked(rec.ID)
892: 	}
893: 	return nil
894: }
895: 
896: // CleanupCrashedIfDead removes crash-preserved files for a session if the
897: // daemon process is confirmed dead and the user hasn't chosen recovery.
898: // This is called as a fallback when a session transitions from crashed to
899: // cleanly_ended (e.g. the daemon's shell finally exits after a crash).
900: func (r *Registry) CleanupCrashedIfDead(id string) {
901: 	if r.lifecycleStore == nil {
902: 		return
903: 	}
904: 	rec, err := r.lifecycleStore.Get(id)
905: 	if err != nil || rec.State != LifecycleCrashed {
906: 		return
907: 	}
908: 	if !processAlive(rec.DaemonPID) {
909: 		// Process long dead — safe to clean up.
910: 		// Use the exact unit from the already-read crashed record.
911: 		r.stopSystemdUnit(rec.SystemdUnit)
912: 		os.Remove(r.SocketPath(id))
913: 		os.Remove(r.metadataPath(id))
914: 	}
915: }
916: 
917: // stopSystemdUnit stops a specific systemd user scope unit by name.
918: // This helper does NOT re-read lifecycle state — the caller is responsible
919: // for passing the correct unit (e.g., from an already-read lifecycle record).
920: // It is best-effort: failures are logged but not returned.
921: func (r *Registry) stopSystemdUnit(unit string) {
922: 	// Test hook: if set, delegate to the injected function instead of
923: 	// spawning a real systemctl process.
924: 	if r.stopUnitFn != nil {
925: 		r.stopUnitFn(unit)
926: 		return
927: 	}
928: 	if unit == "" {
929: 		return
930: 	}
931: 
932: 	log := logrus.WithFields(logrus.Fields{
933: 		"component": "registry",
934: 		"unit":      unit,
935: 	})
936: 
937: 	systemctl, err := exec.LookPath("systemctl")
938: 	if err != nil {
939: 		log.Debug("systemctl not found, skipping scope stop")
940: 		return
941: 	}
942: 
943: 	// Run with a short timeout so we never block the caller.
944: 	stop := exec.Command(systemctl, "--user", "stop", unit)
945: 	// Detach from parent's stdin/stdout.
946: 	stop.Stdin = nil
947: 	stop.Stdout = nil
948: 	stop.Stderr = nil
949: 
950: 	if err := stop.Start(); err != nil {
951: 		log.WithError(err).Debug("failed to start systemctl stop")
952: 		return
953: 	}
954: 
955: 	// Don't wait — systemctl stop on a dead scope may hang briefly.
956: 	// Release the process handle so it runs independently.
957: 	_ = stop.Process.Release()
958: 	log.Debug("requested systemd scope stop")
959: }
960: 
961: // stopSystemdScope reads the unit name for a session and stops it.
962: // Prefer stopSystemdUnit when you already have the unit name from an
963: // already-read lifecycle record, to avoid re-reading mutable state.
964: func (r *Registry) stopSystemdScope(name string) {
965: 	unit := r.readSystemdUnit(name)
966: 	r.stopSystemdUnit(unit)
967: }
968: 
969: // readSystemdUnit returns the systemd unit name from the lifecycle record
970: // or, as a fallback, from the metadata JSON sidecar.
971: func (r *Registry) readSystemdUnit(name string) string {
972: 	// Try lifecycle record first.
973: 	if r.lifecycleStore != nil {
974: 		if rec, err := r.lifecycleStore.Get(name); err == nil && rec.SystemdUnit != "" {
975: 			return rec.SystemdUnit
976: 		}
977: 	}
978: 
979: 	// Fallback: read from metadata sidecar.
980: 	metaPath := r.metadataPath(name)
981: 	data, err := os.ReadFile(metaPath)
982: 	if err != nil {
983: 		return ""
984: 	}
985: 	var meta sessionMeta
986: 	if json.Unmarshal(data, &meta) != nil {
987: 		return ""
988: 	}
989: 	return meta.SystemdUnit
