 14: // SessionMetadata holds mutable, display-oriented state for a single session.
 15: type SessionMetadata struct {
 16: 	ProjectPath      string
 17: 	AgentType        string
 18: 	PromptPreview    string
 19: 	AgentSessionID   string
 20: 	UserPrompt       string    // first user message; set once, for sidebar display
 21: 	LastUserPrompt   string    // latest user message; always updated, for AI naming
 22: 	LastAgentMessage string    // last agent response; always updated
 23: 	DisplayName      string    // AI-generated friendly label, refreshed as work evolves
 24: 	UserSetName      bool      // user manually set DisplayName; AI must not overwrite
 25: 	NameAssigned     bool      // AI naming has run at least once (informational/persisted)
 26: 	Renamed          bool      // underlying session was renamed; one-shot to avoid key churn
 27: 	LastNamedAt      time.Time // last time a generated name was successfully applied (not persisted)
 28: 
 29: 	// LastNamingAttemptAt records the most recent start of an automatic naming
 30: 	// attempt, whether it succeeded or failed. It drives the debounce/backoff
 31: 	// timer for automatic naming and is not persisted.
 32: 	LastNamingAttemptAt time.Time `json:"-"`
 33: 
 34: 	// NamingFailureCount tracks consecutive automatic naming failures for this
 35: 	// session. It resets to zero when an automatic naming attempt succeeds.
 36: 	// It is not persisted and does not affect manual/explicit renames.
 37: 	NamingFailureCount int `json:"-"`
 38: }
