 40: // Manager holds the central state tree.
 41: type Manager struct {
 42: 	mu       sync.RWMutex
 43: 	sessions map[string]*model.Session
 44: 	meta     map[string]SessionMetadata
 45: 	namer    *namer.Namer
 46: 
 47: 	// daemonReg provides metadata lookup for daemon sessions so
 48: 	// loadSessionDetails can populate CWD, PID, and synthetic panes.
 49: 	daemonReg DaemonRegistry
 50: 
 51: 	// previewCache holds debounced prompt-preview snapshots so the 2-second
 52: 	// discovery refresh never blocks on expensive ring captures.
 53: 	previewMu  sync.Mutex
 54: 	previews   map[string]*previewCacheEntry
 55: 	previewGen uint64
 56: 
 57: 	// onRename, when set, fires after a rename is applied (manual, AI naming, or
 58: 	// peer-driven) so external per-session stores keyed by session name can
 59: 	// migrate their entries.
 60: 	onRename func(oldName, newName string)
 61: 
 62: 	// namesPath persists name metadata across restarts so AI/manual display
 63: 	// names survive a server reload (session names persist on their own,
 64: 	// but shell DisplayNames and non-renamed agent names live only in meta).
 65: 	namesPath string
 66: 
 67: 	// autoNameGate enforces automatic naming cadence (success interval and
 68: 	// failure backoff) and serializes concurrent attempts per session. It is
 69: 	// the authoritative source for gating decisions; the SessionMetadata mirror
 70: 	// fields (LastNamedAt, LastNamingAttemptAt, NamingFailureCount) are kept
 71: 	// only for compatibility/tests and logged introspection.
 72: 	autoNameGate *namer.AutomaticGate
 73: 	gateOnce     sync.Once
 74: 
 75: 	// v2 shadow catalog (Task 5). When enabled the legacy manager keeps
 76: 	// running v1 routes but projects the v2 catalog for comparison logging.
 77: 	v2Catalog    *Catalog
 78: 	v2Reconciler *Reconciler
 79: 	v2Enricher   RuntimeEnricher
 80: 	v2Enabled    bool
 81: 
 82: 	// Subscribers for state changes.
 83: 	subMu       sync.RWMutex
 84: 	subscribers []chan StateEvent
 85: }
