125: const (
126: 	// promptPreviewInterval throttles ring captures so the 2-second discovery
127: 	// refresh never pays for repeated expensive buffer replays.
128: 	promptPreviewInterval = 30 * time.Second
129: 
130: 	// promptPreviewTailBytes is the upper bound passed to CaptureTail. A tail
131: 	// this size is enough to find the most recent prompt while keeping CPU low.
132: 	promptPreviewTailBytes = 64 * 1024
133: 
134: 	// promptPreviewEmptyLimit clears a stale preview after this many consecutive
135: 	// successful captures that produce no extractable preview.
136: 	promptPreviewEmptyLimit = 3
137: 
138: 	// nameRefreshInterval debounces continuous AI re-naming of agent sessions so a
139: 	// burst of completed turns does not hammer the namer endpoint.
140: 	nameRefreshInterval = 45 * time.Second
141: )
