185: // automaticGate returns the shared automatic-naming gate. It lazily initializes
186: // with the default policy the first time it is requested; tests may pre-populate
187: // m.autoNameGate with a custom gate before calling any naming method.
188: func (m *Manager) automaticGate() *namer.AutomaticGate {
189: 	m.gateOnce.Do(func() {
190: 		if m.autoNameGate == nil {
191: 			m.autoNameGate = namer.NewAutomaticGate(namer.DefaultAutomaticPolicy())
192: 		}
193: 	})
194: 	return m.autoNameGate
