  38: // --- internal helpers --------------------------------------------------
  39: 
  40: // Clipboard helpers
  41: let pendingClipboard: string | null = null
  42: 
  43: function execCommandCopy(text: string): boolean {
  44:   const ta = document.createElement('textarea')
  45:   ta.value = text
  46:   ta.style.position = 'fixed'
  47:   ta.style.left = '-9999px'
  48:   ta.style.opacity = '0'
  49:   document.body.appendChild(ta)
  50:   ta.select()
  51:   let ok = false
  52:   try {
  53:     ok = document.execCommand('copy')
  54:   } catch { /* ignored */ }
  55:   document.body.removeChild(ta)
  56:   return ok
  57: }
  58: 
  59: export function normalizeSelection(text: string): string {
  60:   return text.replace(/[ \t]+$/gm, '')
  61: }
  62: 
  63: function copyToClipboard(text: string): Promise<void> {
  64:   text = normalizeSelection(text)
  65:   if (navigator.clipboard) {
  66:     return navigator.clipboard.writeText(text).catch(() => {
  67:       if (!execCommandCopy(text)) {
  68:         pendingClipboard = text
  69:       }
  70:     })
  71:   }
  72:   if (!execCommandCopy(text)) {
  73:     pendingClipboard = text
  74:   }
  75:   return Promise.resolve()
  76: }
  77: 
  78: function flushPendingClipboard(): void {
  79:   if (pendingClipboard !== null) {
  80:     const text = pendingClipboard
  81:     pendingClipboard = null
  82:     if (navigator.clipboard) {
  83:       navigator.clipboard.writeText(text).catch(() => {
  84:         if (!execCommandCopy(text)) {
  85:           pendingClipboard = text
  86:         }
  87:       })
  88:     } else if (!execCommandCopy(text)) {
  89:       pendingClipboard = text
  90:     }
  91:   }
  92: }
  93: 
  94: function requestClipboardPermission(): void {
  95:   navigator.permissions?.query({ name: 'clipboard-write' as PermissionName }).catch(() => {})
  96: }
  97: 
  98: const clipboardProvider: IClipboardProvider = {
  99:   readText(selection: ClipboardSelectionType): Promise<string> {
 100:     if (selection !== 'c') return Promise.resolve('')
 101:     return navigator.clipboard?.readText?.() ?? Promise.resolve('')
 102:   },
 103:   writeText(selection: ClipboardSelectionType, text: string): Promise<void> {
 104:     if (selection !== 'c') return Promise.resolve()
 105:     return copyToClipboard(text)
 106:   },
 107: }
