 109: const MAX_PASTED_FILE_BYTES = 10 * 1024 * 1024
 110: 
 111: export function concatU8Legacy(parts: Uint8Array[]): Uint8Array {
 112:   let len = 0
 113:   for (const p of parts) len += p.length
 114:   const out = new Uint8Array(len)
 115:   let off = 0
 116:   for (const p of parts) {
 117:     out.set(p, off)
 118:     off += p.length
 119:   }
 120:   return out
 121: }
 122: 
 123: function indexOfU8(haystack: Uint8Array, needle: Uint8Array, start = 0): number {
 124:   if (needle.length === 0) return start
 125:   outer: for (let i = start; i <= haystack.length - needle.length; i++) {
 126:     for (let j = 0; j < needle.length; j++) {
 127:       if (haystack[i + j] !== needle[j]) continue outer
 128:     }
 129:     return i
 130:   }
 131:   return -1
 132: }
 133: 
 134: // Shared prefix of the DEC mode 2026 synchronized-update markers.
 135: // BSU = \x1b[?2026h, ESU = \x1b[?2026l. The 6-byte prefix is shared; the
 136: // 7th byte disambiguates start (0x68) vs end (0x6c).
 137: const SYNC_MARKER_PREFIX = new Uint8Array([0x1b, 0x5b, 0x3f, 0x32, 0x30, 0x32, 0x36])
 138: 
 139: function bytesToBase64(bytes: Uint8Array): string {
 140:   let binary = ''
 141:   const chunkSize = 0x8000
 142:   for (let i = 0; i < bytes.length; i += chunkSize) {
 143:     const chunk = bytes.subarray(i, i + chunkSize)
 144:     binary += String.fromCharCode(...chunk)
 145:   }
 146:   return btoa(binary)
 147: }
 148: 
 149: async function sendPastedImage(
 150:   ws: WebSocket,
 151:   file: File,
 152:   fallbackType: string,
 153:   entry: PoolEntry,
 154:   gen: number,
 155: ): Promise<void> {
 156:   if (file.size > MAX_PASTED_FILE_BYTES) {
 157:     return
 158:   }
 159:   const buffer = await file.arrayBuffer()
 160:   // Re-validate lease after async gap — entry may have been checked in/out
 161:   if (entry.generation !== gen || entry.connection.socket !== ws || ws.readyState !== WebSocket.OPEN) return
 162:   ws.send(JSON.stringify({
 163:     type: 'paste-image',
 164:     data: bytesToBase64(new Uint8Array(buffer)),
 165:     mime: file.type || fallbackType,
 166:     filename: file.name,
 167:   }))
 168: }
