 170: // Scroll-preserving fit.
 171: //
 172: // fitAddon.fit() reflows rows and can move the viewport, so we restore the
 173: // user's prior scroll anchor afterward.
 174: //
 175: // CRITICAL: we decide whether to preserve a non-bottom offset using
 176: // entry.userScrolled (set only by real wheel/touch/scrollbar gestures), NOT
 177: // buffer geometry. xterm updates viewportY asynchronously during rapid writes
 178: // (spinner/redraw animations), so capturing `baseY - viewportY` mid-frame
 179: // reads a stale in-between state and "restores" the terminal to a phantom
 180: // offset, pinning it mid-history and flashing on every redraw.
 181: function fitPreservingScroll(
 182:   entry: PoolEntry,
 183:   container: HTMLElement,
 184:   opts?: { refreshAfter?: boolean },
 185: ): void {
 186:   const term = entry.terminal
 187:   const fitAddon = entry.fitAddon
 188:   if (container.clientWidth <= 0 || container.clientHeight <= 0) return
 189: 
 190:   const myEpoch = ++entry.fitEpoch
 191:   const buf = term.buffer.active
 192:   // Only preserve a real user offset. geometry-based distFromBottom is
 193:   // unreliable during async writes.
 194:   const userOffset = entry.userScrolled ? Math.max(0, buf.baseY - buf.viewportY) : 0
 195: 
 196:   const isStale = () => entry.fitEpoch !== myEpoch
 197: 
 198:   neutralizeXtermScrollbarFallback(term)
 199:   fitAddon.fit()
 200: 
 201:   if (opts?.refreshAfter) {
 202:     try { term.refresh(0, term.rows - 1) } catch { /* renderer dispose race */ }
 203:   }
 204: 
 205:   if (userOffset === 0) {
 206:     // Following output: pin to bottom once. xterm keeps it there on writes.
 207:     try { term.scrollToBottom() } catch { /* renderer dispose race */ }
 208:     const forceDOM = () => {
 209:       if (isStale()) return
 210:       const vp = container.querySelector('.xterm-viewport') as HTMLElement | null
 211:       if (vp && vp.scrollTop + vp.clientHeight < vp.scrollHeight - 5) {
 212:         vp.scrollTop = vp.scrollHeight
 213:       }
 214:     }
 215:     requestAnimationFrame(forceDOM)
 216:     return
 217:   }
 218: 
 219:   // User is genuinely scrolled up: restore the captured offset, but only
 220:   // across a single deferred frame (xterm recomputes viewport async).
 221:   const restoreOnce = () => {
 222:     if (isStale() || !entry.userScrolled) return
 223:     try {
 224:       const after = term.buffer.active
 225:       if (userOffset > after.baseY) { term.scrollToBottom(); return }
 226:       const target = after.baseY - userOffset
 227:       const delta = target - after.viewportY
 228:       if (delta !== 0) term.scrollLines(delta)
 229:     } catch { /* renderer dispose race */ }
 230:   }
 231:   restoreOnce()
 232:   requestAnimationFrame(restoreOnce)
 233: }
