 347:   // Connection
 348:   connected: boolean
 349: 
 350:   // Lease
 351:   generation: number
 352: 
 353:   // Fit-scheduling epoch. Incremented on every fit() and on user scroll so
 354:   // stale deferred scroll-restore callbacks from a prior fit can no-op.
 355:   fitEpoch: number
