 370:   // Dimensions
 371:   lastCols: number
 372:   lastRows: number
 373:   pendingResizeOnOpen: boolean
 374: 
 375:   // Modifier state
 376:   ctrlModifierActive: boolean
 377:   altModifierActive: boolean
 378:   suppressedInput: string | null
 379: 
 380:   // Selection
 381:   selectionMenu: { x: number; y: number; text: string } | null
 382: 
 383:   // Applied preferences
 384:   appliedPrefs: TerminalPrefs | null
 385: 
 386:   // Live output sync markers
 387:   syncCarryover: Uint8Array | null
 388:   syncActive: boolean
 389:   syncBuffer: Uint8Array[]
 390: 
 391:   // Echo/write coordination
 392:   writePending: boolean
 393: }
