 395: // --- Pool singleton ----------------------------------------------------
 396: 
 397: export class TerminalPool {
 398:   private entries = new Map<string, PoolEntry>()
 399:   private factory: PoolFactory
 400:   private poolRoot: HTMLElement | null = null
 401: 
 402:   constructor(factory?: PoolFactory) {
 403:     this.factory = factory ?? defaultFactory
 404:   }
 405: 
 406:   // ── public API: key management ──────────────────────────────────────
 407: 
 408:   /** Canonical key from session identity. */
 409:   static keyFor(sessionName: string, hostId?: string): string {
 410:     return hostId ? `${hostId}/${sessionName}` : sessionName
 411:   }
 412: 
 413:   keyFor(sessionName: string, hostId?: string): string {
 414:     return TerminalPool.keyFor(sessionName, hostId)
 415:   }
 416: 
 417:   /** Synchronous snapshot lookup without side effects. */
 418:   getSnapshot(key: string): ConnectionSnapshot | null {
 419:     const entry = this.entries.get(key)
 420:     if (!entry) return null
 421:     return {
 422:       connected: entry.connected,
 423:       ctrlModifierActive: entry.ctrlModifierActive,
 424:       altModifierActive: entry.altModifierActive,
 425:     }
 426:   }
 427: 
 428:   /** Return entries count (for tests). */
 429:   get size(): number {
 430:     return this.entries.size
 431:   }
 432: 
 433:   /** All current keys (for tests). */
 434:   get keys(): IterableIterator<string> {
 435:     return this.entries.keys()
 436:   }
 437: 
 438:   // ── public API: checkout / checkin ──────────────────────────────────
 439: 
 440:   checkout(
 441:     identity: PoolIdentity,
 442:     prefs: TerminalPrefs,
 443:     container: HTMLElement,
 444:     callbacks: CheckoutCallbacks,
 445:     factory?: PoolFactory,
 446:   ): LeaseToken {
 447:     // Canonical pool identity is the immutable SessionRef (sessionId/ownerId),
 448:     // NOT the display label. A rename must never rekey, dispose, or reconnect
 449:     // an open terminal; label-only changes hit the same pool entry.
 450:     const canonical = identity.sessionId
 451:       ? TerminalPool.keyFor(identity.sessionId, identity.ownerId ?? identity.hostId)
 452:       : TerminalPool.keyFor(identity.sessionName, identity.hostId)
 453:     const key = canonical
 454:     const ef = factory ?? this.factory
 455:     let entry = this.entries.get(key)
 456: 
 457:     // Dispose & recreate if backend identity changed for same key.
 458:     if (entry) {
 459:       const backendChanged = entry.identity.backend !== (identity.backend ?? undefined)
 460:       if (backendChanged) {
 461:         this.disposeEntry(entry)
 462:         this.entries.delete(key)
 463:         entry = undefined
 464:       }
 465:     }
 466: 
 467:     // Cold create
 468:     if (!entry) {
 469:       entry = this.createEntry(key, identity, prefs, ef)
 470:       this.entries.set(key, entry)
 471:     }
 472: 
 473:     // Increment lease — invalidate any previous owner
 474:     entry.generation++
 475:     const lease: LeaseToken = { generation: entry.generation, key }
 476: 
 477:     // Remove old foreground listeners
 478:     if (entry.listenerCleanup) {
 479:       entry.listenerCleanup()
 480:       entry.listenerCleanup = null
 481:     }
 482:     entry.activeCallbacks = callbacks
 483: 
 484:     // Bind terminal to the foreground container.
 485:     const term = entry.terminal
 486:     const root = term.element as HTMLElement | undefined
 487:     if (root) {
 488:       // Already opened: move the existing DOM node into the new container first.
 489:       (_transferNode ?? transferNode)(root, container)
 490:     }
 491:     try { term.open(container) } catch { /* ignored */ }
 492:     neutralizeXtermScrollbarFallback(term)
 493: 
 494:     entry.activeContainer = container
 495: 
 496:     // Attach foreground listeners
 497:     this.attachListeners(entry)
 498: 
 499:     // Reconcile preferences
 500:     this.reconcilePrefs(entry, prefs)
 501: 
 502:     // Fit and resize
 503:     if (container.clientWidth > 0 && container.clientHeight > 0) {
 504:       fitPreservingScroll(entry, container, { refreshAfter: true })
 505:       if (entry.connection.connected) {
 506:         const ws = entry.connection.socket
 507:         if (ws && ws.readyState === WebSocket.OPEN) {
 508:           const { cols, rows } = entry.terminal
 509:           ws.send(JSON.stringify({ type: 'resize', cols, rows }))
 510:           entry.lastCols = cols
 511:           entry.lastRows = rows
 512:           entry.pendingResizeOnOpen = false
 513:         }
 514:       } else {
 515:         entry.pendingResizeOnOpen = true
 516:       }
 517:     }
 518: 
 519:     // Deferred refresh: xterm's IntersectionObserver pauses rendering while the
 520:     // terminal element is off-screen. Schedule a second fit+refresh in rAF so
 521:     // the render fires once the observer has cleared the pause.
 522:     const deferredKey = lease.key
 523:     const deferredGen = entry.generation
 524:     window.requestAnimationFrame(() => {
 525:       const e = this.entries.get(deferredKey)
 526:       if (!e || e.generation !== deferredGen || !e.activeContainer) return
 527:       const c = e.activeContainer
 528:       if (c.clientWidth > 0 && c.clientHeight > 0) {
 529:         fitPreservingScroll(e, c, { refreshAfter: true })
 530:       } else {
 531:         try { e.terminal.refresh(0, e.terminal.rows - 1) } catch { /* ignored */ }
 532:       }
 533:     })
 534: 
 535:     // Publish initial snapshot
 536:     callbacks.onConnectionChange(entry.connected)
 537:     callbacks.onCtrlModifierChange(entry.ctrlModifierActive)
 538:     callbacks.onAltModifierChange(entry.altModifierActive)
 539: 
 540:     return lease
 541:   }
 542: 
 543:   checkin(lease: LeaseToken): void {
 544:     const entry = this.entries.get(lease.key)
 545:     if (!entry) return
 546:     if (entry.generation !== lease.generation) return
 547: 
 548:     // Invalidate lease so stale token can't operate after checkin
 549:     entry.generation++
 550: 
 551:     // Mark inactive
 552:     entry.activeCallbacks = null
 553:     entry.activeContainer = null
 554: 
 555:     // Remove foreground listeners
 556:     if (entry.listenerCleanup) {
 557:       entry.listenerCleanup()
 558:       entry.listenerCleanup = null
 559:     }
 560: 
 561:     // Capture dimensions from foreground before moving
 562:     if (entry.terminal.element) {
 563:       entry.lastCols = entry.terminal.cols
 564:       entry.lastRows = entry.terminal.rows
 565:     }
 566: 
 567:     // Move root to hidden host using shared transfer primitive
 568:     const root = entry.terminal.element as HTMLElement | undefined
 569:     if (root) {
 570:       const host = this.ensureHiddenHost(entry)
 571:       const { crossedDocument } = (_transferNode ?? transferNode)(root, host)
 572: 
 573:       // Cross-document reopen
 574:       if (crossedDocument) {
 575:         try { entry.terminal.open(host) } catch { /* ignored */ }
 576:       }
 577:     }
 578:   }
 579: 
 580:   // ── public API: lease-gated operations ──────────────────────────────
 581: 
 582:   fit(lease: LeaseToken): void {
 583:     const entry = this.validateLease(lease)
 584:     if (!entry || !entry.activeContainer) return
 585:     const container = entry.activeContainer
 586:     if (container.clientWidth <= 0 || container.clientHeight <= 0) return
 587:     fitPreservingScroll(entry, container, { refreshAfter: true })
 588:   }
 589: 
 590:   focus(lease: LeaseToken): void {
 591:     const entry = this.validateLease(lease)
 592:     if (!entry) return
 593:     try { entry.terminal.focus() } catch { /* ignored */ }
 594:   }
 595: 
 596:   rehost(lease: LeaseToken, container: HTMLElement, forceRebind?: boolean): void {
 597:     const entry = this.validateLease(lease)
 598:     if (!entry) return
 599: 
 600:     const root = entry.terminal.element as HTMLElement | undefined
 601:     if (!root) return
 602: 
 603:     const { crossedDocument } = (_transferNode ?? transferNode)(root, container)
 604: 
 605:     if (crossedDocument || forceRebind) {
 606:       try { entry.terminal.open(container) } catch { /* ignored */ }
 607:       neutralizeXtermScrollbarFallback(entry.terminal)
 608:     }
 609: 
 610:     entry.activeContainer = container
 611:   }
 612: 
 613:   sendRawBytes(lease: LeaseToken, bytes: Uint8Array): void {
 614:     const entry = this.validateLease(lease)
 615:     if (!entry) return
 616:     const ws = entry.connection.socket
 617:     if (ws && ws.readyState === WebSocket.OPEN) {
 618:       ws.send(bytes)
 619:     }
 620:   }
 621: 
 622:   sendText(lease: LeaseToken, text: string): void {
 623:     if (!text) return
 624:     this.sendRawBytes(lease, new TextEncoder().encode(text))
 625:   }
 626: 
 627:   async sendImage(lease: LeaseToken, file: File, fallbackType: string): Promise<void> {
 628:     const entry = this.validateLease(lease)
 629:     if (!entry) return
 630:     const ws = entry.connection.socket
 631:     if (!ws || ws.readyState !== WebSocket.OPEN) return
 632:     const gen = lease.generation
 633:     try {
 634:       await sendPastedImage(ws, file, fallbackType, entry, gen)
 635:     } catch (err) {
 636:       // Swallow; failed image paste should not crash the terminal.
 637:     }
 638:   }
 639: 
 640:   toggleCtrlModifier(lease: LeaseToken): void {
 641:     const entry = this.validateLease(lease)
 642:     if (!entry) return
 643:     entry.ctrlModifierActive = !entry.ctrlModifierActive
 644:     entry.activeCallbacks?.onCtrlModifierChange(entry.ctrlModifierActive)
 645:   }
 646: 
 647:   clearCtrlModifier(lease: LeaseToken): void {
 648:     const entry = this.validateLease(lease)
 649:     if (!entry) return
 650:     entry.ctrlModifierActive = false
 651:     entry.activeCallbacks?.onCtrlModifierChange(false)
 652:   }
 653: 
 654:   toggleAltModifier(lease: LeaseToken): void {
 655:     const entry = this.validateLease(lease)
 656:     if (!entry) return
 657:     entry.altModifierActive = !entry.altModifierActive
 658:     entry.activeCallbacks?.onAltModifierChange(entry.altModifierActive)
 659:   }
 660: 
 661:   clearAltModifier(lease: LeaseToken): void {
 662:     const entry = this.validateLease(lease)
 663:     if (!entry) return
 664:     entry.altModifierActive = false
 665:     entry.activeCallbacks?.onAltModifierChange(false)
 666:   }
 667: 
 668:   setSelectionMenu(lease: LeaseToken, menu: { x: number; y: number; text: string } | null): void {
 669:     const entry = this.validateLease(lease)
 670:     if (!entry) return
 671:     entry.selectionMenu = menu
 672:     entry.activeCallbacks?.onSelectionMenu(menu)
 673:   }
 674: 
 675:   getTerminalForPaste(lease: LeaseToken): Terminal | null {
 676:     const entry = this.validateLease(lease)
 677:     return entry?.terminal ?? null
 678:   }
 679: 
 680:   // ── public API: preferences ─────────────────────────────────────────
 681: 
 682:   /** Reconcile entry against current prefs (idempotent). Call on checkout. */
 683:   reconcilePrefs(entry: PoolEntry, prefs: TerminalPrefs): void {
 684:     // Theme
 685:     const xtermTheme = getXtermTheme(prefs.theme)
 686:     entry.terminal.options.theme = xtermTheme
 687:     try { entry.terminal.refresh(0, entry.terminal.rows - 1) } catch { /* ignored */ }
 688: 
 689:     // Font
 690:     const fontFamily = `'${prefs.fontFamily}', 'JetBrains Mono', 'Fira Code', Menlo, Monaco, 'Inconsolata LGC Nerd Font Mono', 'DejaVu Sans Mono Symbols', monospace`
 691:     entry.terminal.options.fontSize = prefs.fontSize
 692:     entry.terminal.options.fontFamily = fontFamily
 693:     measureXtermCharSize(entry.terminal)
 694: 
 695:     // Renderer
 696:     if (prefs.renderer === 'webgl' && !entry.webglAddon) {
 697:       const wa = this.factory.createWebglAddon()
 698:       if (wa) {
 699:         wa.onContextLoss(() => {
 700:           wa.dispose()
 701:           entry.webglAddon = null
 702:         })
 703:         try { entry.terminal.loadAddon(wa) } catch { /* ignored */ }
 704:         entry.webglAddon = wa as WebglAddon
 705:       }
 706:     } else if (prefs.renderer === 'dom' && entry.webglAddon) {
 707:       entry.webglAddon.dispose()
 708:       entry.webglAddon = null
 709:     }
 710: 
 711:     // Unicode graphemes
 712:     if (prefs.unicodeGraphemes && !entry.graphemesLoaded) {
 713:       const ga = this.factory.createUnicodeGraphemesAddon()
 714:       if (ga) {
 715:         try { entry.terminal.loadAddon(ga) } catch { /* ignored */ }
 716:         entry.graphemesAddon = ga as UnicodeGraphemesAddon
 717:         entry.graphemesLoaded = true
 718:       }
 719:     } else if (!prefs.unicodeGraphemes && entry.graphemesAddon) {
 720:       entry.graphemesAddon.dispose()
 721:       entry.graphemesAddon = null
 722:       entry.graphemesLoaded = false
 723:     }
 724: 
 725:     // Predictive echo
 726:     if (prefs.predictiveEcho && !entry.predictiveEcho) {
 727:       entry.predictiveEcho = this.factory.createPredictiveEcho(entry.terminal)
 728:     } else if (!prefs.predictiveEcho && entry.predictiveEcho) {
 729:       entry.predictiveEcho.dispose()
 730:       entry.predictiveEcho = null
 731:     }
 732:     entry.predictiveEchoEnabled = prefs.predictiveEcho
 733: 
 734:     entry.appliedPrefs = { ...prefs }
 735:   }
 736: 
 737:   /** Apply prefs to all entries (idempotent). */
 738:   applyGlobalPrefs(prefs: TerminalPrefs): void {
 739:     for (const entry of this.entries.values()) {
 740:       const prevScrollback = entry.appliedPrefs?.scrollback
 741:       const newScrollback = prefs.scrollback
 742: 
 743:       // Scrollback change triggers rebuild
 744:       if (prevScrollback !== undefined && prevScrollback !== newScrollback) {
 745:         // Capture identity before disposal
 746:         const identity = entry.identity
 747:         const key = entry.key
 748:         const wasActive = entry.activeContainer !== null
 749:         const prevContainer = entry.activeContainer
 750: 
 751:         this.disposeEntry(entry)
 752:         this.entries.delete(key)
 753: 
 754:         const newEntry = this.createEntry(key, identity, prefs, this.factory)
 755:         this.entries.set(key, newEntry)
 756: 
 757:         if (wasActive && prevContainer) {
 758:           // Re-checkout into same container
 759:           newEntry.generation++
 760:           newEntry.activeContainer = prevContainer
 761:           const root = newEntry.terminal.element as HTMLElement | undefined
 762:           try { newEntry.terminal.open(prevContainer) } catch { /* ignored */ }
 763:           neutralizeXtermScrollbarFallback(newEntry.terminal)
 764:           if (root) prevContainer.appendChild(root)
 765:           this.attachListeners(newEntry)
 766:           // Load renderer-dependent addons (WebGL) AFTER open() above.
 767:           this.reconcilePrefs(newEntry, prefs)
 768:           fitPreservingScroll(newEntry, prevContainer, { refreshAfter: true })
 769:           // Send resize
 770:           const ws = newEntry.connection.socket
 771:           if (ws && ws.readyState === WebSocket.OPEN) {
 772:             const { cols, rows } = newEntry.terminal
 773:             ws.send(JSON.stringify({ type: 'resize', cols, rows }))
 774:           }
 775:         }
 776:       } else {
 777:         this.reconcilePrefs(entry, prefs)
 778:       }
 779:     }
 780:   }
 781: 
 782:   // ── public API: dispose / rekey ─────────────────────────────────────
 783: 
 784:   dispose(key: string): void {
 785:     const entry = this.entries.get(key)
 786:     if (!entry) return
 787:     this.disposeEntry(entry)
 788:     this.entries.delete(key)
 789:   }
 790: 
 791:   /** Remove entries NOT in validKeys. skip when the server-side catalog is
 792:    *  transient/uncertain (reconnect, empty snapshot) so one stale response
 793:    *  cannot dispose active terminals. */
 794:   disposeAbsent(validKeys: Set<string>, catalogUncertain = false): void {
 795:     if (catalogUncertain) return
 796:     for (const key of this.entries.keys()) {
 797:       if (!validKeys.has(key)) {
 798:         this.dispose(key)
 799:       }
 800:     }
 801:   }
 802: 
 803:   /** Rename a pool entry, preserving terminal/WS. */
 804:   rekey(oldKey: string, newKey: string): void {
 805:     if (oldKey === newKey) return
 806:     const entry = this.entries.get(oldKey)
 807:     if (!entry) return
 808: 
 809:     // Dispose destination if it exists
 810:     if (this.entries.has(newKey)) {
 811:       this.dispose(newKey)
 812:     }
 813: 
 814:     // Move entry to new key
 815:     this.entries.delete(oldKey)
 816:     const sessionName = newKey.includes('/') ? newKey.slice(newKey.indexOf('/') + 1) : newKey
 817:     const hostId = newKey.includes('/') ? newKey.slice(0, newKey.indexOf('/')) : undefined
 818:     const prev = entry.identity
 819:     entry.key = newKey
 820:     // Canonical identity is immutable (`sessionId`/`ownerId`/`generation`); a
 821:     // label change must NOT mutate them, so preserve them across a rename and
 822:     // only update the display key fields.
 823:     entry.identity = {
 824:       sessionName,
 825:       hostId,
 826:       backend: prev.backend,
 827:       sessionId: prev.sessionId,
 828:       ownerId: prev.ownerId,
 829:       generation: prev.generation,
 830:     }
 831:     // Update the lease token for current owner
 832:     entry.generation++ // invalidate previous lease
 833:     this.entries.set(newKey, entry)
 834:   }
 835: 
 836:   /**
 837:    * Reconnect an existing pool entry in place after its daemon generation
 838:    * changed (recovery/restart). Same terminal instance, scrollback, and lease
 839:    * are preserved; only the WebSocket URL is rebuilt with the new generation.
 840:    * No-op for unknown keys or when the generation is unchanged.
 841:    */
 842:   updateGeneration(key: string, generation: string): void {
 843:     const entry = this.entries.get(key)
 844:     if (!entry || entry.identity.generation === generation) return
 845:     entry.identity = { ...entry.identity, generation }
 846:     entry.connection.connect(this.buildUrl({ key, identity: entry.identity }))
 847:   }
 848: 
 849:   /** Reset all state (for tests). */
 850:   reset(): void {
 851:     for (const entry of this.entries.values()) {
 852:       this.disposeEntry(entry)
 853:     }
 854:     this.entries.clear()
 855:     if (this.poolRoot) {
 856:       this.poolRoot.remove()
 857:       this.poolRoot = null
 858:     }
 859:     _transferNode = null
 860:   }
 861: 
 862:   // ── private helpers ─────────────────────────────────────────────────
 863: 
 864:   private validateLease(lease: LeaseToken): PoolEntry | null {
 865:     const entry = this.entries.get(lease.key)
 866:     if (!entry || entry.generation !== lease.generation) return null
 867:     return entry
 868:   }
 869: 
 870:   private ensureHiddenHost(entry: PoolEntry): HTMLElement {
 871:     if (entry.hiddenHost) return entry.hiddenHost
 872: 
 873:     if (!this.poolRoot) {
 874:       const root = document.createElement('div')
 875:       root.setAttribute('data-terminal-pool-root', '')
 876:       root.style.position = 'fixed'
 877:       root.style.top = '-9999px'
 878:       root.style.left = '-9999px'
 879:       root.style.width = '1px'
 880:       root.style.height = '1px'
 881:       root.style.overflow = 'hidden'
 882:       root.style.pointerEvents = 'none'
 883:       root.style.visibility = 'visible' // NOT display:none — keep rAF/WebGL alive
 884:       root.style.opacity = '0'
 885:       document.body.appendChild(root)
 886:       this.poolRoot = root
 887:     }
 888: 
 889:     const host = document.createElement('div')
 890:     host.setAttribute('data-terminal-pool-host', entry.key)
 891:     host.style.width = `${Math.max(entry.lastCols * 10, 80)}px`
 892:     host.style.height = `${Math.max(entry.lastRows * 18, 24)}px`
 893:     host.style.pointerEvents = 'none'
 894:     host.style.overflow = 'hidden'
 895:     host.style.visibility = 'visible'
 896:     this.poolRoot.appendChild(host)
 897:     entry.hiddenHost = host
 898:     return host
 899:   }
 900: 
 901:   // ── entry creation ──────────────────────────────────────────────────
 902: 
 903:   private createEntry(
 904:     key: string,
 905:     identity: PoolIdentity,
 906:     prefs: TerminalPrefs,
 907:     ef: PoolFactory,
 908:   ): PoolEntry {
 909:     const xtermTheme = getXtermTheme(prefs.theme)
 910:     const fontFamily = `'${prefs.fontFamily}', 'JetBrains Mono', 'Fira Code', Menlo, Monaco, 'Inconsolata LGC Nerd Font Mono', 'DejaVu Sans Mono Symbols', monospace`
 911: 
 912:     const term = ef.createTerminal({
 913:       theme: xtermTheme,
 914:       fontSize: prefs.fontSize,
 915:       fontFamily,
 916:       cursorBlink: true,
 917:       scrollback: prefs.scrollback,
 918:       allowProposedApi: true,
 919:       rightClickSelectsWord: true,
 920:       macOptionClickForcesSelection: true,
 921:       macOptionIsMeta: true,
 922:     })
 923: 
 924:     const fitAddon = ef.createFitAddon()
 925:     term.loadAddon(fitAddon)
 926:     term.loadAddon(ef.createWebLinksAddon())
 927:     term.loadAddon(ef.createClipboardAddon(clipboardProvider))
 928: 
 929:     // WebGL renderer is loaded lazily AFTER term.open() (xterm.js requirement).
 930:     let webglAddon: WebglAddon | null = null
 931: 
 932:     const imageAddon = ef.createImageAddon()
 933:     if (imageAddon) {
 934:       try { term.loadAddon(imageAddon) } catch { /* ignored */ }
 935:     }
 936: 
 937:     let graphemesAddon: UnicodeGraphemesAddon | null = null
 938:     let graphemesLoaded = false
 939:     if (prefs.unicodeGraphemes) {
 940:       const ga = ef.createUnicodeGraphemesAddon()
 941:       if (ga) {
 942:         try { term.loadAddon(ga) } catch { /* ignored */ }
 943:         graphemesAddon = ga as UnicodeGraphemesAddon
 944:         graphemesLoaded = true
 945:       }
 946:     }
 947: 
 948:     let predictiveEcho: PredictiveEcho | null = null
 949:     if (prefs.predictiveEcho) {
 950:       predictiveEcho = ef.createPredictiveEcho(term)
 951:     }
 952: 
 953:     const replayBuffer = new ReplayBuffer()
 954: 
 955:     // eslint-disable-next-line prefer-const
 956:     let entry!: PoolEntry
 957: 
 958:     const connection = new ConnectionMachine(
 959:       {
 960:         createWebSocket: ef.createWebSocket,
 961:         onConnecting: () => {
 962:           entry.replayBuffer.reset()
 963:           entry.syncActive = false
 964:           entry.syncBuffer = []
 965:           entry.syncCarryover = null
 966:         },
 967:         onConnectionChange: (connected) => this.handleConnectionChange(entry, connected),
 968:         onOpen: () => this.handleOpen(entry),
 969:         onBinaryMessage: (data) => this.handleBinaryMessage(entry, data),
 970:         onTextMessage: (text) => this.handleTextControl(entry, text),
 971:         onReplayStart: () => {
 972:           entry.replayBuffer.reset()
 973:           entry.syncActive = false
 974:           entry.syncBuffer = []
 975:           entry.syncCarryover = null
 976:         },
 977:         onReplayEnd: () => this.flushReplayBuffer(entry),
 978:         onFallback: () => this.flushReplayBuffer(entry),
 979:       },
 980:       this.buildUrl({ key, identity }),
 981:     )
 982: 
 983:     entry = {
 984:       key,
 985:       identity,
 986: 
 987:       terminal: term,
 988:       fitAddon,
 989:       webglAddon,
 990:       imageAddon,
 991:       graphemesAddon,
 992:       graphemesLoaded,
 993:       predictiveEcho,
 994:       predictiveEchoEnabled: prefs.predictiveEcho,
 995: 
 996:       connection,
 997:       replayBuffer,
 998: 
 999:       connected: false,
1000: 
1001:       generation: 0,
1002:       fitEpoch: 0,
1003:       userScrolled: false,
1004: 
1005:       activeContainer: null,
1006:       activeCallbacks: null,
1007:       listenerCleanup: null,
1008: 
1009:       hiddenHost: null,
1010: 
1011:       lastCols: 0,
1012:       lastRows: 0,
1013:       pendingResizeOnOpen: false,
1014: 
1015:       ctrlModifierActive: false,
1016:       altModifierActive: false,
1017:       suppressedInput: null,
1018: 
1019:       selectionMenu: null,
1020: 
1021:       appliedPrefs: { ...prefs },
1022: 
1023:       syncCarryover: null,
1024:       syncActive: false,
1025:       syncBuffer: [],
1026: 
1027:       writePending: false,
1028:     }
1029: 
1030:     connection.connect()
1031:     return entry
1032:   }
1033: 
1034:   // ── connection event handlers ───────────────────────────────────────
1035: 
1036:   private buildUrl(target: { key: string; identity: PoolIdentity }): string {
1037:     const term = this.entries.get(target.key)?.terminal
1038:     const cols = term?.cols || 80
1039:     const rows = term?.rows || 24
1040: 
1041:     const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:'
1042:     const sessionName = target.identity.sessionName
1043:     const hostId = target.identity.hostId
1044:     const backend = target.identity.backend
1045: 
1046:     const hostParam = hostId ? `&host=${encodeURIComponent(hostId)}` : ''
1047:     if (backend === 'daemon') {
1048:       // The legacy `name` param (display label) is required by the remote/
1049:       // peer routing path (handleRemoteSession) and doubles as the daemon key
1050:       // for pre-v2 sessions. The immutable SessionID is emitted only when it
1051:       // is actually known (a real v2 stable id) so legacy display names that
1052:       // are not valid SessionIDs keep routing by name.
1053:       const idParam = target.identity.sessionId
1054:         ? `&sessionID=${encodeURIComponent(target.identity.sessionId)}`
1055:         : ''
1056:       const genParam = target.identity.generation
1057:         ? `&generation=${encodeURIComponent(target.identity.generation)}`
1058:         : ''
1059:       return `${protocol}//${window.location.host}/ws/daemon-session?name=${encodeURIComponent(sessionName)}${idParam}${genParam}&cols=${cols}&rows=${rows}${hostParam}&replay=1`
1060:     }
1061:     if (sessionName.startsWith('direct-pty:')) {
1062:       return `${protocol}//${window.location.host}/ws/direct-session?cols=${cols}&rows=${rows}`
1063:     }
1064:     return `${protocol}//${window.location.host}/ws/session?name=${encodeURIComponent(sessionName)}&cols=${cols}&rows=${rows}${hostParam}&replay=1`
1065:   }
1066: 
1067:   private handleConnectionChange(entry: PoolEntry, connected: boolean): void {
1068:     entry.connected = connected
1069:     if (connected) {
1070:       entry.activeCallbacks?.onConnectionChange(true)
1071:       return
1072:     }
1073:     // Suppress the disconnected overlay while the tab is hidden; the machine
1074:     // will reconnect automatically when visibility returns.
1075:     if (!document.hidden) {
1076:       entry.activeCallbacks?.onConnectionChange(false)
1077:     }
1078:   }
1079: 
1080:   private handleOpen(entry: PoolEntry): void {
1081:     entry.syncActive = false
1082:     entry.syncBuffer = []
1083:     entry.syncCarryover = null
1084:     entry.writePending = false
1085: 
1086:     const ws = entry.connection.socket
1087:     if (entry.pendingResizeOnOpen && entry.activeContainer && ws) {
1088:       entry.pendingResizeOnOpen = false
1089:       const c = entry.terminal.cols
1090:       const r = entry.terminal.rows
1091:       entry.lastCols = c
1092:       entry.lastRows = r
1093:       try { ws.send(JSON.stringify({ type: 'resize', cols: c, rows: r })) } catch { /* ignored */ }
1094:     }
1095:   }
1096: 
1097:   private handleBinaryMessage(entry: PoolEntry, data: Uint8Array): void {
1098:     if (entry.connection.state === 'replaying') {
1099:       const flush = entry.replayBuffer.add(data)
1100:       if (flush) {
1101:         this.writeRaw(entry, flush.bytes)
1102:         entry.connection.markLive()
1103:       }
1104:       return
1105:     }
1106: 
1107:     this.dispatchLiveOutput(entry, data)
1108:   }
1109: 
1110:   private handleTextControl(entry: PoolEntry, text: string): void {
1111:     let ctrl: { type?: string } | null = null
1112:     try {
1113:       ctrl = JSON.parse(text)
1114:     } catch {
1115:       // Not JSON; write the raw string below.
1116:     }
1117: 
1118:     if (ctrl && ctrl.type === 'pong') return
1119:     if (ctrl && ctrl.type === 'replay-start') {
1120:       entry.connection.startReplay()
1121:       return
1122:     }
1123:     if (ctrl && ctrl.type === 'replay-end') {
1124:       entry.connection.endReplay()
1125:       return
1126:     }
1127: 
1128:     // Non-control string (or unknown control): write directly.
1129:     this.writeRaw(entry, text)
1130:   }
1131: 
1132:   private flushReplayBuffer(entry: PoolEntry): void {
1133:     const all = entry.replayBuffer.flush()
1134:     if (all) {
1135:       this.writeRaw(entry, all)
1136:     }
1137:   }
1138: 
1139:   // Replay / non-control output: no latency measurement; just write and scroll.
1140:   private writeRaw(entry: PoolEntry, data: Uint8Array | string): void {
1141:     entry.predictiveEcho?.clear()
1142:     entry.terminal.write(data, () => {
1143:       if (!entry.userScrolled) {
1144:         try { entry.terminal.scrollToBottom() } catch { /* ignored */ }
1145:       }
1146:     })
1147:   }
1148: 
1149:   // ── live output dispatcher (BSU/ESU) ────────────────────────────────
1150: 
1151:   // Live output dispatcher. Handles DEC mode 2026 synchronized-update
1152:   // markers (BSU/ESU) by buffering bytes between markers and flushing them
1153:   // as a single terminal.write. Markers are stripped. Straddling markers are
1154:   // handled via syncCarryover.
1155:   private dispatchLiveOutput(entry: PoolEntry, data: Uint8Array): void {
1156:     if (entry.syncCarryover !== null) {
1157:       data = concatU8Legacy([entry.syncCarryover, data])
1158:       entry.syncCarryover = null
1159:     }
1160: 
1161:     const out: Uint8Array[] = []
1162:     let cursor = 0
1163: 
1164:     while (cursor < data.length) {
1165:       const idx = indexOfU8(data, SYNC_MARKER_PREFIX, cursor)
1166:       if (idx === -1) {
1167:         const rest = data.subarray(cursor)
1168:         const tail = this.findSyncMarkerPrefixTail(rest)
1169:         if (tail !== null) {
