1261:   private findSyncMarkerPrefixTail(data: Uint8Array): Uint8Array | null {
1262:     const marker = SYNC_MARKER_PREFIX
1263:     const max = Math.min(data.length, marker.length - 1)
1264:     for (let len = max; len >= 1; len--) {
1265:       let ok = true
1266:       for (let i = 0; i < len; i++) {
1267:         if (data[data.length - len + i] !== marker[i]) {
1268:           ok = false
1269:           break
1270:         }
1271:       }
1272:       if (ok) return data.subarray(data.length - len)
1273:     }
1274:     return null
1275:   }
