1534:   private disposeEntry(entry: PoolEntry): void {
1535:     // Stop the connection machine first so reconnect timers abort.
1536:     entry.connection.dispose()
1537: 
1538:     // Cleanup listeners
1539:     if (entry.listenerCleanup) {
1540:       entry.listenerCleanup()
1541:       entry.listenerCleanup = null
1542:     }
1543:     entry.activeCallbacks = null
1544:     entry.activeContainer = null
1545: 
1546:     // Dispose addons
1547:     if (entry.webglAddon) { entry.webglAddon.dispose(); entry.webglAddon = null }
1548:     if (entry.imageAddon) { entry.imageAddon.dispose(); entry.imageAddon = null }
1549:     if (entry.graphemesAddon) { entry.graphemesAddon.dispose(); entry.graphemesAddon = null }
1550:     if (entry.predictiveEcho) { entry.predictiveEcho.dispose(); entry.predictiveEcho = null }
1551: 
1552:     // Dispose terminal
1553:     try { entry.terminal.dispose() } catch { /* ignored */ }
1554: 
1555:     // Remove hidden host
1556:     if (entry.hiddenHost) {
1557:       entry.hiddenHost.remove()
1558:       entry.hiddenHost = null
1559:     }
1560: 
1561:     // Clean up pool root if empty
1562:     if (this.poolRoot && this.poolRoot.children.length === 0) {
1563:       this.poolRoot.remove()
1564:       this.poolRoot = null
1565:     }
1566:   }
1567: }
