 190:   // Auto-lock: idle detection
 191:   const lastActivityRef = useRef<number>(Date.now())
 192:   useEffect(() => {
 193:     if (!onLogout || !prefs.lock_timeout_minutes) return
 194: 
 195:     const idleMs = prefs.lock_timeout_minutes * 60 * 1000
 196: 
 197:     // Track user activity
 198:     const onActivity = () => { lastActivityRef.current = Date.now() }
 199:     const events = ['keydown', 'click', 'scroll', 'touchstart', 'mousemove'] as const
 200:     const opts: AddEventListenerOptions = { passive: true, capture: true }
 201:     events.forEach(e => document.addEventListener(e, onActivity, opts))
 202: 
 203:     // Check idle on an interval
 204:     const checkInterval = setInterval(() => {
 205:       const elapsed = Date.now() - lastActivityRef.current
 206:       if (elapsed >= idleMs) {
 207:         onLogout()
 208:       }
 209:     }, 30_000)
 210: 
 211:     return () => {
 212:       events.forEach(e => document.removeEventListener(e, onActivity, opts as EventListenerOptions))
 213:       clearInterval(checkInterval)
 214:     }
 215:   }, [onLogout, prefs.lock_timeout_minutes])
