 260:   // Remove a session leaf from every saved group EXCEPT the active one. Dropping
 261:   // a session into the current view must not leave a duplicate leaf lingering in
 262:   // its previous group: leaves are keyed by session name and the terminal pool
 263:   // is keyed the same, so a cross-group duplicate mirrors one terminal into two
 264:   // groups and the split appears to "land" in the wrong (old) group.
 265:   const detachFromOtherGroups = useCallback((sessKey: string) => {
 266:     const active = activeGroupIdRef.current
 267:     for (const [id, g] of Object.entries(syncedGroupsRef.current)) {
 268:       if (id === active || !findLeaf(g.tree, sessKey)) continue
 269:       const pruned = removeLeaf(g.tree, sessKey)
 270:       if (pruned === null) void deleteGroup(id)
 271:       else void setGroupTree(id, pruned)
 272:     }
 273:   }, [deleteGroup, setGroupTree])
