 275:   const handleDropSession = useCallback((sessKey: string, targetKey: string, edge: 'left'|'right'|'top'|'bottom'|'center') => {
 276:     // Dropping onto a standalone (singleView) session pairs the two into their
 277:     // OWN new group. singleView leaves paneTree/activeGroupId pointing at the
 278:     // previously-viewed group, so merging into the active tree would wrongly
 279:     // dump the dragged session into that background group.
 280:     if (singleView && (targetKey === singleView || targetKey === '')) {
 281:       const anchor = singleView
 282:       detachFromOtherGroups(sessKey)
 283:       detachFromOtherGroups(anchor)
 284:       const direction: 'h' | 'v' = (edge === 'top' || edge === 'bottom') ? 'v' : 'h'
 285:       const newFirst = edge === 'left' || edge === 'top'
 286:       const base = popOut(anchor)
 287:       const newTree = newFirst
 288:         ? insertBesideLeaf(base, anchor, direction, sessKey, true)
 289:         : splitLeaf(base, anchor, direction, sessKey)
 290:       const newGroupId = Math.random().toString(36).slice(2)
 291:       const currentRank = syncedGroups[activeGroupId]?.rank ?? null
 292:       if (paneTree) {
 293:         void setGroupTree(activeGroupId, paneTree)
 294:         if (!currentRank) void setGroupRank(activeGroupId, generateKeyBetween(null, generateKeyBetween(currentRank, null)))
 295:       }
 296:       void setGroupTree(newGroupId, newTree)
 297:       void setGroupRank(newGroupId, generateKeyBetween(currentRank, null))
 298:       setPaneTree(newTree)
 299:       setActiveKey(sessKey)
 300:       setActiveGroupId(newGroupId)
 301:       setSingleView(null)
 302:       return
 303:     }
 304:     setSingleView(null)
 305:     detachFromOtherGroups(sessKey)
 306:     const currentActive = activeKeyRef.current
 307:     setPaneTree((prev: PaneTree | null) => {
 308:       // Standalone session: target is the anchor, dragged session always second
 309:       if (prev === null) {
 310:         if (targetKey) {
 311:           const direction: 'h' | 'v' = (edge === 'top' || edge === 'bottom') ? 'v' : 'h'
 312:           const base = popOut(targetKey)
 313:           return splitLeaf(base, targetKey, direction, sessKey)
 314:         }
 315:         return popOut(sessKey)
 316:       }
 317:       // Already in the layout — just focus, don't duplicate
 318:       if (findLeaf(prev, sessKey)) { setActiveKey(sessKey); return prev }
 319:       const key = (targetKey && findLeaf(prev, targetKey)) ? targetKey
 320:         : currentActive !== null && findLeaf(prev, currentActive) ? currentActive
 321:         : getLeaves(prev)[0] ?? null
 322:       if (!key) return popOut(sessKey)
 323:       const direction: 'h' | 'v' = (edge === 'top' || edge === 'bottom') ? 'v' : 'h'
 324:       const newFirst = edge === 'left' || edge === 'top'
 325:       return newFirst
 326:         ? insertBesideLeaf(prev, key, direction, sessKey, true)
 327:         : splitLeaf(prev, key, direction, sessKey)
 328:     })
 329:     setActiveKey(sessKey)
 330:   }, [detachFromOtherGroups, singleView, paneTree, activeGroupId, syncedGroups, setGroupTree, setGroupRank])
