 383:       if (syncedGroupsRef.current[activeGroupId]) void deleteGroup(activeGroupId)
 384:       const next = Object.entries(syncedGroups)
 385:         .sort(([idA, a], [idB, b]) => {
 386:           const aRank = a.rank ?? ''
 387:           const bRank = b.rank ?? ''
 388:           if (aRank !== bRank) {
 389:             if (!aRank) return 1
 390:             if (!bRank) return -1
 391:             return aRank.localeCompare(bRank)
 392:           }
 393:           return idA.localeCompare(idB)
 394:         })
 395:         .find(([id]) => id !== activeGroupId)
 396:       if (next) {
 397:         const [nextId, nextGroup] = next
 398:         const focusKey = getLeaves(nextGroup.tree)[0] ?? null
 399:         workspaceActions.setActiveGroup(nextId, nextGroup.tree, focusKey)
 400:         if (focusKey) {
