 419:     if (splitTargetRef.current) return // split pending — don't dissolve yet
 420:     const lastLeaf = leaves[0]
 421:     workspaceActions.dissolveToSingle()
 422:     // The active layout is no longer a group; drop its server record so the
 423:     // dissolved (broken-out) session stops re-rendering as grouped. Guard on a
 424:     // real record to avoid tombstoning ids that were never persisted.
 425:     if (syncedGroupsRef.current[activeGroupId]) void deleteGroup(activeGroupId)
 426:     const { host, name } = parseSessionKey(lastLeaf)
 427:     const path = host
 428:       ? `/session/${encodeURIComponent(host)}/${encodeURIComponent(name)}`
 429:       : `/session/${encodeURIComponent(name)}`
 430:     if (window.location.pathname !== path) window.history.replaceState(null, '', path)
 431:   }, [paneTree, activeGroupId, deleteGroup, workspaceActions])
