 456:   // Global keyboard shortcuts (tinykeys). $mod = Cmd on macOS, Ctrl elsewhere.
 457:   useEffect(() => {
 458:     const cycle = (dir: 1 | -1) => {
 459:       const skeys: string[] = []
 460:       document
 461:         .querySelectorAll('[data-session-key]')
 462:         .forEach(el => skeys.push(el.getAttribute('data-session-key')!))
 463:       if (skeys.length === 0) return
 464:       const current = selectedSessionRef.current
 465:       const idx = current ? skeys.indexOf(current) : -1
 466:       const nextIdx =
 467:         dir === 1
 468:           ? idx >= 0
 469:             ? (idx + 1) % skeys.length
 470:             : 0
 471:           : idx > 0
 472:             ? idx - 1
 473:             : skeys.length - 1
 474:       const targetKey = skeys[nextIdx]
 475:       // If target belongs to a saved group, switch to that group first
 476:       const group = Object.entries(syncedGroupsRef.current).find(([, g]) => findLeaf(g.tree, targetKey))
 477:       if (group) {
 478:         const [groupId] = group
 479:         switchToGroupRef.current?.(groupId)
 480:         setActiveKeyRef.current(targetKey)
 481:         const { host, name } = parseSessionKey(targetKey)
 482:         const path = host
 483:           ? `/session/${encodeURIComponent(host)}/${encodeURIComponent(name)}`
 484:           : `/session/${encodeURIComponent(name)}`
 485:         if (window.location.pathname !== path) window.history.pushState(null, '', path)
 486:       } else {
 487:         selectSessionRef.current?.(targetKey)
 488:       }
 489:     }
 490: 
 491:     const handler =
 492:       (fn: (e: KeyboardEvent) => void) => (e: KeyboardEvent) => {
 493:         e.preventDefault()
 494:         fn(e)
 495:       }
 496: 
 497:     // The terminal owns the keyboard. useTerminal() (attachCustomKeyEventHandler)
 498:     // already decides which $mod combos escape xterm and bubble here — that
 499:     // narrow whitelist IS the gate. So we must NOT let tinykeys' default ignore
 500:     // drop events originating from the xterm helper textarea, or whitelisted
 501:     // shortcuts would silently fail while a session is focused. Other form
 502:     // inputs (modals, settings) keep the default ignore behaviour.
 503:     const ignore = (e: KeyboardEvent) => {
 504:       const target = e.target as HTMLElement | null
 505:       if (target?.closest?.('.xterm')) return false
 506:       return (
 507:         e.repeat ||
 508:         e.isComposing ||
 509:         (target !== e.currentTarget &&
 510:           !!target?.matches?.('[contenteditable],input,select,textarea'))
 511:       )
 512:     }
 513: 
 514:     return tinykeys(window, {
 515:       // Help: Cmd/Ctrl + / (Slash). Shift+Slash ('?') handled by same physical key.
 516:       '$mod+Slash': handler(() => setHelpOpen(prev => !prev)),
 517:       '$mod+Shift+Slash': handler(() => setHelpOpen(prev => !prev)),
 518:       // Toggle sidebar: Cmd/Ctrl + \
 519:       '$mod+Backslash': handler(() => setSidebarCollapsed(c => !c)),
 520:       // Settings: Cmd/Ctrl + ,
 521:       '$mod+Comma': handler(() => openSettings()),
 522:       // Split pane: Cmd/Ctrl + Shift + \
 523:       '$mod+Shift+Backslash': handler(() => {
 524:         if (activeKey !== null) {
 525:           splitTargetRef.current = { key: activeKey, direction: 'h' }
 526:           openNewSessionModal()
 527:         }
 528:       }),
 529:       // Quick Switcher: Cmd/Ctrl + Shift + K (K alone collides w/ Firefox search bar)
 530:       '$mod+Shift+k': handler(() => setQuickSwitcherOpen(true)),
 531:       // New session: Cmd/Ctrl + Shift + Enter (N collides w/ browser private window)
 532:       '$mod+Shift+Enter': handler(() => openNewSessionPlain()),
 533:       // Overview: Cmd/Ctrl + Shift + H (Shift+O collides w/ Firefox bookmarks)
 534:       '$mod+Shift+h': handler(() => navigateTo(null)),
 535:       // Wiki panel: Cmd/Ctrl + Shift + G. G is not mnemonic, but the mnemonic
 536:       // keys are all taken by the browser: Shift+W closes the window, Shift+E
 537:       // opens Firefox's network monitor, Shift+D bookmarks every tab, and
 538:       // Shift+F is already terminal fullscreen here.
 539:       '$mod+Shift+g': handler(() => { if (wikiEnabledRef.current) wiki.togglePanel() }),
 540:       // Cycle sessions: Cmd/Ctrl + Shift + Arrow (Shift+[ / ] switches browser tabs)
 541:       '$mod+Shift+ArrowRight': handler(() => cycle(1)),
 542:       '$mod+Shift+ArrowLeft': handler(() => cycle(-1)),
 543:     }, { ignore })
 544:   }, [navigateTo, activeKey, openNewSessionModal, openNewSessionPlain, wiki.togglePanel])
