 546:   // Backend notices (silent failures surfaced to the UI as toasts)
 547:   const [toasts, setToasts] = useState<Toast[]>([])
 548:   const toastIdRef = useRef(0)
 549:   const dismissToast = useCallback((id: number) => setToasts(t => t.filter(x => x.id !== id)), [])
 550: 
 551:   // Client-side notices (e.g. unsupported pop-out) dispatched as window events
 552:   useEffect(() => {
 553:     const onToast = (e: Event) => {
 554:       const d = (e as CustomEvent).detail || {}
 555:       setToasts(t => [...t, {
 556:         id: ++toastIdRef.current,
 557:         severity: d.severity === 'error' || d.severity === 'warn' ? d.severity : 'info',
 558:         source: d.source || 'termyard',
 559:         message: d.message || '',
 560:       }].slice(-4))
 561:     }
 562:     window.addEventListener('termyard:toast', onToast)
 563:     return () => window.removeEventListener('termyard:toast', onToast)
 564:   }, [])
