 566:   const migrateSessionKey = useCallback((oldKey: string, newKey: string) => {
 567:     if (!oldKey || !newKey || oldKey === newKey) return
 568: 
 569:     // v2: mirror the rename into the workspace tree via the typed rename
 570:     // command (pkg/state/workspace.go WorkspaceActionRename, old/new
 571:     // SessionRef) instead of the legacy in-place reducer key swap. Fire and
 572:     // forget -- the authoritative tree update arrives back over the state
 573:     // stream, same pattern as other v2 layout mutations below.
 574:     if (v2Enabled && v2State.layoutId) {
 575:       void v2State.workspaceCommand(v2State.layoutId, {
 576:         action: 'rename',
 577:         old: keyToSessionRef(oldKey),
 578:         new: keyToSessionRef(newKey),
 579:       }).catch(err => console.error('v2 rename command failed:', err))
 580:     }
 581: 
 582:     workspaceActions.renameSession(oldKey, newKey)
 583: 
 584:     // Rekey pool entry: preserve terminal/WS, update reconnect identity.
 585:     // If destination already has an entry (collision), dispose it first.
 586:     terminalPool.dispose(newKey)
 587:     terminalPool.rekey(oldKey, newKey)
 588: 
 589:     const { host: oldHost, name: oldName } = parseSessionKey(oldKey)
 590:     const oldPath = oldHost
 591:       ? `/session/${encodeURIComponent(oldHost)}/${encodeURIComponent(oldName)}`
 592:       : `/session/${encodeURIComponent(oldName)}`
 593:     const { host: newHost, name: newName } = parseSessionKey(newKey)
 594:     const newPath = newHost
 595:       ? `/session/${encodeURIComponent(newHost)}/${encodeURIComponent(newName)}`
 596:       : `/session/${encodeURIComponent(newName)}`
 597:     if (window.location.pathname === oldPath) {
 598:       window.history.replaceState(null, '', newPath)
 599:     }
 600:   }, [workspaceActions])
