 602:   // Listen for state events via WebSocket
 603:   const onEvent = useCallback((evt: any) => {
 604:     if (evt.type === 'notice') {
 605:       const d = evt.data || {}
 606:       setToasts(t => [
 607:         ...t,
 608:         {
 609:           id: ++toastIdRef.current,
 610:           severity: d.severity === 'error' || d.severity === 'warn' ? d.severity : 'info',
 611:           source: d.source || 'server',
 612:           message: d.message || '',
 613:           session: evt.session || undefined,
 614:         },
 615:       ].slice(-4))
 616:       return
 617:     }
 618:     if (evt.type === 'welcome') {
 619:       const v = evt.version || null
 620:       if (!loadedVersionRef.current) {
 621:         loadedVersionRef.current = v
 622:       }
 623:       setServerVersion(v)
