1587: export default function App() {
1588:   const prefsProvider = usePreferencesProvider()
1589:   const { loading, authRequired, needsSetup, authenticated, error: authError, setup, login, logout } = useAuth()
1590:   const [showOnboarding, setShowOnboarding] = useState(false)
1591: 
1592:   useEffect(() => {
1593:     const syncViewport = () => {
1594:       const viewport = window.visualViewport
1595:       const height = viewport?.height ?? window.innerHeight
1596:       const width = viewport?.width ?? window.innerWidth
1597:       document.documentElement.style.setProperty('--app-height', `${Math.round(height)}px`)
1598:       document.documentElement.style.setProperty('--app-width', `${Math.round(width)}px`)
1599:     }
1600: 
1601:     syncViewport()
1602:     window.addEventListener('resize', syncViewport)
1603:     window.visualViewport?.addEventListener('resize', syncViewport)
1604:     window.visualViewport?.addEventListener('scroll', syncViewport)
1605: 
1606:     return () => {
1607:       window.removeEventListener('resize', syncViewport)
1608:       window.visualViewport?.removeEventListener('resize', syncViewport)
1609:       window.visualViewport?.removeEventListener('scroll', syncViewport)
1610:     }
1611:   }, [])
1612: 
1613:   // Re-fetch preferences after login (initial fetch may have gotten 401)
1614:   useEffect(() => {
1615:     if (authenticated) {
1616:       prefsProvider.refetch()
1617:     }
1618:   }, [authenticated]) // eslint-disable-line react-hooks/exhaustive-deps
1619: 
1620:   // Apply last-used theme immediately (before auth) so login page is themed
1621:   useEffect(() => {
1622:     try {
1623:       const cached = localStorage.getItem('termyard:theme')
1624:       if (cached) {
1625:         applyTheme(cached)
1626:       }
1627:     } catch {}
1628:   }, [])
1629: 
1630:   // Apply theme when preferences load or theme changes, and cache for login page
1631:   useEffect(() => {
1632:     if (prefsProvider.loaded) {
1633:       applyTheme(prefsProvider.prefs.theme)
1634:       try {
1635:         localStorage.setItem('termyard:theme', prefsProvider.prefs.theme)
1636:       } catch {}
1637:     }
1638:   }, [prefsProvider.loaded, prefsProvider.prefs.theme])
1639: 
1640:   if (loading) {
1641:     return <div className="flex items-center justify-center h-full w-full bg-background" />
1642:   }
1643: 
1644:   if (authRequired && needsSetup) {
1645:     const handleSetup = async (password: string) => {
1646:       const ok = await setup(password)
1647:       if (ok) setShowOnboarding(true)
1648:       return ok
1649:     }
1650:     return <Login mode="setup" error={authError} onSubmit={handleSetup} />
1651:   }
1652: 
1653:   if (authRequired && !authenticated) {
1654:     return <Login mode="login" error={authError} onSubmit={login} />
1655:   }
1656: 
1657:   if (authenticated && showOnboarding) {
1658:     return (
1659:       <PreferencesContext.Provider value={prefsProvider}>
1660:         <Setup fullPage onComplete={() => {
1661:           setShowOnboarding(false)
1662:           try { localStorage.setItem('termyard:setup-seen', 'true') } catch {}
1663:         }} />
1664:       </PreferencesContext.Provider>
1665:     )
1666:   }
1667: 
1668:   return (
1669:     <PreferencesContext.Provider value={prefsProvider}>
1670:       <AppInner onLogout={authRequired ? logout : undefined} authenticated={authRequired ? authenticated : true} />
1671:     </PreferencesContext.Provider>
1672:   )
1673: }
